                Translate(GUID, null, text5, text5Loc, Language.French);
                Translate(GUID, null, "While " + value.DisplayedNameLocalized + " is on the board, remove ally Terrain and Pelt cards and transform the rest into random Apostles.", "Tant que " + value.DisplayedNameLocalized + " est sur le plateau, retirez les cartes alliées de terrain et de fourrure, puis transformez les autres en Apôtres aléatoires.", Language.French);
                Translate(GUID, null, "[c:bR]The Clock[c:] and your [c:bR]" + value.DisplayedNameLocalized + "[c:] will remain in that abandoned time.", "[c:bR]L'Horloge[c:] et votre carte [c:bR]" + value.DisplayedNameLocalized + "[c:] resteront dans ce temps abandonné.", Language.French);
                Translate(GUID, null, "False " + value.DisplayedNameLocalized, value.DisplayedNameLocalized + " (imitation)", Language.French);
                Translate(GUID, null, "[c:bB]That " + value.DisplayedNameLocalized + " costs more energy than you have.[c:]", "[c:bB]Vous n'avez pas assez d'énergie pour jouer " + value.DisplayedNameLocalized + ".[c:]", Language.French);
            }
            if (source == null)
            for (int max = 1; max <= 10; max++)
            {
                Translate(GUID, null, "[c:bB]Do you still not get it? It costs " + max.ToString() + " energy and you don't have enough.[c:]", "[c:bB]Vous ne comprenez toujours pas ? Cela coûte " + max.ToString() + " " + (max == 1 ? "point" : "points") + " d'énergie et vous n'en avez pas assez.[c:]", Language.French);
                for (int count = 0; count < max; count++)
                {
                    Translate(GUID, null, "[c:bB]That costs " + max.ToString() + " energy and you have " + count.ToString() + ".[c:]", "[c:bB]Cela coûte " + max.ToString() + " " + (max == 1 ? "point" : "points") + " d'énergie et vous en avez " + count.ToString() + ".[c:]", Language.French);
                }
            }


            // LifeCostAPI
            if (source == null) Debug.Log("Post Register Translations for LifeCostAPI");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped to play [c:bG]" + value.DisplayedNameLocalized + "[c:].", "Votre [c:bG]balance[c:] est trop inclinée pour jouer [c:bG]" + value.DisplayedNameLocalized + "[c:].", Language.French);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]" + value.DisplayedNameLocalized + "[c:] requires you to pay in life, in which you can not fullfill without killing yourself.", "Jouer [c:bG]" + value.DisplayedNameLocalized + "[c:] coûte de la vie ; vous ne pouvez pas payer sans mourir.", Language.French);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You would kill yourself if you played [c:bG]" + value.DisplayedNameLocalized + "[c:]. Your [c:bG]Scales[c:] are too tipped", "Jouer [c:bG]" + value.DisplayedNameLocalized + "[c:] vous tuerait. Votre [c:bG]balance[c:] est trop inclinée.", Language.French);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped and you lack the [c:gray]Foils[c:] to play " + value.DisplayedNameLocalized + ".", "Votre [c:bG]balance[c:] est trop inclinée et vous manquez de [c:gray]cartes Premium[c:] pour jouer " + value.DisplayedNameLocalized + ".", Language.French);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You lack the foils to play that [c:gray]" + value.DisplayedNameLocalized + "[c:].", "Vous n'avez pas assez de cartes Premium pour jouer [c:gray]" + value.DisplayedNameLocalized + "[c:].", Language.French);
                for (int count = 0; count <= 20; count++)
                {
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:gray]" + value.DisplayedNameLocalized + "[c:] requires you pay it's cost in [c:gray]foils[c:], that which you have [c:gray]" + count.ToString() + "[c:].", "[c:gray]" + value.DisplayedNameLocalized + "[c:] coûte des [c:gray]cartes Premium[c:] ; vous en avez [c:gray]" + count.ToString() + "[c:].", Language.French);
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That [c:gray]" + value.DisplayedNameLocalized + "[c:] has the cost of [c:gray]" + count.ToString() + "[c:] foils, which you do not have.", "[c:gray]" + value.DisplayedNameLocalized + "[c:] coûte [c:gray]" + count.ToString() + "[c:] " + (count == 1 ? "carte Premium" : "cartes Premium") + ", et vous n'en avez pas assez.", Language.French);
                }
            }

            // Sire_MoDeers
            if (source == null) Debug.Log("Post Register Translations for Sire_MoDeers");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, value.DisplayedName + "'s Protector", "Esprit protecteur de la carte « " + value.DisplayedNameLocalized + " »", Language.French);
            }

            if (source == null) Debug.Log("Post Register Translations Ended");
            stopwatch.Stop();
            if (source == null) Debug.Log($"PostRegisterTranslations 执行时间: {stopwatch.ElapsedMilliseconds} ms");
        }

        private static List<PostRegisterCardData> CachePostRegisterCardData(IEnumerable<CardInfo> source)
        {
            var cards = new List<PostRegisterCardData>();
            foreach (var card in source)
            {
                if (card.SafeIsUnityNull()) continue;
                var value = new PostRegisterCardData(card, card.IsBaseGameCard());
                if (MultilingualTranslationRuntime.IncludeCardForPostRegistration(Language.French, value.Name,
                    value.DisplayedName, value.DisplayedNameEnglish, value.DisplayedNameLocalized,
                    value.Attack, value.Health, value.Abilities, value.Description))
                {
                    cards.Add(value);
                }
            }
            return cards;
        }

        private sealed class PostRegisterCardData
        {
            public PostRegisterCardData(CardInfo card, bool isBaseGameCard)
            {
                IsBaseGameCard = isBaseGameCard;
                DisplayedNameEnglish = card.DisplayedNameEnglish;
                DisplayedNameLocalized = card.DisplayedNameLocalized;
                DisplayedName = card.displayedName;
                Description = card.description;
                Name = card.name;
                Attack = card.Attack;
                Health = card.Health;
                Abilities = card.Abilities?.ToArray() ?? Array.Empty<Ability>();
            }

            public bool IsBaseGameCard { get; }
            public string DisplayedNameEnglish { get; }
            public string DisplayedNameLocalized { get; }
            public string DisplayedName { get; }
            public string Description { get; }
            public string Name { get; }
            public int Attack { get; }
            public int Health { get; }
            public Ability[] Abilities { get; }
            public bool HasDisplayedNameEnglish => DisplayedNameEnglish != null;
            public bool HasDisplayedName => DisplayedName != null;
        }
        private static bool NameStartsWithVowel(string name)
        {
            if (string.IsNullOrEmpty(name))
            {
                return false;
            }
            char c = name.ToLowerInvariant()[0];
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        }

    }

