    public class MagnificusMod
    {
        public static Dictionary<string, string> Cards = new();
        public static Dictionary<string, List<KeyValuePair<string, string>>> CardsDescription = new();

        public static Dictionary<string, string> Abilities = new();

        public static void RegisterCard(string en, string zh, string desen, string deszh)
        {
            if (!Cards.ContainsKey(en))
            {
                Cards.Add(en, zh);
            }
            if (!CardsDescription.ContainsKey(en))
            {
                CardsDescription[en] = new List<KeyValuePair<string, string>>();
            }
            CardsDescription[en].Add(new KeyValuePair<string, string>(desen, deszh));
        }

        public static void RegisterAbility(string en, string zh)
        {
            Abilities.Add(en, zh);
        }

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Magnificus Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New Magnificus Run", "NOUVELLE PARTIE AVEC MAGNIFICUS", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW MAGNIFICUS RUN", "NOUVELLE PARTIE AVEC MAGNIFICUS", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "View Deck", "Voir le deck", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TOWER OF MAGICKS", "TOUR DES MAGIES", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOO DUNGEON", "DONJON DE GLU", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LAVA DUNGEON", "DONJON DE LAVE", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VOID DUNGEON", "DONJON DU NÉANT", Language.French);

            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automatically unlocks every challenge and starter deck in Magnificus' Kaycees Mod. This does NOT change your magnificus challenge point value. If you have a change of heart and decide to unlock the challenges fairly, your challenge points will remain the same.", "Débloque automatiquement tous les défis et decks de départ du Mod de Kaycee de Magnificus. Cela ne change PAS vos points de défi de Magnificus. Si vous changez d'avis et décidez de débloquer les défis à la loyale, vos points de défi resteront les mêmes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base wizard cards from act 2 will keep their original statlines.", "Les cartes de sorcier de base de l'acte 2 conservent leurs caractéristiques d'origine.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the old 2D flat card designs instead of the new 3D models.", "Utilise les anciens modèles de cartes plats en 2D au lieu des nouveaux modèles en 3D.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add paint splashes to the background of every card (like in the original magnificus finale).", "Ajoute des éclaboussures de peinture au fond de chaque carte, comme dans le final original de Magnificus.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third person perspective for magnificus' game. Disable if you want the classic first person experience.", "Perspective à la troisième personne pour le jeu de Magnificus. Désactivez cette option pour retrouver l'expérience classique à la première personne.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Show a grid around the player in tabletop mode.", "Affiche une grille autour du joueur en mode plateau.", Language.French);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Mox", "Mox vierge", Language.French);
            RegisterAbility("Blank Mox", "Mox vierge");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, it will materialize into a random Mox Crystal. \n When on another card, the card will generate a random Mox Crystal.", "Lorsqu'une carte ornée de cet emblème est piochée, elle se matérialise en un cristal de mox aléatoire. \n Sur une autre carte, cet emblème lui fait générer un cristal de mox aléatoire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undecided Mox", "Mox indécis", Language.French);
            RegisterAbility("Undecided Mox", "Mox indécis");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, select a mox type for this card to provide.", "Lorsqu'une carte ornée de cet emblème est jouée, choisissez le type de mox qu'elle fournira.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Heart", "Cœur de rubis", Language.French);
            RegisterAbility("Ruby Heart", "Cœur de rubis");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Ruby Mox in its place.", "Lorsqu'une carte ornée de cet emblème meurt, elle crée un Mox de rubis à sa place.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Heart", "Cœur de saphir", Language.French);
            RegisterAbility("Sapphire Heart", "Cœur de saphir");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Sapphire Mox in its place.", "Lorsqu'une carte ornée de cet emblème meurt, elle crée un Mox de saphir à sa place.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Marrow", "Moelle osseuse", Language.French);
            RegisterAbility("Bone Marrow", "Moelle osseuse");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When one of your non-gem cards perishes, a card bearing this sigil gains 1 power, maxing out at 5.", "Lorsqu'une de vos cartes non gemmes meurt, une carte ornée de cet emblème gagne 1 point de puissance, jusqu'à un maximum de 5.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation", "Stimulation", Language.French);
            RegisterAbility("Stimulation", "Stimulation");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 1 power, maxing out at 4.", "À la fin de chaque tour, une carte ornée de cet emblème gagne 1 point de puissance, jusqu'à un maximum de 4.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation (Health)", "Stimulation de santé", Language.French);
            RegisterAbility("Stimulation (Health)", "Stimulation de santé");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 2 health, maxes out at 10.", "À la fin de chaque tour, une carte ornée de cet emblème gagne 2 points de santé, jusqu'à un maximum de 10.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Draw", "Pioche funèbre", Language.French);
            RegisterAbility("Dead Draw", "Pioche funèbre");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card dies, draw a card from your deck.", "Lorsqu'une carte non gemme meurt, piochez une carte dans votre deck.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Heart", "Cœur d'émeraude", Language.French);
            RegisterAbility("Emerald Heart", "Cœur d'émeraude");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates an Emerald Mox in its place.", "Lorsqu'une carte ornée de cet emblème meurt, elle crée un Mox d'émeraude à sa place.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gooey", "Gluant", Language.French);
            RegisterAbility("Gooey", "Gluant");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the striker loses 1 attack.", "Lorsqu'une carte ornée de cet emblème est frappée, l'attaquant perd 1 point de puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mental Gemnastics", "Gymnastique mentale", Language.French);
            RegisterAbility("Mental Gemnastics", "Gymnastique mentale");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw cards from your deck based on how many Gems are on the board.", "Lorsqu'une carte ornée de cet emblème est jouée, piochez dans votre deck autant de cartes qu'il y a de gemmes sur le plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loot", "Pillage", Language.French);
            RegisterAbility("Loot", "Pillage");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, draw cards from your deck based on how much damage was dealt.", "Lorsqu'une carte ornée de cet emblème inflige des dégâts directs, piochez dans votre deck autant de cartes que de points de dégâts infligés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Steal", "Vol de vie", Language.French);
            RegisterAbility("Life Steal", "Vol de vie");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, the amount dealt will be healed to the owner of this card.", "Lorsqu'une carte ornée de cet emblème inflige des dégâts directs, son propriétaire récupère autant de santé que de dégâts infligés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knockback Hit", "Coup de recul", Language.French);
            RegisterAbility("Knockback Hit", "Coup de recul");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil hits an opposing card, the opposing card will be kicked in the direction inscrybed in the sigil.", "Lorsqu'une carte ornée de cet emblème frappe une carte adverse, cette dernière est repoussée dans la direction indiquée sur l'emblème.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Impaled", "Empalement", Language.French);
            RegisterAbility("Impaled", "Empalement");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Spear in its placed. A spear is defined as Sharp, 0 power, 3 health.", "Lorsqu'une carte ornée de cet emblème meurt, elle crée une Lance à sa place. Une Lance possède Piquants, 0 de puissance et 3 de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnus Mox", "Mox magni", Language.French);
            RegisterAbility("Magnus Mox", "Mox magni");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, it provides an orange gem, a blue gem and a green gem to its owner.", "Tant qu'une carte ornée de cet emblème est sur le plateau, elle fournit une gemme orange, une bleue et une verte à son propriétaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resurrection", "Résurrection", Language.French);
            RegisterAbility("Resurrection", "Résurrection");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card perishes, the dead card will be brought back to life, but this card loses 3 health.", "Lorsqu'une carte non gemme meurt, elle est ramenée à la vie, mais la carte ornée de cet emblème perd 3 points de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rerolls", "Relances de dés", Language.French);
            RegisterAbility("Rerolls", "Relances de dés");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigils' base power will be increased by a random value between 0 and 3.", "À la fin de chaque tour, la puissance de base d'une carte ornée de cet emblème est fixée à une valeur aléatoire comprise entre 0 et 3.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Steel Trap", "Piège d'acier", Language.French);
            RegisterAbility("Steel Trap", "Piège d'acier");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the opposing card also perishes.", "Lorsqu'une carte ornée de cet emblème meurt, la carte en face meurt également.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Shield", "Bouclier de gemmes", Language.French);
            RegisterAbility("Gem Shield", "Bouclier de gemmes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on the board gain a shield.", "Lorsqu'une carte ornée de cet emblème est jouée, toutes les gemmes sur le plateau gagnent un bouclier.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plating Work", "Travail de placage", Language.French);
            RegisterAbility("Plating Work", "Travail de placage");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all gems on your side of the board gain the Sharp Quills sigil, and 2 health.", "Tant qu'une carte ornée de cet emblème est sur le plateau, toutes les gemmes de votre côté du plateau gagnent l'emblème Piquants et 2 points de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "Marionnettiste", Language.French);
            RegisterAbility("Animator", "Marionnettiste");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all non-mox cards with 0 power gain 2 power", "Tant qu'une carte ornée de cet emblème est sur le plateau, toutes les cartes autres que les mox ayant 0 de puissance gagnent 2 points de puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "Absorbeur de gemmes", Language.French);
            RegisterAbility("Gem Absorber", "Absorbeur de gemmes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on your side of the board will perish. For each gem absorbed, gain 1 power and 2 health.", "Lorsqu'une carte ornée de cet emblème est jouée, toutes les gemmes de votre côté du plateau meurent. Cette carte gagne 1 point de puissance et 2 points de santé par gemme absorbée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerge", "Immersion", Language.French);
            RegisterAbility("Submerge", "Immersion");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will submerge. Upon resubmerging, this card will become a random Tentacle Card.", "À la fin du tour, une carte ornée de cet emblème s'immerge. Lorsqu'elle refait surface, elle devient une carte Tentacule aléatoire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Familiar", "Familier", Language.French);
            RegisterAbility("Familiar", "Familier");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish if there are no non-gem cards on the board.", "Une carte ornée de cet emblème meurt s'il n'y a aucune carte non gemme sur le plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fading", "Effacement", Language.French);
            RegisterAbility("Fading", "Effacement");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish at the end of the turn.", "Une carte ornée de cet emblème meurt à la fin du tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morph", "Métamorphose", Language.French);
            RegisterAbility("Morph", "Métamorphose");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will mimic the card opposing it. If there is no card opposing it, this card will perish.", "Lorsqu'une carte ornée de cet emblème est jouée, elle imite la carte en face. S'il n'y a aucune carte en face, elle meurt.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication", "Multiplication matricielle", Language.French);
            RegisterAbility("Multiplication", "Multiplication matricielle");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw another of this card, but with a different gem cost.", "Lorsqu'une carte ornée de cet emblème est jouée, piochez un autre exemplaire de cette carte, avec un coût en gemmes différent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Cycle", "Cycle des mox", Language.French);
            RegisterAbility("Mox Cycle", "Cycle des mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, all the mox on the board will cycle into different gems.", "À la fin de chaque tour, tous les mox sur le plateau changent de type de gemme selon un cycle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Strafe", "Sillage de mox", Language.French);
            RegisterAbility("Mox Strafe", "Sillage de mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, this card will move to the direction inscrybed on the sigil, and leave behind a mox.", "À la fin du tour, cette carte se déplace dans la direction indiquée sur l'emblème et laisse un mox derrière elle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist", "Purisme", Language.French);
            RegisterAbility("Purist", "Purisme");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any card directly opposing this one will have all it's sigils removed.", "Toute carte directement en face de celle-ci perd tous ses emblèmes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brewery", "Brasserie", Language.French);
            RegisterAbility("Brewery", "Brasserie");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, you automatically draw a mox card from your side deck.", "À la fin de chaque tour, vous piochez automatiquement une carte mox dans votre deck secondaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "Embrasement", Language.French);
            RegisterAbility("Ignite", "Embrasement");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, every empty opposing slot will be filled with flames. A flame is defined as a 0/1, Annoying.", "Lorsqu'une carte ornée de cet emblème est jouée, chaque emplacement adverse vide est rempli de flammes magiques. Une Flamme magique est une carte 0/1 avec Fureur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Projection", "Projection stellaire", Language.French);
            RegisterAbility("Projection", "Projection stellaire");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is stuck, it will move and leave behind an astral projection of itself.", "Lorsqu'une carte ornée de cet emblème est frappée, elle se déplace et laisse une projection astrale d'elle-même derrière elle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Book", "Grimoire", Language.French);
            RegisterAbility("Spell Book", "Grimoire");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random spell card.", "Lorsqu'une carte ornée de cet emblème est jouée, piochez une carte de sort aléatoire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scholar", "Érudit des sorts", Language.French);
            RegisterAbility("Scholar", "Érudit des sorts");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random one of Bleene's Books.", "Lorsqu'une carte ornée de cet emblème est jouée, piochez au hasard l'un des livres de Blert.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Midas' Touch", "Toucher de Midas", Language.French);
            RegisterAbility("Midas' Touch", "Toucher de Midas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks another card, the attacked card will lose all of it's attack and turn to gold.", "Lorsqu'une carte ornée de cet emblème attaque une autre carte, la carte attaquée perd toute sa puissance et se change en or.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Made of Gold", "Corps d'or", Language.French);
            RegisterAbility("Made of Gold", "Corps d'or");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the killer will gain 2 crystals.", "Lorsqu'une carte ornée de cet emblème meurt, son tueur gagne 2 cristaux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Runes", "Runes d'invocation", Language.French);
            RegisterAbility("Summon Runes", "Runes d'invocation");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will summon two runes beside it. A rune is defined as 0 power, 1 health, Detonator.", "Lorsqu'une carte ornée de cet emblème est jouée, elle invoque deux runes à ses côtés. Une Rune possède 0 de puissance, 1 de santé et Détonateur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Health", "Sort de santé", Language.French);
            RegisterAbility("Spell of Health", "Sort de santé");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +2 health.", "Lorsqu'un sort orné de cet emblème est joué, toutes les cartes de votre côté du plateau gagnent +2 de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Attack", "Sort d'attaque", Language.French);
            RegisterAbility("Spell of Attack", "Sort d'attaque");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +1 attack.", "Lorsqu'un sort orné de cet emblème est joué, toutes les cartes de votre côté du plateau gagnent +1 de puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Spell", "Sort de givre", Language.French);
            RegisterAbility("Frost Spell", "Sort de givre");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards belonging to the opponent will have their attack set to 0, but given +2 health.", "Lorsqu'un sort orné de cet emblème est joué, toutes les cartes de l'adversaire voient leur puissance fixée à 0, mais gagnent +2 de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Wind", "Sort de vent", Language.French);
            RegisterAbility("Spell of Wind", "Sort de vent");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board will become airborne.", "Lorsqu'un sort orné de cet emblème est joué, toutes les cartes de votre côté du plateau gagnent Vol.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruckus", "Chahut horaire", Language.French);
            RegisterAbility("Ruckus", "Chahut horaire");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all cards on the board will move clockwise.", "Lorsqu'une carte ornée de cet emblème est jouée, toutes les cartes sur le plateau se déplacent dans le sens horaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Water", "Sort d'eau", Language.French);
            RegisterAbility("Spell of Water", "Sort d'eau");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, every card on the board will have their sigils erased.", "Lorsqu'un sort orné de cet emblème est joué, tous les emblèmes de chaque carte sur le plateau sont effacés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Flame", "Sort de flammes", Language.French);
            RegisterAbility("Spell of Flame", "Sort de flammes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a side of the board, every card on that side will lose 2 health (without perishing) and have their attack increased by 1.", "Choisissez un côté du plateau. Chaque carte de ce côté perd 2 points de santé sans mourir et gagne 1 point de puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Set Ablaze", "Mise à feu", Language.French);
            RegisterAbility("Set Ablaze", "Mise à feu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every card on the opposite side will lose 2 health (without perishing) and have their attack increased by 1.", "Chaque carte du côté opposé perd 2 points de santé sans mourir et gagne 1 point de puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Time Spell", "Sort à usage unique", Language.French);
            RegisterAbility("One Time Spell", "Sort à usage unique");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the turn ends, a spell bearing this sigil will perish and be removed from your deck.", "À la fin du tour, un sort orné de cet emblème meurt et est retiré de votre deck.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vase of Greed", "Vase de l'avidité", Language.French);
            RegisterAbility("Vase of Greed", "Vase de l'avidité");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, discard your current hand and draw 4 new cards.", "Lorsqu'un sort orné de cet emblème est joué, défaussez votre main actuelle, puis piochez 4 nouvelles cartes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnomification", "Gnomification", Language.French);
            RegisterAbility("Gnomification", "Gnomification");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a slot to summon a Gnome card in.", "Choisissez un emplacement où invoquer une carte Gnome.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed", "Maudit", Language.French);
            RegisterAbility("Cursed", "Maudit");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, it will immediately perish.", "Lorsqu'un sort orné de cet emblème est joué, il meurt immédiatement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiration", "Inspiration", Language.French);
            RegisterAbility("Inspiration", "Inspiration");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to give Airborne + Looter for 1 turn.", "Choisissez une carte à laquelle accorder Vol + Pillage pendant 1 tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calculus", "Calcul infinitésimal", Language.French);
            RegisterAbility("Calculus", "Calcul infinitésimal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to swap stats.", "Choisissez une carte dont permuter les caractéristiques.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rage", "Frénésie", Language.French);
            RegisterAbility("Rage", "Frénésie");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to kill. The opponent of the card will recieve damage equal to the amount of health the card had.", "Choisissez une carte à tuer. L'adversaire de cette carte subit autant de dégâts qu'elle avait de points de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "Boule de feu", Language.French);
            RegisterAbility("Fireball", "Boule de feu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to take 2 damage.", "Choisissez une carte qui subira 2 points de dégâts.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold to the Touch", "Toucher glacial", Language.French);
            RegisterAbility("Cold to the Touch", "Toucher glacial");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigils attack another card, that card will lose 1 attack.", "Lorsqu'une carte ornée de cet emblème attaque une autre carte, cette dernière perd 1 point de puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen", "Gelé", Language.French);
            RegisterAbility("Frozen", "Gelé");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, this card will lose its frozen health. When all frozen health is depleted, or this card is struck, it will defrost.", "À la fin de chaque tour, cette carte perd sa santé gelée. Lorsque toute sa santé gelée est épuisée, ou si cette carte est frappée, elle dégèle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Pull", "Traction puissante", Language.French);
            RegisterAbility("Strong Pull", "Traction puissante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every opposing card will be inclined to hit this card instead of any other.", "Chaque carte adverse aura tendance à frapper cette carte plutôt qu'une autre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Displacement", "Déplacement", Language.French);
            RegisterAbility("Displacement", "Déplacement");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, another of this card will be added randomly into your deck", "Lorsqu'une carte ornée de cet emblème est piochée, un autre exemplaire est ajouté à une position aléatoire de votre deck.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Reckoning", "Jugement des gemmes", Language.French);
            RegisterAbility("Gem Reckoning", "Jugement des gemmes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, if the owner of this card does not control any gems, the leftmost card in your hand is discarded.", "À la fin de chaque tour, si le propriétaire de cette carte ne contrôle aucune gemme, la carte la plus à gauche de votre main est défaussée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Power", "Puissance de mox", Language.French);
            RegisterAbility("Mox Power", "Puissance de mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "La valeur de cet emblème est égale au nombre de cartes mox que le propriétaire possède de son côté du plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Health", "Santé de mox", Language.French);
            RegisterAbility("Mox Health", "Santé de mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "La valeur de cet emblème est égale au nombre de cartes mox que le propriétaire possède de son côté du plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candle Proximity", "Proximité de la bougie", Language.French);
            RegisterAbility("Candle Proximity", "Proximité de la bougie");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to how close this card is to the Candle on the table.", "La valeur de cet emblème dépend de la proximité de cette carte avec la bougie sur la table.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Murder Power", "Puissance meurtrière", Language.French);
            RegisterAbility("Murder Power", "Puissance meurtrière");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal the total amount of power on the opponents board.", "La valeur de cet emblème est égale à la puissance totale du côté adverse du plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the total amount of power on your board.", "La valeur de cet emblème est égale à la moitié de la puissance totale de votre côté du plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Power", "Puissance des sorts", Language.French);
            RegisterAbility("Spell Power", "Puissance des sorts");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during this current dungeon.", "La valeur de cet emblème est égale au nombre total de sorts joués dans le donjon actuel.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during the battle.", "La valeur de cet emblème est égale au nombre total de sorts joués pendant ce combat.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counterbattery Power", "Puissance de riposte", Language.French);
            RegisterAbility("Counterbattery Power", "Puissance de riposte");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the amount of damage taken by you this battle, divided by two.", "La valeur de cet emblème est égale aux dégâts que vous avez subis pendant ce combat, divisés par deux.", Language.French);
            foreach (Ability ability in Enum.GetValues(typeof(Ability)))
            {
                var info = AbilitiesUtil.GetInfo(ability);
                if (info == null || info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的info，已跳过。");
                    continue;
                }
                if (info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的rulebookName，或本身已注册，已跳过。");
                    continue;
                }
                RegisterAbility(info.rulebookName, FrenchLanguagePack.Localize(info.rulebookName));
            }

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox", "mox", Language.French);
            RegisterCard("Mox", "mox", "its a me moxio", "C'est moi, Moxio !");
