            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Maniac", "Forcené d'émeraude", Language.French);
            RegisterCard("Emerald Maniac", "Forcené d'émeraude", "A crazed maniac.. Drawing out health from the mox..", "Un forcené dément... Qui puise sa santé dans les mox...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A crazed maniac.. Drawing out health from the mox..", "Un forcené dément... Qui puise sa santé dans les mox...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Daemon", "Démon de rubis", Language.French);
            RegisterCard("Ruby Daemon", "Démon de rubis", "If not properly sustained, it will destroy your hand to fuel itself..", "Faute d'être suffisamment nourrie, cette créature détruira ta main pour s'alimenter...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If not properly sustained, it will destroy your hand to fuel itself..", "Faute d'être suffisamment nourrie, cette créature détruira ta main pour s'alimenter...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Friend", "Ami des gemmes", Language.French);
            RegisterCard("Gem Friend", "Ami des gemmes", "fren", "pote");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "fren", "pote", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Druid", "Druide", Language.French);
            RegisterCard("Druid", "Druide", "Just look at what you've done..", "Regarde un peu ce que tu as fait...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just look at what you've done..", "Regarde un peu ce que tu as fait...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Legs", "Jambes enchaînées", Language.French);
            RegisterCard("Chained Legs", "Jambes enchaînées", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sealed Body", "Corps scellé", Language.French);
            RegisterCard("Sealed Body", "Corps scellé", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bound Arms", "Bras entravés", Language.French);
            RegisterCard("Bound Arms", "Bras entravés", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imprisoned Tyrant", "Tyran emprisonné", Language.French);
            RegisterCard("Imprisoned Tyrant", "Tyran emprisonné", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication mage", "Mage des matrices", Language.French);
            RegisterCard("Multiplication mage", "Mage des matrices", "This cycle can go on forever..", "Ce cycle peut se poursuivre éternellement...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cycle can go on forever..", "Ce cycle peut se poursuivre éternellement...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Invisible mage", "Mage invisible", Language.French);
            RegisterCard("Invisible mage", "Mage invisible", "It drank the wrong potion and ended up invisible. How clumsy.", "Ce mage a bu la mauvaise potion et s'est retrouvé invisible. Quelle maladresse.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It drank the wrong potion and ended up invisible. How clumsy.", "Ce mage a bu la mauvaise potion et s'est retrouvé invisible. Quelle maladresse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Sage", "Sage de cristal", Language.French);
            RegisterCard("Crystal Sage", "Sage de cristal", "A young scholar, profoundly studying mana crystals.", "Un jeune érudit qui étudie en profondeur les cristaux de mana.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A young scholar, profoundly studying mana crystals.", "Un jeune érudit qui étudie en profondeur les cristaux de mana.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Guardian", "Garde-gemme", Language.French);
            RegisterCard("Gem Guardian", "Garde-gemme", "The inverse of the Gem Detonator, this one seeks to protect all mox.", "À l'inverse du Détonateur de gemmes, celui-ci cherche à protéger tous les mox.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The inverse of the Gem Detonator, this one seeks to protect all mox.", "À l'inverse du Détonateur de gemmes, celui-ci cherche à protéger tous les mox.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembound Ripper", "Gemmo-éventreur", Language.French);
            RegisterCard("Gembound Ripper", "Gemmo-éventreur", "It is unstable, but such is the price for unending power.", "Cette créature est instable, mais tel est le prix d'une puissance sans fin.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is unstable, but such is the price for unending power.", "Cette créature est instable, mais tel est le prix d'une puissance sans fin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "Dévoreur de gemmes", Language.French);
            RegisterCard("Gem Absorber", "Dévoreur de gemmes", "It seeks out to consume all mana within Mox to grow stronger.", "Cette créature cherche à dévorer tout le mana des mox pour devenir plus puissante.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seeks out to consume all mana within Mox to grow stronger.", "Cette créature cherche à dévorer tout le mana des mox pour devenir plus puissante.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemagus", "Squelette-mage", Language.French);
            RegisterCard("Skelemagus", "Squelette-mage", "Great power for a few, fleeting moments..", "Une grande puissance, pour quelques instants fugaces...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great power for a few, fleeting moments..", "Une grande puissance, pour quelques instants fugaces...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelesage", "Sage squelettique", Language.French);
            RegisterCard("Skelesage", "Sage squelettique", "One of my own Junior Sages, lost and revived.", "L'un de mes Jeunes sages, perdu puis ressuscité.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of my own Junior Sages, lost and revived.", "L'un de mes Jeunes sages, perdu puis ressuscité.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic Scholar", "Érudit agité", Language.French);
            RegisterCard("Erratic Scholar", "Érudit agité", "A panicked scholar.. Always running from its problems..", "Un érudit paniqué... Qui fuit toujours ses problèmes...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A panicked scholar.. Always running from its problems..", "Un érudit paniqué... Qui fuit toujours ses problèmes...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Mage", "Mage des mox", Language.French);
            RegisterCard("Mox Mage", "Mage des mox", "A Mox disguised as a mage.. It's not going to fool anyone.", "Un mox déguisé en mage... Il ne trompera personne.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Mox disguised as a mage.. It's not going to fool anyone.", "Un mox déguisé en mage... Il ne trompera personne.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aurumtact", "Orfèvre transmuteur", Language.French);
            RegisterCard("Aurumtact", "Orfèvre transmuteur", "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "Un vieil érudit, maudit pour sa cupidité, qui enferme tout ce qu'il touche dans l'or pur.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "Un vieil érudit, maudit pour sa cupidité, qui enferme tout ce qu'il touche dans l'or pur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Mox", "Mox enchaîné", Language.French);
            RegisterCard("Chained Mox", "Mox enchaîné", "A collection of 3 moxen, tangled together, combining their mana energy.", "Un ensemble de 3 mox enchevêtrés, qui combinent leur énergie de mana.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of 3 moxen, tangled together, combining their mana energy.", "Un ensemble de 3 mox enchevêtrés, qui combinent leur énergie de mana.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maux", "Maux", Language.French);
            RegisterCard("Maux", "Maux", "In all my years, I have NEVER seen an imitation cruder than this.", "De toute ma vie, je n'ai JAMAIS vu d'imitation plus grossière.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In all my years, I have NEVER seen an imitation cruder than this.", "De toute ma vie, je n'ai JAMAIS vu d'imitation plus grossière.", Language.French);
            RegisterCard("Stim Mage", "Stimumage", "It strives to grow stronger, disregarding its own wellbeing..", "Cette créature cherche à devenir plus puissante, au mépris de sa propre santé...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It strives to grow stronger, disregarding its own wellbeing..", "Cette créature cherche à devenir plus puissante, au mépris de sa propre santé...", Language.French);
            RegisterCard("Gourmage", "Gourmage", "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "Une mage gloutonne qui dévore les cadavres de tes morts pour devenir plus puissante... Répugnant.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "Une mage gloutonne qui dévore les cadavres de tes morts pour devenir plus puissante... Répugnant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunce", "Mage benêt", Language.French);
            RegisterCard("Dunce", "Mage benêt", "This one can never seem to hit its target..", "Ce mage ne semble jamais toucher sa cible...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to hit its target..", "Ce mage ne semble jamais toucher sa cible...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grootslang", "Grootslang", Language.French);
            RegisterCard("Grootslang", "Grootslang", "The mere graze of its fangs is enough to kill any creature. No matter the size.", "Le simple frôlement de ses crocs suffit à tuer n'importe quelle créature, quelle que soit sa taille.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mere graze of its fangs is enough to kill any creature. No matter the size.", "Le simple frôlement de ses crocs suffit à tuer n'importe quelle créature, quelle que soit sa taille.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bookworm", "Rat de bibliothèque", Language.French);
            RegisterCard("Bookworm", "Rat de bibliothèque", "A rare kind of insect that absorbs knowledge out of books.", "Une espèce rare d'insecte qui absorbe le savoir contenu dans les livres.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rare kind of insect that absorbs knowledge out of books.", "Une espèce rare d'insecte qui absorbe le savoir contenu dans les livres.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemist", "Alchimiste", Language.French);
            RegisterCard("Alchemist", "Alchimiste", "A supporting one. It brews potions to empower your cards.", "Une créature de soutien qui prépare des potions pour renforcer tes cartes.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A supporting one. It brews potions to empower your cards.", "Une créature de soutien qui prépare des potions pour renforcer tes cartes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Mage", "Mage carillonneur", Language.French);
            RegisterCard("Chime Mage", "Mage carillonneur", "Its chime can prove to be quite annoying..", "Son carillon peut s'avérer très agaçant...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its chime can prove to be quite annoying..", "Son carillon peut s'avérer très agaçant...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revivor", "Ressuscité", Language.French);
            RegisterCard("Revivor", "Ressuscité", "It brings a mage back from the dead, at the cost of its own health.", "Cette créature ramène un mage d'entre les morts au prix de sa propre santé.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It brings a mage back from the dead, at the cost of its own health.", "Cette créature ramène un mage d'entre les morts au prix de sa propre santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune Mage", "Mage des runes", Language.French);
            RegisterCard("Rune Mage", "Mage des runes", "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "Cette créature invoque des runes explosives à ses côtés lors de son invocation. Ce n'est pas une bonne idée, je dois dire.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "Cette créature invoque des runes explosives à ses côtés lors de son invocation. Ce n'est pas une bonne idée, je dois dire.", Language.French);
            RegisterCard("--~~--~~--", "--~~--~~--", "So it arrives.", "Ainsi, cette créature arrive.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So it arrives.", "Ainsi, cette créature arrive.", Language.French);
            RegisterCard("~-~-~-~-~-~", "~-~-~-~-~-~", "I foresaw its arrival.", "J'avais prévu son arrivée.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I foresaw its arrival.", "J'avais prévu son arrivée.", Language.French);
            RegisterCard("~~--~~--~~", "~~--~~--~~", "At last, it is here.", "Enfin, cette créature est là.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At last, it is here.", "Enfin, cette créature est là.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Sage", "Sage tireur d'élite", Language.French);
            RegisterCard("Sniper Sage", "Sage tireur d'élite", "A mage whose training allows it to cast spells from afar.", "Un mage dont l'entraînement lui permet de lancer des sorts de loin.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage whose training allows it to cast spells from afar.", "Un mage dont l'entraînement lui permet de lancer des sorts de loin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune", "Rune", Language.French);
            RegisterCard("Rune", "Rune", "This is the last call, for alcohol.", "Dernière tournée pour les boissons alcoolisées.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "Dernière tournée pour les boissons alcoolisées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame", "Flamme magique", Language.French);
            RegisterCard("Flame", "Flamme magique", "This is the last call, for alcohol.", "Dernière tournée pour les boissons alcoolisées.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "Dernière tournée pour les boissons alcoolisées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbit", "Lapin", Language.French);
            RegisterCard("Rabbit", "Lapin", "This is the last call, for alcohol.", "Dernière tournée pour les boissons alcoolisées.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "Dernière tournée pour les boissons alcoolisées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for booze.", "Dernière tournée pour la picole.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for ale.", "Dernière tournée pour la bière.", Language.French);
            RegisterCard("Master Goranj", "Maître Vorange", "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "L'imposant Maître Vorange. Un lanceur de magie redoutable, mais aussi d'une posture inébranlable.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "L'imposant Maître Vorange. Un lanceur de magie redoutable, mais aussi d'une posture inébranlable.", Language.French);
            RegisterCard("Master Bleene", "Maître Blert", "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "L'altruiste Maître Blert. Il te viendra en aide dans les moments les plus difficiles... Au prix de sa propre capacité à se défendre. Admirable.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "L'altruiste Maître Blert. Il te viendra en aide dans les moments les plus difficiles... Au prix de sa propre capacité à se défendre. Admirable.", Language.French);
            RegisterCard("Master Orlu", "Maître Oreu", "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "Le grand Maître Oreu plane sur ses ailes pâles, attaque d'en haut et attire les cartes d'en bas...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "Le grand Maître Oreu plane sur ses ailes pâles, attaque d'en haut et attire les cartes d'en bas...", Language.French);
            RegisterCard("Master Magnus", "Maître suprême", "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "Mon nom, c'est... Shake-Zula ! Le roi du micro ! De la vieille école ! Tu cherches les ennuis ? Je te les apporte...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "Mon nom, c'est... Shake-Zula ! Le roi du micro ! De la vieille école ! Tu cherches les ennuis ? Je te les apporte...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Magnus", "Maître suprême", Language.French);
            RegisterCard("Master Magnus", "Maître suprême", "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "Frylock, ouais, je suis au sommet, je te secoue comme un flic. Meatwad, à ton tour, balance ton toc-toc !");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "Frylock, ouais, je suis au sommet, je te secoue comme un flic. Meatwad, à ton tour, balance ton toc-toc !", Language.French);
            RegisterCard("Master Magnus", "Maître suprême", "Meatwad get the money, see. Meatwad get the honeys, G. ", "Meatwad ramasse les billets, tu vois. Meatwad séduit les filles, mon gars. ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meatwad get the money, see. Meatwad get the honeys, G. ", "Meatwad ramasse les billets, tu vois. Meatwad séduit les filles, mon gars. ", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phoenix", "Phénix", Language.French);
            RegisterCard("Phoenix", "Phénix", "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "Un oiseau majestueux, qui aurait été complice de Maître Oreu...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "Un oiseau majestueux, qui aurait été complice de Maître Oreu...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleenehound", "Limier de Blert", Language.French);
            RegisterCard("Bleenehound", "Limier de Blert", "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "Un canidé dévoué, qui aurait été le fidèle compagnon de Maître Blert.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "Un canidé dévoué, qui aurait été le fidèle compagnon de Maître Blert.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemy 101", "Initiation à l'alchimie", Language.French);
            RegisterCard("Alchemy 101", "Initiation à l'alchimie", "[c:g2]Alchemy 101[c:]\n[c:g3]I[c:] [c:g1]never[c:] [c:g3]was[c:] [c:g1]that[c:] [c:g3]great[c:] [c:g1]at[c:] [c:g3]alchemy..[c:]", "[c:g2]Initiation à l'alchimie[c:]\n[c:g3]Je[c:] [c:g1]n'ai[c:] [c:g3]jamais[c:] [c:g1]été[c:] [c:g3]très[c:] [c:g1]doué en[c:] [c:g3]alchimie...[c:]");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]Alchemy 101[c:]\n[c:g3]I[c:] [c:g1]never[c:] [c:g3]was[c:] [c:g1]that[c:] [c:g3]great[c:] [c:g1]at[c:] [c:g3]alchemy..[c:]", "[c:g2]Initiation à l'alchimie[c:]\n[c:g3]Je[c:] [c:g1]n'ai[c:] [c:g3]jamais[c:] [c:g1]été[c:] [c:g3]très[c:] [c:g1]doué en[c:] [c:g3]alchimie...[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guide to Attack", "Guide d'attaque", Language.French);
            RegisterCard("Guide to Attack", "Guide d'attaque", "[c:g2]Guide to Attack[c:]\n[c:g3]One[c:] [c:g1]of[c:] [c:g3]the[c:] [c:g1]first[c:] [c:g3]books[c:] [c:g1]I[c:] [c:g3]ever[c:] [c:g1]read.[c:]", "[c:g2]Guide d'attaque[c:]\n[c:g3]L'un[c:] [c:g1]des[c:] [c:g3]tout[c:] [c:g1]premiers[c:] [c:g3]livres[c:] [c:g1]que j'aie[c:] [c:g3]jamais[c:] [c:g1]lus.[c:]");
