            RegisterCard("Scarecrow Twins", "Épouvantails jumeaux", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stim Sage", "Stimusage", Language.French);
