            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jealous Witch", "Sorcière jalouse", Language.French);
            MagnificusMod.RegisterCard("Jealous Witch", "Sorcière jalouse", "The witch in charge of jealousy has powerful magic and power.", "La sorcière qui règne sur la jalousie possède une magie et une force redoutables.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of jealousy has powerful magic and power.", "La sorcière qui règne sur la jalousie possède une magie et une force redoutables.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Witch", "Sorcière paresseuse", Language.French);
            MagnificusMod.RegisterCard("Lazy Witch", "Sorcière paresseuse", "The witch in charge of the power of laziness is really a lazy guy.", "La sorcière qui maîtrise le pouvoir de la paresse est vraiment une grande paresseuse.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of the power of laziness is really a lazy guy.", "La sorcière qui maîtrise le pouvoir de la paresse est vraiment une grande paresseuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lust Witch", "Sorcière de la luxure", Language.French);
            MagnificusMod.RegisterCard("Lust Witch", "Sorcière de la luxure", "The witch in charge of lust, don't look into her eyes.", "La sorcière qui règne sur la luxure… Ne la regarde pas dans les yeux.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of lust, don't look into her eyes.", "La sorcière qui règne sur la luxure… Ne la regarde pas dans les yeux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nine Color Deer", "Cerf aux neuf couleurs", Language.French);
            MagnificusMod.RegisterCard("Nine Color Deer", "Cerf aux neuf couleurs", "The colorful nine color deer has precious value.", "Le chatoyant cerf aux neuf couleurs est d'une valeur inestimable.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colorful nine color deer has precious value.", "Le chatoyant cerf aux neuf couleurs est d'une valeur inestimable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky MagiChiking", "Poulet magique pestilentiel", Language.French);
            MagnificusMod.RegisterCard("Stinky MagiChiking", "Poulet magique pestilentiel", "Hatched by magic eggs.", "Issu d'un œuf magique.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hatched by magic eggs.", "Issu d'un œuf magique.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Maniac", "Maniaque des bombes", Language.French);
            MagnificusMod.RegisterCard("Bomb Maniac", "Maniaque des bombes", "Even if it detonates itself, it never surrenders to others.", "Même au prix de sa propre explosion, il ne se rendra jamais.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if it detonates itself, it never surrenders to others.", "Même au prix de sa propre explosion, il ne se rendra jamais.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earl Bunny", "Comte Lapin", Language.French);
            MagnificusMod.RegisterCard("Earl Bunny", "Comte Lapin", "The versatile Earl Bunny, not everyone can comprehend this art.", "Le talentueux Comte Lapin… Tout le monde n'est pas capable de comprendre cet art.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The versatile Earl Bunny, not everyone can comprehend this art.", "Le talentueux Comte Lapin… Tout le monde n'est pas capable de comprendre cet art.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chinese Loong", "Dragon chinois", Language.French);
            MagnificusMod.RegisterCard("Chinese Loong", "Dragon chinois", "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "Quand le dragon plonge dans les abysses, les quatre mers s'apaisent ; quand il s'envole, il veille sur toute chose. Son voyage sur des milliers de lieues est partout un présage de bonheur.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "Quand le dragon plonge dans les abysses, les quatre mers s'apaisent ; quand il s'envole, il veille sur toute chose. Son voyage sur des milliers de lieues est partout un présage de bonheur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "Sorcier du fromage", Language.French);
            MagnificusMod.RegisterCard("Cheese Wizard", "Sorcier du fromage", "A humorous wizard who is proficient in cooking, his cheese has magical power.", "Un sorcier plein d'humour et fin cuisinier, dont le fromage possède des pouvoirs magiques.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A humorous wizard who is proficient in cooking, his cheese has magical power.", "Un sorcier plein d'humour et fin cuisinier, dont le fromage possède des pouvoirs magiques.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Golem", "Golem de givre", Language.French);
            MagnificusMod.RegisterCard("Frost Golem", "Golem de givre", "Once on the field, there is a strong sense of oppression.", "Dès son arrivée sur le plateau, sa présence devient écrasante.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once on the field, there is a strong sense of oppression.", "Dès son arrivée sur le plateau, sa présence devient écrasante.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "Mage du baseball", Language.French);
            MagnificusMod.RegisterCard("Baseball Mage", "Mage du baseball", "His soul is bound under sportswear and can never be liberated.", "Son âme est prisonnière de ses vêtements de sport et ne pourra jamais se libérer.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His soul is bound under sportswear and can never be liberated.", "Son âme est prisonnière de ses vêtements de sport et ne pourra jamais se libérer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raid Mage", "Mage d'assaut", Language.French);
            MagnificusMod.RegisterCard("Raid Mage", "Mage d'assaut", "You will understand how terrifying it is for a robber to master magic.", "Tu comprendras combien un brigand qui maîtrise la magie peut être terrifiant.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will understand how terrifying it is for a robber to master magic.", "Tu comprendras combien un brigand qui maîtrise la magie peut être terrifiant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jade Turtle", "Tortue de jade", Language.French);
            MagnificusMod.RegisterCard("Jade Turtle", "Tortue de jade", "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "Une tortue couverte d'émeraudes de la tête aux pieds… Je m'émerveille qu'une telle peinture puisse exister.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "Une tortue couverte d'émeraudes de la tête aux pieds… Je m'émerveille qu'une telle peinture puisse exister.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Cheese", "Fromage magique", Language.French);
            MagnificusMod.RegisterCard("Magic Cheese", "Fromage magique", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scarlet Cuckoo", "Coucou écarlate", Language.French);
            MagnificusMod.RegisterCard("Scarlet Cuckoo", "Coucou écarlate", "The success or failure of the angry magic bird often depends on its face.", "Cet oiseau magique en colère fait souvent dépendre ta réussite ou ton échec de son humeur.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The success or failure of the angry magic bird often depends on its face.", "Cet oiseau magique en colère fait souvent dépendre ta réussite ou ton échec de son humeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear Apprentice", "Apprenti lancier", Language.French);
            MagnificusMod.RegisterCard("Spear Apprentice", "Apprenti lancier", "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "Les apprentis des mages lanciers… Les plus avisés gardent toujours un plan de secours.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "Les apprentis des mages lanciers… Les plus avisés gardent toujours un plan de secours.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Eye of Darkness", "L'Œil des ténèbres", Language.French);
            MagnificusMod.RegisterCard("The Eye of Darkness", "L'Œil des ténèbres", "This precious pearl was once the devil's eye.", "Cette précieuse perle était autrefois l'œil du diable.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This precious pearl was once the devil's eye.", "Cette précieuse perle était autrefois l'œil du diable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forest Spell", "Sort forestier", Language.French);
            MagnificusMod.RegisterCard("Forest Spell", "Sort forestier", "The forest spell obtained from Leshy can provide the most primitive defense.", "Le sort forestier obtenu auprès de Leshy offre la plus primitive des protections.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The forest spell obtained from Leshy can provide the most primitive defense.", "Le sort forestier obtenu auprès de Leshy offre la plus primitive des protections.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MoxShield", "Bouclier mox", Language.French);
            MagnificusMod.RegisterCard("MoxShield", "Bouclier mox", "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "Ce bouclier magique serti de gemmes rassure toujours par sa seule présence.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "Ce bouclier magique serti de gemmes rassure toujours par sa seule présence.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nebula Storm", "Tempête nébuleuse", Language.French);
            MagnificusMod.RegisterCard("Nebula Storm", "Tempête nébuleuse", "This cruel storm can directly take away an enemy.", "Cette tempête impitoyable peut emporter un ennemi d'un seul coup.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cruel storm can directly take away an enemy.", "Cette tempête impitoyable peut emporter un ennemi d'un seul coup.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Contract", "Contrat d'âme", Language.French);
            MagnificusMod.RegisterCard("Soul Contract", "Contrat d'âme", "Perhaps you need more card assistance, and a soul contract is a great choice.", "Tu as peut-être besoin de cartes supplémentaires pour t'aider. Un contrat d'âme serait un excellent choix.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you need more card assistance, and a soul contract is a great choice.", "Tu as peut-être besoin de cartes supplémentaires pour t'aider. Un contrat d'âme serait un excellent choix.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wailing Wall", "Mur des lamentations", Language.French);
            MagnificusMod.RegisterCard("Wailing Wall", "Mur des lamentations", "Such perseverance even moves the thorny walls to weep.", "Une telle persévérance émeut jusqu'aux murs d'épines, qui se mettent à pleurer.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such perseverance even moves the thorny walls to weep.", "Une telle persévérance émeut jusqu'aux murs d'épines, qui se mettent à pleurer.", Language.French);
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Time", "Pause café", Language.French);
            MagnificusMod.RegisterAbility("Coffee Time", "Pause café");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] receives the first damage, it gains 2 strength.", "La première fois que la carte [creature] subit des dégâts, elle gagne 2 points de puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Arrogance", "Mort de l'orgueil", Language.French);
            MagnificusMod.RegisterAbility("Death of Arrogance", "Mort de l'orgueil");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 2 power.", "Quand la carte [creature] meurt, les cartes adjacentes gagnent 2 points de puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Greed", "Mort de l'avidité", Language.French);
            MagnificusMod.RegisterAbility("Death of Greed", "Mort de l'avidité");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 3 health.", "Quand la carte [creature] meurt, les cartes adjacentes gagnent 3 points de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Made", "Création divine", Language.French);
            MagnificusMod.RegisterAbility("God Made", "Création divine");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Homunculus is created on each empty adjacent space. The Homunculus has : 1 power, 1 health, Familiar.", "Quand la carte [creature] est jouée, un Homoncule est créé sur chaque emplacement adjacent vide. L'Homoncule possède : 1 point de puissance, 1 point de santé, Familier.", Language.French);
            MagnificusMod.RegisterAbility("Fir Caller", "Appel des sapins");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the empty slot on the cardholder's side is filled with Great Firs. Great Fir has: 0 Power, 3 Health, Mighty Leap.", "Quand la carte [creature] meurt, les emplacements vides du côté de son propriétaire sont remplis de Grands sapins. Le Grand sapin possède : 0 point de puissance, 3 points de santé, Bond prodigieux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering Taste", "Saveur persistante", Language.French);
            MagnificusMod.RegisterAbility("Lingering Taste", "Saveur persistante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 1 health.", "Quand la carte [creature] meurt, les cartes adjacentes gagnent 1 point de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love of Cheese", "Amour du fromage", Language.French);
            MagnificusMod.RegisterAbility("Love of Cheese", "Amour du fromage");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw a cheese card, cheese has: 0 power, 2 health,Lingering Taste.", "Quand la carte [creature] est jouée, piochez une carte Fromage magique. Le Fromage magique possède : 0 point de puissance, 2 points de santé, Saveur persistante.", Language.French);
            // Other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Expansion", "Extension magique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here comes the card of the fantasy world! More content will be added in the future!", "Voici les cartes du monde fantastique ! Davantage de contenu sera ajouté à l'avenir !", Language.French);
        }
    }
