            // Consumable
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please! You've got to help me get out of here!", "Je vous en prie ! Aidez-moi à sortir d'ici !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you! I hope he doesn't notice me here...", "Merci ! J'espère qu'il ne me remarque pas ici...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you!", "Merci !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So much power, but so much pain...", "Tant de puissance, mais tant de douleur...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good riddance to that little freak.", "Bon débarras, ce petit monstre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goobert", "Goobert", Language.French);
            RegisterConsumable("Goobert", "Goobert");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please! You've got to help me get out of here!", "Je vous en prie ! Aidez-moi à sortir d'ici !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Data Cube", "Cube de données", Language.French);
            RegisterConsumable("Data Cube", "Cube de données");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can be placed on the scales for some damage, if you're into that sort of thing.", "Peut être placé sur la balance pour infliger quelques dégâts, si ça vous tente.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Laser Rifle", "Fusil laser", Language.French);
            RegisterConsumable("Laser Rifle", "Fusil laser");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will give one of your cards the Sniper sigil for the rest of the battle. It's a gun - what else do you want?", "Donne à l'une de vos cartes l'emblème Sniper pour le reste du combat. C'est un fusil : qu'est-ce qu'il vous faut de plus ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amplification Coil", "Bobine d'amplification", Language.French);
            RegisterConsumable("Amplification Coil", "Bobine d'amplification");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Increases your max energy by 2. I suppose you can find some use for this.", "Augmente votre énergie maximale de 2. Vous trouverez sûrement quoi en faire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UFO", "OVNI", Language.French);
            RegisterConsumable("UFO", "OVNI");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abducts a card of your choice. It gets the job done I suppose", "Enlève une carte de votre choix. Ça fait l'affaire, j'imagine.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wiseclock", "Chronospirale", Language.French);
            RegisterConsumable("Wiseclock", "Chronospirale");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It rotates the board clockwise or something. I stole it from Leshy. Do you think he'll notice?", "Ça fait tourner le plateau dans le sens horaire, ou un truc comme ça. Je l'ai volé à Leshy. Vous croyez qu'il va s'en apercevoir ?", Language.French);

            // Rule
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I play a Mr:Clock", "Je joue Monsieur:Horloge", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a random card becomes a fish", "une carte aléatoire devient un poisson", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1 of your lanes catches fire", "1 de vos voies prend feu", Language.French);

            // Mode
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Traps", "Pièges", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems there are some [c:bR]traps[c:] here", "On dirait qu'il y a des [c:bR]pièges[c:] ici", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your bots will have to fight past them to get to me", "Vos robots vont devoir les affronter pour arriver jusqu'à moi", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Rule", "Règle aléatoire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For this battle, I'm going to add an additional rule.", "Pour ce combat, je vais ajouter une règle supplémentaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conveyor", "Convoyeur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears someone activated the [c:bR]conveyor belt[c:]", "On dirait que quelqu'un a activé le [c:bR]convoyeur[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards will rotate clockwise every turn", "Les cartes tournent dans le sens horaire à chaque tour", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosive", "Explosif", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm; it looks like the cards in this battle will [c:bR]explode[c:] when they die", "Hum, on dirait que les cartes de ce combat vont [c:bR]exploser[c:] quand elles mourront", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That seems dangerous", "Ça a l'air dangereux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stickers", "Autocollants", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "See those [c:bR]stickers[c:]? They give my cards extra abilities.", "Vous voyez ces [c:bR]autocollants[c:] ? Ils donnent des capacités supplémentaires à mes cartes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't mind an extra challenge, do you?", "Un défi de plus ne vous dérange pas, j'espère ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Missiles", "Missiles", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, there appears to be a malfunctioning missile launcher here", "Oh, il semble y avoir un lance-missiles défectueux ici", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for rogue missile strikes I guess", "Attention aux missiles perdus, je suppose", Language.French);

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Boss", "Nouveau boss final", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Description for the Final Boss challenge", "Description du défi Boss final", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Missing Remote", "Télécommande manquante", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not start with Mrs. Bomb's Remote", "Vous ne commencez plus avec la télécommande de Mme Bombe", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turbo Vessels", "Récipients turbo", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your vessels have the Double Sprinter sigil.", "Vos récipients possèdent l'emblème Double sprint.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Bridges", "Ponts brisés", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only two regions are available at the start of each run", "Seules deux régions sont accessibles au début de chaque aventure", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pricey Upgrades", "Améliorations coûteuses", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All upgrades cost more", "Toutes les améliorations coûtent plus cher", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eccentric Painter", "Peintre excentrique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All bosses start with a random canvas rule.", "Tous les boss commencent avec une règle de toile aléatoire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Hammer", "Marteau énergétique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hammer now costs 2 energy to use", "L'utilisation du marteau coûte désormais 2 énergies", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Costly Respawn", "Réapparition coûteuse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cost for additional respawns is tripled", "Le coût des réapparitions supplémentaires est triplé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaping Side Deck", "Deck secondaire bondissant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replace your Empty Vessels with L33pbots.", "Remplacez vos Récipients vides par des R0b0saut3relles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wanted Fugitive", "Fugitif recherché", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your bounty level is permanently increased by 2", "Votre niveau de prime augmente définitivement de 2", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strange Encounters", "Rencontres étranges", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Some battles on each map will have additional effects", "Certains combats de chaque carte comportent des effets supplémentaires", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Great Transcendence", "grande transcendance", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlock the secrets of the Great Transcendence", "Découvrez les secrets de la grande transcendance", Language.French);

            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ENTER NAME HERE", "SAISISSEZ VOTRE NOM ICI", Language.French);
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Redraw: $" + count.ToString(), "Nouvelle pioche : $" + count.ToString(), Language.French);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sell Token: " + count.ToString() + " Robobucks", "Vendre le jeton : " + count.ToString() + " " + (count == 1 ? "robopièce" : "robopièces"), Language.French);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reset: $1", "Réinitialiser : $1", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PRINT", "IMPRIMER", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RECALL", "RAPPEL", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TKN", "TKN", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TKN++", "TKN++", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RARE", "RARE", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RARE++", "RARE++", Language.French);

            // Achievement
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "P03 In Kaycee's Mod", "P03 dans le mod de Kaycee", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uber Apocalypse", "Apocalypse suprême", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beat \"P03 in Kaycee's Mod\" for the first time", "Terminez « P03 dans le mod de Kaycee » pour la première fois", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scarlet Skull", "Crâne écarlate", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win a run with every challenge skull from the first page enabled", "Gagnez une aventure avec tous les crânes de défi de la première page activés", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avatar", "Avatar", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take ownership of one of G0lly's beloved trinkets", "Emparez-vous d'un des bibelots favoris de G0lly", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Book of the Dead", "Livre des morts", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "During The Archivist's boss fight, survive 6 turns during phase 2", "Survivez 6 tours pendant la phase 2 du combat contre l'Archiviste", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feral Spirit", "Esprit sauvage", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the Photographer without using the camera", "Battez le Photographe sans utiliser l'appareil photo", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gallery Showcase", "Exposition en galerie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Create an infinite loop in the Unfinished Boss fight", "Créez une boucle infinie pendant le combat contre le Boss inachevé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Battle Frenzy", "Fureur du combat", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Destroy 30 Bounty Hunters in your lifetime", "Détruisez 30 chasseurs de primes au total", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calling for Backup", "Appel de renforts", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete all NPC quests that appear in a single run", "Terminez toutes les quêtes de PNJ qui apparaissent au cours d'une même aventure", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Accelerated Fuse", "Mèche accélérée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleclock and destroy a card given to you by an NPC", "Appliquez l'Overclocking squelettique à une carte donnée par un PNJ, puis détruisez-la", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Blink", "Saut de mana", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have six energy available on turn two", "Ayez six énergies disponibles au deuxième tour", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aimless Assault", "Assaut à l'aveugle", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earn 15 Robobucks in a single battle", "Gagnez 15 robopièces en un seul combat", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rebuild From Scrap", "Reconstruction de ferraille", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a card in your deck that is gemified, skeleclocked, transformable, and can complete a circuit", "Ayez dans votre deck une carte sertie de gemmes, dotée de l'Overclocking squelettique, capable de se transformer et de compléter un circuit", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buy Your Buddy", "Achetez votre ami", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give a card with the maximum amount of SP to the Bot Builder", "Donnez au constructeur de robots une carte ayant le maximum de SP", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Me Smash", "Moi cogner", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strike P03 six separate times in a single turn", "Frappez J03 six fois distinctes en un seul tour", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Absolution", "Absolution", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have the scales tilted 4 points against you on three different turns", "Faites pencher la balance de 4 points contre vous pendant trois tours différents", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Perfect Crime", "Le crime parfait", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win five battles with bounty hunters without killing them", "Gagnez cinq combats avec des chasseurs de primes sans les tuer", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blastenheimer 5000 Ultra Cannon", "Canon ultra Blastenheimer 5000", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deal 6 damage with Plasma Jimmy in a single turn", "Infligez 6 dégâts avec Fusil à plasma en un seul tour", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Time", "Vitesse double", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleclock every card in your deck", "Appliquez l'Overclocking squelettique à toutes les cartes de votre deck", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One And The Same", "Une seule et même chose", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete the Mycologist's experiment and create an abomination of science", "Terminez l'expérience des mycologues et créez une abomination scientifique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Adrenaline", "Adrénaline brûlante", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repair the generator in four turns or less", "Réparez le générateur en quatre tours ou moins", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnival Clown", "Clown de fête foraine", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Achieve a high score of 50 or more on the test of strength", "Atteignez un score de 50 ou plus à l'épreuve de force", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Verse Riff", "Rimes du multivers", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Understand the true meaning of the Great Transcendence", "Comprenez le véritable sens de la grande transcendance", Language.French);

            // Starter
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vanilla", "De base", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb", "Bombe", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shield", "Bouclier", Language.French);
