            P03InKayceesModMod.RegisterCardPart("Gourmage", "Gourmage");
            P03InKayceesModMod.RegisterCardPart("Master", "Maître");
            P03InKayceesModMod.RegisterCardPart("Magnus", "Suprême");
            P03InKayceesModMod.RegisterCardPart("Practice", "D'entraînement");
            P03InKayceesModMod.RegisterCardPart("Stim", "Stimu");

            foreach (var value in P03InKayceesModMod.Cards)
            {
                string name;
                string nameLoc;
                if (value.Key != null && value.Key.ToLowerInvariant().Contains("skel-e"))
                {
                    name = "Skel-E-" + value.Key.Replace(" ", "-");
                    nameLoc = value.Value + " (squelette)";
                }
                else
                {
                    name = "Skele " + value.Key;
                    nameLoc = value.Value + " (exosquelette)";
                }
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, nameLoc, Language.French);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beta " + value.Key, value.Value + " (bêta)", Language.French);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser " + value.Key, value.Value + " (forme juvénile)", Language.French);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder " + value.Key, value.Value + " (forme ancestrale)", Language.French);
                for (int score = 0; score <= 100; score++)
                {
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, value.Key + " " + score.ToString() + ".0", value.Value + " " + score.ToString() + ".0", Language.French);
                }
                //string[] array = value.Key.Split(new char[] { ' ', '-' });
                //Debug.Log(((array.Length > 1) ? (array[0].ToLowerInvariant().Contains("gem") ? array[1] : array[0]) : (value.Key.Contains("bot") ? value.Key.Replace("bot", "") : value.Key)) + ", " + value.Key + ", " + value.Value);
            }

            // DialogueEvent
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glug glug glug", "Glou glou glou", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We seem to have a [c:bR]tentacle[c:] problem", "On dirait que nous avons un problème de [c:bR]tentacules[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you want to help out, talk to me again.", "Si vous voulez nous aider, revenez me parler.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you for your help", "Merci pour votre aide", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are [c:bR]3[c:] tentacles that need to be destroyed.", "Il faut détruire [c:bR]3[c:] tentacules.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once you've done that, come talk to me again.", "Une fois que ce sera fait, revenez me parler.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glug glug glug", "Glou glou glou", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have killed [c:bR][v:0][c:] tentacles.", "Vous avez tué [c:bR][v:0][c:] tentacules.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "See me once you've killed them all.", "Revenez me voir quand vous les aurez tous tués.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glug glug glug", "Glou glou glou", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The scourge of the tentacles has been erased", "Le fléau des tentacules a été éradiqué", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please take this as a token of my gratitude.", "Veuillez accepter ceci en signe de gratitude.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WARNING! WARNING![c:]", "[c:bR]ATTENTION ! ATTENTION ![c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Unidentified flying objects[c:] have been spotted in the area", "Des [c:bR]objets volants non identifiés[c:] ont été repérés dans la région", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should leave [c:bR]immediately[c:] before they return.", "Vous devriez partir [c:bR]immédiatement[c:] avant leur retour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WARNING! WARNING![c:]", "[c:bR]ATTENTION ! ATTENTION ![c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]UFOs[c:] are arriving!", "Les [c:bR]OVNI[c:] arrivent !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]CONGRATULATIONS![c:]", "[c:bR]FÉLICITATIONS ![c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]UFOs[c:] have been defeated!", "Les [c:bR]OVNI[c:] ont été vaincus !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And they event left one behind!", "Et ils en ont même laissé un derrière eux !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]DISASTER! DISASTER![c:]", "[c:bR]CATASTROPHE ! CATASTROPHE ![c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]UFOs[c:] were victorious!", "Les [c:bR]OVNI[c:] ont remporté la victoire !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We may never recover from this failure!", "Nous ne nous remettrons peut-être jamais de cet échec !", Language.French);

            // DialogueState
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GLUG GLUG GLUG", "GLOU GLOU GLOU", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FIGHT THE TENTACLES", "COMBATTEZ LES TENTACULES", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FIGHT THE TENTACLES", "COMBATTEZ LES TENTACULES", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEATH TO THE TENTACLES", "MORT AUX TENTACULES", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WARNING!!!", "ATTENTION !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HERE THEY COME!!!", "LES VOILÀ !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONGRATULATIONS!!!", "FÉLICITATIONS !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DISASTER!!!", "CATASTROPHE !!!", Language.French);
        }
    }
