            Debug.Log("Registering Translations for EyeAndDagger Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dagger", "Dague spéciale", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grants the player a starting dagger instead of a pair of pliers", "Le joueur commence avec une dague spéciale au lieu d'une pince", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goat Eye", "Œil de chèvre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grants the goat eye effect.", "Confère l'effet de l'œil de chèvre.", Language.French);

        }
    }
