    public class CursesMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Curses Mod");
            // Ability/Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bitten By Predator", "Mordu par un prédateur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card was bitten by a predator", "Cette carte a été mordue par un prédateur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bow and Arrow", "Arc et flèches", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Capture", "Capture", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spike Trap", "Piège à pointes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mega Shark", "Requin géant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swallow Whole", "Avaler tout rond", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dynamite!?", "De la dynamite !?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Booby Trap", "Piège explosif", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If this is in your hand at the end of your turn, it explodes. If it is on the board at the end of your opponent's turn, it explodes. Either way, it explodes.", "Si cette carte est dans votre main à la fin de votre tour, elle explose. Si elle est sur le plateau à la fin du tour de votre adversaire, elle explose. Dans les deux cas, elle explose.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is more difficult than anticipated...", "C'est plus difficile que prévu...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We - We may have made things worse", "Nous… Nous avons peut-être empiré les choses", Language.French);

            // Achievement
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Achievements", "Succès maudits", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here For A Good Time", "Pour s'amuser", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete a run with a negative challenge level", "Terminez une aventure avec un niveau de défi négatif", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here For A Hard Time", "Pour en baver", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete a run with a challenge level above 250", "Terminez une aventure avec un niveau de défi supérieur à 250", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utter Insanity", "Pure folie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete a run with two Chaotic Enemy skulls active", "Terminez une aventure avec deux crânes « Ennemis chaotiques » actifs", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Too Spooky", "Trop effrayant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reach the maximum deathcard haunt level", "Atteignez le niveau maximal de hantise des cartes de mort", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's No Moon", "Ce n'est pas une lune", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the Limoncello with the Bigger Moon skull active", "Battez le Limoncello avec le crâne Pleine lune actif", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Tis But A Flesh Wound", "Ce n'est qu'une égratignure", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Retrieve a damaged card from the belly of a Mega Shark", "Récupérez une carte endommagée dans le ventre d'un requin géant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Munitions Expert", "Expert en munitions", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Safely dispose of a stick of dynamite", "Débarrassez-vous sans danger d'un bâton de dynamite", Language.French);


            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full Moon", "Pleine lune", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant cards like the moon have more attack and health", "Les cartes géantes comme la Lune ont plus d'attaque et de santé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minor Boon of the Bone Lord", "Bénédiction mineure du roi des os", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start the game with a Minor Boon of the Bone Lord", "Commencez la partie avec une bénédiction mineure du roi des os", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Checking to see if we should add a deathcard...", "Vérification de l'ajout éventuel d'une carte de mort...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunted Past", "Passé hanté", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathcards will sometimes attack you in battle", "Les cartes de mort vous attaqueront parfois au combat", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exploding Cards", "Cartes explosives", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dynamite is added to your deck after every boss battle", "De la dynamite est ajoutée à votre deck après chaque combat de boss", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Golden Beginnings", "Débuts dorés", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start the game with the ability to draft a rare card", "Commencez la partie en pouvant choisir une carte rare", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boss Revenge", "Revanche des boss", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each boss has an additional phase", "Chaque boss possède une phase supplémentaire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Two Turn Minimum", "Deux tours minimum", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You cannot deal lethal damage on the first turn.", "Vous ne pouvez pas infliger de dégâts mortels au premier tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaotic Enemies", "Ennemis chaotiques", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Opposing creatures gain random abilities", "Les créatures ennemies reçoivent des capacités aléatoires", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Totem Collector", "Collectionneur de totems", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You start with all tribal totem tops", "Vous commencez avec toutes les têtes de totem de tribu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Extra Candle", "Bougie supplémentaire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are given an extra life", "Vous recevez une vie supplémentaire", Language.French);

            // DialogueEvent
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you feel a chill in the air", "vous sentez un froid dans l'air", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the hair stands up on the back of your neck", "les poils de votre nuque se hérissent", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR][v:0][c:] has arrived", "[c:bR][v:0][c:] est arrivé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you suddenly feel weak", "vous vous sentez soudain faible", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "your teeth start to chatter", "vos dents commencent à claquer", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR][v:0][c:] is coming", "[c:bR][v:0][c:] approche", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you can't explain how", "vous ne pouvez pas expliquer comment", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "but you can feel the presence of [c:bR][v:0][c:]", "mais vous sentez la présence de [c:bR][v:0][c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it finally happened: [c:bR][v:0][c:] is here", "c'est enfin arrivé : [c:bR][v:0][c:] est là", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:O]\"I have been looking for you\"[c:] says the apparition", "[c:O]« Je vous cherchais »[c:], dit l'apparition", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:O]\"And now you must die!\"[c:]", "[c:O]« Et maintenant, vous devez mourir ! »[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the apparition has nothing to say", "l'apparition n'a rien à dire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "but you sense that it is here for you", "mais vous sentez qu'elle est venue pour vous", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:O]\"you made a mistake coming here\"[c:] it growls", "[c:O]« Vous avez fait une erreur en venant ici »[c:], grogne-t-elle", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:O]\"let me show you the way home\"[c:]", "[c:O]« Laissez-moi vous montrer le chemin du retour »[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the apparition seems lonely", "l'apparition semble seule", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it wants you to join it in the afterlife", "elle veut que vous la rejoigniez dans l'au-delà", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the apparition fades into the wind", "l'apparition se dissipe dans le vent", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you can't shake the feeling there are [c:O]more[c:] out there waiting", "vous ne pouvez chasser l'impression que d'[c:O]autres[c:] attendent là-bas", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR][v:0][c:] shivers with delight as your candle is extinguished", "[c:bR][v:0][c:] frémit de plaisir lorsque votre bougie s'éteint", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "do you see the [c:O]apparition[c:] encircling you?", "voyez-vous l'[c:O]apparition[c:] qui tourne autour de vous ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you have become [c:O]haunted[c:] by [c:O]those who have come before[c:]", "vous êtes [c:O]hanté[c:] par [c:O]ceux qui vous ont précédé[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the more you [c:O]win in battle[c:] the angrier they become", "plus vous [c:O]gagnez de combats[c:], plus leur colère grandit", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and they may [c:O]oppose you in battle[c:] in the future", "et ils pourraient [c:O]vous affronter au combat[c:] à l'avenir", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's play longer this time!", "Jouons plus longtemps cette fois !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A lil' more fun never hurt nobody!", "Un peu plus d'amusement n'a jamais fait de mal à personne !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I got a little somethin' special for ya!", "J'ai un petit quelque chose de spécial pour toi !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heeeeeeee-haaw! Let's keep the fun goin'!", "Yiiii-ha ! Continuons à nous amuser !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You want more fish?", "Vous voulez plus de poisson ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We get extra fish.", "On a plus de poisson.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Many fish this time.", "Beaucoup de poisson cette fois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm afraid our encounter today will take a little more time", "Je crains que notre rencontre d'aujourd'hui ne prenne un peu plus de temps", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It looks like you and I have extra business to attend to", "On dirait que vous et moi avons encore des affaires à régler", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He swalled it whole..", "Il l'a avalé tout rond...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eating that was a bad idea..", "Ce n'était pas une bonne idée de manger ça...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's a little uncomfortable..", "C'est un peu inconfortable...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bR][v:0][c:] has been fully digested. You will never see it again.", "Votre carte [c:bR][v:0][c:] a été complètement digérée. Vous ne la reverrez jamais.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bR][v:0][c:] is being slowly digested. It has [c:bR][v:1][c:] health left.", "Votre carte [c:bR][v:0][c:] est lentement digérée. Il lui reste [c:bR][v:1][c:] points de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have yet another trade to propose", "J'ai encore un échange à vous proposer", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This time, let us trade our whole decks", "Cette fois, échangeons nos decks entiers", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He's hungry again", "Il a encore faim", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time for more morsels", "Il est temps de manger un peu plus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Back on the hunt", "De retour à la chasse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Think fast!", "Réfléchissez vite !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catch!", "Attrapez !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heads up!", "Attention !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're a dad-gum pain in my backside!", "Tu es une vraie épine dans mon derrière !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's see you get past this!", "Voyons si tu peux passer ça !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish not big enough. Get bigger fish.", "Poisson pas assez gros. Prendre plus gros.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Little fish bad. Big fish better.", "Petit poisson mauvais. Gros poisson meilleur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Need better fish.", "Besoin de meilleur poisson.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That fella looks mighty curious about that [c:bR]empty lane[c:]", "Cette bestiole a l'air drôlement intéressée par cette [c:bR]voie vide[c:]", Language.French);

        }
    }
    public class EndlessAct2Mod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for EndlessAct2 Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SELECT A DECK TO USE.\nTHIS WILL OVERRIDE YOUR CURRENT DECK!", "CHOISISSEZ UN DECK À UTILISER.\nCELA REMPLACERA VOTRE DECK ACTUEL !", Language.French);
            for (int score = 0; score <= 100; score++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "High Score: " + score.ToString(), "Meilleur score : " + score.ToString(), Language.French);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Picked up your new deck.", "Vous avez récupéré votre nouveau deck.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card was added to your collection.", "La carte a été ajoutée à votre collection.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "buh", "Hein", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a card type.", "Choisissez un type de carte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need at least 20 cards in your deck!", "Il vous faut au moins 20 cartes dans votre deck !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "…", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good offering.", "Belle offrande.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have this.", "Prenez ceci.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have a choice of merging two cards here..", "Vous pouvez choisir de fusionner deux cartes ici...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty", "prime", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every 3 succesful battles, you gain a bounty star. With bounty stars, random bounty hunters will start to spawn in battles.", "Toutes les 3 victoires, vous gagnez une étoile de prime. Avec des étoiles de prime, des chasseurs de primes aléatoires commencent à apparaître dans les combats.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon", "Bénédiction", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have only one boon slot.", "Vous n'avez qu'un seul emplacement de bénédiction.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elite", "Élite", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every regular card battle is replaced with an elite battle.", "Chaque combat de cartes ordinaire est remplacé par un combat d'élite.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't merge.", "Ne pas fusionner.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Merge Field Mice", "Fusionner les Mulots", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Merge Sentry Drone", "Fusionner le Drone mitrailleur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Merge Blue Mage", "Fusionner le Mage bleu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Merge Gravedigger", "Fusionner le Fossoyeur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have a choice of merging two cards here..", "Vous pouvez choisir de fusionner deux cartes ici...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select the {} deck?", "Choisir le deck {} ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select the Deck of Beasts?", "Choisir le deck des bêtes ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select the Deck of the Dead?", "Choisir le deck des morts ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select the Deck of Technology?", "Choisir le deck de technologie ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select the Deck of Magick?", "Choisir le deck de magie ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take the deck.", "Prendre le deck.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leave it.", "Le laisser.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need at least 20 cards in your deck!", "Il vous faut au moins 20 cartes dans votre deck !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No offering in your deck?", "Aucune offrande dans votre deck ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fine. Take this instead.", "Bien. Prenez plutôt ceci.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? You still crave more?", "Quoi ? Vous en voulez encore ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fine. Take this.", "Bien. Prenez ceci.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reincarnation", "Réincarnation", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Voltage", "Tension", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Construct", "Construction", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fossil", "Fossile", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BountyHunter", "Chasseur de primes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nuzlocke", "Nuzlocke", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Luck", "Bénédiction de chance", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with a clover.", "Commencez chaque combat avec un trèfle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Start each battle with a clover.", "Avec cette bénédiction équipée, commencez chaque combat avec un trèfle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Flesh", "Bénédiction de chair", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox may be sacrificed.", "Les cartes mox peuvent être sacrifiées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Mox may be sacrificed.", "Avec cette bénédiction équipée, les cartes mox peuvent être sacrifiées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Voltage", "Bénédiction de tension", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When you sacrifice a beast card, you increase your max energy and gain an energy cell.", "Quand vous sacrifiez une carte de bête, vous augmentez votre énergie maximale et gagnez une cellule d'énergie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, When you sacrifice a beast card, you increase your max energy and gain an energy cell.", "Avec cette bénédiction équipée, quand vous sacrifiez une carte de bête, vous augmentez votre énergie maximale et gagnez une cellule d'énergie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Reincarnation", "Bénédiction de réincarnation", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a Skeleton is sacrificed, draw a squirrel.", "Quand un squelette est sacrifié, piochez un écureuil.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, When a Skeleton is sacrificed, draw a squirrel.", "Avec cette bénédiction équipée, quand un squelette est sacrifié, piochez un écureuil.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Necromancy", "Bénédiction de nécromancie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a Skeleton dies, a random mox is placed in it's place.", "Quand un squelette meurt, un mox aléatoire est placé à sa place.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, When a Skeleton dies, a random mox is placed in it's place.", "Avec cette bénédiction équipée, quand un squelette meurt, un mox aléatoire est placé à sa place.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Scrap", "Bénédiction de ferraille", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever you reach full energy, you gain a bone.", "Chaque fois que vous atteignez votre énergie maximale, vous gagnez un os.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Whenever you reach full energy, you gain a bone.", "Avec cette bénédiction équipée, chaque fois que vous atteignez votre énergie maximale, vous gagnez un os.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Construct", "Bénédiction de construction", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any tech card that costs more than 2 energy will drop a random mox on death.", "Toute carte technologique coûtant plus de 2 énergies laisse tomber un mox aléatoire à sa mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Any tech card that costs more than 2 energy will drop a random mox on death.", "Avec cette bénédiction équipée, toute carte technologique coûtant plus de 2 énergies laisse tomber un mox aléatoire à sa mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of The Saving Grace", "Bénédiction de la grâce salvatrice", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever you would recieve fatal damage, the scales are only tipped down to 4.\nONCE PER BATTLE", "Si vous deviez subir des dégâts mortels, la balance est ramenée à 4 points en votre défaveur.\nUNE FOIS PAR COMBAT", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Whenever you would recieve fatal damage, the scales are only tipped down to 4.\nONCE PER BATTLE", "Avec cette bénédiction équipée, si vous deviez subir des dégâts mortels, la balance est ramenée à 4 points en votre défaveur.\nUNE FOIS PAR COMBAT", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with a black goat on the board.", "Commencez chaque combat avec une chèvre noire sur le plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Start each battle with a black goat on the board.", "Avec cette bénédiction équipée, commencez chaque combat avec une chèvre noire sur le plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with +3 bones.", "Commencez chaque combat avec +3 os.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Start each battle with +3 bones.", "Avec cette bénédiction équipée, commencez chaque combat avec +3 os.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw 2 cards each turn instead of 1, but it will only function if you have less than 20 cards in your deck while battling.", "Piochez 2 cartes par tour au lieu de 1, mais uniquement si votre deck contient moins de 20 cartes pendant le combat.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Draw 2 cards each turn instead of 1, but it will only function if you have less than 20 cards in your deck while battling.", "Avec cette bénédiction équipée, piochez 2 cartes par tour au lieu de 1, mais uniquement si votre deck contient moins de 20 cartes pendant le combat.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with 2 firs in your hand.", "Commencez chaque combat avec 2 grands sapins dans votre main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Start each battle with 2 firs in your hand.", "Avec cette bénédiction équipée, commencez chaque combat avec 2 grands sapins dans votre main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Fossils", "Bénédiction des fossiles", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrain cards yield 3 bones on death instead of 1.", "Les cartes de terrain donnent 3 os au lieu de 1 à leur mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Terrain cards yield 3 bones on death instead of 1.", "Avec cette bénédiction équipée, les cartes de terrain donnent 3 os au lieu de 1 à leur mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Marrow", "Bénédiction de moelle", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificing undead cards yields 2 bones instead of 1.", "Sacrifier des cartes mortes-vivantes donne 2 os au lieu de 1.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, Sacrificing undead cards yields 2 bones instead of 1.", "Avec cette bénédiction équipée, sacrifier des cartes mortes-vivantes donne 2 os au lieu de 1.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Bloodstone", "Bénédiction de pierre de sang", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may sacrifice terrain cards.", "Vous pouvez sacrifier les cartes de terrain.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, You may sacrifice terrain cards.", "Avec cette bénédiction équipée, vous pouvez sacrifier les cartes de terrain.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boon of Ouroboros", "Bénédiction d'Ouroboros", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You get a different effect depending on the region:\nBeast Dungeon:+2 Starting bones each battle.\nDeath Dungeon:+1 Starting Energy each battle\nTech Dungeon:Start the game with two random mox in your hand.\nMagick Dungeon:Start the game with 2 Squirrels in your hand.", "Vous obtenez un effet selon la région :\nDonjon des bêtes : +2 os au début de chaque combat.\nDonjon des morts : +1 énergie au début de chaque combat.\nDonjon technologique : commencez chaque combat avec deux mox aléatoires supplémentaires en main.\nDonjon de magie : commencez chaque combat avec 2 écureuils supplémentaires en main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this boon equipped, You get a different effect depending on the region:\nBeast Dungeon:+2 Starting bones each battle.\nDeath Dungeon:+1 Starting Energy each battle\nTech Dungeon:Start the game with two random mox in your hand.\nMagick Dungeon:Start the game with 2 Squirrels in your hand.", "Avec cette bénédiction équipée, vous obtenez un effet selon la région :\nDonjon des bêtes : +2 os au début de chaque combat.\nDonjon des morts : +1 énergie au début de chaque combat.\nDonjon technologique : commencez chaque combat avec deux mox aléatoires supplémentaires en main.\nDonjon de magie : commencez chaque combat avec 2 écureuils supplémentaires en main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ay yo yaw cant stand right here", "Hé, vous ne pouvez pas rester ici !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fir", "Grand sapin", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tombstone", "Pierre tombale", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conduit Tower", "Tour cyborg", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Bot", "Robot cassé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bridge Railing", "Garde-corps du pont", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Boulder", "Rocher d'émeraude", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Boulder", "Rocher de rubis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Boulder", "Rocher de saphir", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty Hunter", "Chasseur de primes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waddup, to all rappers shut up with your shutting up.", "Yo, que tous les rappeurs arrêtent de se taire !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My injuries.. They are severe.", "Mes blessures… Elles sont graves.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am forced to retire.. for now.", "Je suis forcé de me retirer… pour l'instant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Argh!! What have you done to me?", "Argh !! Que m'avez-vous fait ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything hurts... But.. I'll be back..", "Tout me fait mal... Mais… je reviendrai...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well.. you stopped me..", "Eh bien… vous m'avez arrêté...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WILL get you.. challenger..", "Je vous RETROUVERAI… challenger...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've been scrapped!", "Je suis bon pour la ferraille !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You beat me fair and square...", "Vous m'avez battu loyalement...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So I will retreat.. well played.. Expect a rematch soon though..", "Je vais donc me retirer… bien joué… Mais attendez-vous à une revanche prochainement...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, we meet again..", "Nous nous retrouvons...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh.. Its You..", "Oh… C'est vous...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aha! Found you!", "Ah ! Je vous ai trouvé !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've come to get my revenge!", "Je suis venu prendre ma revanche !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surprise!", "Surprise !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey.", "Hé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, Hello there.", "Eh bien, bonjour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greeetings!", "Saalutations !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just what do YOU think you're doing? Wandering around and destroying our dungeons.", "Que pensez-VOUS faire, au juste ? Vous parcourez nos donjons et les détruisez.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A little mouse wanders into my sight..", "Une petite souris entre dans mon champ de vision...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At last, I have found you..", "Enfin, je vous ai trouvé...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beasts", "Bêtes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Technology", "Technologie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magick", "Magie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead", "Mort", Language.French);

            // Bounty
            Dictionary<string, string> bountyName = new Dictionary<string, string>
            {
                {"Barry", "Zblim"},
                {"Bolt", "Pouf"},
                {"Gear", "Splaf"},
                {"Zap", "Zap"},
                {"Rust", "Splouf"},
                {"Clain", "Clain"},
                {"Clank", "Clac"},
                {"Tank", "Chtonk"},
                {"Gun", "Boum"},
                {"Shoot", "Bim"},
                {"Maksim", "Méca"},
                {"Wilkin", "Wilkin"},
                {"Kaycee", "Kaycee"},
                {"Hobbes", "Hobbes"},
                {"Grind", "Grince"},
                {"Blast", "Bang"},
                {"Crash", "Badaboum"},
                {"Moon", "Lune"},
                {"Zip", "Zip"},
                {"Jerry", "Jerry"},
                {"Plasma", "Plasma"},
                {"Jimmy", "Jimmy"},
                {"Silence", "Silence"},
                {"Never", "Jamais"},
                {"Hunt", "Chasse"},
                {"Hunter", "Chasseur"},
                {"Doom", "Fléau"},
                {"Const", "Const"},
                {"Boom", "Boum"},
                {"West", "Ouest"}
            };
            Dictionary<string, string> bountySuffix = new Dictionary<string, string>
            {
                {"son", "son"},
                {"stein", "stein"},
                {"dottir", "dottir"},
                {"vic", "vic"},
                {"berg", "berg"},
                {"sky", "sky"},
                {"ski", "ski"},
                {"sin", "sin"},
                {"sim", "sim"},
                {"fellow", "fellow"},
                {"ed", "ed"},
                {" II", " II"},
                {" III", " III"}
            };
            Dictionary<string, string> bountyPrefix = new Dictionary<string, string>
            {
                {"Mac", "Mac"},
                {"Mc", "Mc"},
                {"Von ", "Von "},
                {"Van ", "Van "},
                {"Sir ", "Sire "},
                {"Madame ", "Madame "}
            };
            foreach (var n in bountyName)
            {
                foreach (var s in bountySuffix)
                {
                    var name = n.Key + s.Key;
                    var namechinese = n.Value + s.Value;
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, namechinese, Language.French);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But this ain't the last of " + name + "!", "Mais tu n'en as pas fini avec " + namechinese + " !", Language.French);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name + ". Seeking revenge..", namechinese + ". En quête de vengeance...", Language.French);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The one who destroyed " + name + "... You won't get away with it again.", "Toi qui as détruit " + namechinese + "... Tu ne t'en tireras pas cette fois.", Language.French);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Didn't expect to see " + name + " again, did ya?", "Tu ne pensais pas revoir " + namechinese + ", n'est-ce pas ?", Language.French);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unfortunately, " + name + " is back.", "Malheureusement, voici de nouveau " + namechinese + ".", Language.French);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They call me.. " + name + ".. You can't defeat ME!", "On m'appelle... " + namechinese + "... Tu ne peux pas ME vaincre !", Language.French);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's see you stop " + name + ".", "Voyons si tu peux arrêter " + namechinese + ".", Language.French);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just remember that " + name + " can not be defeated.", "Souviens-toi que " + namechinese + " est invincible.", Language.French);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name + " will be your executioner for the evening.", namechinese + " sera ton bourreau ce soir.", Language.French);
                    foreach (var p in bountyPrefix)
                    {
                        name = p.Key + name;
                        namechinese = p.Value + namechinese;
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, namechinese, Language.French);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But this ain't the last of " + name + "!", "Mais tu n'en as pas fini avec " + namechinese + " !", Language.French);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name + ". Seeking revenge..", namechinese + ". En quête de vengeance...", Language.French);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The one who destroyed " + name + "... You won't get away with it again.", "Toi qui as détruit " + namechinese + "... Tu ne t'en tireras pas cette fois.", Language.French);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Didn't expect to see " + name + " again, did ya?", "Tu ne pensais pas revoir " + namechinese + ", n'est-ce pas ?", Language.French);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unfortunately, " + name + " is back.", "Malheureusement, voici de nouveau " + namechinese + ".", Language.French);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They call me.. " + name + ".. You can't defeat ME!", "On m'appelle... " + namechinese + "... Tu ne peux pas ME vaincre !", Language.French);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's see you stop " + name + ".", "Voyons si tu peux arrêter " + namechinese + ".", Language.French);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just remember that " + name + " can not be defeated.", "Souviens-toi que " + namechinese + " est invincible.", Language.French);
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name + " will be your executioner for the evening.", namechinese + " sera ton bourreau ce soir.", Language.French);
                    }
                }
            }
        }
    }
    public class WhistleWindAbnormalSigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for WhistleWindAbnormalSigils Mod");
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aggravating", "Provocation", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While this card is on the board, all opposing creatures gain 1 Power.", "Tant que cette carte est sur le plateau, toutes les créatures ennemies gagnent 1 point de puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My beasts are incensed by your creature's presence.", "Mes bêtes sont irritées par la présence de votre créature.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemist", "Alchimiste", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Energy to discard your current hand and draw cards equal to the amount you discarded.", "Payez 2 énergies pour défausser votre main actuelle, puis piochez autant de cartes que vous en avez défaussées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unending faith of countless promises.", "La foi sans fin d'innombrables promesses.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] replaces your hand with a new one!", "La carte [creature] remplace votre main par une nouvelle !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Assimilator", "Assimilateur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card kills an opposing card, it gains 1 Power and 1 Health.", "Quand cette carte tue une carte adverse, elle gagne 1 point de puissance et 1 point de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From the many, one.", "De plusieurs, un seul.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] makes its victim a part of itself.", "La carte [creature] intègre sa victime à elle-même.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Barreler", "Rouleur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, this card moves in the sigil's direction to the end of the board, moving any cards in the way.", "À la fin du tour de son propriétaire, cette carte se déplace jusqu'au bord du plateau dans la direction de l'emblème et déplace les cartes sur son chemin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Make room.", "Faites de la place.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] moves to the end of the board, tossing anything in its way.", "La carte [creature] se déplace jusqu'au bord du plateau et projette tout ce qui lui barre le chemin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Binding Strike", "Frappe entravante", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes an opposing creature, inflict Bind equal to twice this card's Power.", "Quand la carte [creature] frappe une créature adverse, elle lui inflige un Lien égal au double de sa puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beast falls behind the pack.", "Votre bête reste à la traîne.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bitter Enemies", "Ennemis jurés", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card gains 1 Power for each other card on the board that also bears this sigil.", "Cette carte gagne 1 point de puissance pour chaque autre carte du plateau portant aussi cet emblème.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bitter grudge laid bare.", "Une rancœur tenace se révèle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodfiend", "Démon de sang", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card deals damage, it gains 1 Health.", "Quand cette carte inflige des dégâts, elle gagne 1 point de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Accursed fiend.", "Démon maudit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] sucks out fresh life!", "La carte [creature] aspire une vie nouvelle !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodletter", "Saignée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a [creature] is struck with a nonfatal attack, absorb 1 Health from the striker.", "Quand la carte [creature] est frappée par une attaque non mortelle, elle absorbe 1 point de santé de l'attaquant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The blood runs warm with sweet vitality.", "Le sang coule, chaud d'une douce vitalité.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] absorbs nutrients!", "La carte [creature] absorbe des nutriments !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broodmother", "Mère de la couvée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, create a Spiderling in your hand. [define:wstl_spiderling]", "Quand la carte [creature] est frappée, créez une petite araignée dans votre main. [define:wstl_spiderling]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small spider takes refuge in your hand.", "Une petite araignée se réfugie dans votre main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] drops a spiderling!", "La carte [creature] laisse tomber une petite araignée !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conductor", "Chef d'orchestre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The effect of this sigil will change over the next 3 turns while this card is on the board.", "Tant que cette carte est sur le plateau, l'effet de cet emblème changera au cours des 3 prochains tours.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From break and ruin, the most beautiful performance begins.", "De la ruine et des décombres naît le plus beau des spectacles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] plays a quiet symphony.", "La carte [creature] joue une symphonie silencieuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Copycat", "Imitateur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will transform into a copy of the first creature that opposes it.", "La carte [creature] devient une copie de la première créature qui lui fait face.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A near perfect impersonation.", "Une imitation presque parfaite.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] tries to mimick the opposing creature.", "La carte [creature] essaie d'imiter la créature en face.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrector", "Correcteur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, randomly change its stats according to its total play cost.", "Quand la carte [creature] est piochée, ses caractéristiques changent aléatoirement selon son coût total.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How balanced.", "Quel équilibre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] stats are forcefully 'corrected'.", "Les caractéristiques de la carte [creature] sont « corrigées » de force.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Courageous", "Courageux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to this card lose up to 2 Health. For each point of Heath lost, the affected creature gains 1 Power. This effect cannot kill cards.", "Les créatures adjacentes à cette carte perdent jusqu'à 2 points de santé. Pour chaque point de santé perdu, la créature affectée gagne 1 point de puissance. Cet effet ne peut pas tuer de carte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life is only given to those who don't fear death.", "La vie n'est donnée qu'à ceux qui ne craignent pas la mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed", "Maudit", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, the killer transforms into a copy of this card.", "Quand la carte [creature] meurt, son meurtrier se transforme en copie de cette carte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The curse continues unabated.", "La malédiction se poursuit sans faiblir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] passes the curse on.", "La carte [creature] transmet la malédiction.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cycler", "Cyclique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, this card moves in the sigil's direction, looping around the owner's side of the board.", "À la fin du tour de son propriétaire, cette carte se déplace dans la direction de l'emblème en faisant le tour de son côté du plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A never-ending cycle.", "Un cycle sans fin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] moves to a new space, going around its side of the board.", "La carte [creature] se déplace vers un nouvel emplacement en faisant le tour de son côté du plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "False Throne", "Faux trône", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay 1 Health to give Neutered to a chosen creature, then create a free, unaltered copy of it in your hand.", "Une fois par tour, payez 1 point de santé pour donner Castré à une créature choisie, puis créez dans votre main une copie gratuite et non modifiée de celle-ci.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A simple little magic trick.", "Un simple petit tour de magie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gives a false present to the chosen creature.", "La carte [creature] offre un faux cadeau à la créature choisie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flag Bearer", "Porte-drapeau", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While this card is on the board, adjacent creatures gain 2 Health.", "Tant que cette carte est sur le plateau, les créatures adjacentes gagnent 2 points de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morale runs high.", "Le moral est au beau fixe.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruler of Frost", "Souveraine du givre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay 2 Bones to choose a space on the board. If the space is empty, create a Block of Ice. Otherwise, if this card can kill the occupying card, transform it into a Frozen Heart.", "Une fois par tour, payez 2 os pour choisir un emplacement du plateau. S'il est vide, créez un Bloc de glace. Sinon, si cette carte peut tuer la carte qui l'occupe, transformez-la en Cœur gelé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With a wave of her hand, the Snow Queen blocked the path.", "D'un geste de la main, la Reine des neiges bloqua le passage.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] freezes the path.", "La carte [creature] gèle le passage.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen Heart", "Cœur gelé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, the killer gains 2 Health.", "Quand la carte [creature] meurt, son meurtrier gagne 2 points de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spring arrives with blossoming roses.", "Le printemps arrive avec les roses en fleurs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] releases warm life.", "La carte [creature] libère une vie chaleureuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gardener", "Jardinier", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an allied card is killed, create a Sapling in their place. [define:wstl_parasiteTreeSapling]", "Quand une carte alliée est tuée, créez une jeune pousse à sa place. [define:wstl_parasiteTreeSapling]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They proliferate and become whole. Can you feel it?", "Ils prolifèrent et deviennent entiers. Le sentez-vous ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sapling grows out of the dead card's corpse.", "Une jeune pousse grandit sur la dépouille de la carte morte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gift Giver", "Donateur de cadeaux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, create a random card in your hand.", "Quand la carte [creature] est jouée, créez une carte aléatoire dans votre main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gift for you.", "Un cadeau pour vous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has a gift for you!", "La carte [creature] a un cadeau pour vous !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greedy Healing", "Guérison avide", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, this card gains 2 Health. If 2 turns pass without this card taking damage, it will die.", "À la fin du tour de son propriétaire, cette carte gagne 2 points de santé. Si 2 tours passent sans qu'elle subisse de dégâts, elle meurt.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beast has Health in excess.", "Votre bête a trop de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gives itself more Health!", "La carte [creature] se donne davantage de santé !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grinder", "Broyeur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card gains the stats of the creatures sacrificed to play it.", "Cette carte gagne les caractéristiques des créatures sacrifiées pour la jouer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now everything will be just fine.", "Maintenant, tout ira bien.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Group Healer", "Guérisseur de groupe", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of its owner's turn, this card will heal all allies that have taken damage by 1 Health.", "Au début du tour de son propriétaire, cette carte soigne de 1 point de santé tous les alliés blessés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You only delay the inevitable.", "Vous ne faites que retarder l'inévitable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals all its friends.", "La carte [creature] soigne tous ses amis.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healer", "Guérisseur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of your turn, you may choose one of your other cards to heal by 2 Health.", "À la fin de votre tour, vous pouvez choisir une de vos autres cartes et lui rendre 2 points de santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Never underestimate the importance of a healer.", "Ne sous-estimez jamais l'importance d'un guérisseur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals the chosen creature!", "La carte [creature] soigne la créature choisie !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "High-Strung", "À cran", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the current turn, this card gains Haste equal to twice the opposing card's Power.", "À la fin du tour en cours, cette carte gagne une Hâte égale au double de la puissance de la carte en face.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Idol", "Idole", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While this card is on the board, all opposing creatures lose 1 Power.", "Tant que cette carte est sur le plateau, toutes les créatures ennemies perdent 1 point de puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My beasts defer to you.", "Mes bêtes s'inclinent devant vous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Left-Veering Strike", "Frappe déviée à gauche", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing space to the left of the space across from it.", "La carte [creature] frappe l'emplacement situé à gauche de celui qui lui fait face.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Right-Veering Strike", "Frappe déviée à droite", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing space to the right of the space across from it.", "La carte [creature] frappe l'emplacement situé à droite de celui qui lui fait face.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonely", "Solitaire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a card on the board to gain 1 Pebble unless a card with Pebble already exists, then return this card to your hand. If a card with Pebble dies, all ally cards receive 1 additional damage until a new card is chosen.", "Choisissez une carte sur le plateau qui gagne 1 Galet, sauf s'il existe déjà une carte avec Galet, puis renvoyez la carte portant cet emblème dans votre main. Si une carte avec Galet meurt, toutes les cartes alliées subissent 1 dégât supplémentaire jusqu'à ce qu'une nouvelle carte soit choisie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friend to stay.", "Un ami pour rester.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Martyr", "Martyr", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, all allied creatures gain 2 Health and lose any negative status effects.", "Quand la carte [creature] meurt, toutes les créatures alliées gagnent 2 points de santé et perdent leurs effets d'état négatifs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A selfless death to cleanse your beasts of evil.", "Une mort désintéressée pour purifier vos bêtes du mal.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]'s death cleanses your other creatures!", "La mort de la carte [creature] purifie vos autres créatures !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nettle Clothes", "Vêtements d'orties", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, fill all empty spaces on the owner's side of the board with random Brothers. This card gains the first sigil of each allied Brother.", "Quand cette carte est jouée, remplissez tous les emplacements vides du côté de son propriétaire avec des Frères aléatoires. Cette carte gagne le premier emblème de chaque Frère allié.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These clothes will surely restore our happy days.", "Ces vêtements feront sûrement revenir nos jours heureux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] brings out its family!", "La carte [creature] fait venir sa famille !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Neutered", "Castré", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has its Power reduced to 0. At the start of the owner's turn, remove this sigil.", "La puissance de la carte [creature] est réduite à 0. Au début du tour de son propriétaire, retirez cet emblème.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Neutered Latch", "Transmission de castration", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay [sigilcost:2 Bones] to choose a creature to gain the Neutered sigil, then increase this sigil's activation cost by 1 Bone.", "Une fois par tour, payez [sigilcost:2 os] pour choisir une créature qui reçoit l'emblème Castré, puis augmentez le coût d'activation de cet emblème de 1 os.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay 1 bone to choose a creature to gain the Neutered sigil, then increase this sigil's activation cost by 1 Bone.", "Une fois par tour, payez 1 os pour choisir une créature qui reçoit l'emblème Castré, puis augmentez le coût d'activation de cet emblème de 1 os.", Language.French);
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay " + count.ToString() + " bones to choose a creature to gain the Neutered sigil, then increase this sigil's activation cost by 1 Bone.", "Une fois par tour, payez " + count.ToString() + " " + "os" + " pour choisir une créature qui reçoit l'emblème Castré, puis augmentez le coût d'activation de cet emblème de 1 os.", Language.French);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The will to fight has been lost.", "La volonté de se battre a disparu.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] prevents the chosen creature from attacking.", "La carte [creature] empêche la créature choisie d'attaquer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nimble-Footed", "Pied agile", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, this card gains 2 Haste.", "Au début du tour de son propriétaire, cette carte gagne 2 points de Hâte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Opportunistic", "Opportuniste", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals 1 additional damage to opposing cards that cannot attack this card during their own turn.", "La carte [creature] inflige 1 dégât supplémentaire aux cartes adverses qui ne peuvent pas l'attaquer pendant leur propre tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cheap hit.", "Un coup bas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persecutor", "Persécuteur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, create a Nail in the adjacent left space and a Hammer in the adjacent right space if they are empty.", "Quand une carte ornée de cet emblème est jouée, créez un Clou sur l'emplacement adjacent gauche s'il est vide et un Marteau sur l'emplacement adjacent droit s'il est vide.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you guilty of having a closed heart?", "Votre cœur fermé vous rend-il coupable ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] reveals its hidden tools!", "La carte [creature] révèle ses outils cachés !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persistent", "Persistance", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Attacks by this card cannot be avoided or redirected by sigils like Loose Tail or Waterborne.", "Les attaques de cette carte ne peuvent être évitées ni redirigées par des emblèmes comme Queue ou Eau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prey cannot hide so easily.", "Les proies ne peuvent pas se cacher aussi facilement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] chases its prey down.", "La carte [creature] poursuit sa proie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Damage dealt by this card cannot be negated or reduced by sigils such as Armoured or Thick Skin.", "Les dégâts infligés par cette carte ne peuvent être annulés ni réduits par des emblèmes comme Armure ou Peau épaisse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beast runs mine through.", "Votre bête transperce la mienne.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to this card take 1 less damage when struck.", "Les créatures adjacentes à cette carte subissent 1 dégât de moins lorsqu'elles sont frappées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beast shields its ally against the blow.", "Votre bête protège son allié du coup.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] shields its friend!", "La carte [creature] protège son ami !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Punisher", "Punisseur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is killed.", "Quand la carte [creature] est frappée, l'attaquant est tué.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Retaliation is switft and brutal.", "La riposte est rapide et brutale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] swiftly retaliates!", "La carte [creature] riposte vivement !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queen Nest", "Nid de reine", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever another card is killed, create a Worker Bee in your hand. [define:wstl_queenBeeWorker]", "Chaque fois qu'une autre carte est tuée, créez une abeille ouvrière dans votre main. [define:wstl_queenBeeWorker]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For the hive.", "Pour la ruche.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another worker is born to serve [creature].", "Une autre ouvrière naît pour servir la carte [creature].", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reflector", "Réflecteur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is struck, the striker is dealt damage equal to the striker's Power.", "Quand cette carte est frappée, l'attaquant subit des dégâts égaux à sa propre puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What goes around comes around.", "On récolte ce que l'on sème.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] returns the damage.", "La carte [creature] renvoie les dégâts.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Refresh Decks", "Réinitialisation des decks", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Refreshes and reshuffles both draw piles.", "Réinitialise et mélange de nouveau les deux piles de pioche.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of its owner's turn, this card heals adjacent cards by 1 Health.", "Au début du tour de son propriétaire, cette carte rend 1 point de santé aux cartes adjacentes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wounds heal, but the scars remain.", "Les blessures guérissent, mais les cicatrices restent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals adjacent creatures.", "La carte [creature] soigne les créatures adjacentes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Return Card to Hand", "Renvoyer la carte en main", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returns the selected card to your hand with all changes and statuses retained. Change the selected card's cost to 0-2 Bones based on how recently it was played.", "Renvoie la carte choisie dans votre main en conservant toutes ses modifications et tous ses états. Son coût devient 0 à 2 os selon la date à laquelle elle a été jouée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Return to Nihil", "Retour au néant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, deal damage equal to this card's Power to all other cards on the board.", "À la fin du tour de son propriétaire, cette carte inflige à toutes les autres cartes du plateau des dégâts égaux à sa puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One step closer to oblivion.", "Un pas de plus vers l'oubli.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The void calls.", "Le vide appelle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rightful Heir", "Héritière légitime", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay [sigilcost:1 Bone] to transform a chosen creature into a Pumpkin, then increase this sigil's activation cost by 1. [define:wstl_ozmaPumpkin]", "Une fois par tour, payez [sigilcost:1 os] pour transformer une créature choisie en Tête de citrouille, puis augmentez le coût d'activation de cet emblème de 1. [define:wstl_ozmaPumpkin]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay 1 bone to transform a chosen creature into a Pumpkin, then increase this sigil's activation cost by 1. [define:wstl_ozmaPumpkin]", "Une fois par tour, payez 1 os pour transformer une créature choisie en Tête de citrouille, puis augmentez le coût d'activation de cet emblème de 1. [define:wstl_ozmaPumpkin]", Language.French);
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay " + count.ToString() + " bones to transform a chosen creature into a Pumpkin, then increase this sigil's activation cost by 1. [define:wstl_ozmaPumpkin]", "Une fois par tour, payez " + count.ToString() + " " + "os" + " pour transformer une créature choisie en Tête de citrouille, puis augmentez le coût d'activation de cet emblème de 1. [define:wstl_ozmaPumpkin]", Language.French);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All she has left now are her children.", "Il ne lui reste plus que ses enfants.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] turns the creature into a pumpkin.", "La carte [creature] transforme la créature en citrouille.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roots", "Racines", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, create Thorny Vines on adjacent empty spaces. [define:wstl_snowWhitesVine]", "Quand cette carte est jouée, créez des Lianes épineuses sur les emplacements adjacents vides. [define:wstl_snowWhitesVine]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resentment bursts forth like a weed.", "Le ressentiment jaillit comme une mauvaise herbe.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharp thorns shoot out around [creature]!", "Des épines acérées jaillissent autour de la carte [creature] !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scorching", "Brûlure", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature opposing this card takes 1 damage at the end of its owner's turn.", "La créature en face de cette carte subit 1 dégât à la fin du tour de son propre propriétaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slow and painful death.", "Une mort lente et douloureuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature opposing [creature] is burned!", "La créature en face de la carte [creature] est brûlée !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrambler", "Brouilleur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, give its stats to the sacrificing card then randomise the resulting stats.", "Quand la carte [creature] est sacrifiée, transmettez ses caractéristiques à la carte qui la sacrifie, puis modifiez aléatoirement les caractéristiques obtenues.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, give its stats to the sacrificing card then randomise the resulting stats. Works for Spells.", "Quand la carte [creature] est sacrifiée, transmettez ses caractéristiques à la carte qui la sacrifie, puis modifiez aléatoirement les caractéristiques obtenues. Fonctionne avec les sorts.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you love your city?", "Aimez-vous votre ville ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent's Nest", "Nid de serpent", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker gains 1 Worms.", "Quand la carte [creature] est frappée, l'attaquant gagne 1 point de Vers.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It can enter your body through any aperture.", "Il peut entrer dans votre corps par n'importe quel orifice.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Made of Slime", "Fait de glu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, give adjacent cards this sigil, and deal 1 damage to this card if it is not a Slime. This card transforms into a Slime on death.", "À la fin du tour de son propriétaire, cette carte donne cet emblème aux cartes adjacentes et subit 1 dégât si elle n'est pas une Glu. À sa mort, elle devient une Glu.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its army grows everyday.", "Son armée grandit chaque jour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] melts into slime!", "La carte [creature] fond en glu !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sporogenic", "Sporogène", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to this card gain 1 Spores at the end of its owner's turn. This sigil activates before other sigils.", "Les créatures adjacentes à cette carte gagnent 1 Spore à la fin du tour du propriétaire de cette carte. Cet emblème s'active avant les autres.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They will love this curse like a blessing.", "Ils aimeront cette malédiction comme une bénédiction.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] scatters spores on the adjacent cards!", "La carte [creature] répand des spores sur les cartes adjacentes !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Team Leader", "Chef d'équipe", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While this card is on the board, all allied creatures gain 1 Power.", "Tant que cette carte est sur le plateau, toutes les créatures alliées gagnent 1 point de puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beast emboldens its allies.", "Votre bête donne du courage à ses alliés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Train", "Le Train", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, kill all creatures on the board. Creatures killed this way do not drop bones.", "Quand la carte [creature] est jouée, tuez toutes les créatures du plateau. Les créatures tuées ainsi ne laissent pas tomber d'os.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The train boards those that don't step away from the tracks.", "Le train emporte ceux qui ne s'écartent pas des rails.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The train blows its mighty horn.", "Le train fait retentir son puissant avertisseur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thick Skin", "Peau épaisse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever [creature] takes damage, reduce that damage by 1.", "Chaque fois que la carte [creature] subit des dégâts, réduisez ces dégâts de 1.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creature's hide absorbs the blow.", "La peau de votre créature absorbe le coup.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] absorbs the blow.", "La carte [creature] absorbe le coup.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Volatile", "Instable", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card dies, adjacent and opposing cards are dealt 10 damage.", "Quand cette carte meurt, les cartes adjacentes et en face subissent 10 dégâts.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An explosive finish.", "Une fin explosive.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] detonates! Adjacent creatures are killed in the blast.", "La carte [creature] explose ! Les créatures adjacentes sont tuées par l'explosion.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Witness", "Témoin", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to increase the selected creature's Health by 2 and their taken damage by 1. This effect stacks up to 3 times.", "Payez 2 os pour augmenter de 2 la santé de la créature choisie et de 1 les dégâts qu'elle subit. Cet effet peut se cumuler jusqu'à 3 fois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The truth will set you free.", "La vérité vous rendra libre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The chosen beholds [creature] and is reborn.", "L'élu contemple la carte [creature] et renaît.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woodcutter", "Bûcheron", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposite this card, they take damage equal to this card's Power.", "Quand une créature se déplace sur l'emplacement en face de cette carte, elle subit des dégâts égaux à la puissance de cette carte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter how many trees fall, the forest remains dense.", "Peu importe le nombre d'arbres abattus, la forêt reste dense.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes a free swing.", "La carte [creature] porte un coup gratuit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, this card moves in the sigil's direction, looping around the owner's side of the board. Allied creatures towards this card in the sigil's direction as far as possible.", "À la fin du tour de son propriétaire, cette carte se déplace dans la direction de l'emblème en bouclant sur son côté du plateau. Les autres créatures alliées se déplacent dans cette direction pour se rapprocher d'elle autant que possible.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's go, together.", "Allons-y ensemble.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] leads your creatures forward.", "La carte [creature] entraîne vos créatures vers l'avant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil is immune to the effects of Touch of Death, Stinky, Punisher, Cursed, and Idol.", "Une carte ornée de cet emblème est immunisée contre Toucher de la Mort, Pestilence, Punisseur, Maudit et Idole.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adjacent creatures gain Power equal to half this card's base Power, rounded down. This effect changes next turn.", "Les créatures adjacentes gagnent une puissance égale à la moitié de la puissance de base de cette carte, arrondie à l'entier inférieur. Cet effet change au prochain tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allied creatures on the board gain Power equal to half this card's base Power, rounded down. This effect changes next turn.", "Les créatures alliées du plateau gagnent une puissance égale à la moitié de la puissance de base de cette carte, arrondie à l'entier inférieur. Cet effet change au prochain tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All other creatures on the board gain Power equal to this card's Power.", "Toutes les autres créatures du plateau gagnent une puissance égale à celle de cette carte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are no cards you can choose.", "Il n'y a aucune carte que vous puissiez choisir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't target the air.", "Vous ne pouvez pas cibler l'air.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must choose one of your other cards.", "Vous devez choisir une de vos autres cartes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's already latched...", "Il a déjà reçu une transmission...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must choose one of your other cards.", "Vous devez choisir une de vos autres cartes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Some things in this world are too unique to replicate.", "Certaines choses de ce monde sont trop uniques pour être reproduites.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lie falls apart, revealing your pitiful true self.", "Le mensonge s'effondre, révélant votre véritable moi pitoyable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creature's consitution is too weak.", "La constitution de votre créature est trop faible.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowards don't get the boon of the brave.", "Les lâches ne reçoivent pas la bénédiction des braves.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love yourself.", "Aimez-vous vous-même.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beast's moxie withers away.", "L'audace de votre bête s'évanouit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The curse abates.", "La malédiction s'apaise.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With a single kiss, the Snow Queen froze their hearts.", "D'un seul baiser, la Reine des neiges gela leurs cœurs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The snow melts away. Perhaps spring is coming.", "La neige fond. Le printemps arrive peut-être.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why do they always leave?", "Pourquoi partent-ils toujours ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She saw her dear brothers in the distance.", "Elle aperçut ses chers frères au loin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Her family that needed the nettle clothing to be free of the curse.", "Sa famille avait besoin des vêtements d'orties pour être libérée de la malédiction.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She fell to the ground, vomiting ooze like the rest of [c:bR]the City[c:].", "Elle tomba à terre, vomissant de la glu comme le reste de [c:bR]la Cité[c:].", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lake ripples gently. As if a number of swans just took flight.", "Le lac ondule doucement. Comme si des cygnes venaient de s'envoler.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The punishment for greed is getting everything you wanted.", "La punition de l'avidité est d'obtenir tout ce que l'on désire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A new nest is born.", "Un nouveau nid naît.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Status Effect Overflow", "Débordement des effets d'état", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card has more than 5 status effects, display the overflow here.", "Si une carte a plus de 5 effets d'état, affichez ici ceux qui dépassent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one to heal.", "Personne à soigner.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No allies to receive a blessing. [c:bR]An enemy[c:] will suffice instead.", "Aucun allié ne peut recevoir de bénédiction. [c:bR]Un ennemi[c:] fera l'affaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No enemies either. It seems no blessings will be given this turn.", "Pas d'ennemis non plus. Il semble que personne ne recevra de bénédiction ce tour-ci.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The enemy is immune to the cold.", "Cet ennemi est immunisé contre le froid.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its heart is too strong to ensare.", "Son cœur est trop fort pour être entravé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature burns with passion. It cannot freeze.", "Cette créature brûle de passion. Elle ne peut pas geler.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost cannot penetrate this one. Choose another.", "Le givre ne peut pas atteindre cette cible. Choisissez-en une autre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Woodcutter stuffs the melted heart into his chest.", "Le Bûcheron enfonce le cœur fondu dans sa poitrine.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These tools remain hidden for now.", "Ces outils restent cachés pour l'instant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not enough space for the vines to grow.", "Pas assez de place pour que les lianes poussent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There's no one to hear your message.", "Personne n'est là pour entendre votre message.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must choose one of your other cards to proselytise.", "Vous devez choisir une de vos autres cartes à convertir.", Language.French);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abnormal Sigils is disabled in the configuration. This will likely break things.", "Abnormal Sigils est désactivé dans la configuration. Cela risque de provoquer des erreurs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abnormal Sigils loaded!", "Abnormal Sigils chargé !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Little Witch's Friend", "Ami de la Petite Sorcière", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Little Witch's Big Friend", "Grand ami de la Petite Sorcière", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime", "Glu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nail", "Clou", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jack", "Jack", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pumpkin", "Tête de citrouille", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapling", "Jeune pousse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Worker Bee", "Abeille ouvrière", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Block of Ice", "Bloc de glace", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen Heart", "Cœur gelé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thorny Vines", "Lianes épineuses", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spider Brood", "Couvée d'araignées", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiderling", "Petite araignée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Brother", "Premier Frère", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Second Brother", "Deuxième Frère", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third Brother", "Troisième Frère", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fourth Brother", "Quatrième Frère", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fifth Brother", "Cinquième Frère", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sixth Brother", "Sixième Frère", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spore Mold Creature", "Créature de moisissure à spores", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nihil", "Néant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of empty spaces on the board.", "La valeur de cet emblème est égale au nombre d'emplacements vides sur le plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sigil Power", "Puissance des emblèmes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the power level of this card's strongest sigil.", "La valeur de cet emblème est égale au niveau de puissance de l'emblème le plus fort de cette carte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loving Slimes", "Glus aimantes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Slimes that the owner has on their side of the table.", "La valeur de cet emblème est égale au nombre de Glus sur le côté du plateau de son propriétaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Passing Time", "Temps qui passe", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of turns that have passed since this card was placed on the board.", "La valeur de cet emblème est égale au nombre de tours écoulés depuis que cette carte a été placée sur le plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bind", "Lien", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card attacks after ally cards with less Bind. At 4 Bind, attack after opposing cards as well. Remove all Bind from this card when it attacks or on next upkeep.", "Cette carte attaque après les cartes alliées ayant moins de Lien. À 4 Liens, elle attaque aussi après les cartes ennemies. Retirez tous les Liens de cette carte lorsqu'elle attaque ou au début du prochain tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card attacks before ally cards with less Haste. At 4 Haste, attack before opposing cards as well. Remove all Haste from this card when it attacks or on next upkeep.", "Cette carte attaque avant les cartes alliées ayant moins de Hâte. À 4 Hâte, elle attaque aussi avant les cartes ennemies. Retirez toute la Hâte de cette carte lorsqu'elle attaque ou au début du prochain tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pebble", "Galet", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card regains 1 Health at the end of the owner's turn. When this card is struck, reduce the received damage by 1.", "Cette carte récupère 1 point de santé à la fin du tour de son propriétaire. Quand elle est frappée, réduisez les dégâts reçus de 1.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flagellated", "Flagellé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is struck, take damage equal to this status effect.", "Quand cette carte est frappée, elle subit des dégâts égaux à la valeur de cet effet d'état.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spores", "Spores", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of its owner's turn, this card takes damage equal to its Spores. Upon dying, create a Spore Mold Creature with stats equal to its Spores.", "Au début du tour de son propriétaire, cette carte subit des dégâts égaux à ses Spores. À sa mort, créez une Créature de moisissure à spores dont les caractéristiques sont égales à ses Spores.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Worms", "Vers", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, this card gains 1 Worms. At 5+ Worms, attack allied creatures instead with a chance to give 1 Worms to struck cards.", "Au début du tour de son propriétaire, cette carte gagne 1 point de Vers. À 5 Vers ou plus, elle attaque les créatures alliées à la place et peut donner 1 point de Vers aux cartes frappées.", Language.French);

        }
    }
    public class WhistleWindLobotomyMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for WhistleWind_Lobotomy_Mod Mod");

            //other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION II - STATUS EFFECTS {0}", "ANNEXE XII, SOUS-SECTION II - EFFETS D'ÉTAT {0}", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are no cards you can choose.", "Il n'y a aucune carte que vous puissiez choisir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't target the air.", "Vous ne pouvez pas cibler l'air.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must choose one of your other cards.", "Vous devez choisir une de vos autres cartes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's already latched...", "Il a déjà reçu une transmission...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LatchParent", "Transmission parente", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature rises from the well and joins your caravan. Ignoring the cries from the well, you hastily continue on.", "La créature sort du puits et rejoint votre caravane. Ignorant les cris provenant du puits, vous reprenez rapidement votre route.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may choose [c:bR]1[c:] to join you. The others will remain submerged and forgotten.", "Vous pouvez en choisir [c:bR]1[c:] pour vous accompagner. Les autres resteront immergés et oubliés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adoration", "Adoration", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, if Melting Love is at 1 Health, absorb the Health of adjacent Slime cards until Melting Love is at max Health.", "Au début du tour de son propriétaire, si l'Amour dissolvant a 1 point de santé, il absorbe la santé des cartes Glu adjacentes jusqu'à atteindre sa santé maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Down", "En bas", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Ye who are full of blessings, rejoice. For I am with ye.[c:]", "[c:bR]Vous qui êtes comblés de bénédictions, réjouissez-vous. Car je suis avec vous.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Thou cannot stop my ascension.[c:]", "[c:bR]Vous ne pouvez arrêter mon ascension.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]The time has come again. I will be thy guide.[c:]", "[c:bR]Le moment est revenu. Je serai votre guide.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Rise, my servants. Rise and serve me.[c:]", "[c:bR]Levez-vous, mes serviteurs. Levez-vous et servez-moi.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Thou shalt have no other gods before me.[c:]", "[c:bR]Tu n'auras pas d'autres dieux devant moi.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hands of the Clock move towards salvation.", "Les aiguilles de l'Horloge avancent vers le salut.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]When the day comes, find me.[c:]", "[c:bR]Quand le jour viendra, trouve-moi.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I will save your life from destruction and raise you from the end of the world.[c:]", "[c:bR]Je sauverai ta vie de la destruction et te relèverai à la fin du monde.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bless", "Bénir", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever Plague Doctor successfully heals another card using the Healer sigil, it changes its appearance.", "Chaque fois que le Médecin de peste soigne une autre carte avec l'emblème Guérisseur, son apparence change.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Rage", "Rage aveugle", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Servant of Wrath will target a random space on the board when attacking, prioritising occupied spaces.", "La Servante du courroux cible un emplacement aléatoire du plateau lorsqu'elle attaque, en privilégiant les emplacements occupés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CENSORED", "[CENSURÉ]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenver CENSORED kills a card, create a CENSORED in your hand with the killed card's Power, tribes, and sigils.", "Chaque fois que [CENSURÉ] tue une carte, créez dans votre main un [CENSURÉ] possédant la puissance, les tribus et les emblèmes de la carte tuée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Concord", "Concorde", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When Yang is adjacent to Yin, activate a special sequence.", "Quand Yang est adjacent à Yin, une séquence spéciale s'active.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly", "Lâche", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If there is an non-Structure ally card on the board, Scaredy Cat transforms into a stronger forme. Otherwise transform into a weaker forme.", "S'il y a sur le plateau une autre carte alliée qui n'est pas une Structure, le Chat peureux prend une forme plus forte. Sinon, il prend une forme plus faible.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Scar", "Cicatrice écarlate", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big and Will Be Bad Wolf and Red Hooded Mercenary will gain 1 Power when their counterpart is played on the board. While they're on the board, target them exclusively.", "Le Grand Loup qui sera méchant et la Mercenaire au petit chaperon rouge gagnent 1 point de puissance lorsque l'autre est joué sur le plateau. Tant que les deux sont sur le plateau, chacun cible exclusivement l'autre.", Language.French);


            //ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Monster in the Black Forest", "Monstre de la Forêt noire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Once upon a time, three birds lived happily in the lush forest...'", "« Il était une fois trois oiseaux qui vivaient heureux dans une forêt luxuriante... »", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The three birds, now one, wandered vainly looking for the monster.", "Les trois oiseaux, désormais réunis en un seul, erraient en vain à la recherche du monstre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apostle", "Apôtre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Thou wilt abandon flesh and be born again.'", "« Tu abandonneras ta chair et renaîtras. »", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Eyes", "Grands yeux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While this card is on the board, all creatures on the board are unaffected by Power-changing effects.", "Tant que cette carte est sur le plateau, toutes les créatures du plateau sont insensibles aux effets qui modifient la puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While this card is on the board, all creatures on the board are unaffected by Power-changing effects. Upon reaching 80/60/40 Health, permanently disable this effect then switch phase.", "Tant que cette carte est sur le plateau, toutes les créatures du plateau sont insensibles aux effets qui modifient la puissance. À 80/60/40 points de santé, désactivez définitivement cet effet, puis changez de phase.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Confession and Pentinence", "Confession et pénitence", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep faith with unwavering resolve.", "Gardez la foi avec une résolution inébranlable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Keep faith with unwavering resolve.[c:]", "[c:bG]Gardez la foi avec une résolution inébranlable.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dazzling", "Rayonnant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The turn after this card is played, inflict up to 3 other cards on the board with Enchanted.", "Au tour suivant la mise en jeu de cette carte, infligez Enchanté à jusqu'à 3 autres cartes du plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Like moths to a flame.", "Comme des papillons de nuit attirés par la flamme.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long Arms", "Longs bras", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card is immune to status ailments.", "Cette carte est immunisée contre les effets d'état néfastes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card is immune to status ailments. Upon reaching 80/60/40 Health, permanently disable this effect then switch phase.", "Cette carte est immunisée contre les effets d'état néfastes. À 80/60/40 points de santé, désactivez définitivement cet effet, puis changez de phase.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Misdeeds Not Allowed", "Méfaits interdits", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever this card takes damage, gain 1 Power until the end of the owner's turn.", "Chaque fois que cette carte subit des dégâts, elle gagne 1 point de puissance jusqu'à la fin du tour de son propriétaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Small Beak", "Petit bec", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the turn, target a random lane on the board.  At the start of the next turn, kill all cards in the targeted lane, excluding this card.", "Au début du tour, ciblez une voie aléatoire du plateau. Au début du tour suivant, tuez toutes les cartes de cette voie, sauf cette carte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the turn, target a random lane on the board.  At the start of the next turn, kill all cards in the targeted lane, excluding this card. Upon reaching 80/60/40 Health, permanently disable this effect then switch phase.", "Au début du tour, ciblez une voie aléatoire du plateau. Au début du tour suivant, tuez toutes les cartes de cette voie, sauf cette carte. À 80/60/40 points de santé, désactivez définitivement cet effet, puis changez de phase.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time Machine", "Machine à remonter le temps", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "End the current battle or phase then remove this card from the player's deck. The player must choose an additional card from a selection of 3 to remove from their deck. Selection is based on card power.", "Terminez le combat ou la phase en cours, puis retirez cette carte du deck du joueur. Le joueur doit choisir une carte supplémentaire parmi une sélection de 3 pour la retirer de son deck. La sélection dépend de la puissance des cartes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Close your eyes and count to ten.", "Fermez les yeux et comptez jusqu'à dix.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "True Saviour", "Véritable sauveur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'My story is nowhere, unknown to all.'", "« Mon histoire est nulle part, inconnue de tous. »", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I am death and life. Darkness and light.[c:]", "[c:bR]Je suis la mort et la vie. L'ombre et la lumière.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unjust Scale", "Balance injuste", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, inflict 1 Sin on all other cards. At the start of owner's turn, kill all other cards with 3+ Sin.", "À la fin du tour de son propriétaire, cette carte inflige 1 Péché à toutes les autres cartes. Au début du tour de son propriétaire, elle tue toutes les autres cartes ayant au moins 3 Péchés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quick Draw", "Tir rapide", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The early bird gets the worm.", "L'oiseau matinal attrape le ver.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will transform into an alternate forme after 1 turn on the board.", "Une carte ornée de cet emblème prend une autre forme après 1 tour sur le plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marksman", "Tireur d'élite", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beast strikes with precision.", "Votre bête frappe avec précision.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adding rulebook entries for special abilities.", "Ajout d'entrées au livre de règles pour les capacités spéciales.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All mod cards are disabled, adding Standard Training-Dummy Rabbit as a fallback to prevent issues.", "Toutes les cartes du mod sont désactivées ; ajout du Lapin mannequin d'entraînement standard comme solution de secours pour éviter les problèmes.", Language.French);


            //cards
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirabelle", "Mirabelle", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Apocalypse Bird", "Oiseau supérieur de l'Apocalypse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poussey", "Poussey", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stemcell-642", "Cellule souche-642", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noah", "Noah", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yumi", "Yumi", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summer", "Summer", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Currince", "Currince", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Igoree", "Igoree", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genie", "Genie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mao", "Mao", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evangeline", "Evangeline", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ttungsil", "Ttungsil", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mabel", "Mabel", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Adult Who Tells Lies", "L'adulte qui ment", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All-Around Helper", "Assistant polyvalent", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A murderous cleaning machine. Far nicer than a certain other...well, nevermind.", "Une machine de nettoyage meurtrière. Bien plus aimable qu'une certaine autre… enfin, peu importe.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alriune", "Alriune", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A doll yearning to be a human. A human yearning to be a doll.", "Une poupée qui aspire à devenir humaine. Un humain qui aspire à devenir une poupée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angela", "Angela", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A trustworthy AI assistant. You will trust her with your life.", "Une assistante IA digne de confiance. Vous lui confierez votre vie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspect of Big Bird", "Aspect du Grand oiseau", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspect of Small Bird", "Aspect du Petit oiseau", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspect of Long Bird", "Aspect de l'Oiseau long", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eyeball Chick", "Poussin aux yeux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keeper of the Black Forest", "Gardien de la Forêt noire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Runaway Bird", "Oiseau fugitif", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apocalypse Bird", "Oiseau de l'Apocalypse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guardian Apostle", "Apôtre gardien", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heretic", "Hérétique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moleman Apostle", "Apôtre homme-taupe", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scythe Apostle", "Apôtre à la faux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear Apostle", "Apôtre à la lance", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Staff Apostle", "Apôtre au bâton", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Army in Black", "Armée en noir", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Army in Pink", "Armée en rose", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friendly pink soldier. It will protect you wherever you go.", "Un soldat rose amical. Il vous protégera où que vous alliez.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backward Clock", "Horloge inversée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A clock to rewind your wasted time. Will you pay the toll?", "Une horloge pour remonter le temps que vous avez gaspillé. Accepterez-vous d'en payer le prix ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beauty and the Beast", "La Belle et la Bête", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pitiable creature. Death would be a mercy for it.", "Une créature pitoyable. La mort serait une délivrance pour elle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Behaviour Adjustment", "Correction du comportement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A device made to 'fix' errant beasts. Its idea of 'fixing' might not be yours, however.", "Un appareil conçu pour « corriger » les bêtes égarées. Sa définition de « corriger » n'est toutefois peut-être pas la vôtre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Bird", "Grand oiseau", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its eyes light up the darkness like stars.", "Ses yeux illuminent les ténèbres comme des étoiles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Binah", "Binah", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though not as powerful as she once was, she will still make a great ally.", "Bien que moins puissante qu'autrefois, elle reste une alliée précieuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodbath", "Bain de sang", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tub of blood. The hands of people you once loved wait inside.", "Une baignoire de sang. Les mains de ceux que vous avez aimés y attendent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Star", "Étoile bleue", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this is over, let's meet again as stars.", "Quand tout sera fini, retrouvons-nous sous forme d'étoiles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Burrowing Heaven", "Le Paradis fouisseur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't look away. Contain it in your sight.", "Ne détournez pas le regard. Gardez-le dans votre champ de vision.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crumpled Can of WellCheers", "Canette de WellCheers froissée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rusted Can of WellCheers", "Canette de WellCheers rouillée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Shrimp", "Crevette squelette", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Opened Can of WellCheers", "Canette de WellCheers ouverte", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A vending machine dispensing ocean soda.", "Un distributeur automatique de soda marin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CENSORED", "[CENSURÉ]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's best you never learn what it looks like.", "Il vaut mieux ne jamais découvrir à quoi il ressemble.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chesed", "Chesed", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing like a fresh cup of coffee to start your day.", "Rien de tel qu'une tasse de café frais pour commencer la journée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Child of the Galaxy", "Enfant de la galaxie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small child longing for an eternal friend. Will you be his?", "Un jeune enfant qui désire un ami éternel. Serez-vous cet ami ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crumbling Armour", "Armure en ruine", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A suit of armour that rewards the brave and punishes the cowardly.", "Une armure qui récompense les braves et punit les lâches.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Il Pianto della Luna", "Il Pianto della Luna", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In reality, man despairs at [c:bR]the moon[c:].", "En réalité, l'homme désespère devant [c:bR]la lune[c:].", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Der Freischütz", "Der Freischütz", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friendly hunter to some, a cruel gunsman to others. His bullets always hit their mark.", "Un chasseur amical pour certains, un tireur cruel pour d'autres. Ses balles atteignent toujours leur cible.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't Touch Me", "Ne me touchez pas", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't touch it.", "Ne le touchez pas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimensional Refraction Variant", "Variante de réfraction dimensionnelle", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "4th Dimensional Refraction Variant", "Variante de réfraction de 4e dimension", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange phenomenon. Or rather, the creature is the phenomena in and of itself.", "Un phénomène étrange. Ou plutôt, la créature est le phénomène lui-même.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Dreaming Current", "Le Courant rêveur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sickly child. Everyday it was fed candy that let it see the ocean.", "Un enfant malade. Chaque jour, on lui donnait un bonbon qui lui permettait de voir l'océan.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Elder Dreaming Current", "Le Courant rêveur ancestral", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dream of a Black Swan", "Rêve d'un cygne noir", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sister of six brothers. Tirelessly she worked to protect them, all for naught.", "La sœur de six frères. Elle travailla sans relâche pour les protéger, mais en vain.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Express Train to Hell", "Train express pour l'enfer", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the time comes, the train will sound its mighty horn.", "Quand le moment viendra, le train fera retentir son puissant avertisseur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fairy Festival", "Festival des fées", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will be peaceful while you're under the fairies' care.", "Tout sera paisible tant que les fées veilleront sur vous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flesh Idol", "Idole de chair", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prayer inevitably ends with the worshipper's despair.", "La prière s'achève inévitablement par le désespoir du fidèle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forsaken Murderer", "Meurtrier abandonné", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Experimented on then forgotten. What was anger has become abhorrence.", "Sujet d'expériences, puis oublié. Sa colère est devenue une haine profonde.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fragment of the Universe", "Fragment de l'univers", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You see a song in front of you. It's approaching, becoming more colourful by the second.", "Vous voyez une chanson devant vous. Elle approche et devient plus colorée à chaque seconde.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funeral of the Dead Butterflies", "Funérailles des papillons morts", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The coffin is a tribute to the fallen. A memorial to those who can't return home.", "Le cercueil rend hommage aux disparus. Un mémorial pour ceux qui ne peuvent pas rentrer chez eux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gebura", "Gebura", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Head of the Disciplinary Team. A fierce warrior and ally.", "Cheffe de l'équipe disciplinaire. Une guerrière redoutable et une alliée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Tree Sap", "Sève d'arbre géant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sap from a tree at the end of the world. It is a potent healing agent.", "De la sève d'un arbre au bout du monde. Un puissant remède.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "2nd Funeral of the Dead Butterflies", "2e Funérailles des papillons morts", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grave of Cherry Blossoms", "Tombe des cerisiers en fleurs", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blooming cherry tree. The more blood it has, the more beautiful it becomes.", "Un cerisier en fleurs. Plus il a de sang, plus il devient beau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Happy Teddy Bear", "Ours en peluche heureux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A discarded stuffed bear. Its memories began with a warm hug.", "Un ours en peluche abandonné. Ses souvenirs commencent par une étreinte chaleureuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Heart of Aspiration", "Le Cœur de l'aspiration", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A heart without an owner. It emboldens those nearby.", "Un cœur sans propriétaire. Il donne du courage à ceux qui l'entourent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hod", "Hod", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though death is guaranteed, it never hurts to be prepared, right?", "Même si la mort est certaine, il vaut toujours mieux se préparer, non ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hokma", "Hokma", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All things will happen in time. Just have faith.", "Chaque chose arrivera en son temps. Il suffit d'avoir foi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Honoured Monk", "Moine vénérable", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A monk seeking enlightenment through good deeds. But surely there's a quicker way to nirvana...", "Un moine qui cherche l'illumination par de bonnes actions. Mais il existe sûrement un chemin plus court vers le nirvana...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Sin and Hundreds of Good Deeds", "Un péché et des centaines de bonnes actions", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Jester of Nihil", "Le Bouffon du néant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Judgement Bird", "Oiseau du jugement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A long bird that judges sinners with swift efficiency. It alone is above consequences.", "Un long oiseau qui juge les pécheurs avec une efficacité expéditive. Lui seul échappe aux conséquences.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Laetitia", "Laetitia", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A little witch carrying a heart-shaped gift.", "Une petite sorcière portant un cadeau en forme de cœur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Luminous Bracelet", "Bracelet lumineux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bracelet that will heal its bearer. It does not forgive the greedy.", "Un bracelet qui soigne son porteur. Il ne pardonne pas aux avides.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Servant of Wrath", "La Servante du courroux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind protector of another world.", "Protectrice aveugle d'un autre monde.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The King of Greed", "Le Roi de l'avidité", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A girl encased in hardened amber. Happiness trapped by greed.", "Une jeune fille enfermée dans de l'ambre durci. Le bonheur prisonnier de l'avidité.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Queen of Hatred", "La Reine de la haine", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magical Girl", "Fille magique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hero of love and justice. She will aid you on your journey.", "Une héroïne de l'amour et de la justice. Elle vous aidera pendant votre voyage.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Knight of Despair", "La Chevalière du désespoir", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal knight fighting to protect those close to her.", "Une chevalière fidèle qui se bat pour protéger ses proches.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malkuth", "Malkuth", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The head of the Control Team, here to assist you any way she can.", "La cheffe de l'équipe de contrôle, prête à vous aider de toutes les façons possibles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meat Lantern", "Lanterne de chair", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A beautiful flower attached to a mysterious creature.", "Une belle fleur attachée à une créature mystérieuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Melting Love", "Amour dissolvant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let your beasts get too close now.", "Ne laissez pas vos bêtes s'approcher trop près.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1.76 MHz", "1.76 MHz", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is a record, a record of a day we must never forget.", "C'est un enregistrement, le souvenir d'un jour que nous ne devons jamais oublier.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mirror of Adjustment", "Le Miroir d'ajustement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mirror that reflects nothing on its surface.", "Un miroir dont la surface ne reflète rien.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mountain of Smiling Bodies", "La Montagne des corps souriants", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mass grave, melted and congealed into one eternally hungry beast.", "Une fosse commune, fondue et figée en une seule bête éternellement affamée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nameless Fetus", "Fœtus sans nom", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A neverending supply of blood. Just don't wake it up.", "Une source de sang inépuisable. Veillez seulement à ne pas le réveiller.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Netzach", "Netzach", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite his lack of motivation, he'll do his best to succeed.", "Malgré son manque de motivation, il fera de son mieux pour réussir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nosferatu", "Nosferatu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creature of the night, noble and regal. Will you help sate its thirst?", "Une créature de la nuit, noble et royale. L'aiderez-vous à étancher sa soif ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Notes from a Crazed Researcher", "Notes d'un chercheur dément", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An insane garble of guilty confessions and incoherent gibberish.", "Un délire insensé de confessions coupables et de paroles incohérentes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing There", "Rien du tout", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An Egg", "Un œuf", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yumi", "Yumi", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't remember this challenger...", "Je ne me souviens pas de ce challenger...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Faith and Promise", "Foi et promesse anciennes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mysterious marble. Use it without desire or expectation and you may be rewarded.", "Une bille mystérieuse. Utilisez-la sans désir ni attente et vous pourriez être récompensé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Lady", "Vieille dame", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An aged storyteller. She can tell you any tale, even those that can't exist.", "Une conteuse âgée. Elle peut raconter n'importe quelle histoire, même celles qui ne peuvent exister.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A floating skull. Its hollow sockets see through you.", "Un crâne flottant. Ses orbites vides lisent en vous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ozma", "Ozma", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The former ruler of a far away land, now reduced to this.", "L'ancienne souveraine d'un pays lointain, réduite à cet état.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasite Tree", "Arbre parasite", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A beautiful tree. It wants only to help you and your beasts.", "Un bel arbre. Il ne veut qu'aider vos bêtes et vous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pinocchio", "Pinocchio", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wooden doll that mimics the beasts it encounters. Can you see through its lie?", "Une poupée de bois qui imite les bêtes qu'elle rencontre. Saurez-vous percer son mensonge ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plague Doctor", "Médecin de peste", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A worker of miracles. He humbly requests to join you.", "Un faiseur de miracles. Il demande humblement à vous rejoindre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Porccubus", "Porccubus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A prick from one of its quills creates a deadly euphoria.", "La piqûre de l'un de ses piquants provoque une euphorie mortelle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ppodae", "Ppodae", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An innocent little puppy.", "Un innocent petit chiot.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Price of Silence", "Prix du silence", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unflinching hand of time cuts down man and beast alike.", "La main inflexible du temps abat hommes et bêtes sans distinction.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Punishing Bird", "Oiseau du châtiment", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small bird on a mission to punish evildoers.", "Un petit oiseau chargé de punir les malfaiteurs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queen Bee", "Reine des abeilles", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A monstrous amalgam of a hive and a bee.", "Un amalgame monstrueux d'une ruche et d'une abeille.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Little Red Riding Hooded Mercenary", "Mercenaire au petit chaperon rouge", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A skilled mercenary with a bloody vendetta. Perhaps you can help her sate it.", "Une mercenaire habile, animée par une vendetta sanglante. Peut-être pouvez-vous l'aider à l'assouvir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Red Shoes", "Souliers rouges", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How pretty. Maybe they'll fit.", "Comme ils sont beaux. Peut-être seront-ils à votre taille.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rudolta of the Sleigh", "Rudolta du traîneau", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A grotesque effigy of a reindeer. With its infinite hate, it bequeaths gifts onto you.", "Une effigie grotesque de renne. Dans sa haine infinie, elle vous offre des cadeaux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scaredy Cat", "Chat peureux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Schadenfreude", "Joie du malheur d'autrui", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange machine. You can feel someone's persistent gaze through the keyhole.", "Une machine étrange. À travers le trou de la serrure, vous sentez le regard insistant de quelqu'un.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scorched Girl", "Fille calcinée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though there's nothing left to burn, the fire won't go out.", "Même s'il ne reste plus rien à brûler, le feu ne s'éteint pas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shelter From the 27th of March", "Refuge du 27 mars", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It makes itself the safest place in the world by altering the reality around it.", "Il fait de lui-même le lieu le plus sûr du monde en modifiant la réalité qui l'entoure.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Silent Girl", "Fille silencieuse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A girl hiding a hammer and nail behind her back.", "Une jeune fille cache un marteau et un clou derrière son dos.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chairs", "Chaises", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Silent Orchestra", "L'Orchestre silencieux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soon, the song none can hear but all can listen to will begin.", "Bientôt commencera le chant que personne ne peut entendre, mais que tous peuvent écouter.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Singing Machine", "Machine chantante", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wind-up music machine. The song it plays is to die for.", "Une machine à musique à remontoir. Sa chanson vaut bien qu'on en meure.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skin Prophecy", "Prophétie de peau", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A holy book. Its believers wrapped it in skin to preserve its sanctity.", "Un livre sacré. Ses croyants l'ont enveloppé de peau pour préserver sa sainteté.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Snow Queen", "La Reine des neiges", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A queen from far away. Those who enter her palace never leave.", "Une reine venue de loin. Ceux qui entrent dans son palais n'en ressortent jamais.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snow White's Apple", "La Pomme de Blanche-Neige", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A poisoned apple brought to life, on a fruitless search for its own happily ever after.", "Une pomme empoisonnée qui a pris vie et cherche en vain sa propre fin heureuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snow White's Rotted Apple", "La Pomme pourrie de Blanche-Neige", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spider Bud", "Bourgeon d'araignée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A grotesque mother of spiders. Its children are small but grow quickly.", "Une mère araignée grotesque. Ses petits sont minuscules, mais grandissent vite.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Firebird", "L'Oiseau de feu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bird that longs for the thrill of being hunted.", "Un oiseau qui aspire au frisson de la chasse dont il est la proie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Little Prince", "Le Petit Prince", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A giant mushroom chunk. A mist of spores surrounds it.", "Un énorme morceau de champignon. Une brume de spores l'entoure.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Naked Nest", "Le Nid nu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They can enter your body through any aperture.", "Ils peuvent entrer dans votre corps par n'importe quel orifice.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Naked Worm", "Ver nu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It can enter your body through any aperture.", "Il peut entrer dans votre corps par n'importe quel orifice.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Theresia", "Theresia", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An old music box. It plays a familiar melody.", "Une vieille boîte à musique. Elle joue une mélodie familière.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Road Home", "Le Chemin du retour", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A young girl on a quest to return home with her friends.", "Une jeune fille qui cherche à rentrer chez elle avec ses amis.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiphereth", "Tiphereth", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of a pair of twins. Don't underestimate her capabilities.", "L'une de deux jumelles. Ne sous-estimez pas ses capacités.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Shy Look", "Regard timide du jour", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An indecisive creature. Her expression is different whenever you draw her.", "Une créature indécise. Son expression change chaque fois que vous piochez sa carte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tomorrow's Shy Look", "Regard timide de demain", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Happy Look", "Regard heureux du jour", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tomorrow's Happy Look", "Regard heureux de demain", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tomorrow's Angry Look", "Regard furieux de demain", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Angry Look", "Regard furieux du jour", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Standard Training-Dummy Rabbit", "Lapin mannequin d'entraînement standard", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A beast in the shape of a training dummy. The safest of these abnormal creatures.", "Une bête en forme de mannequin d'entraînement. La plus sûre de ces créatures anormales.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Single Recall", "Rappel unique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Total Recall", "Rappel total", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reshuffle Decks", "Remélanger les decks", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Dream", "Rêve du néant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sleeping goat. Or is it a sheep?", "Une chèvre endormie. Ou est-ce un mouton ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Lady Facing the Wall", "La Dame face au mur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A deep sorrow, grown to obsession. Perhaps it's best to leave her be.", "Un chagrin profond devenu obsession. Peut-être vaut-il mieux la laisser tranquille.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Elder Lady Facing the Wall", "La Dame face au mur (forme ancestrale)", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warm-Hearted Woodsman", "Bûcheron au grand cœur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tin woodsman on the search for a heart. Perhaps you can give him yours.", "Un bûcheron de fer-blanc en quête d'un cœur. Peut-être pouvez-vous lui offrir le vôtre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We Can Change Anything", "Nous pouvons tout changer", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever you're dissatisfied with, this machine will fix it. You just have to step inside.", "Quoi qu'il vous déplaise, cette machine le corrigera. Il vous suffit d'entrer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WhiteNight", "Nuit blanche", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The time has come.", "Le moment est venu.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big and Will Be Bad Wolf", "Grand Loup qui sera méchant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's the fate of all wolves to be the villains of fairy tales.", "Le destin de tous les loups est d'être les méchants des contes de fées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scarecrow Searching for Wisdom", "Épouvantail en quête de sagesse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hollow-headed scarecrow. Blood soaks its straw limbs.", "Un épouvantail à la tête creuse. Ses membres de paille sont imbibés de sang.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Portrait of Another World", "Portrait d'un autre monde", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This portrait captures a moment, one we're destined to lose.", "Ce portrait capture un instant que nous sommes destinés à perdre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yang", "Yang", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A white pendant that heals those nearby.", "Un pendentif blanc qui soigne ceux qui l'entourent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yesod", "Yesod", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The head of the Information Department. Incompetence will not be tolerated.", "Le responsable du service d'information. L'incompétence ne sera pas tolérée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yin", "Yin", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A black pendant in search of its missing half.", "Un pendentif noir à la recherche de sa moitié perdue.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You Must Be Happy", "Vous devez être heureux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those that undergo the procedure find themselves rested and healthy again.", "Ceux qui subissent la procédure se retrouvent reposés et en bonne santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're Bald...", "Vous êtes chauve...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've always wondered what it's like to be bald.", "Je me suis toujours demandé ce que ça faisait d'être chauve.", Language.French);


            //talkingcards
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The human heart is black, and must be cleaned.", "Le cœur humain est noir et doit être purifié.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hand rises from the scarlet pool.", "Une main émerge du bassin écarlate.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another pale hand emerges.", "Une autre main pâle apparaît.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A third hand reaches out, as if asking for help.", "Une troisième main se tend, comme pour demander de l'aide.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What have you done to my beast?", "Qu'avez-vous fait à ma bête ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At long last, she has found him.", "Après si longtemps, elle l'a enfin trouvé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That familiar red cloth...", "Ce tissu rouge familier...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desire unfulfilled, the koi continues for Eden.", "Son désir inassouvi, la carpe koï poursuit sa route vers l'Éden.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Having failed to protect again, the knight fell once more to despair.", "Après avoir encore échoué à protéger les siens, la chevalière sombra de nouveau dans le désespoir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The balance must be maintained. Good cannot exist without evil.", "L'équilibre doit être préservé. Le bien ne peut exister sans le mal.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They give themselves lovingly.", "Ils se donnent avec amour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With each body added, its appetite grows.", "À chaque corps ajouté, son appétit grandit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't worry, bodies are in no short supply.", "Ne vous inquiétez pas, les corps ne manquent pas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you cut into the beast's flesh, it lets out a piercing cry.", "Lorsque vous entamez la chair de la bête, elle pousse un cri perçant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is that thing?", "Qu'est-ce que c'est que cette chose ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems to be trying to mimic you. 'Trying' is the key word.", "Elle semble essayer de vous imiter. « Essayer » est le mot important.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is it doing?", "Que fait-elle ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hands of the Clock move towards salvation.", "Les aiguilles de l'Horloge avancent vers le salut.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A formidable attack. Shame it has left her too tired to defend herself.", "Une attaque redoutable. Dommage qu'elle l'ait trop fatiguée pour se défendre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The monster returns to full strength.", "Le monstre retrouve toute sa force.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abandoned and betrayed, she rages against her own failure.", "Abandonnée et trahie, elle s'emporte contre son propre échec.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Some days you don't feel like smiling.", "Certains jours, on n'a pas envie de sourire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There was no place for frowns in the City.", "Les mines renfrognées n'avaient pas leur place dans la Cité.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unable to decide what face to wear, she became shy again.", "Incapable de choisir quelle expression adopter, elle redevint timide.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now you become the sky, and I the land.", "Maintenant tu deviens le ciel, et moi la terre.", Language.French);

            //Angela_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A decrepit old man.", "Un vieil homme décrépit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I believe that pack animal", "Je crois que cette bête de somme", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "will aid us with its death.", "nous aidera par sa mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you wonder if he ever bathes?", "Vous demandez-vous s'il se lave un jour ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should know what to do by now.", "Vous devriez savoir quoi faire maintenant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He appears to have a simple mind.", "Il semble avoir l'esprit simple.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can easily manipulate him.", "Nous pouvons facilement le manipuler.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish are a lot like people, aren't they?", "Les poissons ressemblent beaucoup aux gens, non ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I recommend holding your breath.", "Je vous conseille de retenir votre souffle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone has a different side to them.", "Chacun a plusieurs facettes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you think, manager?", "Vous ne trouvez pas, directeur ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't die manager.", "Ne mourez pas, directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for traps.", "Attention aux pièges.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Does the cold bother you?", "Le froid vous dérange-t-il ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We appear to have reached the end.", "Nous semblons avoir atteint la fin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I expect you to conquer this challenge", "Je m'attends à ce que vous surmontiez ce défi", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "quite easily, manager.", "très facilement, directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A final trial for you, manager.", "Une dernière épreuve pour vous, directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It has been quite the journey, yes?", "Quel voyage, n'est-ce pas ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...do not expect a comment from me.", "... N'attendez aucun commentaire de ma part.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do not be deceived.", "Ne vous laissez pas tromper.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He is not an abnormality.", "Ce n'est pas une anomalie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unloyal crew...", "Un équipage déloyal...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He reminds me of you", "Il me rappelle vous", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "in a way.", "d'une certaine façon.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This threat may be beyond you.", "Cette menace est peut-être au-delà de vos forces.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We kept them separated for", "Nous les avons gardés séparés", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this reason, manager.", "pour cette raison, directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello manager.", "Bonjour, directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shall we get going?", "On y va ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am here to assist you.", "Je suis là pour vous aider.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gotten yourself in trouble?", "Vous avez des ennuis ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can rely on me.", "Vous pouvez compter sur moi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you.", "Merci.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try not to make a mess.", "Essayez de ne pas mettre le désordre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's hurry this up, yes?", "Dépêchons-nous, d'accord ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing I can't overcome.", "Rien que je ne puisse surmonter.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see.", "Je vois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reminds me of the facility.", "Ça me rappelle le complexe.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No point in hesitating.", "Inutile d'hésiter.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "Il faut faire des sacrifices.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing you should be uncomfortable with.", "Rien qui devrait vous mettre mal à l'aise.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A golden opportunity.", "Une occasion en or.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I expect you to know the best choice.", "Je compte sur vous pour faire le meilleur choix.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I leave it to your discretion.", "Je vous laisse décider.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must all overcome ordeals in life.", "Nous devons tous surmonter des épreuves dans la vie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You taught me that.", "C'est vous qui me l'avez appris.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You wouldn't fail so easily, right?", "Vous n'échoueriez pas si facilement, n'est-ce pas ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No point in dilly-dallying now.", "Inutile de traîner davantage.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yet another obstacle in my way...", "Encore un obstacle sur mon chemin...", Language.French);

            //ApocalypseBird_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let me tell you a story. The story of the [c:bR]Black Forest[c:].", "Laissez-moi vous raconter une histoire. Celle de la [c:bR]Forêt noire[c:].", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The three birds, [c:bR]now one[c:] looked around for [c:bR]the Beast[c:]. But there was nothing.", "Les trois oiseaux, [c:bR]désormais réunis en un seul[c:], cherchèrent [c:bR]la Bête[c:] autour d'eux. Mais il n'y avait rien.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No creatures. No beast. No sun or moon or stars. Only a single bird, alone in an empty forest.", "Aucune créature. Aucune bête. Ni soleil, ni lune, ni étoiles. Un seul oiseau, seul dans une forêt vide.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once upon a time, [c:bR]three birds[c:] lived happily in the lush Forest with their fellow animals.", "Il était une fois [c:bR]trois oiseaux[c:] qui vivaient heureux dans la forêt luxuriante avec les autres animaux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One day a stranger arrived at the Forest. He proclaimed that the Forest would soon be ensared in a bitter conflict.", "Un jour, un étranger arriva dans la forêt. Il annonça qu'elle serait bientôt prise dans un conflit acharné.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One that would only end when everything was devoured by a [c:bR]terrible Beast[c:].", "Un conflit qui ne prendrait fin que lorsque tout aurait été dévoré par une [c:bR]terrible Bête[c:].", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The birds, frightened by this doomsay, sought to prevent conflict from ever breaking out.", "Effrayés par cette prophétie funeste, les oiseaux voulurent empêcher tout conflit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fights began to break out. More and more creatures left the Forest, no matter how hard the birds worked.", "Les combats éclatèrent. De plus en plus de créatures quittaient la forêt, quels que soient les efforts des oiseaux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They decided to combine their powers. This way, they could better protect their home.", "Ils décidèrent d'unir leurs pouvoirs. Ainsi, ils pourraient mieux protéger leur foyer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This way they could better return the peace.", "Ainsi, ils pourraient mieux ramener la paix.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Darkness fell upon the forest. Mayhem ran amok as creatures screamed in terror at the towering bird.", "L'obscurité tomba sur la forêt. Le chaos se déchaîna et les créatures crièrent de terreur devant l'oiseau gigantesque.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Someone yelled out [c:bB]'It's the Beast! A big, scary monster lives in the Black Forest!'[c:]", "Quelqu'un cria : [c:bB]« C'est la Bête ! Un grand monstre terrifiant vit dans la Forêt noire ! »[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Big Bird[c:] with his many eyes kept constant watch over the entire Forest.", "Avec ses nombreux yeux, [c:bG]Grand oiseau[c:] surveillait sans cesse toute la forêt.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bSG]Long Bird[c:] weighed the sins of all creatures in the forest with his scales.", "[c:bSG]Oiseau long[c:] pesait les péchés de toutes les créatures de la forêt sur sa balance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Small Bird[c:] punished wrongdoers with his beak.", "[c:bR]Petit oiseau[c:] punissait les malfaiteurs avec son bec.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You walk down into a large clearing, the black trees crowding around you.", "Vous descendez dans une grande clairière, entouré d'arbres noirs et serrés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An otherworldly roar brings you to attention. The very earth quails in fear as something approaches you.", "Un rugissement d'un autre monde attire votre attention. La terre elle-même tremble de peur tandis que quelque chose approche.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lumbering yet impossibly fast, you find yourself face-to-face with...", "Malgré sa démarche lourde, la chose est incroyablement rapide, et vous vous retrouvez face à face avec...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An otherworldly roar shakes you to your core. The forest floor quakes as something approaches you.", "Un rugissement d'un autre monde vous ébranle jusqu'au plus profond de vous-même. Le sol de la forêt tremble alors que quelque chose approche.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]The Beast[c:].", "[c:bR]La Bête[c:].", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The far-sighted eyes have been blinded.", "Les yeux qui voyaient au loin ont été aveuglés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The head that looked to the cosmos has been lowered.", "La tête qui regardait vers le cosmos s'est abaissée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mouth that devours everything has been shut.", "La bouche qui dévore tout s'est refermée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]The monster[c:] is not so easily tamed.", "[c:bR]Le monstre[c:] ne se laisse pas dompter si facilement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your efforts prove futile.", "Vos efforts se révèlent vains.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Beast is [c:bR]immune to mortal damage[c:].", "La Bête est [c:bR]immunisée contre les dégâts mortels[c:].", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yet even it has its weaknesses.", "Et pourtant, même elle a ses faiblesses.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gather your courage, and march onward.", "Rassemblez votre courage et avancez.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bSG]Into the twilight.[c:]", "[c:bSG]Dans le crépuscule.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mouth that devours everything opens.", "La bouche qui dévore tout s'ouvre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Small Bird's beak whispered endlessly.", "Le bec du Petit oiseau murmurait sans fin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beast's maw snaps shut on empty air.", "La gueule de la Bête se referme brusquement sur le vide.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Big Bird's eyes imprisoned light...", "Les yeux du Grand oiseau emprisonnaient la lumière...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...and they burned like stars.", "... et ils brûlaient comme des étoiles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...but there was nothing to behold.", "... mais il n'y avait rien à contempler.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Long Bird's arms concealed time...", "Les bras de l'Oiseau long dissimulaient le temps...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...yet sins continued day after day.", "... pourtant les péchés continuaient jour après jour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Beast senses your hunger, and grows more daring.", "La Bête sent votre faim et devient plus audacieuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Beast begins to grow desperate.", "La Bête commence à perdre espoir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your power angers the Beast.", "Votre puissance met la Bête en colère.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Beast grows more aggressive.", "La Bête devient plus agressive.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Beast's strength grows beyond imagination...", "La force de la Bête dépasse l'imagination...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Beast's hide hardens under your creatures' claws.", "La peau de la Bête durcit sous les griffes de vos créatures.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Beast and its ilk move quickly and frequently. Use these to reposition your creatures.", "La Bête et ses semblables se déplacent vite et souvent. Servez-vous de ces moyens pour repositionner vos créatures.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returned creatures will have their cost changed based on how recently you played them.", "Le coût des créatures renvoyées change selon le temps écoulé depuis que vous les avez jouées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Newly played creatures will cost [c:bR]2 Bones[c:] to play again.", "Les créatures jouées récemment coûteront [c:bR]2 os[c:] à rejouer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will reduce their recall cost over time, until they become [c:bR]free[c:] to replay.", "Je réduirai progressivement leur coût de rappel jusqu'à ce que vous puissiez les rejouer [c:bR]gratuitement[c:].", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use these to reposition your creatures, for a cost.", "Servez-vous de ces moyens pour repositionner vos créatures, moyennant un coût.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why don't we continue a little longer?", "Pourquoi ne pas continuer encore un peu ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beast is immune to mortal damage.", "La Bête est immunisée contre les dégâts mortels.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excess injury will instead yield you up to [c:bR]2[c:] bones.", "Les blessures excédentaires vous rapportent jusqu'à [c:bR]2[c:] os.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't worry about running dry, the ground you walk on is full of them.", "Ne craignez pas d'en manquer : le sol sous vos pieds en est rempli.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ground is full of bones.", "Le sol est rempli d'os.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backed into a corner, the Beast releases one final burst of strength.", "Acculée, la Bête libère une dernière poussée de force.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the Beast attacks a space marked in [c:bR]red[c:], it will deal twice the normal damage.", "Quand la Bête attaque un emplacement marqué en [c:bR]rouge[c:], elle inflige le double des dégâts habituels.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the Beast attacks a space marked in [c:bSG]white[c:], it will deal half the normal damage, but regain vitality.", "Quand la Bête attaque un emplacement marqué en [c:bSG]blanc[c:], elle inflige la moitié des dégâts habituels, mais récupère de la vitalité.", Language.French);

            //BackwardClock
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Close your eyes and count to ten.", "Fermez les yeux et comptez jusqu'à dix.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When you open them, you will be standing at the exact moment you wish to be in.", "Quand vous les ouvrirez, vous vous trouverez exactement au moment désiré.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]One of your creatures[c:] must stay behind to operate [c:bR]the Clock[c:].", "[c:bR]Une de vos créatures[c:] doit rester pour faire fonctionner [c:bR]l'Horloge[c:].", Language.French);

            //Binah_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deal with those beasts quickly.", "Occupez-vous vite de ces bêtes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small obstacle.", "Un petit obstacle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let us begin.", "Commençons.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't lose your appetite now.", "Ne perdez pas l'appétit maintenant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I grow tired of fish.", "Je commence à en avoir assez du poisson.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must enjoy the stench.", "Vous devez apprécier cette puanteur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another two-faced deceiver.", "Encore un imposteur à double visage.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one helps you without a price.", "Personne ne vous aide sans contrepartie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be wary of where your foot falls.", "Prenez garde où vous posez le pied.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems we have reached the conclusion.", "Il semble que nous ayons atteint la conclusion.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are we doing this again?", "On recommence ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have fought stronger foes.", "J'ai affronté des adversaires plus forts.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is this?", "Qu'est-ce que c'est ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A captain of a sunken vessel.", "Le capitaine d'un navire englouti.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His crew has no loyalty.", "Son équipage n'a aucune loyauté.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have wandered into a dangerous place.", "Vous avez pénétré dans un lieu dangereux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you think yourself immortal?", "Vous croyez-vous immortel ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quite the marvelous beast, isn't it?", "Quelle bête merveilleuse, n'est-ce pas ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have entered its lair once more.", "Vous êtes revenu dans son antre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must have a death wish.", "Vous devez avoir envie de mourir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I do enjoy this place.", "J'aime bien cet endroit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well look who it is.", "Eh bien, regardez qui voilà.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose.", "Choisissez.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be calm.", "Restez calme.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miss me?", "Je vous ai manqué ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Countless stars light the sky today.", "D'innombrables étoiles illuminent le ciel aujourd'hui.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your outlook is what decides things.", "Votre façon de voir les choses décide de leur issue.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am curious to see", "Je suis curieux de voir", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what memories you yielded.", "quels souvenirs vous avez donnés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excellent.", "Excellent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have done well.", "Vous avez bien agi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This power is incomplete.", "Cette puissance est incomplète.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "More bodies to clean.", "Encore des corps à nettoyer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The closer to death, the freer you are.", "Plus vous êtes proche de la mort, plus vous êtes libre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you think you could avoid it?", "Pensiez-vous pouvoir l'éviter ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is nearing the end.", "La fin approche.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your breath is fading.", "Votre souffle s'affaiblit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one will blame you.", "Personne ne vous en voudra.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inching closer to wholeness.", "Nous nous rapprochons peu à peu de la plénitude.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you up to the task?", "Êtes-vous à la hauteur ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tis an ordeal to overcome.", "C'est une épreuve à surmonter.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no obstacle you can't overcome.", "Il n'y a aucun obstacle que vous ne puissiez surmonter.", Language.French);

            //Chesed_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many animals~", "Tant d'animaux~", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So much dust.", "Tant de poussière.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do we have to fight?", "Devons-nous nous battre ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's an impressive hook there~.", "Quel crochet impressionnant~", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you feeling hungry?", "Vous avez faim ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm used to the stench of decay by now.", "Je suis maintenant habitué à l'odeur de la décomposition.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an odd fellow.", "Quel étrange individu.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What tricks are up their sleeve?", "Quels tours ont-ils dans leur manche ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing like a cup of coffee", "Rien de tel qu'une tasse de café", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to keep you warm~", "pour vous réchauffer~", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've come so far...", "Nous avons fait tant de chemin...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "just a little more now.", "encore un petit effort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you prepared manager?", "Êtes-vous prêt, directeur ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can't hesitate now.", "Nous ne pouvons pas hésiter maintenant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pirate? How fun~", "Un pirate ? Comme c'est amusant~", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch your head now.", "Attention à votre tête.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one...", "Celui-ci...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope you're prepared.", "J'espère que vous êtes prêt.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I worry you have a death wish.", "J'ai peur que vous ayez envie de mourir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are we really doing this?", "Est-ce vraiment ce que nous allons faire ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey~ manager.", "Hé~ directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Off on a nice stroll?", "Vous partez pour une belle promenade ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who will it be this time~?", "À qui le tour cette fois~ ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sure we can do this well.", "Je suis sûr que nous pouvons bien faire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's try our best, yeah?", "Faisons de notre mieux, d'accord ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't overwork yourself~", "Ne vous épuisez pas trop~", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey, thanks~", "Hé, merci~", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was smooth~", "C'était fluide~", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess I gotta work harder", "Je suppose que je dois redoubler d'efforts", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "in their stead, huh?", "à leur place, hein ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How about a nice cup of coffee?", "Que diriez-vous d'une bonne tasse de café ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah!", "Ah !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm.", "Hum.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tch.", "Tss.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't want anyone to die here.", "Je ne veux pas que quelqu'un meure ici.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If there's a meaning to this fight...", "Si ce combat a un sens...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No choice but to stand our ground.", "Nous n'avons pas d'autre choix que de tenir bon.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All this effort wasted on fighting.", "Tous ces efforts gaspillés à se battre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess this is as far as I can go...", "Je suppose que je ne peux pas aller plus loin...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "Ah...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heh...", "Hé...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "See you in Hell.", "On se retrouve en enfer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm...", "Hmm...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This again?", "Encore ça ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can lose everything", "Nous pouvons tout perdre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if we hesitate.", "si nous hésitons.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'd hate for us to suffer even more.", "Je ne voudrais pas que nous souffrions encore plus.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This looks promising~", "Ça s'annonce prometteur~", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, this again~", "Oh, encore ça~", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wouldn't mind a nice of cup of coffee now.", "Une bonne tasse de café ne serait pas de refus.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who will it be~?", "À qui le tour~ ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sometimes, you have to get bold", "Parfois, il faut oser", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "in order to protect something.", "pour protéger quelque chose.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing we haven't seen before.", "Rien que nous n'ayons déjà vu.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sure this will go well.", "Je suis sûr que ça se passera bien.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's do our best and finish the job~", "Donnons tout et terminons le travail~", Language.French);

            //Gebura_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who's this geezer?", "Qui est ce vieux bonhomme ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This guy...", "Ce type...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a pain.", "Quel casse-pieds.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's make quick work of him.", "Réglons vite son compte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This stench takes me back.", "Cette puanteur me rappelle des souvenirs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch that hook there.", "Attention à ce crochet.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep on your toes now.", "Restez sur vos gardes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These traps are annoying.", "Ces pièges sont agaçants.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clear a path and strike cleanly.", "Dégagez la voie et frappez net.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing left but to continue forward.", "Il ne reste qu'à avancer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've got this.", "Nous allons y arriver.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One more enemy left.", "Il ne reste qu'un ennemi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not the strangest thing I've seen.", "Ce n'est pas la chose la plus étrange que j'aie vue.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be quick and avoid those cannons.", "Soyez rapide et évitez ces canons.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His goons are tougher than they look.", "Ses sbires sont plus coriaces qu'ils n'en ont l'air.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why have you come here?", "Pourquoi êtes-vous venu ici ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You trying to die?", "Vous cherchez à mourir ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let me handle this.", "Laissez-moi m'en charger.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These stupid birds...", "Ces oiseaux stupides...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't chicken out now.", "Ne reculez pas maintenant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manager.", "Directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey manager.", "Hé, directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not as strong as I used to be.", "Je ne suis plus aussi fort qu'avant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still not used to it.", "Je ne m'y suis toujours pas habitué.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let your strength get to your head.", "Ne laissez pas votre force vous monter à la tête.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always keep a cool head.", "Gardez toujours la tête froide.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm starting to get accustomed", "Je commence à m'habituer", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to this new body.", "à ce nouveau corps.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't waste this strength.", "Je ne gaspillerai pas cette force.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks.", "Merci.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kch.", "Tch.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bastard.", "Salaud.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That all?", "C'est tout ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wasn't so feeble before...", "Je n'étais pas aussi faible avant...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's beat these guys into submission.", "Bastonnons-les jusqu'à ce qu'ils se rendent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's do this.", "Allons-y.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We mustn't falter just yet.", "Nous ne devons pas encore faiblir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We'll talk after everything's over.", "Nous parlerons quand tout sera terminé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let it be in vain, yeah?", "Ne laissez pas tout cela être vain, d'accord ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't like this...", "Je n'aime pas ça...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wayward wrath will only ruin yourself.", "Une colère incontrôlée ne fera que vous détruire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know this isn't just a silly game, right?", "Vous savez que ce n'est pas qu'un jeu stupide, n'est-ce pas ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind where you point your blade.", "Faites attention où vous pointez votre lame.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not a chance.", "Aucune chance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This looks like a good opportunity.", "Ça ressemble à une bonne occasion.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess I'll cop a nap.", "Je crois que je vais piquer un somme.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another opportunity, huh?", "Encore une occasion, hein ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't take it for granted.", "Ne le tenez pas pour acquis.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A test of some sort?", "Une sorte d'épreuve ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let me have a go.", "Laissez-moi essayer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's work together", "Travaillons ensemble", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and give it our best shot.", "et donnons le meilleur de nous-mêmes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I defer to your judgement.", "Je m'en remets à votre jugement.", Language.French);

            //Hod_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for that pickaxe.", "Attention à cette pioche.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've prepared for this.", "Nous nous y sommes préparés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll follow your lead.", "Je suivrai votre exemple.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Urk, the smell...", "Beurk, cette odeur...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's get out of here quickly...", "Sortons vite d'ici...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't knock over those buckets.", "Ne renversez pas ces seaux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A betrayal...", "Une trahison...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll trust you, manager.", "Je vous fais confiance, directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many pelts...", "Tant de fourrures...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The moon's so large...", "La lune est si grande...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can do this.", "Nous pouvons y arriver.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're a lot stronger than before.", "Nous sommes bien plus forts qu'avant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pirate...skeleton?", "Un pirate… squelette ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those cannons hurt a lot...", "Ces canons font vraiment mal...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That monster...", "Ce monstre...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do we do?", "Que fait-on ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep calm...keep calm...", "Du calme… du calme...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember our training.", "Souvenez-vous de notre entraînement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh! Um...", "Oh ! Euh...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello manager.", "Bonjour, directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't be a hindrance!", "Je ne serai pas un obstacle !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who do you choose?", "Qui choisissez-vous ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not that skilled...", "Je ne suis pas si doué...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "but I'll do my best!", "mais je ferai de mon mieux !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll try not to be a hindrance.", "Je vais essayer de ne pas gêner.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If we prepare, we can overcome this.", "Si nous nous préparons, nous pouvons surmonter cela.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm here to do my best.", "Je suis là pour donner le meilleur de moi-même.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I still have a lot to improve on...", "J'ai encore beaucoup à améliorer...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I gotta get on everyone else's level.", "Je dois me mettre au niveau des autres.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this I can better help everyone.", "Avec ça, je peux mieux aider tout le monde.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope this helps.", "J'espère que cela aidera.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah!", "Ah !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ow!", "Aïe !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I-I can take it...", "J-je peux tenir...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't let them down...", "Je ne peux pas les décevoir...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I’m nervous, but...", "Je suis nerveux, mais...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't let you down...!", "Je ne vous décevrai pas... !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't let you down!", "Je ne vous décevrai pas !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope nothing bad happens.", "J'espère que rien de grave ne se produira.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alright, here I come!", "D'accord, j'arrive !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will work out...", "Tout s'arrangera...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe...", "Peut-être...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If we brace ourselves, we can win this.", "Si nous nous préparons, nous pouvons gagner.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can do this.", "Je peux le faire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I was nothing but trouble...", "Je n'ai fait que causer des ennuis...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My body feels numb...", "Mon corps est engourdi...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I should've done a better job.", "J'aurais dû faire mieux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't like this...", "Je n'aime pas ça...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe someone else can go?", "Quelqu'un d'autre peut peut-être y aller ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't...not again...", "Je ne peux pas… pas encore...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need me, right?", "Vous avez besoin de moi, n'est-ce pas ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's think about this...", "Réfléchissons...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If it will make me more helpful...", "Si cela peut me rendre plus utile...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will this give me my courage?", "Cela me donnera-t-il du courage ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A trial?", "Une épreuve ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope I can help.", "J'espère pouvoir aider.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope I'm prepared.", "J'espère être prêt.", Language.French);

            //Hokma_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is no different from anything else.", "Ce n'est pas différent du reste.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've done this before.", "Nous l'avons déjà fait.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must move onward.", "Nous devons avancer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can endlessly question", "Nous pouvons nous demander sans fin", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "why we must endure this endeavour.", "pourquoi nous devons endurer cette épreuve.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take all possibilities", "Prenez toutes les possibilités", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "into consideration.", "en considération.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's work quickly now.", "Travaillons rapidement maintenant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His madness can be used to our advantage.", "Nous pouvons tirer avantage de sa folie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bend the rules to your favour.", "Pliez les règles en votre faveur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let the snow blind you.", "Ne laissez pas la neige vous aveugler.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We are all bound by something greater.", "Nous sommes tous liés par quelque chose de plus grand.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He is no exception.", "Il ne fait pas exception.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If we focus, victory is assured.", "Si nous restons concentrés, la victoire est assurée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will happen as it should.", "Tout arrivera comme il se doit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...I admit I am caught off-guard.", "... J'avoue être pris au dépourvu.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In the end, this is all a pointless errand.", "Au bout du compte, ce n'est qu'une tâche inutile.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cannons are slow.", "Les canons sont lents.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can easily avoid them.", "Nous pouvons facilement les éviter.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every Goliath has its David.", "À chaque Goliath son David.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have faith in yourself, and in us.", "Ayez foi en vous et en nous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings manager.", "Salutations, directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is work to be done.", "Il y a du travail à faire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What matters more than strength...", "Ce qui compte plus que la force...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "is faith in our victory.", "c'est la foi en notre victoire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stay true to your belief.", "Restez fidèle à votre conviction.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have come to the point", "Vous avez atteint le point", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "of no return.", "de non-retour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It begins once more.", "Cela recommence.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will help greatly.", "Cela sera d'une grande aide.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let us begin the day.", "Commençons la journée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overconfidence is the greatest enemy.", "L'excès de confiance est le pire ennemi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's hurry to finish this work.", "Dépêchons-nous de terminer ce travail.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pointless errand.", "Une tâche inutile.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An opportunity presents itself.", "Une occasion se présente.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be prudent about this.", "Soyez prudent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have faith in your decision.", "J'ai confiance en votre décision.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boundless pride and ambition", "L'orgueil et l'ambition sans limites", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "will bring about a bitter end...", "mèneront à une fin amère...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do not be hasty.", "Ne vous précipitez pas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no halting now.", "On ne peut plus s'arrêter.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An endless series of trials.", "Une série d'épreuves sans fin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have faith in yourself and us.", "Ayez foi en vous et en nous.", Language.French);

            //JesterOfNihil
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch them carefully.", "Observez-les attentivement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They're calling - no, praying for something.", "Ils appellent… non, ils prient pour quelque chose.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There was no way to know if they had gathered to become [c:gray]the Jester[c:],", "On ne pouvait savoir s'ils s'étaient rassemblés pour devenir [c:gray]le Bouffon[c:],", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "or if [c:gray]the Jester[c:] had come to resemble them.", "ou si [c:gray]le Bouffon[c:] avait fini par leur ressembler.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:gray]The Jester[c:] retraced the steps of a path everyone would've taken.", "[c:gray]Le Bouffon[c:] retraçait les pas d'un chemin que tout le monde aurait emprunté.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter what it did, the Jester always found itself at the end of that road.", "Quoi qu'il fasse, le Bouffon se retrouvait toujours au bout de cette route.", Language.French);

            //LyingAdult
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long ago, there was a city made of shining emerald.", "Il y a longtemps, il existait une ville faite d'émeraude étincelante.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruled by the princess [c:bR]Ozma[c:], it was home to many otherworldly splendors.", "Gouvernée par la princesse [c:bR]Ozma[c:], elle abritait de nombreuses merveilles venues d'ailleurs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One day, an adult named [c:g1]Oz[c:] arrived to the Emerald City.", "Un jour, une adulte nommée [c:g1]Oz[c:] arriva à la Cité d'émeraude.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looking upon the brilliant city, she came up with a brilliant plan.", "En contemplant cette ville brillante, elle eut une brillante idée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soon, [c:g1]Oz[c:] came to be known as a wizard by the people.", "Bientôt, les habitants connurent [c:g1]Oz[c:] comme une sorcière.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing is as deceptive as evident truth.", "Rien n'est plus trompeur qu'une vérité évidente.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unable to ever go back home, they began an endless journey.", "Ne pouvant plus jamais rentrer chez eux, ils entamèrent un voyage sans fin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]I’ll make your wishes come true. What do you wish for?[c:]", "[c:g1]Je réaliserai vos souhaits. Que désirez-vous ?[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor [c:bR]Ozma[c:] didn’t know that lying adults don’t approach others without reason.", "La pauvre [c:bR]Ozma[c:] ignorait que les adultes menteurs n'approchent pas les autres sans raison.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Last of all, road that is lost. I will send you home.[c:]", "[c:g1]Enfin, chemin égaré. Je te ramènerai chez toi.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]What are you fighting for so fiercely when you have nowhere to go back to?[c:]", "[c:g1]Pour quoi te bats-tu avec tant d'ardeur, alors que tu n'as nulle part où retourner ?[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Poor stuffing of straw. I'll give you the wisdom to ponder over anything.[c:]", "[c:g1]Pauvre être bourré de paille. Je te donnerai la sagesse de réfléchir à toute chose.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Do you think jabbering away with your oh-so smart mouth is all that matters?[c:]", "[c:g1]Crois-tu qu'il suffit de bavarder avec ta bouche si intelligente ?[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Cowardly kitten, I'll give you the courage to stand up to anything and everything.[c:]", "[c:g1]Petit chat peureux, je te donnerai le courage d'affronter tout et n'importe quoi.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]What are you even going to do when you lack the bravery to face anything head-on?[c:]", "[c:g1]Que comptes-tu faire sans le courage d'affronter quoi que ce soit ?[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Tin-cold woodsman. I'll give you the heart to forgive and love anyone.[c:]", "[c:g1]Bûcheron froid comme l'étain. Je te donnerai un cœur capable de pardonner et d'aimer tous les êtres.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Who do you possibly expect to understand with that ice-cold heart of yours?[c:]", "[c:g1]Qui espères-tu comprendre avec ton cœur glacé ?[c:]", Language.French);

            //Malkuth_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heads up manager!", "Attention, directeur !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've got this!", "Nous allons y arriver !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's stay sharp, now!", "Restons vigilants !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The familiar smell of death.", "L'odeur familière de la mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winning's just a matter of time!", "Ce n'est qu'une question de temps avant de gagner !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for those bait buckets!", "Attention à ces seaux d'appâts !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be on the look-out!", "Restez aux aguets !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for traps!", "Attention aux pièges !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We need to be smart about this.", "Il faut agir intelligemment.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This guy looks tough.", "Ce type a l'air coriace.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take a deep breath, and focus.", "Respirez profondément et concentrez-vous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've made this far.", "Nous sommes arrivés jusque-là.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can't lose now!", "Nous ne pouvons pas perdre maintenant !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are those cannons?", "Ce sont des canons ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've dealt with worse.", "Nous avons connu pire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No need to worry too much!", "Pas besoin de trop s'inquiéter !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Treat it as another abnormality", "Traitez cela comme une autre anomalie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and act accordingly!", "et agissez en conséquence !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This thing is huge...", "Cette chose est énorme...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uh, don't worry!", "Euh, ne vous inquiétez pas !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can do it!", "Nous pouvons y arriver !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We just need to outlast it...", "Nous devons simplement tenir plus longtemps qu'elle...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manage your resources carefully!", "Gérez vos ressources avec soin !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nice to meet you, manager!", "Ravi de vous rencontrer, directeur !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello again!", "Heureux de vous revoir !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm prepared to help!", "Je suis prêt à aider !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I promise to succeed!", "Je promets de réussir !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings Manager!", "Salutations, directeur !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trust me and follow my lead!", "Faites-moi confiance et suivez-moi !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's do this!", "Allons-y !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm fully prepared now!", "Je suis enfin prêt !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winning is just a matter of time!", "La victoire n'est qu'une question de temps !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll do my best within my ability!", "Je ferai de mon mieux dans la mesure de mes moyens !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you manager!", "Merci, directeur !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't panic.", "Ne paniquez pas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stay calm.", "Restez calme.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll fight harder, don't worry!", "Je me battrai davantage, ne vous inquiétez pas !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've got a good feeling about this!", "J'ai un bon pressentiment !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's stay sharp, shall we?", "Restons vigilants, d'accord ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Focus on the path forward!", "Concentrez-vous sur la voie à suivre !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not like this...", "Pas comme ça...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Don't give up.", "... N'abandonnez pas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I talked big and failed, again.", "J'ai fait le fier et j'ai échoué, encore une fois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stay calm, everyone.", "Tout le monde, restez calme.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have faith in your decision.", "J'ai confiance en votre décision.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why don't we take a deep breath?", "Pourquoi ne pas respirer un bon coup ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Things are going smoothly!", "Tout se passe bien !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's make the most of this!", "Tirons-en le meilleur parti !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I trust your judgement!", "Je fais confiance à votre jugement !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have faith in me!", "Ayez confiance en moi !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've got this manager!", "Vous pouvez y arriver, directeur !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing we haven't solved before!", "Rien que nous n'ayons déjà résolu !", Language.French);

            //MapNodes
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You enter a clearing surrounded by dark, twisting trees.", "Vous entrez dans une clairière entourée d'arbres sombres et tortueux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their branches claw at the leering moon as you approach the well at the clearing's centre.", "Leurs branches griffent la lune narquoise tandis que vous approchez du puits au centre de la clairière.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unearthly voices arise from the its inky depths, pleading, screaming, wishing and wanting.", "Des voix surnaturelles s'élèvent de ses profondeurs d'encre, suppliant, hurlant, désirant et réclamant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are things in the well, waiting to be drawn up. Powerful, mysterious,", "Des choses attendent dans le puits qu'on les en tire. Puissantes, mystérieuses,", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]abnormal[c:].", "[c:bR]anormales[c:].", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you journey through the wilderness, you come across a small group of humans.", "En traversant la nature sauvage, vous rencontrez un petit groupe d'humains.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They're dressed oddly for this climate, and even odder, [c:bR]they seem to recognise you[c:].", "Leurs vêtements conviennent mal au climat et, plus étrange encore, [c:bR]ils semblent vous reconnaître[c:].", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They are on an expedition of some kind, in search of [c:bR]strange[c:] beasts.", "Ils participent à une sorte d'expédition à la recherche de bêtes [c:bR]étranges[c:].", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their appear quite knowledgeable. Perhaps you can convince them to aid you on your journey.", "Ils semblent bien informés. Peut-être pourrez-vous les convaincre de vous aider pendant votre voyage.", Language.French);

            //Netzach_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That banging's annoying...", "Ces coups sont agaçants...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Again?", "Encore ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not a fan of that pickaxe.", "Je n'aime pas cette pioche.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many buckets of fish...", "Tant de seaux de poisson...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smell's making me sick.", "Cette odeur me rend malade.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can't we take the long way around?", "Ne pouvons-nous pas faire un détour ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone here's crazy...", "Tout le monde est fou ici...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least those traps are obvious.", "Au moins, ces pièges sont visibles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just want to lie down in the snow", "J'ai juste envie de m'allonger dans la neige", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and go to sleep.", "et de m'endormir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the final boss?", "C'est le boss final ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Since we've come this far, may as well.", "Puisque nous sommes arrivés jusque-là, autant continuer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's finish this.", "Terminons-en.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...am I hallucinating?", "... Est-ce une hallucination ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess I've seen weirder things.", "J'ai déjà vu des choses plus étranges, je crois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those cannons are pretty slow, huh?", "Ces canons sont plutôt lents, non ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is that thing?", "Qu'est-ce que c'est que cette chose ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't need this stress...", "Je n'ai pas besoin de ce stress...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why are we back here?", "Pourquoi sommes-nous revenus ici ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pick someone else?", "Choisir quelqu'un d'autre ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Know what I need most? Retreat and sleep.", "Vous savez ce dont j'ai le plus besoin ? Battre en retraite et dormir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sigh...", "Soupir...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm too tired for this.", "Je suis trop fatigué pour ça.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This battlefield atmosphere...", "Cette ambiance de champ de bataille...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not a fan of it.", "Je n'aime pas ça.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That should be enough, right?", "Ça devrait suffire, non ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waste of effort.", "Des efforts gâchés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll try not to disappoint.", "Je vais essayer de ne pas décevoir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks, I guess.", "Merci, je suppose.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just wanna nap in the back...", "Je veux juste faire une sieste à l'arrière...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did I end up doing things like this?", "Comment en suis-je arrivé à faire ce genre de choses ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's do this...", "Allons-y...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's get this over with.", "Finissons-en.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess I can sleep now.", "Je suppose que je peux dormir maintenant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sorry I couldn't help.", "Désolé de ne pas avoir pu aider.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why is the end always futile?", "Pourquoi la fin est-elle toujours vaine ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...I just wanna end this quickly.", "... Je veux juste en finir vite.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can I opt out?", "Puis-je me retirer ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is leaving an option?", "Partir est une option ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose whoever.", "Choisissez qui vous voulez.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At your discretion, manager.", "À votre discrétion, directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why with all the tests?", "Pourquoi tous ces tests ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh...", "Pff...", Language.French);

            //Tiphereth_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's deal with this guy quickly.", "Occupons-nous vite de ce type.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Should've stayed out of the way.", "J'aurais dû rester à l'écart.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You still haven't beat him?", "Vous ne l'avez toujours pas battu ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It smells like the Backstreets here.", "Ça sent les ruelles de l'Arrière-ville ici.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least his actions are predictable.", "Au moins, ses actions sont prévisibles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quickly now.", "Vite, maintenant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess we're next on the chopping block.", "On dirait que nous sommes les prochains sur le billot.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those knives look sharp. Careful.", "Ces couteaux ont l'air tranchants. Prudence.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hold onto those pelts now.", "Gardez bien ces fourrures.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've got this manager.", "Nous allons y arriver, directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't forget, you have us to help.", "N'oubliez pas que nous sommes là pour vous aider.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One more foe to beat.", "Encore un adversaire à battre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seriously?", "Sérieusement ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Never was that into pirates.", "Je n'ai jamais vraiment aimé les pirates.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This guy can't aim at all.", "Ce type ne sait pas viser.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's massive...", "C'est gigantesque...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope you know", "J'espère que vous savez", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what you're doing.", "ce que vous faites.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep your head on tight, manager.", "Gardez bien votre tête sur vos épaules, directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This'll be tough.", "Ce sera difficile.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We'll make it out for sure.", "Nous allons forcément nous en sortir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hurry and pick one of us.", "Dépêchez-vous d'en choisir un parmi nous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't keep up waiting.", "Ne nous faites pas attendre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buckle up manager.", "Accrochez-vous, directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have faith.", "Ayez confiance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're not fighting alone.", "Vous ne vous battez pas seul.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't plan forever.", "Vous ne pouvez pas planifier indéfiniment.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now's the time for action.", "Il est temps d'agir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know what to do, right?", "Vous savez quoi faire, n'est-ce pas ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can't let everyone die here.", "Nous ne pouvons pas laisser tout le monde mourir ici.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Think I can't do this myself?", "Vous pensez que je ne peux pas y arriver seul ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not bad.", "Pas mal.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This better be useful.", "Ça a intérêt à être utile.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I was too slow...", "J'étais trop lent...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Push forward!", "En avant !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't get cocky.", "Ne soyez pas trop sûr de vous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can still fight!", "Je peux encore me battre !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Sorry", "... Désolé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why'd you bring us here?", "Pourquoi nous avez-vous amenés ici ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No.", "Non.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you dare.", "N'osez pas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A respite?", "Un répit ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Decide for yourself.", "Décidez vous-même.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Make good use of this.", "Faites-en bon usage.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose someone that needs it.", "Choisissez quelqu'un qui en a besoin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A trial?", "Une épreuve ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We've gone through worse.", "Nous avons traversé pire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can handle it.", "Je peux m'en charger.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll win this for sure.", "Je vais gagner, c'est sûr.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll do fine, like always.", "Vous vous en sortirez bien, comme toujours.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here we go.", "C'est parti.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a strange place...", "Quel endroit étrange...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time to work.", "Au travail.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's do our best.", "Faisons de notre mieux.", Language.French);

            //WhiteNight
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]The time has come. A new world will come.[c:]", "[c:bR]Le moment est venu. Un nouveau monde naîtra.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I am death and life. Darkness and light.[c:]", "[c:bR]Je suis la mort et la vie. L'ombre et la lumière.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Have I not chosen you, the Twelve? Yet one of you is a devil.[c:]", "[c:bR]Ne vous ai-je pas choisis, vous les Douze ? Pourtant, l'un de vous est un démon.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]None of you can leave my side until I permit you.[c:]", "[c:bR]Aucun de vous ne peut me quitter sans ma permission.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Be at ease. No calamity shall be able to trouble you.[c:]", "[c:bR]Soyez en paix. Aucune calamité ne pourra vous troubler.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I shall not leave thee until I have completed my mission.[c:]", "[c:bR]Je ne te quitterai pas avant d'avoir accompli ma mission.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]What did you do?[c:]", "[c:bR]Qu'avez-vous fait ?[c:]", Language.French);

            //Yesod_talk
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let his age lull you into", "Ne laissez pas son âge vous donner", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a false sense of security.", "un faux sentiment de sécurité.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That pickaxe is sharp. Stay vigilant.", "Cette pioche est tranchante. Restez vigilant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's not waste any time.", "Ne perdons pas de temps.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let the smell dull your mind.", "Ne laissez pas l'odeur embrumer votre esprit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His hook always seems to hit its mark.", "Son crochet semble toujours atteindre sa cible.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sure you know how to deal with it.", "Je suis sûr que vous savez comment vous en occuper.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This isn't particularly pleasant...", "Ce n'est pas particulièrement agréable...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come up with a plan, then execute it.", "Élaborez un plan, puis exécutez-le.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let the cold cloud your senses, manager.", "Ne laissez pas le froid troubler vos sens, directeur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hasty actions will bring more harm than good.", "La précipitation fera plus de mal que de bien.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must make sound judgements", "Nous devons juger avec discernement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "before rushing forward.", "avant de nous précipiter en avant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use what we've learned until now.", "Utilisons ce que nous avons appris jusqu'ici", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to take him down.", "pour le vaincre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Consider this your final test.", "Considérez ceci comme votre épreuve finale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A skeleton? That's new.", "Un squelette ? Voilà qui est nouveau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His crew seems persuadable.", "Son équipage semble ouvert à la persuasion.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can't say I'm impressed.", "Je ne peux pas dire que je sois impressionné.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't be intimidated.", "Ne vous laissez pas intimider.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manage your creatures wisely,", "Gérez judicieusement vos créatures,", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and maintain constant fire.", "et maintenez un feu continu.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We know its tricks now.", "Nous connaissons ses tours maintenant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We are at an advantage.", "Nous avons l'avantage.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't lose your cool now.", "Ne perdez pas votre sang-froid maintenant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recklessly charging is not an effecient combat method.", "Une charge irréfléchie n'est pas une méthode de combat efficace.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must prioritise concluding this fight quickly.", "Notre priorité doit être de terminer ce combat rapidement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I take it you're prepared for any outcome.", "J'imagine que vous êtes prêt à toute éventualité.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In a situation such as this,", "Dans une situation comme celle-ci,", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "we must be calm and make sound judgements.", "nous devons rester calmes et juger avec discernement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will fulfill my responsibility.", "Je remplirai ma responsabilité.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I accept this with grace.", "J'accepte cela avec grâce.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kh.", "Kh.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay no mind to me.", "Ne t'occupe pas de moi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Focus on the goal.", "Concentre-toi sur l'objectif.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If there's no opportunity to strike,", "S'il n'y a pas d'occasion de frapper,", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "we'll simply make one.", "nous en créerons une.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's end this quickly.", "Finissons-en vite.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Very well.", "Très bien.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's not push ourselves too carelessly.", "Ne nous surmenons pas imprudemment.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't want to waste any time.", "Je ne veux pas perdre de temps.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no need to pity me.", "Tu n'as pas besoin d'avoir pitié de moi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I couldn't see the path ahead.", "Je ne voyais pas le chemin devant moi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What did I do wrong?", "Qu'ai-je fait de mal ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's entirely my fault.", "C'est entièrement ma faute.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This isn't particularly delightful.", "Ce n'est pas particulièrement réjouissant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This death must not be in vain.", "Cette mort ne doit pas être vaine.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose I should just accept this.", "Je suppose que je dois simplement l'accepter.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frankly,", "Franchement,", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I dislike how numb I've become to death.", "je déteste être devenue aussi insensible à la mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I trust you will choose correctly.", "Je compte sur toi pour faire le bon choix.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be logical about this.", "Fais preuve de logique.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems to be a test of some kind.", "Cela semble être une sorte d'épreuve.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A single mistake could cause disaster.", "Une seule erreur pourrait provoquer un désastre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must always proceed with discretion.", "Nous devons toujours agir avec prudence.", Language.French);

            //部分印记、说明补充
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Single Recall is created in your hand. A Single Recall can return a card on your side of the board to your hand.", "Un Rappel unique est créé dans votre main. Il permet de renvoyer dans votre main une carte de votre côté du plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will let you return a played card to your hand. Returned cards will cost [c:bR]Bones[c:] to replay.", "Cette carte permet de reprendre en main une carte jouée. Les cartes reprises coûtent des [c:bR]os[c:] lorsqu'elles sont rejouées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Total Recall is created in your hand. A Total Recall will return all cards on your side of the board to your hand.", "Un Rappel total est créé dans votre main. Il renvoie dans votre main toutes les cartes de votre côté du plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will return all your cards to your hand. Returned cards will cost [c:bR]Bones[c:] to replay.", "Cette carte renvoie toutes vos cartes dans votre main. Les cartes reprises coûtent des [c:bR]os[c:] lorsqu'elles sont rejouées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justitia", "Justitia", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Non-Terrain cards targeted by Judgement Bird are killed regardless of Health. Judgement Bird is not affected by abilities like Sharp and Punisher.", "Les cartes qui ne sont pas des terrains ciblées par l'Oiseau du jugement sont tuées quelle que soit leur santé. L'Oiseau du jugement n'est pas affecté par les capacités comme Piquants et Punisseur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In the Name of Love and Hate", "Au nom de l'amour et de la haine", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When 2 more ally cards have died than opposing cards or vice versa, Magical Girl will transform then move to the side of the board that lost more cards.", "Lorsque 2 cartes alliées de plus que de cartes adverses sont mortes, ou inversement, la Fille magique se transforme puis rejoint le côté du plateau qui a perdu le plus de cartes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magical Girls", "Filles magiques", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain a special card when all 4 Magical Girls or their evolutions are on the same side of the board.", "Obtenez une carte spéciale lorsque les 4 Filles magiques ou leurs évolutions se trouvent du même côté du plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mimicry", "Mimétisme", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing There reveals itself on death.", "Rien du tout révèle sa véritable forme à sa mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pink", "Rose", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Army in Pink will transform when 3 ally cards die.", "L'Armée en rose se transforme lorsque 3 cartes alliées meurent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sap", "Sève", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever Giant Tree Sap is sacrificed, there is an increasing chance the sacrificing card will explode.", "Chaque fois que la Sève d'arbre géant est sacrifiée, la carte qui la sacrifie a une probabilité croissante d'exploser.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smile", "Sourire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mountain of Smiling Bodies grows into a stronger forme whenever killing a card. Upon dying, revert to a previous forme if possible.", "La Montagne des corps souriants évolue vers une forme plus puissante chaque fois qu'elle tue une carte. À sa mort, elle revient à une forme précédente si possible.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sound of a Star", "Le son d'une étoile", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If there are no cards on the opposing side that can be attacked, Blue Star strikes all slots directly.", "S'il n'y a aucune carte attaquable du côté adverse, l'Étoile bleue frappe directement tous les emplacements.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Sword Sharpened with Tears", "L'épée aiguisée par les larmes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight of Despair and Servant of Wrath will transform when an adjacent card dies.", "La Chevalière du désespoir et la Servante du courroux se transforment lorsqu'une carte adjacente meurt.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Syrinx", "Syrinx", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nameless Fetus transforms when sacrificed six times.", "Le Fœtus sans nom se transforme après avoir été sacrifié six fois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Homing Instinct", "L'instinct du retour", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When The Road Home is played, create a Scaredy Cat in your hand. [define:wstl_scaredyCat]", "Lorsque le Chemin du retour est joué, créez un Chat peureux dans votre main. [define:wstl_scaredyCat]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Three Birds", "Trois oiseaux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain a special card when Punishing Bird, Judgement Bird, and Big Bird are on the same side of the board.", "Obtenez une carte spéciale lorsque l'Oiseau du châtiment, l'Oiseau du jugement et le Grand oiseau sont du même côté du plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Expression", "L'expression du jour", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Shy Look changes forme when drawn.", "Le Regard timide du jour change de forme lorsqu'il est pioché.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wrist Cutter", "Tranche-poignets", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodbath transforms whenever a card is sacrificed.", "Le Bain de sang se transforme chaque fois qu'une carte est sacrifiée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yellow Brick Road", "La route de briques jaunes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain a special card when Ozma, The Road Home, Warm-Hearted Woodsman, and Scarecrow Searching for Wisdom are all on the same side of the board.", "Obtenez une carte spéciale lorsque Ozma, le Chemin du retour, le Bûcheron au grand cœur et l'Épouvantail en quête de sagesse sont tous du même côté du plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clouded Monk", "Moine dans les nuages", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanted", "Enchanté", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card will target cards with the Dazzling sigil, dealing no damage to them and dying after attacking. At the start of the owner's next turn, lose 1 stack of this effect.", "Cette carte cible les cartes portant l'emblème Rayonnant, ne leur inflige aucun dégât et meurt après avoir attaqué. Au début du prochain tour de son propriétaire, elle perd 1 cumul de cet effet.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sin", "Péché", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card deals damage to another creature, transfer 1 Sin to that card.", "Lorsque cette carte inflige des dégâts à une autre créature, elle lui transfère 1 Péché.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WhistleWind Lobotomy Mod", "Mod Lobotomy de WhistleWind", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Through the Twilight", "À travers le crépuscule", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survive the apocalypse and defeat the Beast.", "Survivez à l'apocalypse et vainquez la Bête.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Impuritas Civitatis", "Impuritas Civitatis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meet Angela at a Sephirot choice node.", "Rencontrez Angela à un nœud de choix de Sephirot.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gather the guardians of the Black Forest.", "Rassemblez les gardiens de la Forêt noire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full House", "Full", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring all of the magical girls together.", "Rassemblez toutes les Filles magiques.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reunite a group of long-lost friends.", "Réunissez un groupe d'amis séparés depuis longtemps.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blessing", "Bénédiction", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You witnessed His coming.", "Vous avez été témoin de Sa venue.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good cannot exist without evil.", "Le bien ne peut exister sans le mal.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange gurgling sound comes from your beast's stomach.", "Un étrange gargouillement provient de l'estomac de votre bête.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Sephirah agrees, and the others continue their separate way.", "Le Sephirah accepte, et les autres poursuivent chacun leur chemin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before they go, they promise to see you again.", "Avant de partir, ils promettent de vous revoir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may ask [c:bR]1[c:] to join you. The others will continue on their own.", "Vous pouvez demander à [c:bR]1[c:] d'entre eux de vous rejoindre. Les autres continueront seuls.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something prevents its function. You cannot escape this one.", "Quelque chose empêche son fonctionnement. Vous ne pouvez pas vous échapper cette fois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have I backed you into a corner? Or am I simply boring you?", "Vous ai-je acculé ? Ou suis-je simplement en train de vous ennuyer ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose it doesn't matter. I will honour your request.", "Je suppose que cela n'a aucune importance. Je vais accéder à votre demande.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You cannot escape so easily.", "Vous ne pouvez pas vous échapper si facilement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Divine power infuses the beasts in your caravan, empowering them.", "Une puissance divine imprègne les bêtes de votre caravane et les renforce.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Do not deny me.[c:]", "[c:bR]Ne me refusez pas.[c:]", Language.French);

            //packandchallenges
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A set of " + count.ToString() + " cards based on the abnormalities from Lobotomy Corporation and Library of Ruina.", "Un ensemble de " + count.ToString() + " " + (count == 1 ? "carte" : "cartes") + " basé sur les Anormalités de Lobotomy Corporation et Library of Ruina.", Language.French);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A set of [summary] exclusively featuring abnormalities and related phenomena.", "Un ensemble de [summary] consacré exclusivement aux anomalies et aux phénomènes qui leur sont liés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abnormal Bosses", "Boss anormaux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vanilla bosses will play Abnormalities during their battles.", "Les boss du jeu de base jouent des cartes Anomalie pendant leurs combats.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abnormal Encounters", "Rencontres anormales", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All regular battles will only use abnormality cards.", "Tous les combats ordinaires utilisent uniquement des cartes Anomalie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start with a Beast", "Commencer avec une Bête", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start your run with Apocalypse Bird in your deck.", "Commencez votre aventure avec l'Oiseau de l'Apocalypse dans votre deck.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Better Rare Chances", "Plus de chances de cartes rares", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rare cards are more likely to appear at abnormal choice nodes.", "Les cartes rares ont plus de chances d'apparaître aux nœuds de choix d'anomalies.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Apocalypse", "Apocalypse finale", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy is replaced as the final boss of the run with the Beast.", "La Bête remplace Leshy comme boss final de l'aventure.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Coming", "Avènement final", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Saviour boss will be stronger and guaranteed to appear.", "Le boss Sauveur sera plus puissant et apparaîtra à coup sûr.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Laugh", "Dernier rire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy is replaced as the final boss of the run with the Fool.", "Le Bouffon remplace Leshy comme boss final de l'aventure.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Trick", "Dernier tour de passe-passe", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Adult boss will be stronger and guaranteed to appear.", "Le boss Adulte sera plus puissant et apparaîtra à coup sûr.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start with a Fool", "Commencer avec un Bouffon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start your run with Jester of Nihil in your deck.", "Commencez votre aventure avec le Bouffon du néant dans votre deck.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start with a Liar", "Commencer avec un menteur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start your run with Adult Who Tells Lies in your deck.", "Commencez votre aventure avec l'Adulte qui ment dans votre deck.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miracle Worker", "Faiseur de miracles", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy will play Plague Doctor against you. Beware the Clock.", "Leshy jouera le Médecin de peste contre vous. Méfiez-vous de l'horloge.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Too fast. Too soon.[c:]", "[c:bR]Trop vite. Trop tôt.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your journey has brought here, to a dark, oppressive forest.", "Votre voyage vous a mené ici, dans une forêt sombre et oppressante.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sky above you is an inky void, empty of even a single star.", "Le ciel au-dessus de vous est un vide d'encre, où ne brille pas une seule étoile.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A horrible roar rattles your bones, and a fearful chill overcomes you.", "Un rugissement terrible fait trembler vos os et un frisson d'effroi vous saisit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Somewhere beyond the dark trees, there's a monster.", "Quelque part derrière les arbres sombres se cache un monstre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]A monster in the Black Forest.[c:]", "[c:bR]Un monstre dans la Forêt noire.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your journey has brought here, to an unknown yet familiar forest.", "Votre voyage vous a mené ici, dans une forêt inconnue et pourtant familière.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Somewhere beyond the dark trees, you know, there's a monster.", "Vous savez qu'un monstre se cache quelque part derrière les arbres sombres.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dag nab it! My reindeer!", "Nom d'un chien ! Mon renne !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cute Lil Guy", "Adorable petit gars", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will enter a downed state instead of dying. Downed creatures are invulnerable under special conditions.", "[creature] tombe à terre au lieu de mourir. Les créatures à terre sont invulnérables dans certaines conditions.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill WhiteNight and all Apostles on the board then deal 33 direct damage.", "Tuez Nuit blanche et tous les Apôtres sur le plateau, puis infligez 33 dégâts directs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of combat, this card will mark random spaces with coloured targets, then attack those spaces on its next turn. Red: this card's damage is doubled; White: this card's damage is halved and it heals equal to its Power; Yellow: no special effect.", "À la fin du combat, cette carte marque des emplacements aléatoires avec des cibles colorées, puis les attaque à son prochain tour. Rouge : ses dégâts sont doublés ; blanc : ses dégâts sont divisés par deux et elle récupère autant de santé que sa puissance ; jaune : aucun effet spécial.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every 3 turns, change the active egg effect. On the final phase, this sigil changes behaviour. Opponent cards may move at the end of the turn. This card cannot go below 90/60/30 Health.", "Tous les 3 tours, changez l'effet d'œuf actif. Lors de la phase finale, cet emblème change de comportement. Les cartes adverses peuvent se déplacer à la fin du tour. La santé de cette carte ne peut pas descendre sous 90/60/30.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, deal direct damage to the owner proportional to how much damage this card received during the turn.", "À la fin du tour de son propriétaire, cette carte lui inflige des dégâts directs proportionnels aux dégâts qu'elle a subis pendant ce tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eat 'em!", "Dévorez-les !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Single Recall Bottle", "Bouteille de Rappel unique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Total Recall Bottle", "Bouteille de Rappel total", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twilight falls...", "Le crépuscule tombe...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beginning at the end.", "Le commencement à la fin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The end at the beginning.", "La fin au commencement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything is equal. Everything is as it should be.", "Tout est égal. Tout est comme il se doit.", Language.French);

        }
    }
    public class TVFsBossesMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for TVFsBosses Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though there was no one in sight, some offerings were laid out before you.", "Bien qu'il n'y ait personne en vue, des offrandes étaient disposées devant vous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There was no [c:bR]Woodcarver[c:] nearby.", "Il n'y avait pas de [c:bR]Sculptrice sur bois[c:] à proximité.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still, her totem pieces remained.", "Ses pièces de totem étaient pourtant toujours là.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The old [c:bR]Woodcarver[c:] was nowhere to be found.", "La vieille [c:bR]Sculptrice sur bois[c:] était introuvable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Her carvings remained by the log she once sat upon.", "Ses sculptures restaient près de la bûche sur laquelle elle s'asseyait autrefois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]Woodcarver[c:] emerged from the thicket.", "La [c:bR]Sculptrice sur bois[c:] sortit du fourré.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Her face looked somehow more stern than usual.", "Son visage semblait plus sévère que d'habitude.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient woman approached.", "Une femme très âgée s'approcha.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She looked intensely displeased with you.", "Elle semblait extrêmement mécontente de vous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nearby branches rustled as The [c:bR]Woodcarver[c:] revealed herself.", "Les branches voisines bruissèrent tandis que la [c:bR]Sculptrice sur bois[c:] se montrait.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She had no offerings this time.", "Cette fois, elle n'avait aucune offrande.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Leave.[c:]", "[c:bR]Partez.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turn back.", "Faites demi-tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are not prepared.", "Vous n'êtes pas prêt.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woodcarver Boss", "Boss Sculptrice sur bois", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Prospector is replaced as the boss of the Woodlands.", "La Sculptrice sur bois remplace le Prospecteur comme boss des bois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You found yourself among a grove of thick and pungent mushrooms.", "Vous vous retrouvâtes au milieu d'un bois de champignons denses et à l'odeur âcre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The operating table lay abandoned.", "La table d'opération avait été abandonnée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]Mycologists[c:] stepped out from behind an enormous mushroom.", "Les [c:bR]mycologues[c:] sortirent de derrière un champignon gigantesque.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of them looked anxious, but the other bore a very serious expression.", "L'un d'eux semblait inquiet, mais l'autre affichait une expression très grave.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You squinted to see a figure through the thick cloud of spores.", "Vous plissâtes les yeux et distinguâtes une silhouette à travers l'épais nuage de spores.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]Mycologists[c:]' shared body was posed in a threatening stance.", "Le corps partagé des [c:bR]mycologues[c:] avait pris une pose menaçante.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:bR]Mycologists[c:] appeared more crazed with each breath they took.", "Les [c:bR]mycologues[c:] semblaient plus déments à chaque respiration.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was clear they wanted to experiment on more than just your creatures.", "Il était clair qu'ils voulaient expérimenter sur bien plus que vos créatures.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:3]It will suffice.[size:]", "[size:3]Cela suffira.[size:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:3]For our experiments, yes.[size:]", "[size:3]Pour nos expériences, oui.[size:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:3]Do not worry. I have a backup plan.[size:]", "[size:3]Ne t'inquiète pas. J'ai un plan de secours.[size:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:3]Satisfactory results.[size:]", "[size:3]Des résultats satisfaisants.[size:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "B- But there is only one challenger?", "M-mais il n'y a qu'un seul prétendant ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We... We need your body?", "Nous... Nous avons besoin de ton corps ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y- You will... not submit your body for our experiments?", "T-tu ne... nous confieras pas ton corps pour nos expériences ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mycologists Boss", "Boss Mycologues", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Angler is replaced as the boss of the Wetlands.", "Les mycologues remplacent le Pêcheur comme boss des marais.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Experiment", "Expérience", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOOD.", "BIEN.", Language.French);

        }
    }
    public class ZephtSunMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for ZephtSun Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DebugSun", "Débogage du soleil", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sun: ", "Soleil : ", Language.French);
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sun: " + count.ToString(), "Soleil : " + count.ToString(), Language.French);
            }

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Night time", "La nuit", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will no longer get passive sun falling from the sky.", "Vous ne recevrez plus passivement de soleil tombant du ciel.", Language.French);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunBoost", "Gain de soleil", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is placed on the board, the owner will gain sun.", "Lorsque [creature] est placé sur le plateau, son propriétaire gagne du soleil.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wise use of emergency supplies.", "Un usage judicieux des provisions d'urgence.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunKill", "Soleil mortel", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] defeats another card, the other card will drop sun.", "Lorsque [creature] vainc une autre carte, celle-ci laisse tomber du soleil.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recycle your enemies back into nutrients", "Recyclez vos ennemis en nutriments", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunMaker 1", "Production de soleil 1", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will produce 1 sun, if it belongs to the player.", "À la fin du tour de son propriétaire, [creature] produit 1 soleil si elle appartient au joueur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every little bit counts", "Chaque petit geste compte", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunMaker 2", "Production de soleil 2", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will produce 2 sun, if it belongs to the player.", "À la fin du tour de son propriétaire, [creature] produit 2 soleils si elle appartient au joueur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If only the moon was this useful", "Si seulement la lune était aussi utile", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunMaker 3", "Production de soleil 3", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will produce 3 sun, if it belongs to the player.", "À la fin du tour de son propriétaire, [creature] produit 3 soleils si elle appartient au joueur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of the sun, in the palm of your hand", "Le pouvoir du soleil au creux de votre main", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunMaker", "Production de soleil", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will produce X sun, if it belongs to the player. Some cards produce more sun than others.", "À la fin du tour de son propriétaire, [creature] produit X soleils si elle appartient au joueur. Certaines cartes produisent plus de soleil que d'autres.", Language.French);

            // ShowThenClear
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dont have enough sun for that one", "Vous n'avez pas assez de soleil pour cette carte", Language.French);

        }
    }
    public class PlantsVSZombiesMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for PlantsVSZombies Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Peashooter", "Lance-pois", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repeater", "Double lance-pois", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaflitter", "Litière de feuilles", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A plant commonly used to fend off the undead", "Une plante couramment utilisée pour repousser les morts-vivants", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Threepeater", "Triple lance-pois", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A more powerful version of the iconic peashooter", "Une version plus puissante de l'emblématique lance-pois", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "they say 3 heads are better than one", "On dit que 3 têtes valent mieux qu'une", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cactus", "Cactus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try not to prick yourself on it", "Essayez de ne pas vous piquer dessus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splinters", "Éclats", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homing Thistle", "Chardon à tête chercheuse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one tracks down its target with ease", "Celui-ci repère facilement sa cible", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cattail", "Massette", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nyah~", "Miaou~", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chomper", "Mâchouille", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No bark and all bite", "Il ne fait qu'une bouchée sans jamais aboyer", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starfruit", "Carambole", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surprisingly not a ball of fire", "Étonnamment, ce n'est pas une boule de feu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloomerang", "Florang", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't be deceived, it won't just return if you throw it away", "Ne vous y trompez pas : si vous le jetez, il ne reviendra pas forcément", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "bonk choy", "Pak-choï frappeur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A feisty one for sure", "Un sacré tempérament, c'est certain", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Citron", "Citron", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you can afford to play it, it's zest is bound to aid you", "Si vous pouvez vous permettre de la jouer, son zeste ne manquera pas de vous aider", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Red Stinger", "Dard rouge", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Position it strategically if you want to use its full potential", "Placez-le avec stratégie pour exploiter tout son potentiel", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spikerock", "Roche épineuse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spikeweed", "Herbe épineuse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will you lay the spikeweed as a trap for those who dare approach it?", "Placerez-vous l'Herbe épineuse comme piège pour ceux qui osent l'approcher ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anybody who attempts to trample it will meet a sharp fate.", "Quiconque tente de la piétiner connaîtra un sort piquant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Artichoke", "Artichaut", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This drone has seen some warfare", "Ce drone a connu la guerre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beeshooter", "Lance-abeilles", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "According to all known laws of aviation, there is no way a bee should be able to fly", "D'après toutes les lois connues de l'aviation, une abeille ne devrait pas pouvoir voler", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puffshroom", "Petit champi", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It might not be very powerful, but it can get you out of a pinch", "Il n'est peut-être pas très puissant, mais il peut vous tirer d'un mauvais pas", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seashroom", "Champi marin", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just a little mushroom, sitting on the water", "Un petit champignon, tout simplement posé sur l'eau", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scaredyshroom", "Champi peureux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Some may consider this one a coward for its tactics", "Certains verraient de la lâcheté dans sa tactique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fume", "Vapeur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fumeshroom", "Champi fumant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its fumes can hit many foes", "Ses vapeurs peuvent toucher de nombreux ennemis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sporeshroom", "Champi à spores", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Put divide and conquer into practice", "Mettez en pratique le principe : diviser pour régner", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sunflower", "Tournesol", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These can power entire infantries", "Ils peuvent alimenter des armées entières", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twin Sunflower", "Tournesol double", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truly a great powerplant", "Une véritable centrale végétale", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunShroom", "Champignon solaire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "allow the sunshroom some time to reach its full potential", "Laissez au Champignon solaire le temps d'atteindre son plein potentiel", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ToadStool", "Champi crapaud", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A frogish fungus, how curious", "Un champignon qui ressemble à une grenouille, comme c'est étrange", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sun bean", "Haricot solaire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "will you invest in the sun bean?", "Investirez-vous dans le Haricot solaire ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wallnut", "Noix muraille", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an iconic line of defence", "Une ligne de défense emblématique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tallnut", "Grande noix", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Near nothing can get past this one", "Presque rien ne peut passer au-dessus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endurian", "Durian blindé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's outer shell wont be so enjoyable to get through", "Traverser sa coque ne sera pas une partie de plaisir", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Garlic", "Ail", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Control the upcoming onslaughts with the Garlic's stench.", "Contrôlez les assauts à venir grâce à la puanteur de l'Ail.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infi-nut", "Noix infinie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeating this one isn't so simple", "Ce n'est pas si simple de la vaincre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Potato Mine", "Mine de pomme de terre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small but potentially dangerous spud", "Une petite patate potentiellement dangereuse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cherry Bomb", "Bombe cerise", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It may be sweet but you shouldnt underestimate it", "Elle est peut-être sucrée, mais ne la sous-estimez pas", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jalapeno", "Jalapeño", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I would not want to eat that", "Je ne voudrais pas manger ça", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DoomShroom", "Champi funeste", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A force to be reckoned with", "Une force avec laquelle il faut compter", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torchwood", "Souche torche", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It can boost it's allies' power", "Il peut renforcer la puissance de ses alliés", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MagnetShroom", "Champi aimant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weakens the enemy to aid its allies", "Affaiblit l'ennemi pour aider ses alliés", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hypnoshroom", "Champi hypnotique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One mans foe is another mans friend", "L'ennemi de l'un est l'ami de l'autre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gold Leaf", "Feuille d'or", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foil your opponents' plans by turning over a new leaf", "Déjouez les plans de vos adversaires en tournant une nouvelle feuille", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pumpkin", "Tête de citrouille", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fortify all of your cards with this one simple trick", "Renforcez toutes vos cartes grâce à cette astuce toute simple", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Escape Root", "Racine de fuite", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allows other cards the freedom of escaping to safety", "Elle permet aux autres cartes de s'échapper en lieu sûr", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee bean", "Grain de café", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It can energise plants and unlock further potential", "Il peut revigorer les plantes et libérer davantage leur potentiel", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sprout", "Pousse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But a simple sprout, what will it grow into? nobody knows, Limitless potential", "Une simple pousse, mais que deviendra-t-elle ? Nul ne le sait. Son potentiel est sans limites", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A common browncoat, hungry for brains", "Un zombie ordinaire en veste brune, affamé de cervelles", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conehead", "Tête de cône", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A browncoat that equipped itself with road work equipment", "Un zombie en veste brune équipé de matériel de chantier", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buckethead", "Tête de seau", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To think headgear could provide so much protection", "Qui aurait cru qu'un couvre-chef puisse protéger autant ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flag Zombie", "Zombie porte-drapeau", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A true leader, calling in allies for combat", "Un vrai meneur qui appelle ses alliés au combat", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snorkel", "Plongeur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dives in the deep and emerges for a munch", "Il plonge dans les profondeurs et remonte pour grignoter", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Screen Door", "Porte grillagée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I much prefer doors of sturdy wood", "Je préfère de loin les portes en bois solide", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jack in a box", "Boîte à ressort", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one brings tension with such a simple melody", "Une mélodie toute simple suffit à créer la tension", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crater", "Cratère", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just a hole", "Juste un trou", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cycle of the forest", "Le cycle de la forêt", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shroom Chunksr", "Morceaux de champi", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chunks of shrooms", "Des morceaux de champignon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shards of shells", "Des éclats de coquille", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zombie Arm", "Bras de zombie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A zombie must have dropped this", "Un zombie a dû perdre ça", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stray Cat", "Chat errant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How bizarre.. i don't recognise that one", "Comme c'est bizarre... Je ne reconnais pas celui-là", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stray Cat Requiem", "Requiem du Chat errant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debugger", "Débogueur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debuggest", "Super débogueur", Language.French);

            // Starter
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plants vs Zombies", "Plantes contre zombies", Language.French);
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds plants vs zombies cards to the mix, with a custom sun currency too. Contains " + count.ToString() + " new cards.", "Ajoute des cartes Plants vs. Zombies et une ressource de soleil personnalisée. Contient " + count.ToString() + " " + (count == 1 ? "nouvelle carte" : "nouvelles cartes") + ".", Language.French);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The original seeds", "Les graines d'origine", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The midnight crew", "L'équipe de minuit", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Zen Garden", "Le jardin zen", Language.French);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add Stats", "Ajout de caractéristiques", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, its health, attack, and other sigils will be added to every other non terrain card on your side of the board. Then this card will perish. Cards bearing this sigil cannot be used in sigil transfers or campfires.", "Quand la carte [creature] est jouée, sa santé, son attaque et ses autres emblèmes sont ajoutés à toutes les autres cartes qui ne sont pas des terrains de votre côté du plateau. Elle périt ensuite. Les cartes ornées de cet emblème ne peuvent pas être utilisées pour les transferts d'emblèmes ni aux feux de camp.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of teamwork", "La force du travail d'équipe", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add Stats Opponent", "Ajout de caractéristiques adverses", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, its health, attack, and other sigils will be added to every card on the opposing side of the board. Then this card will perish. Cards bearing this sigil cannot be used in sigil transfers or campfires.", "Quand la carte [creature] est jouée, sa santé, son attaque et ses autres emblèmes sont ajoutés à toutes les cartes du côté adverse du plateau. Elle périt ensuite. Les cartes ornées de cet emblème ne peuvent pas être utilisées pour les transferts d'emblèmes ni aux feux de camp.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blight your foes", "Ravagez vos ennemis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armor breaker", "Briseur d'armure", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it removes all defense sigils from all of the opposing cards.", "Quand la carte [creature] est jouée, elle retire tous les emblèmes défensifs de toutes les cartes adverses.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Removing defense is a great offense", "La meilleure attaque consiste à briser les défenses", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DoomBringer", "Porteur de ruine", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will explode and deal 7 damage to all of the opponent's cards, along with 1 damage to all of the owners cards.", "À la fin du tour de son propriétaire, [creature] explose et inflige 7 dégâts à toutes les cartes adverses ainsi que 1 dégât à toutes les cartes de son propriétaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only destruction lays in its wake", "Seule la destruction subsiste sur son passage", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fade Away", "Disparition progressive", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will take 1 damage.", "À la fin du tour de son propriétaire, [creature] subit 1 dégât.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing can last forever", "Rien ne dure éternellement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hard Headed", "Tête dure", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is attacked, the damage taken will be reduced by 2. Then this sigil will be removed.", "Lorsque [creature] est attaquée, les dégâts subis sont réduits de 2. Cet emblème est ensuite retiré.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headwear is surprisingly good at negating wounds", "Un couvre-chef protège étonnamment bien des blessures", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hypnotist", "Hypnotiseur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] gets defeated, its killer will move to take its place.", "Lorsque [creature] est vaincue, la carte qui l'a tuée se déplace à sa place.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To think that betrayal can happen so easily", "Dire que la trahison peut arriver si facilement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pierce", "Perforation", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before attacking, [creature] attacks the given card in the opposing queue, it also nullifies the Armored sigil.", "Avant d'attaquer, [creature] attaque la carte visée dans la file adverse et annule aussi l'emblème Armure.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding in the back doesn't protect you here", "Se cacher derrière ne vous protégera pas ici", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spicy", "Épicé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will explode and deal 4 damage to the opposing card and to the card on the opposing backline. Cards bearing this sigil cannot be used in sigil transfers or campfires.", "À la fin du tour de son propriétaire, [creature] explose et inflige 4 dégâts à la carte en face et à la carte derrière celle-ci dans la file adverse. Les cartes ornées de cet emblème ne peuvent pas être utilisées pour les transferts d'emblèmes ni aux feux de camp.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never been too fond of spice", "Je n'ai jamais beaucoup aimé les épices", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spore Spreader", "Propagation de spores", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] defeats another card, a copy of itself will be returned to your hand.", "Si [creature] vainc une autre carte, une copie d'elle-même est ajoutée à votre main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "just how much will these spores spread?", "Jusqu'où ces spores se propageront-elles ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spudow", "Pataboum", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] gets defeated, it deals 4 damage to the opposing card.", "Lorsque [creature] est vaincue, elle inflige 4 dégâts à la carte en face.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always watch your step in a potato field", "Regardez toujours où vous mettez les pieds dans un champ de pommes de terre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sweet", "Douceur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will explode and deal 3 damage to the cards in the 3 enemy slots around it, then deal 1 damage to the cards in your adjacent slots. Cards bearing this sigil cannot be used in sigil transfers or campfires.", "À la fin du tour de son propriétaire, [creature] explose et inflige 3 dégâts aux cartes des 3 emplacements ennemis autour d'elle, puis 1 dégât aux cartes de vos emplacements adjacents. Les cartes ornées de cet emblème ne peuvent pas être utilisées pour les transferts d'emblèmes ni aux feux de camp.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe there's a bit more tartness than anticipated", "Peut-être est-ce un peu plus acide que prévu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scaredy", "Peureux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 attack but gains 1 health when against an opposing card whose attack is greater than 0, unless the opposing card retreats too.", "[creature] perd 1 attaque mais gagne 1 santé lorsqu'elle fait face à une carte adverse dont l'attaque est supérieure à 0, sauf si cette carte porte elle aussi l'emblème Peureux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They call it a tactical retreat", "Ils appellent ça une retraite tactique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zombie Caller", "Appel des zombies", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, A zombie gets played on each empty adjacent space, though it may have headgear. [define:zep_pvz_zombie]", "Quand la carte [creature] est jouée, un zombie, avec éventuellement un couvre-chef, est joué sur chaque emplacement adjacent vide. [define:zep_pvz_zombie]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A huge wave of zombies is approaching", "Une énorme vague de zombies approche", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrooms", "Champignons", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of mushrooms that the owner has on their side of the table.", "La valeur représentée par cet emblème est égale au nombre de champignons du côté du plateau de son propriétaire.", Language.French);

        }
    }
    public class SmallTweakHydraMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SmallTweak_Hydra Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this Sigil hatches when drawn if 5 unique numbers are in the Health of creatures in your deck, and in their Power, and if there is a creature of 5 unique tribes in your deck. [This Excludes all cards bearing this sigil]", "Une carte ornée de cet emblème éclot quand elle est piochée si les créatures de votre deck présentent 5 valeurs de santé différentes et 5 valeurs d'attaque différentes, et s'il y a dans votre deck des créatures de 5 tribus différentes. [Toutes les cartes ornées de cet emblème sont exclues du calcul]", Language.French);


        }
    }
    public class MoreItemsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MoreItems Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All Brittle", "Atonie générale", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All Sharp", "Piquants pour tous", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards on the board gain Brittle", "Toutes les cartes sur le plateau gagnent Atonie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards on the board gain Sharp", "Toutes les cartes sur le plateau gagnent Piquants", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All Split Strike", "Attaque bifurquée pour tous", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards on the board gain Split Strike", "Toutes les cartes sur le plateau gagnent Attaque bifurquée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shuffle Sigils", "Mélange d'emblèmes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All sigils on the board are removed and added to a random card", "Tous les emblèmes du plateau sont retirés et ajoutés à une carte aléatoire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No Waterbourne", "Plus d'immersion", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All my cards on the board with Submerge are revealed and the sigil removed", "Toutes les cartes adverses du plateau portant Immersion sont révélées et perdent cet emblème", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hot Meat", "Viande chaude", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Using this item at the campfire will save your card from being destroyed for a single turn.", "Utilisé au feu de camp, cet objet protège votre carte contre la destruction pendant cette visite au feu de camp.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Places Bait Buckets on all empty spaces. The smell is overwhelming.", "Place des Seaux à appâts sur tous les emplacements vides. L'odeur est insoutenable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mrs. Bomb's Remote", "Télécommande de Mme Bombe", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Places Explode Bots on all empty spaces. Pretty annoying honestly.", "Place des Roboboums sur tous les emplacements vides. Plutôt agaçant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mrs. Bomb's Remote. Click that thing and Explode Bots will drop in every open space.", "La télécommande de Mme Bombe. Cliquez dessus et des Roboboums tomberont sur chaque emplacement vide.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returns the last friendly card that perished card to your hand", "Rend à votre main la dernière carte alliée qui a péri", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mycologist Saw", "Scie des mycologues", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combine 2 cards on your side of the board to become one.", "Combine 2 cartes de votre côté du plateau pour n'en former qu'une.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A temporary abomination if I ever 'saw' one.", "Une abomination temporaire, si j'en ai jamais scié une.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survivor", "Survivant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a card on the board to have a chance to either be destroyed or buffed.", "Choisissez une de vos cartes sur le plateau : elle a une chance d'être détruite ou renforcée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teeth Jar", "Bocal de dents", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 10 teeth to your currency bowl. Does not get added to your scales.", "Ajoute 10 dents à votre bol de monnaie. Elles ne sont pas ajoutées à votre balance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack", "Paquet de cartes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 5 random cards to your hand.", "Ajoute 5 cartes aléatoires à votre main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that's why my pack mules are coming back short.", "Voilà pourquoi mes mules de bât reviennent avec une cargaison incomplète.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meat Cake", "Gâteau de viande", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Relights a candle if you have lost a battle. Does not work during boss battles.", "Rallume une bougie si vous avez perdu un combat. Ne fonctionne pas pendant les combats de boss.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In case you change your mind", "Au cas où vous changeriez d'avis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trap", "Piège", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds a rabbit and pelts to your hand.", "Ajoute des fourrures à votre main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pick Axe", "Pioche", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All my cards on the board are replaced with a gold nugget", "Toutes les cartes adverses sur le plateau sont remplacées par des pépites d'or", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still sharp since the day i crafted it", "Toujours aussi tranchante que le jour où je l'ai fabriquée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camera", "Appareil photo bestial", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take a picture of a card on the board and add it to your deck", "Photographiez une carte sur le plateau et ajoutez-en une copie à votre main", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My spare camera, use it wisely.", "Mon appareil photo de secours, utilisez-le avec sagesse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mystical power of that item scared the survivors away.", "Le pouvoir mystique de cet objet a effrayé les survivants et les a fait fuir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "May you continue their legacy", "Puissiez-vous perpétuer leur héritage", Language.French);

        }
    }
    public class DinoMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Dino Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Akainacephalus", "Akainacéphale", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A brutish beast. The first attacks to it's shell it will completely disregard.", "Une bête brutale. Elle ignore complètement les premières attaques contre sa carapace.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgasaur", "Amalgasaur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Ever-Changing amalgasaur. It can never decide on its true stats.", "L'Amalgasaur en perpétuelle évolution. Il ne parvient jamais à se fixer sur ses véritables caractéristiques.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber", "Ambre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient amber..", "Un morceau d'ambre ancien...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ancient Geck", "Gecko ancien", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow.. CLap.CLap.Calp!", "Ouah... Clap. Clap. Clap !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asteroid", "Astéroïde", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A full board clear, but be careful. It crashes after 1 use.", "Nettoie entièrement le plateau, mais attention : il plante après 1 utilisation.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Vial", "Fiole brisée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oops. You bwoke it.", "Oups. Tu l'as cassé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "Brontosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lanky Brontosaurus. It's neck streches so high up, it can catch airborne creatures in mid-air.", "Le Brontosaurus dégingandé. Son cou s'étire si haut qu'il peut attraper des créatures volantes en plein ciel.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asteroid Crashsite", "Site d'impact de l'astéroïde", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DJ Bronto", "DJ Bronto", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fossil", "Fossile", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dinosaur fossil long forgotten. It's slowly falling apart.", "Un fossile de dinosaure oublié depuis longtemps. Il tombe lentement en morceaux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen T-Rex", "T. rex gelé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's frozen. You may regret releasing it.", "Il est gelé. Vous pourriez regretter de le libérer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Dinosaur", "Dinosaure fantôme", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A ghost, stuck in the mortal realm, forever wadnering.", "Un fantôme prisonnier du monde des mortels, condamné à errer éternellement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indominus", "Indominus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long Bronto", "Long Bronto", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalodon", "Mégalodon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even the great white shivers when confronted by this horror..", "Même le grand requin blanc frissonne face à cette horreur...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mononykus", "Mononykus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a weird looking creature..", "Quelle créature étrange...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lepidoptera", "Lépidoptère", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A feeble moth. Maybe you can find a way to power it up?", "Un papillon de nuit fragile. Peut-être trouverez-vous un moyen de le renforcer ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bronto Neck", "Cou de Bronto", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insect Neck", "Cou d'insecte", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feathered Neck", "Cou à plumes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Furry Neck", "Cou poilu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scaly Neck", "Cou écailleux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Neck", "Cou", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Notosaurus", "Notosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Notosaurus, a giant swimming beast.", "Le Notosaurus, une gigantesque bête aquatique.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus", "Parasaurolophus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Parasaurolophus. This beast calls its allies to help defend itself.", "Le Parasaurolophus. Cette bête appelle ses alliés pour l'aider à se défendre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodactyl", "Ptérodactyle", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Pterodactyl, a fearsome flying beast. It swoops down on its prey with maximum efficiency.", "Le Ptérodactyle, une redoutable bête volante. Il fond sur sa proie avec une efficacité maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raptor Hatchling", "Jeune raptor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A weak dinosaur hatchling. Make sure to protect it.", "Un jeune dinosaure fragile. Veillez à le protéger.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rox", "Rox", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a curious creature..", "Quelle curieuse créature...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Raptor", "Raptor mort-vivant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Undead Velociraptor. It manages to stay alive, but only for a while.", "Le Velociraptor mort-vivant. Il parvient à rester en vie, mais seulement un temps.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiked Raptor", "Raptor hérissé de pointes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinosaurus", "Spinosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Spinosaurus. This beast is agile in water, and on land.", "Le Spinosaurus. Cette bête est agile aussi bien dans l'eau que sur terre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Egg", "Œuf mystérieux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't actually know whats in it..", "Je ne sais vraiment pas ce qu'il contient...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tessie", "Tessie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creature originating from a frozen wasteland..", "Une créature originaire d'une étendue glacée...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T-rex", "T. rex", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triceratops", "Triceratops", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mighty Triceratops. It turns from defense, to offense after 1 hit.", "Le puissant Triceratops. Après 1 coup, il passe de la défense à l'attaque.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velociraptor", "Velociraptor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Velociraptor, a flighty, agile beast.", "Le Velociraptor, une bête vive et nerveuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strange Vial", "Fiole étrange", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A demonic fluid in a vile. Under the right conditions it can evolve into a horryfying beast.", "Un liquide démoniaque dans une fiole. Dans les bonnes conditions, il peut évoluer en une bête terrifiante.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Call Allies", "Appel des alliés", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will summon allies adjacent of where the card is placed.", "Quand une carte ornée de cet emblème est jouée, elle invoque des alliés sur les emplacements adjacents vides.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dino-Mod Card Pack", "Paquet de cartes du mod Dino", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds silly dinos and prehistoric beasts to the game!", "Ajoute au jeu de drôles de dinosaures et bêtes préhistoriques !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unknown Hatchling", "Éclosion inconnue", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil has a chance to hatch into a random Dinosaur.", "À la fin du tour, une carte ornée de cet emblème a une chance d'éclore en un dinosaure aléatoire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crumbling", "Effritement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will create 1 bone, but will lose 1 health.", "À la fin du tour, une carte ornée de cet emblème produit 1 os, mais perd 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roar of Terror", "Rugissement de terreur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature opposing the bearer of this sigil will have its damage set to 1.", "Les dégâts de la créature faisant face au porteur de cet emblème sont fixés à 1.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stretching", "Étirement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will move, and stretch it's neck.", "À la fin du tour de son propriétaire, une carte ornée de cet emblème se déplace dans la direction indiquée par l'emblème et étire son cou.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Experimental Vial", "Fiole expérimentale", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil dies, it will transform into a monster.", "Lorsqu'une carte ornée de cet emblème meurt, elle se transforme en monstre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DinoMod", "Mod Dino", Language.French);
        }
    }
