    public class TooManySigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for TooManySigils Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ants Minus", "Fourmis moins une", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cards power is equal to the amount of Ant's on field, minus this one.", "La puissance de cette carte est égale au nombre de fourmis sur le plateau, moins celle-ci.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is damaged, It takes half the Damage it would normally.", "Lorsque cette carte subit des dégâts, elle n'en reçoit que la moitié.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bell Presser", "Sonneur de cloche", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cards power is equal to the amount of times the bell has been rung.", "La puissance de cette carte est égale au nombre de fois que la cloche a sonné.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Borrowed Time", "Temps emprunté", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card perishes its Icecube is summoned if done in time, or else if over the EvolveTurns a corrupt version will be summoned.", "Lorsque cette carte périt à temps, la créature emprisonnée dans sa glace est invoquée. Si le nombre de tours avant évolution est dépassé, une version corrompue est invoquée à la place.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coins Within", "Pièces intérieures", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is struck it provides 1 foil to its owner, as long as it lives anyway.", "Lorsque cette carte est frappée, elle fournit 1 carte Premium à son propriétaire, à condition de survivre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Covalesce", "Convalescence", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is alive during your endstep, This card gains 1 health.", "Si une carte ornée de cet emblème est vivante à la fin de votre tour, elle gagne 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Pack", "Paquet funeste", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it provides 1 Item to its owner.", "Lorsqu'une carte ornée de cet emblème périt, elle fournit 1 objet à son propriétaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish Out Of Water", "Poisson hors de l'eau", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, this card switches from having Airborne to Waterborne and so on. If neither are present will start with Waterborne.", "À la fin du tour, cette carte passe de Vol à Eau ou inversement. Si elle ne possède aucun des deux, elle commence par Eau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain One Battery", "Gagner une batterie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains one Max Energy.", "Quand une carte ornée de cet emblème est jouée, son propriétaire gagne un point d'énergie maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Two Batteries", "Gagner deux batteries", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains two Max Energy.", "Quand une carte ornée de cet emblème est jouée, son propriétaire gagne deux points d'énergie maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Three Batteries", "Gagner trois batteries", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains three Max Energy.", "Quand une carte ornée de cet emblème est jouée, son propriétaire gagne trois points d'énergie maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Four Batteries", "Gagner quatre batteries", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains four Max Energy.", "Quand une carte ornée de cet emblème est jouée, son propriétaire gagne quatre points d'énergie maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Five Batteries", "Gagner cinq batteries", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains five Max Energy.", "Quand une carte ornée de cet emblème est jouée, son propriétaire gagne cinq points d'énergie maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Six Batteries", "Gagner six batteries", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains six Max Energy.", "Quand une carte ornée de cet emblème est jouée, son propriétaire gagne six points d'énergie maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Locked", "Cœur verrouillé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is damaged, It only takes 1 Damage.", "Lorsqu'une carte ornée de cet emblème subit des dégâts, elle ne reçoit que 1 dégât.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is damaged, a card is added to your hand.", "Lorsqu'une carte ornée de cet emblème subit des dégâts, une carte est ajoutée à votre main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is on the field during your endstep, a card is launched to one of your empty spaces.", "Si une carte ornée de cet emblème est sur le terrain à la fin de votre tour, une carte est envoyée sur un de vos emplacements vides.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose One Battery", "Perdre une batterie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses one Max Energy.", "Quand une carte ornée de cet emblème est jouée, son propriétaire perd un point d'énergie maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Two Batteries", "Perdre deux batteries", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses two Max Energy.", "Quand une carte ornée de cet emblème est jouée, son propriétaire perd deux points d'énergie maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Three Batteries", "Perdre trois batteries", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses three Max Energy.", "Quand une carte ornée de cet emblème est jouée, son propriétaire perd trois points d'énergie maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Four Batteries", "Perdre quatre batteries", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses four Max Energy.", "Quand une carte ornée de cet emblème est jouée, son propriétaire perd quatre points d'énergie maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Five Batteries", "Perdre cinq batteries", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses five Max Energy.", "Quand une carte ornée de cet emblème est jouée, son propriétaire perd cinq points d'énergie maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Six Batteries", "Perdre six batteries", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses six Max Energy.", "Quand une carte ornée de cet emblème est jouée, son propriétaire perd six points d'énergie maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Fourth Chance Instakill", "Mort instantanée une fois sur quatre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card would be attacked, there is a 25% chance that the striker perishes.", "Lorsqu'une carte s'apprête à attaquer celle-ci, l'attaquante a 25 % de chances de périr.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rotting", "Putréfaction", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is alive during your endstep, this card loses 1 power and 1 health.", "Si une carte ornée de cet emblème est vivante à la fin de votre tour, elle perd 1 puissance et 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is on field during your endstep, this card moves in the direction inscribed in the sigil, and a card is played in its previous space.", "Si une carte ornée de cet emblème est sur le terrain à la fin de votre tour, elle se déplace dans la direction indiquée par l'emblème et une carte est jouée sur son ancien emplacement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is damaged, It takes 1 less Damage.", "Lorsqu'une carte ornée de cet emblème subit des dégâts, elle en reçoit 1 de moins.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Treasure Tracker", "Chercheur de trésors", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At The end of the Owners turn, this card will provide the owner with 1 foil.", "À la fin du tour de son propriétaire, cette carte lui fournit 1 carte Premium.", Language.French);

        }
    }
    public class PizzaTowerCardsMod
    {
        public static void RegisterTranslations()
        {
