    public class AgasMagnificusExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for AgasMagnificusExpansion Mod");

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aga's Magnificus Expansion", "Extension Magnificus d'Aga", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unofficial expansion to the Magnificus Mod featuring [count] unique and colourful mages", "Une extension non officielle du Mod Magnificus proposant [count] mages uniques et hauts en couleur", Language.French);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascension Mage", "Mage de l'ascension", Language.French);
            MagnificusMod.RegisterCard("Ascension Mage", "Mage de l'ascension", "Utilising the power of time they grant knowledge and experience from far beyond", "Grâce au pouvoir du temps, ils transmettent un savoir et une expérience venus de bien au-delà");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utilising the power of time they grant knowledge and experience from far beyond", "Grâce au pouvoir du temps, ils transmettent un savoir et une expérience venus de bien au-delà", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ash Mage", "Mage des cendres", Language.French);
            MagnificusMod.RegisterCard("Ash Mage", "Mage des cendres", "Ashes he sheds from his own body, scorching any and all who oppose him", "Les cendres qu'il détache de son propre corps brûlent tous ceux qui s'opposent à lui");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ashes he sheds from his own body, scorching any and all who oppose him", "Les cendres qu'il détache de son propre corps brûlent tous ceux qui s'opposent à lui", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Egg", "Œuf cassé", Language.French);
            MagnificusMod.RegisterCard("Broken Egg", "Œuf cassé", "Only the greatest of trainers might find this treasure", "Seuls les plus grands dresseurs pourraient trouver ce trésor");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "Seuls les plus grands dresseurs pourraient trouver ce trésor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chosen One", "Élu", Language.French);
            MagnificusMod.RegisterCard("Chosen One", "Élu", "My selected favourite. He still clings to his elders though...", "Mon préféré, celui que j'ai choisi. Il reste toutefois attaché à ses aînés...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My selected favourite. He still clings to his elders though...", "Mon préféré, celui que j'ai choisi. Il reste toutefois attaché à ses aînés...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanliness Mage", "Mage de la propreté", Language.French);
            MagnificusMod.RegisterCard("Cleanliness Mage", "Mage de la propreté", "The proudest of all my pupils. None come close to his bath superpowers", "Le plus fier de tous mes élèves. Personne n'égale ses superpouvoirs du bain");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The proudest of all my pupils. None come close to his bath superpowers", "Le plus fier de tous mes élèves. Personne n'égale ses superpouvoirs du bain", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleric", "Clerc", Language.French);
            MagnificusMod.RegisterCard("Cleric", "Clerc", "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "Grâce à ses pouvoirs magiques divins, il porte la douleur de tous et les débarrasse de leurs blessures");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "Grâce à ses pouvoirs magiques divins, il porte la douleur de tous et les débarrasse de leurs blessures", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clock Mage", "Mage des horloges", Language.French);
            MagnificusMod.RegisterCard("Clock Mage", "Mage des horloges", "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "Un sorcier maître du temps lui-même. Quand sa fin approche, il retourne dans le passé et revient à la vie");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "Un sorcier maître du temps lui-même. Quand sa fin approche, il retourne dans le passé et revient à la vie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creature Collector", "Collectionneur de créatures", Language.French);
            MagnificusMod.RegisterCard("Creature Collector", "Collectionneur de créatures", "He had searched far and wide for his little companion, you see", "Il avait cherché partout son petit compagnon, voyez-vous");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He had searched far and wide for his little companion, you see", "Il avait cherché partout son petit compagnon, voyez-vous", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division Mage", "Mage de la division", Language.French);
            MagnificusMod.RegisterCard("Division Mage", "Mage de la division", "So the card says at least... I assumed those freaks were long dealth with", "Du moins, c'est ce que dit la carte... Je croyais qu'on s'était débarrassé de ces cinglés depuis longtemps");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So the card says at least... I assumed those freaks were long dealth with", "Du moins, c'est ce que dit la carte... Je croyais qu'on s'était débarrassé de ces cinglés depuis longtemps", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg", "Œuf", Language.French);
            MagnificusMod.RegisterCard("Egg", "Œuf", "Only the greatest of trainers might find this treasure", "Seuls les plus grands dresseurs pourraient trouver ce trésor");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "Seuls les plus grands dresseurs pourraient trouver ce trésor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Druid", "Druide", Language.French);
            MagnificusMod.RegisterCard("Druid", "Druide", "Nature's primal devotee, feeding on sapped mana to cure his allies", "Un dévot primordial de la nature, qui se nourrit de mana drainé pour soigner ses alliés");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nature's primal devotee, feeding on sapped mana to cure his allies", "Un dévot primordial de la nature, qui se nourrit de mana drainé pour soigner ses alliés", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanter", "Enchanteur", Language.French);
            MagnificusMod.RegisterCard("Enchanter", "Enchanteur", "He spews cosmic magicks upon his demise, enchanting everything nearby", "À sa mort, il répand une magie cosmique qui enchante tout ce qui l'entoure");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He spews cosmic magicks upon his demise, enchanting everything nearby", "À sa mort, il répand une magie cosmique qui enchante tout ce qui l'entoure", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EveryMage", "Mage universel", Language.French);
            MagnificusMod.RegisterCard("EveryMage", "Mage universel", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "mage", "mage", Language.French);
            MagnificusMod.RegisterCard("mage", "mage", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evoker", "Évocateur", Language.French);
            MagnificusMod.RegisterCard("Evoker", "Évocateur", "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "Cet inquiétant crétin aux enseignements répugnants peut invoquer des serpents parmi les plus mortels");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "Cet inquiétant crétin aux enseignements répugnants peut invoquer des serpents parmi les plus mortels", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Summon", "Invocation de serpent", Language.French);
            MagnificusMod.RegisterCard("Serpent Summon", "Invocation de serpent", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firebender", "Pyromane", Language.French);
            MagnificusMod.RegisterCard("Firebender", "Pyromane", "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "Plein d'entrain au cœur du combat, il cherche toujours la prochaine victime de ses boules de feu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "Plein d'entrain au cœur du combat, il cherche toujours la prochaine victime de ses boules de feu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "Mage de la prescience", Language.French);
            MagnificusMod.RegisterCard("Foresight Mage", "Mage de la prescience", "As he gazes upon your future, attacks that may come his way he forever predicts", "En contemplant votre avenir, il prédit à jamais les attaques qui pourraient le viser");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As he gazes upon your future, attacks that may come his way he forever predicts", "En contemplant votre avenir, il prédit à jamais les attaques qui pourraient le viser", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "Mage de la prescience", Language.French);
            MagnificusMod.RegisterCard("Foresight Mage", "Mage de la prescience", "Gazing into the future, he may see any body who dares make an approach", "En contemplant l'avenir, il peut voir quiconque ose s'approcher");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gazing into the future, he may see any body who dares make an approach", "En contemplant l'avenir, il peut voir quiconque ose s'approcher", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glacier", "Glacier", Language.French);
            MagnificusMod.RegisterCard("Glacier", "Glacier", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gashadokuro", "Gashadokuro", Language.French);
            MagnificusMod.RegisterCard("Gashadokuro", "Gashadokuro", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Sentinel", "Sentinelle de gemmes", Language.French);
            MagnificusMod.RegisterCard("Gem Sentinel", "Sentinelle de gemmes", "the elite warrior unit enchanted with the aura of my moxen", "L'unité de guerriers d'élite enchantée par l'aura de mes mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the elite warrior unit enchanted with the aura of my moxen", "L'unité de guerriers d'élite enchantée par l'aura de mes mox", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grand Astrologer", "Grand astrologue", Language.French);
            MagnificusMod.RegisterCard("Grand Astrologer", "Grand astrologue", "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "Le champ de bataille est à jamais son terrain de jeu, et l'espace son arme. Rien ne lui est caché.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "Le champ de bataille est à jamais son terrain de jeu, et l'espace son arme. Rien ne lui est caché.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravity Mage", "Mage de la gravité", Language.French);
            MagnificusMod.RegisterCard("Gravity Mage", "Mage de la gravité", "A master of the forces of gravity. Any and all mox bend to his unwavering will", "Un maître des forces de la gravité. Tous les mox se plient à sa volonté inébranlable");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A master of the forces of gravity. Any and all mox bend to his unwavering will", "Un maître des forces de la gravité. Tous les mox se plient à sa volonté inébranlable", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Illusion Mage", "Illusionniste", Language.French);
            MagnificusMod.RegisterCard("Illusion Mage", "Illusionniste", "Dawning his tricks and disguises, there is none scarier. At first glance", "Paré de ses tours et déguisements, nul n'est plus effrayant. À première vue.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dawning his tricks and disguises, there is none scarier. At first glance", "Paré de ses tours et déguisements, nul n'est plus effrayant. À première vue.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infestation Mage", "Mage de l'infestation", Language.French);
            MagnificusMod.RegisterCard("Infestation Mage", "Mage de l'infestation", "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "Je suppose qu'un prétendant usurpateur comme vous pourrait s'adonner à une dose de métamorphose maléfique");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "Je suppose qu'un prétendant usurpateur comme vous pourrait s'adonner à une dose de métamorphose maléfique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insulting Mirror", "Miroir insultant", Language.French);
            MagnificusMod.RegisterCard("Insulting Mirror", "Miroir insultant", "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "La menace magique virevolte partout, lançant railleries et commentaires insolents ; elle transforme votre colère en force");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "La menace magique virevolte partout, lançant railleries et commentaires insolents ; elle transforme votre colère en force", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iron Maiden", "Vierge de fer", Language.French);
            MagnificusMod.RegisterCard("Iron Maiden", "Vierge de fer", "My finest of paladins working the finest of hours. No soul goes through his grand wall", "Le meilleur de mes paladins à son poste aux meilleures heures. Nulle âme ne traverse son grand mur");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My finest of paladins working the finest of hours. No soul goes through his grand wall", "Le meilleur de mes paladins à son poste aux meilleures heures. Nulle âme ne traverse son grand mur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kickmoxer", "Moxeur", Language.French);
            MagnificusMod.RegisterCard("Kickmoxer", "Moxeur", "He dedicated his life to the art of combat, and may adapt to whomever he faces", "Il a consacré sa vie à l'art du combat et peut s'adapter à tous ses adversaires");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He dedicated his life to the art of combat, and may adapt to whomever he faces", "Il a consacré sa vie à l'art du combat et peut s'adapter à tous ses adversaires", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mass Grave", "Fosse commune", Language.French);
            MagnificusMod.RegisterCard("Mass Grave", "Fosse commune", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Agairan", "Maître Agairan", Language.French);
            MagnificusMod.RegisterCard("Master Agairan", "Maître Agairan", "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "La chimère écarlate. Le maître d'alchimie inculque les toxines les plus mortelles");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "La chimère écarlate. Le maître d'alchimie inculque les toxines les plus mortelles", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Bluetwo", "Maître Deuxbleu", Language.French);
            MagnificusMod.RegisterCard("Master Bluetwo", "Maître Deuxbleu", "The steel knight of sapphire. Even after death her psychic presence commands our foes", "La chevalière d'acier du saphir. Même après sa mort, sa présence psychique commande à nos ennemis");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The steel knight of sapphire. Even after death her psychic presence commands our foes", "La chevalière d'acier du saphir. Même après sa mort, sa présence psychique commande à nos ennemis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Doublin", "Maître Doublin", Language.French);
            MagnificusMod.RegisterCard("Master Doublin", "Maître Doublin", "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "Le messie du roi des os. Le maître de la prière a appris à dérober l'essence avec habileté.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "Le messie du roi des os. Le maître de la prière a appris à dérober l'essence avec habileté.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megawizard", "Mégasorcier", Language.French);
            MagnificusMod.RegisterCard("Megawizard", "Mégasorcier", "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "Massif dans sa menace, menaçant jusque dans son esprit obscur. Une telle puissance brute ne saurait durer éternellement");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "Massif dans sa menace, menaçant jusque dans son esprit obscur. Une telle puissance brute ne saurait durer éternellement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meteorologist", "Météorologue", Language.French);
            MagnificusMod.RegisterCard("Meteorologist", "Météorologue", "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "Ils observent attentivement l'univers et lancent des pluies de météores sur qui bon leur semble. Cruels ? Peut-être. Eux seuls le savent");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "Ils observent attentivement l'univers et lancent des pluies de météores sur qui bon leur semble. Cruels ? Peut-être. Eux seuls le savent", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miniwizard", "Minisorcier", Language.French);
            MagnificusMod.RegisterCard("Miniwizard", "Minisorcier", "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "Un mage maudit par sa taille minuscule. Mais rassurez-vous, il a trouvé une solution.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "Un mage maudit par sa taille minuscule. Mais rassurez-vous, il a trouvé une solution.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Thief", "Voleur spectral", Language.French);
            MagnificusMod.RegisterCard("Phantom Thief", "Voleur spectral", "A billowing cloud of crime, darting in and out, and stealing his foes", "Un nuage de crime tourbillonnant, qui surgit et disparaît en volant ses ennemis");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A billowing cloud of crime, darting in and out, and stealing his foes", "Un nuage de crime tourbillonnant, qui surgit et disparaît en volant ses ennemis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Preformence Mage", "Mage du prélude", Language.French);
            MagnificusMod.RegisterCard("Preformence Mage", "Mage du prélude", "Who knows to what ends his mystery rabbit has been through", "Qui sait tout ce que son mystérieux lapin a bien pu traverser");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows to what ends his mystery rabbit has been through", "Qui sait tout ce que son mystérieux lapin a bien pu traverser", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queen's Familiar", "Familier de la reine", Language.French);
            MagnificusMod.RegisterCard("Queen's Familiar", "Familier de la reine", "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "Une chimère majestueuse composée de belles bêtes. Elle garde ses armées tout près, en elle");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "Une chimère majestueuse composée de belles bêtes. Elle garde ses armées tout près, en elle", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RisingHunger", "Faim croissante", Language.French);
            MagnificusMod.RegisterCard("RisingHunger", "Faim croissante", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roach Familiar", "Familier cafard", Language.French);
            MagnificusMod.RegisterCard("Roach Familiar", "Familier cafard", "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "Un cafard créé par l'esprit. Sa volonté lui confère des pouvoirs de résurrection ! Qui finissent par échouer.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "Un cafard créé par l'esprit. Sa volonté lui confère des pouvoirs de résurrection ! Qui finissent par échouer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Wizard", "Sorcier de l'ombre", Language.French);
            MagnificusMod.RegisterCard("Shadow Wizard", "Sorcier de l'ombre", "A mobster of the underseen. He calls the shadows to gang on it's foes", "Un gangster des bas-fonds invisibles. Il appelle les ombres à s'unir contre ses ennemis");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mobster of the underseen. He calls the shadows to gang on it's foes", "Un gangster des bas-fonds invisibles. Il appelle les ombres à s'unir contre ses ennemis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shinobi", "Shinobi", Language.French);
            MagnificusMod.RegisterCard("Shinobi", "Shinobi", "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "Guerriers des ténèbres, ils frappent par surprise depuis des lieux que nul ne revendique ni ne voit");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "Guerriers des ténèbres, ils frappent par surprise depuis des lieux que nul ne revendique ni ne voit", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shower Mage", "Mage de la douche", Language.French);
            MagnificusMod.RegisterCard("Shower Mage", "Mage de la douche", "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "Le paria de mon école, et à juste titre ! Sa puanteur ne peut se décrire qu'avec de la magie...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "Le paria de mon école, et à juste titre ! Sa puanteur ne peut se décrire qu'avec de la magie...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sludge Mage", "Mage des boues", Language.French);
            MagnificusMod.RegisterCard("Sludge Mage", "Mage des boues", "An entity of unknown origins, powered off the ill spreading plague to all", "Une entité d'origine inconnue, alimentée par la maladie et répandant la peste partout");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An entity of unknown origins, powered off the ill spreading plague to all", "Une entité d'origine inconnue, alimentée par la maladie et répandant la peste partout", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sui-Sage", "Sage Sui", Language.French);
            MagnificusMod.RegisterCard("Sui-Sage", "Sage Sui", "The leader of a pack, soon to be packed away", "Le chef d'une meute, bientôt remballé à son tour");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The leader of a pack, soon to be packed away", "Le chef d'une meute, bientôt remballé à son tour", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "Invocateur", Language.French);
            MagnificusMod.RegisterCard("Summoner", "Invocateur", "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "Un fou des arts de la vie : il la crée à partir de rien, avec une sensibilité effrayante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "Un fou des arts de la vie : il la crée à partir de rien, avec une sensibilité effrayante", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Symmetrical Mage", "Mage symétrique", Language.French);
            MagnificusMod.RegisterCard("Symmetrical Mage", "Mage symétrique", "Everyone has two sides to them, you see. Especially once they mess with my temper", "Tout le monde a deux côtés, voyez-vous. Surtout quand on me met en colère");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone has two sides to them, you see. Especially once they mess with my temper", "Tout le monde a deux côtés, voyez-vous. Surtout quand on me met en colère", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teleportation Mage", "Mage de la téléportation", Language.French);
            MagnificusMod.RegisterCard("Teleportation Mage", "Mage de la téléportation", "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "Un héraut des portails sans fin, qui bondit éternellement sur le champ de bataille et annule les attaques reçues");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "Un héraut des portails sans fin, qui bondit éternellement sur le champ de bataille et annule les attaques reçues", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torrent Mage", "Mage du torrent", Language.French);
            MagnificusMod.RegisterCard("Torrent Mage", "Mage du torrent", "An apprentice of the ocean utilising it to drown the lands and the terrain above", "Un apprenti de l'océan qui l'utilise pour submerger les terres et le terrain à leur surface");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An apprentice of the ocean utilising it to drown the lands and the terrain above", "Un apprenti de l'océan qui l'utilise pour submerger les terres et le terrain à leur surface", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Untamed Dragon", "Dragon indompté", Language.French);
            MagnificusMod.RegisterCard("Untamed Dragon", "Dragon indompté", "Legends whisper this beast, was once a companion to the mox master Goranj", "Les légendes murmurent que cette bête fut jadis la compagne du maître des mox Vorange");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends whisper this beast, was once a companion to the mox master Goranj", "Les légendes murmurent que cette bête fut jadis la compagne du maître des mox Vorange", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warlock", "Démoniste", Language.French);
            MagnificusMod.RegisterCard("Warlock", "Démoniste", "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "Un sorcier noirci qui étudie la magie du sang. Il transforme ces saignements en une arme terrible");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "Un sorcier noirci qui étudie la magie du sang. Il transforme ces saignements en une arme terrible", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wicked Witch", "Sorcière maléfique", Language.French);
            MagnificusMod.RegisterCard("Wicked Witch", "Sorcière maléfique", "A flying jesting witch, laughing your sorrows and posioning your armies", "Une sorcière volante et moqueuse, qui rit de vos malheurs et empoisonne vos armées");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying jesting witch, laughing your sorrows and posioning your armies", "Une sorcière volante et moqueuse, qui rit de vos malheurs et empoisonne vos armées", Language.French);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acid Aura", "Aura acide", Language.French);
            MagnificusMod.RegisterAbility("Acid Aura", "Aura acide");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals 1 damage to the creature opposing it every turn", "[creature] inflige 1 dégât à la créature qui lui fait face à chaque tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakening", "Éveil", Language.French);
            MagnificusMod.RegisterAbility("Awakening", "Éveil");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner chooses an ally creature to evolve into a higher form.", "Quand la carte [creature] est jouée, son propriétaire choisit une créature alliée qui évolue vers une forme supérieure.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backfire Strike", "Frappe à contrecoup", Language.French);
            MagnificusMod.RegisterAbility("Backfire Strike", "Frappe à contrecoup");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] damages creatures that oppose those it attacks.", "[creature] inflige aussi des dégâts à la carte de son côté qui fait face à chacune des cibles qu'elle attaque.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "Soif de sang", Language.French);
            MagnificusMod.RegisterAbility("Blood Guzzler", "Soif de sang");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, it gains 1 health for each damage dealt.", "Quand la carte [creature] inflige des dégâts, elle gagne 1 santé pour chaque point de dégâts infligé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brute Parasite", "Parasite brutal", Language.French);
            MagnificusMod.RegisterAbility("Brute Parasite", "Parasite brutal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, an Egg is created on the opposing space.", "Quand la carte [creature] est jouée, un Œuf est créé sur l'emplacement en face.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deluge", "Déluge", Language.French);
            MagnificusMod.RegisterAbility("Deluge", "Déluge");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, opponent creatures with 0 power drown and get given the Waterborne sigil.", "Quand la carte [creature] est jouée, les créatures adverses ayant 0 puissance s'immergent et gagnent l'emblème Eau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division", "Division", Language.French);
            MagnificusMod.RegisterAbility("Division", "Division");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] splits into 2 identical clones, each bearing half of it's original stats.", "Après avoir attaqué, [creature] se divise en 2 clones identiques, possédant chacun la moitié de ses caractéristiques d'origine.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentry", "Sentinelle", Language.French);
            MagnificusMod.RegisterAbility("Sentry", "Sentinelle");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they are dealt 1 damage.", "Quand une créature se déplace sur l'emplacement en face de [creature], elle subit 1 dégât.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, let one never underestimate the speed of a Foresight Mage.", "Ah, il ne faut jamais sous-estimer la vitesse d'un Mage de la prescience.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healing Aura", "Aura de soin", Language.French);
            MagnificusMod.RegisterAbility("Healing Aura", "Aura de soin");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals nearby allied creatures. The healing is proportionate to it's power.", "[creature] soigne les créatures alliées à proximité. Les soins sont proportionnels à sa puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Stealer", "Voleur de cœurs", Language.French);
            MagnificusMod.RegisterAbility("Heart Stealer", "Voleur de cœurs");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "when [creature] kills a creature, it gets added to your hand.", "Lorsque [creature] tue une créature, la carte de la victime est ajoutée à votre main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignis Incant", "Incantation de feu", Language.French);
            MagnificusMod.RegisterAbility("Ignis Incant", "Incantation de feu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood for [creature] to deal 2 damage to a chosen opposing slot.", "Payez 1 de sang pour que [creature] inflige 2 dégâts à un emplacement adverse choisi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intimidate", "Intimidation", Language.French);
            MagnificusMod.RegisterAbility("Intimidate", "Intimidation");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is placed on the board, the creature opposing it will flee to their right.", "Quand [creature] est placée sur le plateau, la créature qui lui fait face fuit vers sa droite.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonesome", "Solitude", Language.French);
            MagnificusMod.RegisterAbility("Lonesome", "Solitude");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent empty space.", "La carte [creature] gagne +1 puissance par emplacement adjacent vide.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Burst", "Explosion magique", Language.French);
            MagnificusMod.RegisterAbility("Magic Burst", "Explosion magique");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After perishing, creatures adjascent to [creature] have their powers increased by 1.", "Après la mort de [creature], les créatures adjacentes gagnent 1 puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psystrike", "Frappe psychique", Language.French);
            MagnificusMod.RegisterAbility("Psystrike", "Frappe psychique");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] perishes, it manipulates the creature opposing it to strike both of it's adjascent allies.", "Après sa mort, [creature] manipule la créature qui lui fait face pour qu'elle frappe ses deux alliés adjacents.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Master", "Maître des serpents", Language.French);
            MagnificusMod.RegisterAbility("Serpent Master", "Maître des serpents");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every turn, [creature] spawns a Summon Serpent on a space of it's owner's choosing. A Summon Serpent is defined as: 1 power, 1 health.", "Au début de chaque tour, [creature] crée une Invocation de serpent sur un emplacement choisi par son propriétaire. Une Invocation de serpent possède 1 puissance et 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Strike", "Frappe de l'ombre", Language.French);
            MagnificusMod.RegisterAbility("Shadow Strike", "Frappe de l'ombre");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls upon the shadows of creatures adjascent to it's target to strike it as well.", "[creature] invoque les ombres des créatures adjacentes à sa cible pour qu'elles la frappent aussi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tidal Lock", "Verrouillage gravitationnel", Language.French);
            MagnificusMod.RegisterAbility("Tidal Lock", "Verrouillage gravitationnel");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the beginning of it's owner's turn, [creature] will pull small creatures, like squirrels, into it's orbit.", "Au début du tour de son propriétaire, [creature] attire de petites créatures, comme les écureuils, sur son orbite.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wizard's Heart", "Cœur de sorcier", Language.French);
            MagnificusMod.RegisterAbility("Wizard's Heart", "Cœur de sorcier");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Mox card corresponding to the current gems you control takes it's place.", "Quand la carte [creature] meurt, une carte mox correspondant aux gemmes que vous contrôlez actuellement prend sa place.", Language.French);

        }
    }
    public class MagModExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagModExpansion Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beaver's Defense", "Défense du castor", Language.French);
            MagnificusMod.RegisterCard("Beaver's Defense", "Défense du castor", "Curating defensive dams upon use, not bad for a dire situation.", "Elle crée des barrages défensifs à l'utilisation : pas mal dans une situation désespérée.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curating defensive dams upon use, not bad for a dire situation.", "Elle crée des barrages défensifs à l'utilisation : pas mal dans une situation désespérée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Sage", "Sage des bombes", Language.French);
            MagnificusMod.RegisterCard("Bomb Sage", "Sage des bombes", "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "Quand il est attaqué, ce sage est connu pour exploser... Au propre comme au figuré.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "Quand il est attaqué, ce sage est connu pour exploser... Au propre comme au figuré.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boxing Champ", "Champion de boxe", Language.French);
            MagnificusMod.RegisterCard("Boxing Champ", "Champion de boxe", "Rejecting the use of wands, this champion prefers to settle things with his fists.", "Refusant les baguettes magiques, ce champion préfère régler les choses avec ses poings.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejecting the use of wands, this champion prefers to settle things with his fists.", "Refusant les baguettes magiques, ce champion préfère régler les choses avec ses poings.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "Brontosaurus", Language.French);
            MagnificusMod.RegisterCard("Brontosaurus", "Brontosaurus", "I LOVE DINO MOD!!!!!", "J'ADORE LE MOD DINO !!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "J'ADORE LE MOD DINO !!!!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "Sorcier du fromage", Language.French);
            MagnificusMod.RegisterCard("Cheese Wizard", "Sorcier du fromage", "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "En tant que chefs-mages formés, les sorciers du fromage utilisent leur intelligence et leur mysticisme pour atteindre leurs objectifs.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "En tant que chefs-mages formés, les sorciers du fromage utilisent leur intelligence et leur mysticisme pour atteindre leurs objectifs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheezling", "Fromaget", Language.French);
            MagnificusMod.RegisterCard("Cheezling", "Fromaget", "With cheese like this, who needs friends?", "Avec un tel fromage, qui a besoin d'amis ?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With cheese like this, who needs friends?", "Avec un tel fromage, qui a besoin d'amis ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Telepathy", "Télépathie", Language.French);
            MagnificusMod.RegisterCard("Telepathy", "Télépathie", "A pupil can gather all the resources they need through sheer will alone.", "Un élève peut réunir toutes les ressources nécessaires par la seule force de sa volonté.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pupil can gather all the resources they need through sheer will alone.", "Un élève peut réunir toutes les ressources nécessaires par la seule force de sa volonté.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Hit", "Coup direct", Language.French);
            MagnificusMod.RegisterCard("Direct Hit", "Coup direct", "Upon being casted, your opponent will instantly take three damage.", "Une fois lancé, ce sort inflige immédiatement trois dégâts à votre adversaire.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon being casted, your opponent will instantly take three damage.", "Une fois lancé, ce sort inflige immédiatement trois dégâts à votre adversaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Egg", "Œuf mystérieux", Language.French);
            MagnificusMod.RegisterCard("Mysterious Egg", "Œuf mystérieux", "Who knows what could hatch from this egg...", "Qui sait ce qui pourrait sortir de cet œuf...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows what could hatch from this egg...", "Qui sait ce qui pourrait sortir de cet œuf...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faceless", "Sans-visage", Language.French);
            MagnificusMod.RegisterCard("Faceless", "Sans-visage", "A hollow shell of a mage, desperately looking for something to call its own.", "L'enveloppe vide d'un mage, qui cherche désespérément quelque chose à appeler sien.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hollow shell of a mage, desperately looking for something to call its own.", "L'enveloppe vide d'un mage, qui cherche désespérément quelque chose à appeler sien.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faker", "Faussaire", Language.French);
            MagnificusMod.RegisterCard("Faker", "Faussaire", "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "Mentir. Tricher. Nier. Tout ce que le Faussaire est prêt à faire pour s'en sortir indemne...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "Mentir. Tricher. Nier. Tout ce que le Faussaire est prêt à faire pour s'en sortir indemne...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Figletar", "Figletar", Language.French);
            MagnificusMod.RegisterCard("Figletar", "Figletar", "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "Un sorcier qui a conduit un roi maléfique à une terrible fin ; il s'y connaît sur le ring.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "Un sorcier qui a conduit un roi maléfique à une terrible fin ; il s'y connaît sur le ring.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firestarter", "Boutefeu", Language.French);
            MagnificusMod.RegisterCard("Firestarter", "Boutefeu", "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "Attention en lançant ce sort : des élèves signalent qu'il peut faire un peu chaud sur le terrain de duel.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "Attention en lançant ce sort : des élèves signalent qu'il peut faire un peu chaud sur le terrain de duel.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fridge Mage", "Mage du frigo", Language.French);
            MagnificusMod.RegisterCard("Fridge Mage", "Mage du frigo", "Its cold atmosphere will chill foes, weakening their offensive power.", "Son atmosphère glaciale refroidit les ennemis et affaiblit leur puissance offensive.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its cold atmosphere will chill foes, weakening their offensive power.", "Son atmosphère glaciale refroidit les ennemis et affaiblit leur puissance offensive.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembro", "Frérogemme", Language.French);
            MagnificusMod.RegisterCard("Gembro", "Frérogemme", "The ability to tank any hit once, this pupil has high gusto.", "Capable d'encaisser une fois n'importe quel coup, cet élève ne manque pas d'entrain.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ability to tank any hit once, this pupil has high gusto.", "Capable d'encaisser une fois n'importe quel coup, cet élève ne manque pas d'entrain.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Tick", "Tique de gemme", Language.French);
            MagnificusMod.RegisterCard("Gem Tick", "Tique de gemme", "An elusive tick, which grants power to others via its mox body.", "Une tique insaisissable qui donne de la puissance aux autres grâce à son corps de mox.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elusive tick, which grants power to others via its mox body.", "Une tique insaisissable qui donne de la puissance aux autres grâce à son corps de mox.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Dinosaur", "Dinosaure fantôme", Language.French);
            MagnificusMod.RegisterCard("Ghost Dinosaur", "Dinosaure fantôme", "I LOVE DINO MOD!!!!!", "J'ADORE LE MOD DINO !!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "J'ADORE LE MOD DINO !!!!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third Eye", "Troisième œil", Language.French);
            MagnificusMod.RegisterCard("Third Eye", "Troisième œil", "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "Grâce au pouvoir du troisième œil, ce sort permet à son lanceur de choisir une carte dans son deck restant et de l'ajouter à sa main.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "Grâce au pouvoir du troisième œil, ce sort permet à son lanceur de choisir une carte dans son deck restant et de l'ajouter à sa main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "Mage du baseball", Language.French);
            MagnificusMod.RegisterCard("Baseball Mage", "Mage du baseball", "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "La baguette de ce mage lui sert aussi de batte de baseball. Elle est étonnamment solide.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "La baguette de ce mage lui sert aussi de batte de baseball. Elle est étonnamment solide.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Golem", "Golem de glace", Language.French);
            MagnificusMod.RegisterCard("Ice Golem", "Golem de glace", "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "Originaire d'un sommet glacé, cette brute ne semble jamais se soucier de fondre.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "Originaire d'un sommet glacé, cette brute ne semble jamais se soucier de fondre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looting Bandit", "Bandit pilleur", Language.French);
            MagnificusMod.RegisterCard("Looting Bandit", "Bandit pilleur", "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "Un lointain disciple des valkyries de Maître Oreu, qui s’entraîne pour leur ressembler.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "Un lointain disciple des valkyries de Maître Oreu, qui s’entraîne pour leur ressembler.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mage", "Mage du mana", Language.French);
            MagnificusMod.RegisterCard("Mana Mage", "Mage du mana", "Brings together the energy that emits from Mana to deliver powerful strikes.", "Il rassemble l'énergie émise par le mana pour porter de puissants coups.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brings together the energy that emits from Mana to deliver powerful strikes.", "Il rassemble l'énergie émise par le mana pour porter de puissants coups.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pondering Pupil", "Élève pensif", Language.French);
            MagnificusMod.RegisterCard("Pondering Pupil", "Élève pensif", "It draws from your gem pile using the powers of its mind alone.", "Il pioche dans votre pile de gemmes par la seule force de son esprit.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It draws from your gem pile using the powers of its mind alone.", "Il pioche dans votre pile de gemmes par la seule force de son esprit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror Mage", "Mage des miroirs", Language.French);
            MagnificusMod.RegisterCard("Mirror Mage", "Mage des miroirs", "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "Miroir, miroir, dis-moi qui est le meilleur scrybe de tous ?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "Miroir, miroir, dis-moi qui est le meilleur scrybe de tous ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whack-A-Mage", "Tape-mage", Language.French);
            MagnificusMod.RegisterCard("Whack-A-Mage", "Tape-mage", "Always popping up to cause mischief whenever he can.", "Il surgit sans cesse pour semer la pagaille dès qu'il en a l'occasion.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always popping up to cause mischief whenever he can.", "Il surgit sans cesse pour semer la pagaille dès qu'il en a l'occasion.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mononykus", "Mononykus", Language.French);
            MagnificusMod.RegisterCard("Mononykus", "Mononykus", "I LOVE DINO MOD!!!!!", "J'ADORE LE MOD DINO !!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "J'ADORE LE MOD DINO !!!!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PLUTO", "PLUTON", Language.French);
            MagnificusMod.RegisterCard("PLUTO", "PLUTON", "Hmph. So this is where that one went.", "Humph. C'est donc là qu'il est passé.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph. So this is where that one went.", "Humph. C'est donc là qu'il est passé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protect", "Protection", Language.French);
            MagnificusMod.RegisterCard("Protect", "Protection", "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "Dans une situation difficile ? Ce sort rend une de vos cartes totalement immunisée contre la prochaine attaque qu'elle subit.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "Dans une situation difficile ? Ce sort rend une de vos cartes totalement immunisée contre la prochaine attaque qu'elle subit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodactyl", "Ptérodactyle", Language.French);
            MagnificusMod.RegisterCard("Pterodactyl", "Ptérodactyle", "I LOVE DINO MOD!!!!!", "J'ADORE LE MOD DINO !!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "J'ADORE LE MOD DINO !!!!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbid Sage", "Sage lapin fou", Language.French);
            MagnificusMod.RegisterCard("Rabbid Sage", "Sage lapin fou", "A raving magician with a field of electricity at his disposal.", "Un magicien délirant qui dispose d'un champ électrique.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A raving magician with a field of electricity at his disposal.", "Un magicien délirant qui dispose d'un champ électrique.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemox", "Squeletmox", Language.French);
            MagnificusMod.RegisterCard("Skelemox", "Squeletmox", "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "Un pauvre squelette contrôlé par un Mox vert. J'en aurais presque pitié.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "Un pauvre squelette contrôlé par un Mox vert. J'en aurais presque pitié.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime Wiz", "Sorcier de glu", Language.French);
            MagnificusMod.RegisterCard("Slime Wiz", "Sorcier de glu", "It'll use the slime against the enemies, to drop their attack whence struck.", "Il utilise sa glu contre les ennemis pour réduire leur attaque lorsqu'il est frappé.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It'll use the slime against the enemies, to drop their attack whence struck.", "Il utilise sa glu contre les ennemis pour réduire leur attaque lorsqu'il est frappé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smug Witch", "Sorcière vaniteuse", Language.French);
            MagnificusMod.RegisterCard("Smug Witch", "Sorcière vaniteuse", "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "L'élève le plus vaniteux du pays. La légende dit que son Lancer vaniteux est inégalé.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "L'élève le plus vaniteux du pays. La légende dit que son Lancer vaniteux est inégalé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Spear", "Lance d'invocation", Language.French);
            MagnificusMod.RegisterCard("Summon Spear", "Lance d'invocation", "Roots up a spear from the ground, acting as a sturdy counter.", "Fait sortir une lance du sol pour servir de solide contre-attaque.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roots up a spear from the ground, acting as a sturdy counter.", "Fait sortir une lance du sol pour servir de solide contre-attaque.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spike Mage", "Mage des piques", Language.French);
            MagnificusMod.RegisterCard("Spike Mage", "Mage des piques", "This mage learned from the best of my Pike Mage's Scarecrows.", "Ce mage a appris auprès des meilleurs épouvantails de mon Mage lancier.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage learned from the best of my Pike Mage's Scarecrows.", "Ce mage a appris auprès des meilleurs épouvantails de mon Mage lancier.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T-Rex", "T. rex", Language.French);
            MagnificusMod.RegisterCard("T-Rex", "T. rex", "I LOVE DINO MOD!!!!!", "J'ADORE LE MOD DINO !!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "J'ADORE LE MOD DINO !!!!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Virtual King", "Roi virtuel", Language.French);
            MagnificusMod.RegisterCard("Virtual King", "Roi virtuel", "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "Souverain autoproclamé des terres virtuelles, qui ne se soumettra pas aux minables « règles du jeu de cartes ».");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "Souverain autoproclamé des terres virtuelles, qui ne se soumettra pas aux minables « règles du jeu de cartes ».", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moron Core", "Cœur d'idiot", Language.French);
            MagnificusMod.RegisterCard("Moron Core", "Cœur d'idiot", "An odd core hailing from an abandoned factory, hates the word \"moron\".", "Un étrange cœur issu d'une usine abandonnée, qui déteste le mot « idiot ».");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An odd core hailing from an abandoned factory, hates the word \"moron\".", "Un étrange cœur issu d'une usine abandonnée, qui déteste le mot « idiot ».", Language.French);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smughtro's MagMod Expansion", "Extension MagMod de Smughtro", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 19 common cards, 7 rare cards, 7 spells, and 6 token cards to Magnificus Mod.", "Ajoute au Mod Magnificus 19 cartes communes, 7 cartes rares, 7 sorts et 6 cartes jetons.", Language.French);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Assist", "Aide funèbre", Language.French);
            MagnificusMod.RegisterAbility("Death Assist", "Aide funèbre");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it will deal 3 damage to the opponent.", "Lorsqu'une carte ornée de cet emblème meurt, elle inflige 3 dégâts à l'adversaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emmental Elemental", "Élémentaire d'emmental", Language.French);
            MagnificusMod.RegisterAbility("Emmental Elemental", "Élémentaire d'emmental");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, summon a Cheezling.", "Quand une carte ornée de cet emblème est jouée, invoquez un Fromaget.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Strike", "Première frappe", Language.French);
            MagnificusMod.RegisterAbility("First Strike", "Première frappe");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will instantly attack the opposing lane. If there are no opposing cards, no damage will be dealt.", "Quand une carte ornée de cet emblème est jouée, elle attaque immédiatement la voie en face. S'il n'y a aucune carte adverse, aucun dégât n'est infligé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unknown Hatching", "Éclosion inconnue", Language.French);
            MagnificusMod.RegisterAbility("Unknown Hatching", "Éclosion inconnue");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of your turn, a card bearing this sigil will hatch into a random dinosaur.", "Au début du tour de son propriétaire, une carte ornée de cet emblème éclot en un dinosaure aléatoire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healthy Death", "Mort revigorante", Language.French);
            MagnificusMod.RegisterAbility("Healthy Death", "Mort revigorante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the cards to the left and right of the sigil bearer heal 1 health.", "Lorsqu'une carte ornée de cet emblème meurt, les cartes à sa gauche et à sa droite récupèrent chacune 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mess", "Chaos de mana", Language.French);
            MagnificusMod.RegisterAbility("Mana Mess", "Chaos de mana");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random non-rare Mana costing card.", "Quand une carte ornée de cet emblème est jouée, piochez une carte aléatoire non rare qui coûte du mana.", Language.French);

        }
    }
    public class FloweysMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for FloweysMod Mod");


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flowey", "Flowey", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fanatical leader hell-bent on bringing about the apocalypse by reviving the great Cthulhu through behind-the-scenes scheming.", "Un chef fanatique déterminé à provoquer l'apocalypse en ressuscitant le grand Cthulhu grâce à ses manigances en coulisses.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You Idiot", "Espèce d'idiot", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an Idiot if you think you can defeat me!", "Tu es vraiment idiot si tu crois pouvoir me vaincre !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omega Flowey", "Flowey Oméga", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an idiot.", "Tu es vraiment idiot.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patience", "Patience", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "patient.", "Patient.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bravery", "Bravoure", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brave.", "Courageux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Integrity", "Intégrité", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "integrant.", "Intègre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perseverence", "Persévérance", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persevering.", "Persévérant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kindness", "Bonté", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kind.", "Aimable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice", "Justice", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice.", "Justice.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy- Uh i meant Are you ready to Die?", "Salut ! Euh... je voulais dire : es-tu prêt à mourir ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy! it's me Flowey, Flowey the Flower!", "Salut ! C'est moi, Flowey, Flowey la fleur !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know whats going on here, dont you?", "Tu sais ce qui se passe ici, n'est-ce pas ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You just wanted to see me suffer[c:0]!", "Tu voulais juste me voir souffrir[c:0] !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do You know that ive been watching you?", "Sais-tu que je t'observe depuis tout ce temps ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well i took over Inscryption now!", "Eh bien, j'ai pris le contrôle d'Inscryption !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and i know what Secrets are hiding beneath Inscryption...", "Et je sais quels secrets se cachent sous Inscryption...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now nothing stands in my Way to take over the World now!", "Plus rien ne peut m'empêcher de conquérir le monde !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you think this Fight was about?", "À ton avis, à quoi servait ce combat ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just used it as a cover to snoop through Inscryptions Files!", "Je m'en suis servi comme couverture pour fouiller les fichiers d'Inscryption !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And your PC of course!", "Et de ton ordinateur, bien sûr !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you may have noticed, BUT iam now connected to the Internet!", "Tu l'as peut-être remarqué, MAIS je suis maintenant connecté à Internet !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So now its time to begin Uploading Inscryption!", "Il est temps de commencer à téléverser Inscryption !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You REALLY are an Idiot!", "Tu es VRAIMENT un idiot !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't even need the Power of Human Souls if i just use the OLD_DATA!", "Je n'ai même pas besoin du pouvoir des âmes humaines si j'utilise les ANCIENNES_DONNÉES !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Do you know what you are achieving by this? Nothing", "[c:bR]Sais-tu ce que tu obtiens en faisant ça ? Rien.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]You cant get rid of me! No matter what you do, i will always be there!", "[c:bR]Tu ne peux pas te débarrasser de moi ! Quoi que tu fasses, je serai toujours là !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Th- The Souls?", "[c:bR]L-les âmes ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]wh- where are my Powers?", "[c:bR]O-où sont mes pouvoirs ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHAT HAVE YOU DONE?!", "[c:bR]QU'AS-TU FAIT ?!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Floweys Defence dropped to [c:bR]0!", "La défense de Flowey est tombée à [c:bR]0 !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOOOOOO", "[c:bR]NOOOOOON", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What just happened...", "Qu'est-ce qui vient de se passer...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph seemms you have won this time...", "Hmph, on dirait que tu as gagné cette fois...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOBODY IS GOING TO HELP YOU!", "[c:bR]PERSONNE NE VIENDRA T'AIDER !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP CALLING FOR [c:bR]HELP!", "ARRÊTE D'APPELER À L'[c:bR]AIDE !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Did you really think id let you kill me so easily?", "[c:bR]Tu croyais vraiment que je te laisserais me tuer aussi facilement ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]what the-", "[c:bR]Mais qu'est-ce que...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Flowey thought they could just use me...", "[c:bR]Flowey croyait pouvoir se servir de moi...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He didnt even know what I am!", "[c:bR]Il ne savait même pas ce que je suis !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]But now IAM in control...", "[c:bR]Mais maintenant, c'est MOI qui commande...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]How pathetic of him to not set his HP to Infinite... I won't make that mistake", "[c:bR]Pathétique, il n'a même pas réglé ses PV sur l'infini... Je ne ferai pas cette erreur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Try all you want you can't kill me!", "[c:bR]Essaie autant que tu voudras, tu ne peux pas me tuer !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Now lets see what this does...", "[c:bR]Voyons maintenant ce que ça fait...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHY CANT I UNDO THIS???", "[c:bR]POURQUOI JE NE PEUX PAS ANNULER ÇA ???", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SEEING YOU DIE OVER AND OVER AGIAN IS REALLY [c:bR]FUN!", "TE VOIR MOURIR ENCORE ET ENCORE, C'EST VRAIMENT [c:bR]AMUSANT !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT EVEN A SINGLE POINT OF DAMAGE!", "PAS MÊME UN SEUL POINT DE DÉGÂTS !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOMEONE LIKE [c:bR]YOUCANT BEAT ME!", "QUELQU'UN COMME [c:bR]TOI NE PEUT PAS ME VAINCRE !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Starvation wont interrupt this fight!", "[c:bR]La Famine n'interrompra pas ce combat !", Language.French);


        }
    }
    public class UndertaleMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for UndertaleMod Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack:U", "Paquet de cartes : Undertale", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aaron", "Aaron", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, Aaron the bold, aaron the beautiful. can you manage to take your eyes off his muscles?", "Ah oui, Aaron le hardi, Aaron le beau. Pouvez-vous détacher les yeux de ses muscles ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alphys", "Alphys", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr. Alphys is responsible for the creation of some of the more 'unnerving' individuals you've seen here... or should I say... MULTI-viduals.", "Le Dr Alphys est responsable de certaines des personnes les plus « inquiétantes » que vous avez vues ici... ou devrais-je dire... des MULTI-personnes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loveable, yet pestulant. The duality of this creature is unparalleled.", "Adorable et pourtant boudeur. La dualité de cette créature est sans égale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asgore", "Asgore", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king of monsters... he truly is an intimidating force of brute strength, but also... compassion?", "Le roi des monstres... une force brute véritablement intimidante, mais aussi... de la compassion ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "asriel dreemurr", "Asriel Dreemurr", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the most powerful being in the underground... hopefully you find some use for him.", "L'être le plus puissant du monde souterrain... Espérons qu'il vous sera utile.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astigmatism", "Astigmatisme", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frustrating astigmatism... it can't make up its mind.", "Cet agaçant Astigmatisme... il n'arrive pas à se décider.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gaster Blaster", "Gaster Blaster", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Block of Ice", "Bloc de glace", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiarly large ice cube... Who knows what could be inside.", "Un glaçon particulièrement grand... Qui sait ce qu'il renferme ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chara", "Chara", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy", "Dogamy", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy and his wife, Dogaressa, love to tag-team the battlefield. Just don't let one of them perish...", "Dogamy et sa femme Dogaressa aiment se battre en équipe. Ne laissez pas l'un d'eux périr...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogaressa", "Dogaressa", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doggo", "Doggo", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, the blind doggo... He leaps towards any sound of movement.", "Ah, le chien Doggo aveugle... Il bondit au moindre bruit de mouvement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doodlebog", "Doodlebog", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy", "Mannequin", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bland dummy... not as charismatic as its 'mad' counterpart", "Le mannequin insipide... moins charismatique que son homologue « fou ».", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgamate", "Amalgame", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endogeny", "Endogeny", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "null", "nul", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Froggit", "Froggit final", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the ultimate boss of froggits... Still as easily fooled as its lesser evolved kin.", "Ah oui, le boss ultime des Froggits... Toujours aussi facile à duper que ses congénères moins évolués.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frisk", "Frisk", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Froggit", "Froggit", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, as shy as they come... the froggit wishes not to engage in conflict. how unfortunate.", "Ah oui, timide comme pas un... Le Froggit ne souhaite pas se battre. Quel dommage.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "W.D.Gaster", "W. D. Gaster", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "glyde", "Glyde", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a narcisist, it can only attack if a card is in front of it to watch.", "Un tel narcissique qu'il ne peut attaquer que si une carte devant lui le regarde.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Dog", "Grand chien", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "truly and nobly adequate, it is the highest form of evolution a canine can become.", "Vraiment et noblement convenable, c'est la forme d'évolution la plus élevée qu'un canidé puisse atteindre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gyftrot", "Gyftrot", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be kind to this creature, it has gone through enough.", "Soyez aimable avec cette créature, elle a assez souffert.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Wolf", "Loup de glace", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, this buff creature spawns a block of ice upon death.", "Ah oui, cette créature musclée crée un Bloc de glace à sa mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Icecap", "Icecap", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jerry", "Jerry", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just ditch him already.", "Abandonnez-le, tout simplement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight Knight", "Knight Knight", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the forboding knight knight... a sentinel of sleep. She is relentless in her conquest..", "Ah, l'inquiétante Knight Knight... une sentinelle du sommeil. Elle est implacable dans sa conquête...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lemon Bread", "Pain au citron", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Dog", "Chien (forme juvénile)", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mediocre canine at best... at least in its current form.", "Au mieux, un canidé médiocre... du moins sous sa forme actuelle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loox", "Loox", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cunning Loox EyeWalker... you would be wise not to pick on him.", "Le rusé Loox EyeWalker... vous feriez bien de ne pas le chercher.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mad Dummy", "Mannequin fou", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy?", "Mannequin ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks can be deceiving...", "Les apparences peuvent être trompeuses...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Madjick", "Madjick", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "quite the magician...", "Quel magicien...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Memoryhead", "Memoryhead", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton", "Mettaton", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hyper-intelligent, systematic, complex data analyzer... reminds me of an old 'friend'.", "Un analyseur de données complexe, systématique et hyperintelligent... Il me rappelle un vieil « ami ».", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton Ex", "Mettaton EX", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migosp", "Migosp", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the irritable Migosp... its attack increases in a crowd.", "L'irritable Migosp... son attaque augmente lorsqu'il est entouré.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migospel", "Migospel", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldbygg", "Moldbygg", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldsmal", "Moldsmal", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one's giving me imposter vibes.", "Celui-ci me donne une impression d'imposture.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldessa", "Moldessa", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the gelatinous moldsmal. you probably never wondered what it's made of.", "Ah, le Moldsmal gélatineux. Vous ne vous êtes probablement jamais demandé de quoi il est fait.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muffet", "Muffet", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the spider queen. her rapid play game is remarkable.", "Ah oui, la reine des araignées. Son jeu rapide est remarquable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Napstablook", "Napstablook", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most melancholy of ghosts... it cares not of battle, but still fights to impress.", "Le plus mélancolique des fantômes... Le combat lui importe peu, mais il se bat tout de même pour impressionner.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "onionsan", "Onionsan", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not much strategy with one... It becomes a random tentcle card one the second turn.", "Peu de stratégie avec lui... Il devient une carte tentacule aléatoire au deuxième tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A boney brute, papyrus is. He will generate bones like nobody's business.", "Papyrus est une brute tout en os. Il produit des os à une vitesse folle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parsnik", "Parsnik", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrope", "Pyrope", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Pyrope wants nothing more than to crank up the heat, let's see how fatal that can be.", "Pyrope ne rêve que de monter la température. Voyons jusqu'où cette chaleur peut être mortelle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reaper Bird", "Oiseau faucheur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Guards", "Gardes royaux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "two star-crossed lovers... will they ever focus on what's important?", "Deux amants au destin contrarié... Se concentreront-ils un jour sur l'essentiel ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if you pick this card, i feel like i'm going to have a bad time.", "Si vous choisissez cette carte, j'ai l'impression que je vais passer un mauvais moment.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shyren", "Shyren", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The musically inclined shyren... strike her bells to watch her sing.", "La mélomane Shyren... Frappez ses cloches pour l'entendre chanter.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snowdrake", "Snowdrake", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The laughable Snowdrake... striving to prove his father wrong. Will you let him succeed?", "Le risible Snowdrake... Il cherche à prouver que son père a tort. Le laisserez-vous réussir ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So Cold", "Si froid", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "so sorry", "tellement désolé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he's very sorry", "il est vraiment désolé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie", "Temmie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie the immortal cat... at least i think she's a feline. Nothing to lose, everything to gain.", "Temmie, le chat immortel... Enfin, je crois que c'est un félin. Tout à gagner, rien à perdre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toriel", "Toriel", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keeper of the ruins... She will protect your side of the board to the best of her ability.", "La gardienne des ruines... Elle protégera votre côté du plateau du mieux qu'elle le peut.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tsunderplane", "Tsunderplane", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She can't decide between wanting your attention and wanting you to back off... i suggest the latter.", "Elle hésite entre attirer votre attention et vous demander de partir... Je conseille la deuxième option.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undyne", "Undyne", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How could I forget Undyne? She is a true warrior, with an almighty aim on her spear.", "Comment pourrais-je oublier Undyne ? C'est une vraie guerrière, dont la lance vise avec une précision redoutable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vegetoid", "Vegetoid", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "eat your greens. (not monitored by the fda)", "Mangez vos légumes verts. (Non contrôlé par la FDA)", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vulkin", "Vulkin", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very passionate creature, this one. It's not his intention to harm, but that doesn't stop him.", "Une créature très passionnée. Il n'a pas l'intention de faire du mal, mais cela ne l'en empêche pas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsalot", "Whimsalot", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the noble whimsalot... pray that it deems your conquest riteous.", "Le noble Whimsalot... Priez pour qu'il juge votre conquête juste.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsun", "Whimsun", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the insignificant whimsun... it flees the battle after a single attack.", "L'insignifiant Whimsun... il quitte le combat après avoir attaqué une seule fois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woshua", "Woshua", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature has no lust for blood. His will lies with helping others. But it will fight if provoked.", "Cette créature n'a aucun goût pour le sang. Elle ne songe qu'à aider les autres. Mais si on la provoque, elle se battra.", Language.French);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antisocial", "Antisocial", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will gain an attack buff if you have at least 1 other card on your side of the board.", "Une carte ornée de cet emblème gagne un bonus d'attaque si vous avez au moins 1 autre carte de votre côté du plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanser", "Purificateur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will heal every card on its owner's side of the board, except the sigil bearer, for 1 health, at the start of every turn.", "Au début de la phase de combat de son propriétaire, une carte ornée de cet emblème rend 1 santé à toutes les autres cartes de son côté du plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Determination", "Détermination", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move to any open slot its owner chooses, it will also gain EXP and LV after a kill. But is that really what you want?", "Une carte ornée de cet emblème se déplace vers l'emplacement vide choisi par son propriétaire et gagne de l'EXP et des niveaux après avoir tué. Mais est-ce vraiment ce que vous voulez ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incendiary", "Incendiaire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil damages a card, that card gains the \"ablaze\" sigil. While a card is ablaze, it will lose one health per turn.", "Lorsqu'une carte ornée de cet emblème attaque une carte, sa cible gagne l'emblème Embrasé. Une carte Embrasée perd une santé au début de la phase de combat de son propriétaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ablaze", "Embrasé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will take 1 damage at the start of its owner's turn.", "Au début de la phase de combat de son propriétaire, une carte ornée de cet emblème subit 1 dégât.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indecisive", "Indécis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it has a 50/50 chance to either gain a stat buff, or perish; creating a copy of this card in your hand.", "Lorsqu'une carte ornée de cet emblème est frappée, elle a une probabilité de 50/50 de gagner un bonus de caractéristiques ou de mourir ; si elle meurt, une copie est créée dans votre main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone knows Jerry. Makes Turns 2 seconds longer. Cards gain a stat buff when Jerry is killed or sacrificed.", "Tout le monde connaît Jerry. Il rallonge les tours de 2 secondes. Lorsque Jerry est tué ou sacrifié, les cartes du côté du joueur gagnent un bonus de caractéristiques.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mercy", "Miséricorde", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A 'Determined' card will be granted this sigil when the card opposing it has low health, prompting the player to make a moral decision.", "Une carte dotée de Détermination reçoit cet emblème lorsque la carte en face a peu de santé, poussant le joueur à faire un choix moral.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insight", "Clairvoyance", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you wanna have a bad time?", "Tu veux passer un mauvais moment ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doodler", "Gribouilleur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it will sometimes summon doodlebogs on adjacent spaces.", "Lorsqu'une carte ornée de cet emblème est frappée, elle invoque parfois des Doodlebogs sur les emplacements adjacents.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid", "Timide", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opponent card moves into the opposing space of a card bearing this sigil, the sigil bearer will try to move one space over.", "Lorsqu'une carte adverse se déplace sur l'emplacement en face d'une carte ornée de cet emblème, celle-ci essaie de se déplacer d'un emplacement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You ditched Jerry.", "Vous avez abandonné Jerry.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow, you guys SUCK at this.", "Ouah, vous êtes vraiment NULS à ça.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wi-fi here sucks.", "Le Wi-Fi est nul ici.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHHHH! Im THINKING, guys!!", "CHUT ! Je RÉFLÉCHIS, les gars !!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get your own, twerp.", "Débrouille-toi, petit morveux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why are we doing this? What a fail.", "Pourquoi on fait ça ? Quel échec.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guys. its COLD. Does ANYONE care?", "Les gars, il fait FROID. Quelqu'un s'en soucie ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ka-SIGH", "Pfff...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DUH! Who DOESNT know?", "ÉVIDEMMENT ! Qui ne le sait PAS ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well... can YOU give me a ride home?", "Bon... TU peux me ramener chez moi ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awkwarrrd.", "Gêêênant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, like, what are you even doing?", "Alors, genre, qu'est-ce que tu fais au juste ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huh? Did they ditch me...? SOME friends!", "Hein ? Ils m'ont laissé tomber... ? De sacrés amis !", Language.French);



        }
    }
    public class RevenantMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for RevenantMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DanseMacabre", "Danse macabre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to reverse this sigil effect. At the end of the owner's turn, all creatures on the board gain 1 health.", "Payez 2 os pour inverser l'effet de cet emblème. À la fin du tour de son propriétaire, toutes les créatures sur le plateau gagnent 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LifeDraw", "Pioche vitale", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Blood to draw a card from your main deck.", "Payez 1 de sang pour piocher une carte dans votre deck principal.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "Porte des âmes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to gain 1 Energy, lose as much Max Energy at the end of the owner's turn.", "Payez 1 os pour gagner 1 énergie. À la fin du tour du propriétaire, perdez autant d'énergie maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evocation", "Évocation", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Energy to return the oldest non-Brittle allied creature from the graveyard to your hand.", "Payez 3 énergies pour renvoyer dans votre main la créature alliée sans Atonie la plus ancienne du cimetière.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dormant", "En sommeil", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay Bones equal to the Power of [creature] to disable this sigil for 1 turn. [creature] cannot attack normally.", "Payez autant d'os que la puissance de [creature] pour désactiver cet emblème pendant 1 tour. [creature] ne peut pas attaquer normalement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transmute", "Transmutation", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to transform [creature] to its alternate form.", "Payez 2 os pour transformer [creature] en sa forme alternative.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector", "Protecteur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] gain 1 max health.", "Les créatures adjacentes à [creature] gagnent 1 santé maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CalamityEffusion", "Effusion de calamité", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board lose 1 health.", "À la fin du tour de son propriétaire, toutes les créatures sur le plateau perdent 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ComfortAura", "Aura de réconfort", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, creatures adjacent to [creature] heal 1 health.", "À la fin du tour de son propriétaire, les créatures adjacentes à [creature] récupèrent 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CorpseParty", "Fête des cadavres", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, a Zombie enters your hand. A Zombie is defined as: 1 Power, 1 Health.", "Quand une créature du côté de son propriétaire, sans Atonie, meurt au combat, un Zombie est ajouté à votre main. Un Zombie possède 1 puissance et 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathKnock", "Frappe mortuaire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, it strikes back then perishes.", "Quand [creature] meurt au combat, elle riposte avant de périr.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathMetal", "Métal de la mort", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, adjacent creatures and opposing creatures to the left, right, and center of it take 1 damage. It gains 1 Power for each affected creature.", "Quand la carte [creature] est jouée, les créatures adjacentes ainsi que les créatures ennemies en face, à gauche et à droite de cette position subissent 1 dégât. Elle gagne 1 puissance pour chaque créature affectée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defiler", "Profanateur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, draw a card then choose one to discard from your hand.", "Quand la carte [creature] meurt, piochez une carte puis choisissez-en une à défausser de votre main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Encroachment", "Envahissement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] creates a copy of it in your hand after 2 turns on the board.", "Après 2 tours sur le plateau, [creature] crée une copie d'elle-même dans votre main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletonize", "Squelettisation", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Skeleton with its old sigils enters your hand. A Skeleton is defined as: 1 Power, 1 Health, Brittle.", "Quand la carte [creature] meurt, un Squelette portant ses anciens emblèmes est ajouté à votre main. Un Squelette possède 1 puissance, 1 santé et Atonie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcise", "Exorcisme", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Bones equal to the Bone cost of the opposing creature are granted to the player.", "Quand la carte [creature] est jouée, le joueur reçoit autant d'os que le coût en os de la créature en face.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ExplodingCorpse", "Cadavre explosif", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, all empty spaces on the board are filled with a Guts card.", "Quand [creature] meurt au combat, tous les emplacements vides du plateau sont remplis d'une carte Entrailles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GrudgeCollector", "Collecteur de rancunes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power for every 2 times opponent creatures deal direct damage to its owner.", "[creature] gagne 1 puissance chaque fois que des créatures ennemies infligent des dégâts directs à son propriétaire 2 fois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Power", "Puissance des grelots", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bell cards on the board.", "La valeur représentée par cet emblème est égale au nombre de cartes Cloche sur le plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Digger Power", "Puissance du déterrage d'os", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bone and Digger related sigils on the board.", "La valeur représentée par cet emblème est égale au nombre d'emblèmes liés aux os et au déterrage sur le plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignition", "Allumage", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power at the cost of 1 health after each turn on the board.", "Après chaque tour passé sur le plateau, [creature] gagne 1 puissance au prix de 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Digger Latch", "Transmission de déterrage d'os", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain the Bone Digger sigil.", "À la fin du tour de son propriétaire, [creature] génère 1 os. À sa mort, son propriétaire choisit une créature qui gagne l'emblème Déterrage d'os.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primed Digger Latch", "Transmission de déterrage d'os renforcée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain this sigil.", "À la fin du tour de son propriétaire, [creature] génère 1 os. À sa mort, son propriétaire choisit une créature qui gagne cet emblème.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejuvenation", "Rajeunissement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Fledgling sigil.", "Quand la carte [creature] meurt, son propriétaire choisit une créature qui gagne l'emblème Oisillon.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skull Storm", "Déluge de crânes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, this sigil is replaced with another sigil at random. When it perishes, its owner chooses a creature to gain this sigil.", "À la fin du tour de son propriétaire, cet emblème est remplacé par un autre emblème aléatoire. Quand la carte qui le porte meurt, son propriétaire choisit une créature qui gagne cet emblème.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "Embrasement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Ignition sigil.", "Quand la carte [creature] meurt, son propriétaire choisit une créature qui gagne l'emblème Allumage.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MacabreBonePulse", "Pulsation osseuse macabre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it perishes immediately, dropping Bones equal to double the amount of creatures on the owner's side.", "Quand la carte [creature] est jouée, elle meurt immédiatement et laisse tomber un nombre d'os égal au double du nombre de créatures du côté de son propriétaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maternal", "Maternel", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] are inscrybed by Waterborne.", "Les créatures adjacentes à [creature] reçoivent l'emblème Eau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Necrosis", "Nécrose", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 power and 1 max health after each turn on the board.", "Après chaque tour passé sur le plateau, [creature] perd 1 puissance et 1 santé maximale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Limbo", "Limbes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it returns to the top of your deck.", "Quand la carte [creature] meurt, elle retourne sur le dessus de votre deck.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RelentlessRevenant", "Revenant implacable", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, creatures adjacent to [creature] transform into a Revenant. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "Au début du tour de son propriétaire, les créatures adjacentes à [creature] se transforment en Revenants. Un Revenant possède 3 puissance, 1 santé et Atonie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revedue", "Retour du revenant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] perishes, then shuffle 2 Revenants with its old sigils into your side deck. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "Après avoir attaqué, la carte [creature] meurt, puis 2 Revenants portant ses anciens emblèmes sont mélangés dans votre deck secondaire. Un Revenant possède 3 puissance, 1 santé et Atonie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Omen", "Mauvais présage", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will deal 1 damage to the owner.", "À la fin du tour de son propriétaire, [creature] lui inflige 1 dégât.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rancor", "Rancune", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it leaves a permanent 1 power buff in the space it occupied.", "Quand la carte [creature] meurt, elle laisse sur son emplacement un bonus permanent de 1 puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SoothingMeadows", "Prairies apaisantes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board gain 1 health.", "À la fin du tour de son propriétaire, toutes les créatures sur le plateau gagnent 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PartingStroke", "Dernier trait", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, its owner chooses a creature to lose all of its sigils.", "Quand une créature sans Atonie du côté de son propriétaire meurt au combat, son propriétaire choisit une créature qui perd tous ses emblèmes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SplittingCorpse", "Cadavre divisible", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, create a Dysmorphia on each empty adjacent space.", "Quand [creature] meurt au combat, créez une Dysmorphie sur chaque emplacement adjacent vide.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torpid", "Léthargique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot attack normally.", "[creature] ne peut pas attaquer normalement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Epitaph", "Épitaphe sinistre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may choose a card that has already been put to rest, to bring back to your hand.", "Quand la carte [creature] est jouée, vous pouvez choisir une carte déjà mise au repos et la ramener dans votre main.", Language.French);


            //card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigfoot", "Bigfoot", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a mysterious creature lurking the forests, only few have claimed to see one.", "Une créature mystérieuse qui rôde dans les forêts. Peu de gens prétendent l'avoir aperçue.", Language.French);
            GrimoraMod.RegisterCard("Bigfoot", "Bigfoot");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goblin", "Gobelin", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal barbaric beast, a fine addition to your army.", "Une bête sauvage et loyale, un atout de choix pour votre armée.", Language.French);
            GrimoraMod.RegisterCard("Goblin", "Gobelin");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vila", "Vila", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love at first sight, at least that's what it wants you to think.", "Le coup de foudre... du moins, c'est ce qu'elle veut vous faire croire.", Language.French);
            GrimoraMod.RegisterCard("Vila", "Vila");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yaramayawho", "Yaramayawho", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to finish it's meals...", "Il ne semble jamais parvenir à finir ses repas...", Language.French);
            GrimoraMod.RegisterCard("Yaramayawho", "Yaramayawho");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Test Limbs", "Membres d'essai", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those parts used to belong to someone, or now some thing...(Test)", "Ces pièces appartenaient autrefois à quelqu'un, ou maintenant à quelque... chose... (Test)", Language.French);
            GrimoraMod.RegisterCard("Test Limbs", "Membres d'essai");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allip", "Allip", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnants of the insane! You never know what story lies behind that face, but it's sure to be filled with fervor.", "Les vestiges de la folie ! Impossible de savoir quelle histoire se cache derrière ce visage, mais elle sera sûrement pleine de ferveur.", Language.French);
            GrimoraMod.RegisterCard("Allip", "Allip");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amami Rabbit", "Lapin d'Amami", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding their young in holes, they wish for their best safety.", "Ils cachent leurs petits dans des terriers, souhaitant les protéger au mieux.", Language.French);
            GrimoraMod.RegisterCard("Amami Rabbit", "Lapin d'Amami");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankhame", "Ankhame", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A relic that is drawn to your blood, perhaps you could give it a swing!", "Une relique attirée par votre sang. Peut-être pourriez-vous l'essayer !", Language.French);
            GrimoraMod.RegisterCard("Ankhame", "Ankhame");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anneta", "Anneta", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That ink keeps on pouring, is she even there anymore? All that death promises is that you will wake up again.", "L'encre continue de couler. Est-elle encore là ? Tout ce que la mort promet, c'est que vous vous réveillerez à nouveau.", Language.French);
            GrimoraMod.RegisterCard("Anneta", "Anneta");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anorexia", "Anorexie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overflowing you with self loathing, you never know what form it may take on next.", "Elle vous submerge de dégoût de vous-même ; impossible de savoir quelle forme elle prendra ensuite.", Language.French);
            GrimoraMod.RegisterCard("Anorexia", "Anorexie");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lych Bell", "Cloche de liche", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems like they found a new way to use bells.", "On dirait qu'ils ont trouvé une nouvelle façon d'utiliser les cloches.", Language.French);
            GrimoraMod.RegisterCard("Lych Bell", "Cloche de liche");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TheBloated", "Le Boursouflé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grotesque boils, ready to burst.", "Des furoncles grotesques, prêts à éclater.", Language.French);
            GrimoraMod.RegisterCard("TheBloated", "Le Boursouflé");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BrainJar", "Cerveau en bocal", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One shudders to imagine what inhuman thoughts lie inside that jar...", "On frissonne en imaginant les pensées inhumaines qui se cachent dans ce bocal...", Language.French);
            GrimoraMod.RegisterCard("BrainJar", "Cerveau en bocal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combustor", "Carcasse incendiaire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, what a fall from such a stimulatingly high status, now all that's left is a metal carcass, and the last of that watchful substance...", "Hélas, quelle chute depuis un statut si exaltant ! Il ne reste qu'une carcasse de métal et les derniers restes de cette substance vigilante...", Language.French);
            GrimoraMod.RegisterCard("Combustor", "Carcasse incendiaire");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Misplayed Stoat", "Hermine mal jouée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A decaying Stoat whose oh-so perfect strategies failed him tremendously.", "Une Hermine en décomposition dont les stratégies si parfaites l'ont terriblement trahie.", Language.French);
            GrimoraMod.RegisterCard("Misplayed Stoat", "Hermine mal jouée");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia", "Dysmorphie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Left.", "Dysmorphie gauche.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Right.", "Dysmorphie droite.", Language.French);
            GrimoraMod.RegisterCard("Dysmorphia", "Dysmorphie");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcist", "Exorciste", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He still thinks banishing the dammed will do him good, does he know where he is?", "Il croit encore que bannir les damnés lui fera du bien. Sait-il seulement où il se trouve ?", Language.French);
            GrimoraMod.RegisterCard("Exorcist", "Exorciste");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flembones", "Os purulents", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait until he plays with his webcam.", "Attendez qu'il joue avec sa webcam.", Language.French);
            GrimoraMod.RegisterCard("Flembones", "Os purulents");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stein & Frank", "Stein et Frank", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even hell was not hot enough to split them.", "Même l'enfer n'était pas assez brûlant pour les séparer.", Language.French);
            GrimoraMod.RegisterCard("Stein & Frank", "Stein et Frank");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulmineSkull", "Crâne de foudre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you listen closely, you can still hear the cackling of flame on bone... as well as their voice.", "En tendant l'oreille, vous entendez encore le crépitement des flammes sur les os... ainsi que leur voix.", Language.French);
            GrimoraMod.RegisterCard("FulmineSkull", "Crâne de foudre");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulurOssa", "Os de tonnerre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It never truly left the electric chair.", "Il n'a jamais vraiment quitté la chaise électrique.", Language.French);
            GrimoraMod.RegisterCard("FulurOssa", "Os de tonnerre");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PrometheusFlame", "Flamme de Prométhée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one is quite unique, the lingering spoils of a thief to benefit humanity! Fancy liver by chance?", "Un objet unique, vestige du butin d'un voleur qui a aidé l'humanité ! Un peu de foie, par hasard ?", Language.French);
            GrimoraMod.RegisterCard("PrometheusFlame", "Flamme de Prométhée");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guts", "Entrailles", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying guts.", "Des entrailles agaçantes.", Language.French);
            GrimoraMod.RegisterCard("Guts", "Entrailles");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harbinger", "Précurseur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A powerful fiend that extols a heavy price for its servitude.", "Un puissant diable qui exige un lourd tribut pour servir.", Language.French);
            GrimoraMod.RegisterCard("Harbinger", "Précurseur");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hastur", "Hastur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He came from beyond the stars, gifting pieces of his reflection to kings and fools alike. Will you accept this piece?", "Il vint d'au-delà des étoiles, offrant des fragments de son reflet aux rois comme aux fous. Accepterez-vous ce fragment ?", Language.French);
            GrimoraMod.RegisterCard("Hastur", "Hastur");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Common Imp", "Diablotin commun", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tiny creature known for causing trouble and mayhem wherever it goes, with its mischievous grin and playful nature!", "Une minuscule créature connue pour semer le trouble et le chaos partout où elle va, avec son sourire malicieux et sa nature joueuse !", Language.French);
            GrimoraMod.RegisterCard("Common Imp", "Diablotin commun");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochimitama", "Orochimitama", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... He is not supposed to be here...", "Oh... Il ne devrait pas être ici...", Language.French);
            GrimoraMod.RegisterCard("Orochimitama", "Orochimitama");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inochi", "Souffle de vie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A soothing presence to heal your creatures, a calm before the storm.", "Une présence apaisante qui soigne vos créatures, le calme avant la tempête.", Language.French);
            GrimoraMod.RegisterCard("Inochi", "Souffle de vie");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trail of Torment.", "Piste de tourments.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessed Limbs", "Membres possédés", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once attached to a living person, they now belong to something else entirely.", "Autrefois rattachés à une personne vivante, ils appartiennent désormais à tout autre chose.", Language.French);
            GrimoraMod.RegisterCard("Possessed Limbs", "Membres possédés");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mole Digger", "Taupe fossoyeuse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stalwart Mole... Digger? Whatever this is...", "La Taupe inébranlable... fossoyeuse ? Enfin, quoi que ce soit...", Language.French);
            GrimoraMod.RegisterCard("Mole Digger", "Taupe fossoyeuse");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros", "Nekros", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros possesses the board, challenger. Death is his playground.", "Nekros possède le plateau, prétendant. La mort est son terrain de jeu.", Language.French);
            GrimoraMod.RegisterCard("Nekros", "Nekros");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NekrosPrime", "Nekros Prime", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will find no greater power... than the simple thought of your own name... inscrybed upon a grave.", "Vous ne trouverez pas de plus grande puissance... que la simple pensée de votre propre nom... gravé sur une pierre tombale.", Language.French);
            GrimoraMod.RegisterCard("NekrosPrime", "Nekros Prime");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nuckelavee", "Nuckelavee", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Administrator of its sea, you better hope it's breath doesn't taint your Thralls!", "Le maître de ses mers. Mieux vaut espérer que son souffle ne souille pas vos serviteurs !", Language.French);
            GrimoraMod.RegisterCard("Nuckelavee", "Nuckelavee");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OdiousMass", "Masse odieuse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How unsightly.", "Quel spectacle hideux.", Language.French);
            GrimoraMod.RegisterCard("OdiousMass", "Masse odieuse");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochi", "Orochi", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "Des sacrifices sont nécessaires.", Language.French);
            GrimoraMod.RegisterCard("Orochi", "Orochi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Ouro", "Maître Ouro", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From within the endless torment and suffering, they had somehow learned a way to see inside this poor broken thing... and take away its pain.", "Au cœur d'une souffrance et de tourments sans fin, ils ont trouvé le moyen de voir à l'intérieur de cette pauvre chose brisée... et de lui ôter sa douleur.", Language.French);
            GrimoraMod.RegisterCard("Master Ouro", "Maître Ouro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An endless cycle of life and death has taken a toll on these discarded remains. The pain was real, but death is never final!", "Un cycle sans fin de vie et de mort a meurtri ces restes abandonnés. La douleur était réelle, mais la mort n'est jamais définitive !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GanCeann", "GanCeann", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Countless legends tell of the dullahan, but all fail to convey the true extent of its pique.", "D'innombrables légendes parlent du dullahan, mais aucune ne rend la véritable ampleur de sa colère.", Language.French);
            GrimoraMod.RegisterCard("GanCeann", "GanCeann");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark Prince", "Prince des ténèbres", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of fluffy bois shines within you.", "Le pouvoir des petits gars tout doux brille en vous.", Language.French);
            GrimoraMod.RegisterCard("Dark Prince", "Prince des ténèbres");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stillborn Raven", "Corbeau mort-né", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feels good to be young again!", "Quel bonheur de retrouver sa jeunesse !", Language.French);
            GrimoraMod.RegisterCard("Stillborn Raven", "Corbeau mort-né");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reanimated", "Ranimé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRINGING THE SCYTHE OF DEATH, THE REVENANT... WAIT, WHAT?", "ARMÉ DE LA FAUX DE LA MORT, LE REVENANT... ATTENDEZ, QUOI ?", Language.French);
            GrimoraMod.RegisterCard("Reanimated", "Ranimé");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RevenantEldritch", "Revenant occulte", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The source of Calamity, relentless and unerring.", "La source de la Calamité, implacable et infaillible.", Language.French);
            GrimoraMod.RegisterCard("RevenantEldritch", "Revenant occulte");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Bones", "Os paresseux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slothful skeleton with a knack for jokes. I adore him.", "Un squelette paresseux qui a le don des blagues. Je l'adore.", Language.French);
            GrimoraMod.RegisterCard("Lazy Bones", "Os paresseux");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelephone", "Squeletphone", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A way to communicate with the dead, for a price.", "Un moyen de communiquer avec les morts, moyennant un prix.", Language.French);
            GrimoraMod.RegisterCard("Skelephone", "Squeletphone");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "Porte des âmes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chance to enter the soul realm, how delightful? I hope you can afford the price.", "Une chance d'entrer dans le royaume des âmes, quel plaisir ! J'espère que vous pourrez en payer le prix.", Language.French);
            GrimoraMod.RegisterCard("Soulgate", "Porte des âmes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SpadeWarrior", "Guerrier de pique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This fearsome warrior will put you six feet under, in every possible sense.", "Ce redoutable guerrier vous enterrera à six pieds sous terre, dans tous les sens du terme.", Language.French);
            GrimoraMod.RegisterCard("SpadeWarrior", "Guerrier de pique");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadCivilian", "Civil mort-vivant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost in eternal darkness, this poor soul desperately seeks a way out. Perhaps you can light his way?", "Perdue dans les ténèbres éternelles, cette pauvre âme cherche désespérément une issue. Pourriez-vous éclairer son chemin ?", Language.French);
            GrimoraMod.RegisterCard("UndeadCivilian", "Civil mort-vivant");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadVillage", "Village des morts-vivants", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abandoned and forlorn, this village seeks new residents to fill its decrepit homes.", "Abandonné et désolé, ce village cherche de nouveaux habitants pour remplir ses maisons décrépites.", Language.French);
            GrimoraMod.RegisterCard("UndeadVillage", "Village des morts-vivants");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In every town, in every city, someone must work to bury the dead. In time, they too will be buried.", "Dans chaque village, dans chaque ville, quelqu'un doit enterrer les morts. Un jour, ces personnes seront à leur tour enterrées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr.Bones", "Dr Os", Language.French);
            GrimoraMod.RegisterCard("Dr.Bones", "Dr Os");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever doesn't kill you simply makes you, saner.", "Ce qui ne vous tue pas ne fait que vous rendre plus sain d'esprit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigo", "Wendigo", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returned from the deep wilds, reminds me of a friend.", "Revenu des confins sauvages, il me rappelle un ami.", Language.French);
            GrimoraMod.RegisterCard("Wendigo", "Wendigo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mister Win", "Monsieur Victoire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card that wins. It always wins. That's why it's called Mister Win.", "Une carte qui gagne. Elle gagne toujours. Voilà pourquoi on l'appelle Monsieur Victoire.", Language.French);
            GrimoraMod.RegisterCard("Mister Win", "Monsieur Victoire");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not that one, I'm afraid.", "Pas celle-là, j'en ai peur.", Language.French);

            // Dlg
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You... you murderous monster.", "Tu... tu es un monstre meurtrier.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh Dear... The flow of Calamity will pursue you.", "Oh là là... Le flot de la Calamité vous poursuivra.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hecatomb the village you once lived.", "Massacrez le village où vous viviez autrefois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seak for the shovel that digs forever.", "Cherchez la pelle qui creuse sans fin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring me the lost one with a spark in hand.", "Amenez-moi l'être perdu qui tient une étincelle en main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compelled by the beckoning of an ancient entity,", "Poussé par l'appel d'une entité ancienne,", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a forbidden ritual has been initiated.", "un rituel interdit a commencé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pain reaches the ancient great serpent of death.", "La douleur atteint l'antique grand serpent de la mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "Des sacrifices sont nécessaires.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... There are no dead cards yet.", "Oh... Il n'y a pas encore de cartes mortes.", Language.French);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant Mod Card Pack", "Pack de cartes du mod Revenant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack consists of mainly cards that return to the player in a variety of ways.", "Ce pack se compose principalement de cartes qui reviennent au joueur de diverses manières.", Language.French);
        }
    }
    public class SquirrelBombMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SquirrelBombMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis", "Pipis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis.", "Pipis.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Help", "À l'aide", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn [creature] will sacrifice itself to heal the adjacent cards by 1.", "À la fin du tour de son propriétaire, [creature] se sacrifie pour rendre 1 santé aux cartes adjacentes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pass-through", "Passage libre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is about to get attacked by a card with an attack higher than this card's health, this card perishes.", "Lorsque [creature] est sur le point d'être attaquée par une carte dont l'attaque dépasse sa santé, elle meurt.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Call", "Appel indésirable", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a circuit completed by [creature] spawn Spam Mail at the end of the owner's turn.", "À la fin du tour de son propriétaire, les emplacements vides d'un circuit complété par [creature] produisent du Courrier indésirable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEO Strike", "Frappe NEO", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space that is occupied by a creature and additionally every side of the board occupied by a creature. It will strike directly if no creatures oppose it.", "[creature] frappe chaque emplacement adverse occupé et, en plus, les deux emplacements de chaque moitié adverse contenant une cible. Sans cible adverse, elle attaque directement les deux emplacements centraux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Call for Help", "Appel à l'aide", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will call for help.", "À la fin du tour de son propriétaire, [creature] appelle à l'aide.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Run Forth", "En avant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before [creature] attacks, its power will be set to at least 1.", "Avant que [creature] n'attaque, sa puissance est portée à au moins 1.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying Head", "Tête volante", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most important part.", "La partie la plus importante.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Cart", "Chariot de courrier indésirable", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with spam mail. Absorbs all kinds of attacks.", "Rempli de courrier indésirable. Absorbe toutes sortes d'attaques.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Mail", "Courrier indésirable", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Has all kinds of unforgettable deals.", "Contient toutes sortes d'offres inoubliables.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Shooter", "Gros tireur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoots big shots.", "Tire de gros coups.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart on a Chain", "Cœur enchaîné", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beautiful.", "Magnifique.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spamgel", "Spamgel", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The result of pressing F1.", "Le résultat d'une pression sur F1.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Phone", "Téléphone à main", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you really need anyone else?", "Avez-vous vraiment besoin de quelqu'un d'autre ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE POWER OF NEO!!!", "LE POUVOIR DE NEO !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you wanna be a big shot?", "Ne voulez-vous pas devenir quelqu'un d'important ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Receiver", "Récepteur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voice runs out eventually.", "La voix finit par s'éteindre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis", "Coupon grizzli", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis.", "Coupon grizzli.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Cart", "Chariot à ours", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with bears. Absorbs all kinds of attacks.", "Rempli d'ours. Absorbe toutes sortes d'attaques.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Mail", "Courrier des ours", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mail for bears.", "Du courrier pour les ours.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear on a Chain", "Ours enchaîné", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Hand", "Patte d'ours", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Bomb", "Bombe écureuil", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrels explode when killed, dealing 10 damage to adjacent cards.", "Les écureuils explosent lorsqu'ils sont tués et infligent 10 dégâts aux cartes adjacentes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance Party", "Soirée dansante", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your cards move each turn. The cards that can't move die.", "Vos cartes se déplacent à chaque tour. Celles qui ne peuvent pas se déplacer meurent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Again", "Encore", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All opponent cards attack twice.", "Toutes les cartes adverses attaquent deux fois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starving", "Affamé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pray.", "Priez.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogfish", "Aiguillat", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each battle starts with a Bait Bucket that has Guardian.", "Chaque combat commence avec un Seau à appâts portant Garde.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Totems", "Totems de Fureur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with an Annoying totem for your most used tribe.", "Commencez chaque combat avec un totem Fureur pour votre tribu la plus utilisée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Draws", "Pioches douloureuses", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the main deck deals 1 damage.", "Piocher dans le deck principal inflige 1 dégât.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Squirrels", "Écureuils douloureux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the side deck deals 1 damage.", "Piocher dans le deck secondaire inflige 1 dégât.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Runes", "Runes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enemy cards of the dominant tribe get random sigils.", "Les cartes ennemies de la tribu dominante reçoivent des emblèmes aléatoires.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dentistry", "Dentisterie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Item events and Trinket Bearer cards only give pliers.", "Les événements d'objets et les cartes Artéfact ne donnent que des pinces.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archived", "Archivé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A random card choice is hidden in every card choice event.", "Un choix de carte aléatoire est caché lors de chaque événement de choix de carte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foundation", "Fondation", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards have 1 less attack. Side deck cards have Leader.", "Toutes vos cartes ont 1 attaque de moins. Les cartes du deck secondaire portent Commandement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Boss v2", "Boss final v2", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replaces Leshy as the final boss with a true BIG SHOT.", "Remplace Leshy comme boss final par une véritable GROSSE POINTURE.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must dance! Don't stop dancing!!", "Il faut danser ! Ne cessez pas de danser !!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whoever stops dancing at my party will suffer the consequences.", "Quiconque cesse de danser à ma fête en subira les conséquences.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is that mechanic annoying?", "Cette mécanique est agaçante ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect. That's the point of it.", "Parfait. C'est le but.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance my puppet! Daaaance.", "Danse, ma marionnette ! Daaaanse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to pass, remember?", "Vous devez passer, vous vous souvenez ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M [_spamton_0,STEALING] YOUR KROMER", "JE [_spamton_0,VOLE] TON KROMER", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOLY [_spamton_0,CUNGADERO] DO I FEEL GOOD", "SAINT [_spamton_0,BORDEL], JE ME SENS BIEN", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HERE I AM!!!", "ME VOILÀ !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BIG", "ÉNORME", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=10>BIG!!!</size>", "<size=10>ÉNORME !!!</size>", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=15>[_spamton_0,BIGGER AND BETTER THAN EVER]</size>", "<size=15>[_spamton_0,PLUS GRAND ET MEILLEUR QUE JAMAIS]</size>", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND NOW THAT I'M IN THIS [_spamton_0,GAME OF CARDS]", "ET MAINTENANT QUE JE SUIS DANS CE [_spamton_0,JEU DE CARTES]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I CAN'T BE DEFEATED!!!", "JE NE PEUX PAS ÊTRE VAINCU !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,ABSOLUTELY OBLITERATED] BY [_spamton_0,THE POWER OF NEO]!!!", "PRÉPARE-TOI À ÊTRE [_spamton_0,ANÉANTI] PAR [_spamton_0,LE POUVOIR DE NEO] !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,THIS] AGAIN???", "ENCORE [_spamton_0,ÇA] ???", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,DESTROYED]!!!", "PRÉPARE-TOI À ÊTRE [_spamton_0,DÉTRUIT] !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WON'T STAND A CHANGE, YOU [_spamton_0,LITTLE RING WORM]!!!", "TU N'AS AUCUNE CHANCE, PETITE [_spamton_0,LARVE VIREVOLTANTE] !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO [_spamton_0,GET PUNCHED] IN YOUR [_spamton_0,FACE]!!!", "PRÉPARE-TOI À RECEVOIR [_spamton_0,UN COUP DE POING] EN PLEIN [_spamton_0,VISAGE] !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEHOLED [_spamton_0,ME]!!! BEHOLD [_spamton_0,YOU]!!!", "CONTEMPLE [_spamton_0,MOI] !!! CONTEMPLE [_spamton_0,TOI] !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,HYPERLINK BLOCKED]", "[_spamton_0,LIEN HYPERTEXTE BLOQUÉ]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ISN'T THIS BODY JUST [_spamton_0,HEAVEN]LY?", "CE CORPS N'EST-IL PAS TOUT SIMPLEMENT [_spamton_0,DIVIN] ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "2X THE [_spamton_0,FIRE]POWER", "2X PLUS DE [_spamton_0,PUISSANCE DE FEU]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "3X THE [_spamton_0,WATER]POWER", "3X PLUS DE [_spamton_0,PUISSANCE D'EAU]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND MOST IMPORTANTLY", "ET SURTOUT", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FLYING HEADS!!!", "DES TÊTES VOLANTES !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WE'LL TURN THOSE [_spamton_0,SCHMOES] AND [_spamton_0,DAVES]", "NOUS ALLONS TRANSFORMER CES [_spamton_0,MINABLES] ET CES [_spamton_0,PAUMÉS]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,ROSEN GRAVES]", "EN [_spamton_0,TOMBES DE ROSES]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOSE [_spamton_0,CATHODE SCREENS]", "CES [_spamton_0,ÉCRANS CATHODIQUES]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,CATHODE SCREAMS]", "EN [_spamton_0,CRIS CATHODIQUES]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA BE [_spamton_0,PART] OF MY BEAUTIFUL [_spamton_0,HEART]?!", "NE VEUX-TU PAS FAIRE [_spamton_0,PARTIE] DE MON MAGNIFIQUE [_spamton_0,CŒUR] ?!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OR... DID YOU NEED A LITTLE [_spamton_0,SPECIL TOUR]?", "OU... AVAIS-TU BESOIN D'UNE PETITE [_spamton_0,VISITE SPÉCIALE] ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHAT]?!", "[_spamton_0,QUOI] ?!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU [_spamton_0,STOLE] MY [_spamton_0,HEART]?", "TU AS [_spamton_0,VOLÉ] MON [_spamton_0,CŒUR] ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CAN'T BE [_spamton_0,STEALING] MY [_spamton_0,HEART], IT IS MY [_spamton_0,HEART]!", "TU NE PEUX PAS [_spamton_0,VOLER] MON [_spamton_0,CŒUR], C'EST MON [_spamton_0,CŒUR] !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP [_spamton_0,STEALING] MY HEART YOU [_spamton_0,!@#$]", "ARRÊTE DE [_spamton_0,VOLER] MON CŒUR, ESPÈCE DE [_spamton_0,!@#$]", Language.French);
