            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO YOU KNOW THAT IT [_spamton_0,HURTS] WHEN YOU [_spamton_0,DO] THAT?!", "SAIS-TU QUE ÇA [_spamton_0,FAIT MAL] QUAND TU [_spamton_0,FAIS] ÇA ?!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA HELP YOUR OLD PAL SPAMTON?", "NE VEUX-TU PAS AIDER TON VIEUX POTE SPAMTON ?", Language.French);
