            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE NO [_spamton_0,FRIENDS] IN THIS [_spamton_0,WORLD]!!!", "TU N'AS PAS D'[_spamton_0,AMIS] DANS CE [_spamton_0,MONDE] !!!", Language.French);
