            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHO'RE YOU GONNA CALL, THE [_spamton_0,POLICE]?", "QUI VAS-TU APPELER, LA [_spamton_0,POLICE] ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU'RE [_spamton_0,PATHETIC]!!", "TU ES [_spamton_0,PATHÉTIQUE] !!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,SCREAMING] FOR [_spamton_0,HELP] [_spamton_0,AT THE BOTTOM OF A DUMPSTER]!!!", "[_spamton_0,CRIER] À L'[_spamton_0,AIDE] [_spamton_0,AU FOND D'UNE BENNE] !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE'S NO [_spamton_0,HELP] FOR YOU!!!", "PERSONNE NE VIENDRA T'[_spamton_0,AIDER] !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR [_spamton_0,VOICE] IS GOING TO RUN OUT EVENTUALLY!!", "TA [_spamton_0,VOIX] FINIRA PAR S'ÉTEINDRE !!", Language.French);
