            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT IS A [_spamton_0,MAGNIFICUS]? IS IT A KIND OF [_spamton_0,BLOWFISH]?", "QU'EST-CE QU'UN [_spamton_0,MAGNIFICUS] ? UNE SORTE DE [_spamton_0,POISSON-GLOBE] ?", Language.French);
