            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,LESHY]???", "[_spamton_0,LESHY] ???", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IS THAT THE [_spamton_0,GUY] WHO I [_spamton_0,HIT] AT THE BEGGINING OF OUR [_spamton_0,FIGHT]???", "C'EST LE [_spamton_0,TYPE] QUE J'AI [_spamton_0,FRAPPÉ] AU DÉBUT DE NOTRE [_spamton_0,COMBAT] ???", Language.French);
