            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OR DOES IT SOUND LIKE A [_spamton_0,SHIP] IS COMING [_spamton_0,OUR] WAY??", "OU DIRAIT-ON QU'UN [_spamton_0,NAVIRE] VIENT VERS [_spamton_0,NOUS] ??", Language.French);
