            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack was originally created by KingSlime, later revamped and maintained by Nostalgist, containing [count] Abnormality cards from Lobotomy Corporation.", "Ce paquet, créé à l'origine par KingSlime puis remanié et entretenu par Nostalgist, contient [count] cartes d'anomalies de Lobotomy Corporation.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Dawn", "Aube ambrée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Dawn, searching for the perfect meals", "L'aube ambrée cherche les repas parfaits.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Dusk", "Crépuscule ambré", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Dusk, loves the taste", "Le crépuscule ambré aime le goût.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Midnight", "Minuit ambré", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'they fough amongst themselves to feed'", "« Ils se battaient entre eux pour se nourrir. »", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "apocalypse, the horrid amalgamation of the defenders of the forest. a shame how it ended for them", "L'Oiseau de l'Apocalypse, horrible amalgame des défenseurs de la forêt. Quelle triste fin pour eux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Aspiration, it loves seeing the battlefield", "L'Aspiration aime observer le champ de bataille.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crazed notes, seems the writer lost thier mind", "Les notes démentes. Leur auteur semble avoir perdu la raison.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Dawn", "Aube cramoisie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crimson Dawn, a walking circus", "L'aube cramoisie, un cirque ambulant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Dusk", "Crépuscule cramoisi", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The circus tent is finally here", "Le chapiteau du cirque est enfin là.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Noon", "Midi cramoisi", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson Noon, even more deformed then its brothers", "Le midi cramoisi est encore plus difforme que ses semblables.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Dawn", "Aube émeraude", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the emerald Dawn, building towards that they came", "L'aube émeraude construit vers son lieu d'origine.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Dusk", "Crépuscule émeraude", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "constructing a tower from whence they came, so much potential", "Ils construisent une tour vers leur origine. Quel potentiel !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Midnight", "Minuit émeraude", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'the tower is touched by the sky, and it will leave nothing on this earth'", "« La tour touche le ciel et ne laissera rien sur cette terre. »", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Noon", "Midi émeraude", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "emerald noon, expresseing only despair and ire", "Le midi émeraude n'exprime que désespoir et colère.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the flesh idol, worshiped by those who are truly insane", "L'idole de chair, adorée par les véritables fous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Great Sap, usefull past the card", "La grande sève est utile au-delà de la carte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hod, the training meltdown", "Hod, l’effondrement de l'entraînement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malkuth, The meltdown of annoying me", "Malkuth, l’effondrement qui m'agace.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mirror of adjustment, some say it leads to another world", "Le Miroir d'ajustement. Certains disent qu'il mène à un autre monde.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "netzach, the safety meltdown", "Netzach, l’effondrement de la sécurité.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime, heard he trying hard to make this mod good", "Glu, paraît-il qu'il travaille dur pour améliorer ce mod.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the band, popular amongst teens", "Le groupe est populaire auprès des adolescents.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orchestra", "Orchestre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bear, it waits to show its true self", "L'ours attend de révéler sa vraie nature.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bloody, seems the blood never ends", "La sanglante : le sang semble ne jamais finir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the box, dont stare into the keyhole for to long", "La boîte. Ne regarde pas trop longtemps par la serrure.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The clockwork, the humming of its motors arent the only annoyance it makes", "Le mécanisme : le bourdonnement de ses moteurs n'est pas son seul désagrément.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Current, an experiment that has never seen the real world", "Le courant, une expérience qui n'a jamais vu le monde réel.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the cute, its looks can melt even the coldest hearts", "L'adorable : son apparence peut faire fondre les cœurs les plus froids.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this one is no longer cute", "Celle-ci n'est plus mignonne.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the dream, a peaceful ram that loves to sleep", "Le rêve, un bélier paisible qui aime dormir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "guess its dream came true", "Son rêve s'est réalisé, on dirait.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the exposed, taking the direct approach", "L'exposée adopte une approche directe.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The flower, living and walking on sunshine", "La fleur vit et marche au soleil.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the fragment, the poor creature experimented on into its form", "Le fragment, une pauvre créature transformée par des expériences.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Happy, calm yet in a state of excietment", "La joyeuse est calme mais excitée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the hatefull, innocent mind for what she hides underneath", "La haineuse : sous ce qu'elle cache se trouve un esprit innocent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the helper, it just wants to help you out", "L'assistant veut simplement t'aider.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the judge, decider of the good and the bad", "Le juge décide du bien et du mal.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the killer, made with intent", "Le tueur a été créé dans un but précis.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the lady, no one knows what she truly looks like", "La dame : personne ne connaît sa véritable apparence.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The little red, hunting the wolf in a game of cat and mouse", "Le petit chaperon rouge chasse le loup dans un jeu du chat et de la souris.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mad, its given up on playing nice", "La folle a renoncé à faire semblant d'être gentille.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Many, Containing all the fun of 5 in 1", "La multiple réunit 5 plaisirs en 1.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the masiyah, the prophet that speaks past death", "Le messie, le prophète qui parle au-delà de la mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The melting, master of the servants", "La fondante, maîtresse des serviteurs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Moral, It Tries but fails to keep balance", "La morale essaie de maintenir l'équilibre, en vain.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yin and Yang", "Yin et Yang", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the nameless, abondend and always hungering", "La sans-nom, abandonnée et toujours affamée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Neurtal, the only one i can deal with", "La neutre, la seule que je puisse supporter.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Neutral Look", "Expression neutre du jour", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the old, no one is here to keep her company", "La vieille, personne n'est là pour lui tenir compagnie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the phoenix, its ashes keep it forever alive", "Le phénix, dont les cendres lui donnent la vie éternelle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Plague, its only the beginning", "La peste, ce n'est que le début.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the poisoned, this apple keeps everyone away", "L'empoisonnée : cette pomme tient tout le monde à distance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the reindeer, dragging christmas fun all over the world", "Le renne traîne la joie de Noël partout dans le monde.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Sad, its destined to never see the light", "La triste est condamnée à ne jamais voir la lumière.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Sad Look", "Expression triste du jour", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the sniper, one shot is all it needs", "Le sniper n'a besoin que d'un tir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the star, the center of both attention and fashion", "La star, au centre de l'attention et de la mode.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the swan, its song sound similar to those of the band", "Le cygne chante presque comme le groupe.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The train, best not walk in its way", "Le Train : mieux vaut ne pas se mettre sur son chemin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the tree, spreading its roots to help its allies", "L'arbre étend ses racines pour aider ses alliés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the true hatred, seems she let out what she had inside", "La vraie haine semble avoir libéré ce qu'elle gardait en elle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the wolf, seems cute on first glance", "Le loup paraît mignon au premier abord.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the woodsman, sweeping the forest with its axe", "Le bûcheron balaie la forêt avec sa hache.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Army, they never seem to end", "L'armée semble ne jamais finir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never seen this one here", "Je ne l'ai jamais vu ici.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The CherryTree, Contains the bodies of thousands", "Le cerisier contient les corps de milliers d'êtres.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Fruit, its ripe for the picking.", "Le fruit est mûr, prêt à être cueilli.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Galaxy, a blessing, and a curse.", "La galaxie, une bénédiction et une malédiction.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The greedfull, carefull not to touch it.", "La cupide : attention à ne pas la toucher.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hive, The true ruler of the hive", "La ruche, sa véritable souveraine.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Innocent, Ignorant in everything besides pain", "L'innocente ne connaît rien d'autre que la douleur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mountain, it smiles upon you ", "La montagne te sourit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Nest, its presence is unsettling  ", "Le nid : sa présence est troublante.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Nothing...", "Le néant...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Silent, Performing the best orchestra around.", "La Silencieuse, qui dirige le meilleur orchestre des environs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Silent", "La Silencieuse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Swarm, he dresses for the occasion", "L'essaim s'est habillé pour l'occasion.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Trap, So Cute yet so deadly", "Le piège, si mignon et pourtant si mortel.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiphereth, the command meltdown", "Tiphereth, l'effondrement du commandement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Violet Dawn", "Aube violette", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet dawn, radiating the field", "L'aube violette irradie le champ.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet Midnight", "Minuit violet", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "we tried to accept it,we wanted to understand them", "Nous avons essayé de l'accepter, nous voulions les comprendre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Violet noon", "Midi violet", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet noon, enscrybing the words of their gods", "Le midi violet grave les paroles de leurs dieux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that explains the chills", "Voilà qui explique ces frissons.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the white night, the true end of the world", "La nuit blanche, la véritable fin du monde.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yesod, the concealing meltdown", "Yesod, l'effondrement de la dissimulation.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Claw", "La Griffe", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you can survive this white midnight.", "Peut-être survivras-tu à ce minuit blanc.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You definitely won't press the button, right?", "Tu ne vas certainement pas appuyer sur le bouton, n'est-ce pas ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If it's not voluntary, does anyone really need to be 'fixed'?", "Si ce n'est pas volontaire, a-t-on vraiment besoin d'être « réparé » ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one wants to know what truly protects them.", "Personne ne veut savoir ce qui les protège réellement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is currently unclear why such a painting would exist.", "On ignore encore pourquoi un tel tableau existe.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gloomy Seahorse", "Hippocampe morose", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play the fatal movement.", "Jouez le mouvement fatal.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why does the mysterious ray appear within the facility?", "Pourquoi la mystérieuse raie apparaît-elle dans l'établissement ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stingray", "Raie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What sorrow.", "Quelle tristesse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intangible creation.", "Une création intangible.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A scarecrow soaked in fresh blood.", "Un épouvantail trempé de sang frais.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you yearn for blessings?", "Aspires-tu aux bénédictions ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps, she can protect no one.", "Peut-être ne peut-elle protéger personne.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mechanical creations, restoring peace and health", "Des créations mécaniques qui restaurent paix et santé.", Language.French);

        }
    }
    public class NevernamedsBestiaryMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Nevernameds_Bestiary Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ace Lord", "Seigneur des as", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aderyn Y corph", "Aderyn Y corph", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The corpse bird. It's appearance portends the end.", "L'oiseau des cadavres. Son apparition présage la fin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adipocere", "Adipocire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor little corpse wax, it can be molded into any shape you can think of.", "Pauvre petite adipocire, on peut lui donner toutes les formes imaginables.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It lurks below the water, until the time is ripe to rend the land for prey.", "Elle se cache sous l'eau jusqu'au moment de déchirer la terre pour trouver une proie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahuizotl", "Ahuizotl", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Albatross", "Albatros", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The noble albatross. It's vast wingspan creates an impressive downdraft.", "Le noble albatros. Son immense envergure produit un impressionnant courant descendant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Albatross Chick", "Poussin d'albatros", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The young of the immense albatross, it seems almost lost inside of it's own down.", "Le petit de l'immense albatros semble presque perdu dans son propre duvet.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gar Roe", "Œufs de lépisosté", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxic gar roe, will kill anything that swallows it.", "Ces œufs toxiques tuent tout ce qui les avale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alligator Gar", "Lépisosté alligator", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ferocious Alligator Gar. It squirts out it's toxic eggs when frightened.", "Le féroce lépisosté alligator projette ses œufs toxiques lorsqu'il a peur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amorphous Shame", "Honte amorphe", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...such a shame...", "... quelle honte...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anaconda", "Anaconda", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't... don't say it. I have heard it all before, and it is not funny.", "Ne... ne dis rien. J'ai déjà tout entendu, et ce n'est pas drôle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anansi", "Anansi", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anansi, the many legged trickster. He attacks multiple times per turn, in flagrant disregard for the rules.", "Anansi, le farceur aux nombreuses pattes. Il attaque plusieurs fois par tour, au mépris des règles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anchimayen", "Anchimayen", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anemone", "Anémone", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The soft, unassuming anemone- it seems to have remarkable potential for propagation, but no means as of yet...", "La douce et discrète anémone semble avoir un remarquable potentiel de reproduction, mais aucun moyen pour l'instant...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angel Shark", "Requin-ange", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite the name, it is far from divine.", "Malgré son nom, elle est loin d'être divine.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That irritating canine...", "Cet agaçant canidé...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anteater", "Fourmilier", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The slothly anteater only attacks with vigour when presented with a meal.", "Le fourmilier paresseux n'attaque avec vigueur qu'en présence d'un repas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antingaw", "Antingaw", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar mollusk. It gathers sustenance from burrowing into barren rock...", "Un mollusque étrange. Il se nourrit en creusant la roche stérile...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So small... so fragile...", "Si petit... si fragile...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The larvae of the antlion. It's skill for trapping knows no match... in the insect world.", "La larve du fourmilion. Nul ne l'égale pour tendre des pièges... dans le monde des insectes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ararach", "Ararach", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infinilegged crawler, the Ararach never settles on a definitive strategy of attack for long...", "Ararach, le rampant aux innombrables pattes, ne garde jamais longtemps la même stratégie d'attaque...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The archerfish is quick to retaliate to any confrontation with a precise jet of water.", "Le poisson-archer riposte rapidement à toute confrontation par un jet d'eau précis.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Areion", "Areion", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The eternally running Areion. It loyally moves wherever it's owner demands it in the blink of an eye.", "Areion court sans fin. Fidèle, il rejoint en un clin d'œil l'endroit désigné par son propriétaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Artful Magister", "Magister astucieux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspidochelone", "Aspidochelone", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That ruthless spiny turtle... it shares it's spines with it's comrades..", "Cette tortue épineuse sans pitié... elle partage ses piquants avec ses compagnons.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automamox", "Automamox", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Axehandle Hound", "Chien à manche de hache", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peculiar axehandle hound. It uses it's sharp, bladed nose to cut clean through it's foes with the cold precision of a lumberjack...", "L'étrange chien à manche de hache. Son museau tranchant découpe ses ennemis avec la froide précision d'un bûcheron...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Axe Murderer", "Meurtrier à la hache", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Through night he hunts, in blackened brush, the bite of an axe heralds a blood red stream.", "Il chasse de nuit dans les buissons noircis ; la morsure d'une hache annonce un flot rouge sang.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Babai", "Babai", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baboon", "Babouin", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Far more vicious than its name and appearance would betray- it needs only a reason to strike.", "Bien plus féroce que ne le suggèrent son nom et son apparence : il lui suffit d'une raison pour frapper.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bakunawa", "Bakunawa", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lengthy Bakunawa, terror of the sea and skies.", "L'immense Bakunawa, terreur des mers et des cieux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Balaur", "Balaur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The three-headed Balaur dragon. It lashes out with each of it's maws when threatened.", "Balaur, le dragon à trois têtes. Menacé, il frappe avec chacune de ses gueules.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bald Eagle", "Pygargue à tête blanche", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truly the most patriotic of birds.", "Le plus patriote de tous les oiseaux, assurément.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ball Droid", "Droïde sphérique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Balloondroid", "Droïde ballon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bandito", "Bandit", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar deathcard- no matter how many times I tear it to pieces, I always find it back in my deck...", "Une étrange carte de mort. Peu importe combien de fois je la déchire, je la retrouve toujours dans mon deck...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bannana", "Banane", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a small, sweet spider... It couldn't hurt a fl- ...oh", "Une araignée si petite et douce... Elle ne ferait pas de mal à une mou... oh.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Barnacle", "Balane", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unimpressive barnacle. Anything that strikes it will be torn to shreds on it's rough shell.", "Le balane insignifiant. Tout ce qui le frappe sera déchiqueté sur sa coquille rugueuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilisk", "Basilic", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The grim basilisk. Life withers and dies under it's mere gaze.", "Le sinistre basilic. La vie se flétrit et meurt sous son seul regard.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Bat", "Chauve-souris en flammes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first... and last time one of my... associates attempted to use living organisms to it's own advantage.", "La première... et dernière fois qu'un de mes... associés a tenté d'utiliser des êtres vivants à son profit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Batfly", "Chauve-mouche", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The perturbing batfly. It clings to airborne creatures for a free ride.", "La troublante chauve-mouche. Elle s'accroche aux créatures volantes pour voyager gratuitement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bat Tery", "Chauve-pile", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beached Whale", "Baleine échouée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The poor thing, completely out of it's element... it bursts upon death.", "La pauvre, complètement hors de son élément... Elle éclate à sa mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beast Of Exmoor", "Bête d'Exmoor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The illusory exmoor cat... hard to catch, harder to kill.", "Le chat insaisissable d'Exmoor... difficile à attraper, encore plus à tuer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Belladin", "Palacloche", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bellbird", "Oiseau-cloche", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their cry is melodic, like the ringing of a great chime.", "Leur cri est mélodieux, comme la sonnerie d'une grande cloche.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bellbot", "Robot-cloche", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bhoot", "Bhoot", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How she floats above the holy earth... I wonder what form she will take next!", "Comme elle flotte au-dessus de la terre sacrée... Quelle forme prendra-t-elle ensuite ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bind Warden", "Gardien des liens", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Biscione", "Biscione", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious biscione, it is insatiable in it's lust for flesh.", "Le féroce Biscione, insatiable dans son désir de chair.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bishop", "Évêque", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bison", "Bison", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trampling Bison. It destroys anything in it's path, and becomes more enraged as it becomes more soaked with blood...", "Le bison piétineur détruit tout sur son passage et devient plus furieux à mesure qu'il se couvre de sang...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Dog", "Chien noir", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The grim black dog, haunter of graveyards... omen incarnate.", "Le sinistre chien noir hante les cimetières... un présage incarné.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Egg", "Œuf noir", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something pulses dimly, below the surface...", "Quelque chose pulse faiblement sous la surface...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Giant Squirrel", "Écureuil géant noir", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shadowy Black Giant Squirrel. It hits hard and is easily deployed, but perishes with no brothers or sisters by it's side...", "L'obscur écureuil géant noir frappe fort et se joue facilement, mais meurt sans frères ni sœurs à ses côtés...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Kite", "Milan noir", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It carries the flames of a previous inferno to drive prey from cover...", "Il transporte les flammes d'un ancien incendie pour débusquer ses proies...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Widow", "Veuve noire", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The black widow spider. It's infamous bite kills swiftly.", "La veuve noire. Sa morsure tristement célèbre tue rapidement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Obelisk", "Obélisque vierge", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blank obelisk. Unremarkable.", "Un obélisque vierge. Rien de remarquable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blast Termite", "Termite explosif", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disgusting blasting termite. It explodes it's foes upon death.", "Le répugnant termite explosif fait exploser ses ennemis à sa mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Mouse", "Souris aveugle", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those blind mice... always travelling in a group. See how they run...", "Ces souris aveugles... toujours en groupe. Regardez-les courir...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Scorpion", "Scorpion aveugle", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The poor blinded scorpion. It's venom is immaculate, but it's aim?... less so.", "Le pauvre scorpion aveugle. Son venin est parfait, mais sa précision... beaucoup moins.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloated Leech", "Sangsue gonflée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disquieting leech. It has reached full maturity.", "L'inquiétante sangsue a atteint sa pleine maturité.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blockhead", "Tête de bloc", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A comically frontheavy insect.", "Un insecte à l'avant si lourd qu'il en est comique.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodbag", "Poche de sang", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Cell", "Cellule sanguine", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Knight", "Chevalier de sang", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Red Dog", "Chien rouge sang", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infamous blood red dog, nothing can stop it's lust for combat. We'll have tea in hell today...", "L'infâme chien rouge sang : rien n'arrête sa soif de combat. Nous prendrons le thé en enfer aujourd'hui...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodstopper", "Arrête-sang", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Witch", "Sorcière de sang", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloodstarved beast. It will wither and die if it does not taste violence each turn.", "La bête assoiffée de sang se flétrit et meurt si elle ne goûte pas à la violence à chaque tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloody Sack", "Sac ensanglanté", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blowfly", "Mouche à viande", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disgusting.", "Dégoûtant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bluebottle", "Mouche bleue", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bluebottle... what secrets lie beyond it's squishy facade?", "La mouche bleue... quels secrets cache sa molle apparence ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue-Ringed", "Pieuvre à anneaux bleus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Blue-Ringed Octopus. It's venom is one of the most potent in the world...", "La pieuvre à anneaux bleus. Son venin est l'un des plus puissants au monde...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Whale", "Baleine bleue", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The greatest mortal beast ever to roam the seas... but not the greatest immortal one.", "La plus grande bête mortelle ayant parcouru les mers... mais pas la plus grande des immortelles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BoardWipe", "Nettoyage du plateau", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bobbit Worm", "Ver Bobbit", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrifying bobbit worm. It leaps from it's aquatic burrow to attack with it's razor sharp jaws.", "Le terrifiant ver Bobbit surgit de son terrier aquatique pour attaquer avec ses mâchoires tranchantes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bobcat", "Lynx roux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Often underestimated, the Bobcat will strike the moment it is played.", "Souvent sous-estimé, le lynx roux frappe dès qu'il est joué.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Body Snatcher", "Voleur de corps", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boil", "Furoncle", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A festering little blotch.", "Une petite tache purulente.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bolotnik", "Bolotnik", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloated swampman. It drags others down to hades- returning for more.", "L'homme des marais boursouflé entraîne les autres aux enfers, puis revient en chercher d'autres.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombardier Beetle", "Scarabée bombardier", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The incandescant bombardier beetle. It's boiling hot secretions scald it's prey.", "Le scarabée bombardier incandescent. Ses sécrétions brûlantes ébouillantent ses proies.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Cell", "Cellule osseuse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Clutter", "Amas d'os", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneworm", "Ver d'os", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The morbid boneworm. It excells in bringing remains to the surface of the churning soil...", "Le macabre ver d'os excelle à ramener les restes à la surface du sol remué...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Booting Bot", "Robot démarrage", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bot Printer", "Imprimante à robots", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bowerbird", "Jardinier", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crafty bowerbird, master of manipulating materials around itself.", "Le rusé jardinier, maître dans l'art de manipuler les matériaux autour de lui.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Box Jelly", "Méduse-boîte", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Small, but possessing of a crippling set of stingers.", "Petite, mais dotée de dards paralysants.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Proceed", "Continuer", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brazen Bull", "Taureau d'airain", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrific brazen bull. A true metric of human depravity.", "L'horrible taureau d'airain. Un véritable reflet de la dépravation humaine.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's go!", "Allons-y !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play me properly", "Joue-moi correctement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAAH, YES!", "HAHAHAHA, OUI !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES, YES!", "OUI, OUI !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S MAKE A RING", "FAISONS UN CERCLE", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OF FIRE", "DE FEU", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAH", "HAHAHAHAHA", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURN", "BRÛLER", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I want to", "Je veux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "see the fire", "voir le feu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "for glory!", "Pour la gloire !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yes, very well", "Oui, très bien", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's get to work", "Mettons-nous au travail", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHA", "HAHAHAHA", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHAHAH", "HAHAHAHAHAHA", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO GLORY", "À LA GLOIRE", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHAH", "HAHAHAHAHA", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAH, YES!", "HAHAHA, OUI !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IMPROVE ME", "AMÉLIORE-MOI", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can be", "Je peux être", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So much more!", "Bien plus !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you want.", "Si tu veux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SACRIFICE ME!", "SACRIFIE-MOI !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES", "OUI", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WILL DIE", "JE MOURRAI", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOR YOU", "POUR TOI", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's up to you", "À toi de décider", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harder!", "Plus fort !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO IT!", "FAIS-LE !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHA!", "HAHAHAHAHA !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES! MORE!", "OUI ! ENCORE !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Very good.", "Très bien.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANK YOU, THANK YOU!", "MERCI, MERCI !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VICTORY?", "VICTOIRE ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO GLORY!", "POUR LA GLOIRE !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES, YES", "OUI, OUI", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brine Shrimp", "Artémie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tiny, fleeting brine shrimp, so small it's as if it's not even there...", "La minuscule et fugace artémie, si petite qu'elle semble inexistante...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brollachan", "Brollachan", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wicked Brollachan. It can take many powerful forms...", "Le maléfique Brollachan peut prendre de nombreuses formes puissantes...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brown Recluse", "Recluse brune", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unassuming Brown Recluse. It attacks when threatened.", "La discrète recluse brune attaque lorsqu'elle est menacée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Budgerigar", "Perruche ondulée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friendly bird of domesticated breed, the Budgerigar will follow your command...", "Un oiseau domestique amical, la perruche ondulée obéira à vos ordres...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bugbear", "Bugbear", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrifying Bugbear. No creatures wish to remain in it's presence.", "L'horrible Bugbear. Aucune créature ne veut rester en sa présence.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Busted Bot", "Robot hors service", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Busted Conduit", "Conducteur hors service", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buzzard", "Buse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shameless buzzard- an inescapable symbol of death in the sands.", "La buse sans vergogne, symbole incontournable de la mort dans les sables.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiny Ant", "Fourmi épineuse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friendly ant covered in sharp thorns.", "Une fourmi amicale couverte d'épines acérées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The splifficated Cactus Cat, it roams the desert drinking the fermented juice of it's lookalike plant...", "Le chat-cactus ivre erre dans le désert en buvant le jus fermenté de la plante qui lui ressemble...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caged Beasts", "Bêtes en cage", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor, caged animals. Won't you set them free?", "Pauvres animaux en cage. Ne les libérerez-vous pas ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calygreyhound", "Calygreyhound", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The calygreyhound- a confusing chimeric clash which nonetheless stirs the loyalties of it's comrades.", "Le Calygreyhound, un assemblage chimérique déroutant qui inspire pourtant la loyauté de ses compagnons.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camazotz", "Camazotz", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camazotz, the bat god. He flies low amongst his enemies, slashing them with his bloodstained claws.", "Camazotz, le dieu chauve-souris. Il vole au ras de ses ennemis et les lacère de ses griffes ensanglantées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cam Drone", "Drone caméra", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stocky camel, it is resilient against most any threat", "Le robuste chameau résiste à presque toutes les menaces.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camel Spider", "Solifuge", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Camel Spider... an unpleasant arachnid to even gaze upon.", "Le solifuge... un arachnide désagréable à regarder.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candiru", "Candiru", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bloodsucking fish with a terrifying reputation.", "Un poisson suceur de sang à la réputation terrifiante.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Canopic Hawk", "Faucon canope", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A delicate ceramic bird, full of guts...", "Un délicat oiseau en céramique, rempli d'entrailles...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The much-beloved Capybara... it's fighting spirit is closely tied to it's wellbeing.", "Le capybara, tant aimé... son esprit combatif est étroitement lié à son bien-être.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caracal", "Caracal", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A quizzacious predator, ready to leap at any unsuspecting prey.", "Un prédateur curieux, prêt à bondir sur toute proie imprudente.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carrion Fly", "Mouche charognarde", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disgusting carrion fly. Drawn to death.", "La répugnante mouche charognarde. Attirée par la mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catalogue Keeper", "Gardien du catalogue", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catron", "Catron", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cattle Rustler", "Voleur de bétail", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cellar Spider", "Pholque", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Cellar spider. An exemplar of all arachnida.", "Le pholque. Un modèle pour tous les arachnides.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chameleon", "Caméléon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chameleon always changes it's spots, as is the proverb.", "Comme dit le proverbe, le caméléon change toujours de taches.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged Fey", "Fée enragée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The development of the changeling is entirely dependant on it's early childhood... violence begets violence.", "Le développement du changelin dépend entièrement de sa petite enfance... La violence engendre la violence.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pitiful Fey", "Fée pitoyable", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Changeling", "Changelin", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Card", "Carte du chaos", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Engine", "Moteur du chaos", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charred Lump", "Morceau calciné", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charybdis", "Charybde", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charybdis, the infernal vortex. Sucks all around it into it's collossal maw.", "Charybde, le tourbillon infernal. Elle aspire tout ce qui l'entoure dans son immense gueule.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A vindictive, nasty little bird.", "Un petit oiseau vindicatif et méchant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chicken Bones", "Os de poulet", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awfully sharp... and awfully disposable.", "Terriblement tranchants... et terriblement jetables.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chimpanzee", "Chimpanzé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The true utility of the chimp lies in it's dilligent hands...", "La véritable utilité du chimpanzé réside dans ses mains laborieuses...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chiral Crawler", "Rampeur chiral", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can a creature that drags its shackles along with it ever truly be free?", "Une créature qui traîne ses chaînes peut-elle jamais être vraiment libre ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chochin", "Chochin", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aha! The little lantern spook, such a mischevious little spirit it is!", "Ah ! Ce petit fantôme de lanterne, quel esprit espiègle !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chuman", "Chuman", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unholy union.", "Union impie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This beast of the night will tear apart any small prey he finds...", "Cette bête nocturne déchirera toute petite proie qu'elle trouvera...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clanklion", "Clanklion", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clumsy Pupil", "Élève maladroit", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cobra", "Cobra", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift cobra. Usually passive, but it delivers a nasty bite when startled.", "Le cobra agile. Généralement paisible, il mord férocement lorsqu'il est surpris.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cockle", "Coque", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unremarkable cockle, it feeds upon the remnants of the dead...", "La discrète coque se nourrit des restes des morts...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Code Thief", "Voleur de code", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coinchenn", "Coinchenn", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It lurks in the shadows of history, and shows no mercy to its prey.", "Elle rôde dans les ombres de l'histoire et n'accorde aucune pitié à ses proies.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Colossal Squid", "Calmar colossal", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colossal squid. It drags it's foes down to a watery grave.", "Le calmar colossal. Il entraîne ses ennemis vers une tombe aquatique.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tubular Bells", "Cloches tubulaires", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cone Snail", "Cône", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The venomous cone snail. Beware it's paralysing toxin.", "Le cône venimeux. Prenez garde à sa toxine paralysante.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjurer", "Invocateur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Copepod", "Copépode", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unassuming copepod, resilient to the last.", "Le discret copépode, résistant jusqu'au bout.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mysterious copycat. When it perishes, it... warps, to mimic it's murderer.", "Le mystérieux imitateur. Quand il périt, il... se déforme pour prendre l'apparence de son meurtrier.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coral", "Corail", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stoic coral colony, akin more to the landscape around it than to any other beast...", "Une colonie de corail stoïque, qui ressemble davantage au paysage qui l'entoure qu'à toute autre bête...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counstabot", "Agentbot", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cow", "Vache", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Centuries of domestication have not made it any less stubborn...", "Des siècles de domestication ne l'ont pas rendue moins têtue...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cowardly lion. It attempts to live up to the ferocity of it's cousins, but with little success.", "Le lion peureux. Il tente d'égaler la férocité de ses cousins, mais sans grand succès.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly Lion", "Lion peureux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowbird", "Vacher", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Too cowardly to remain for long, the cowbird is always eager to cause trouble.", "Trop lâche pour rester longtemps, le vacher est toujours prêt à semer le trouble.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time for crab.", "Place au crabe.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crab Spider", "Araignée-crabe", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hardy crab spider, it clings relentlessly to any source of food or warmth.", "La robuste araignée-crabe s'accroche sans relâche à toute source de nourriture ou de chaleur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crayfish", "Écrevisse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unrelenting crayfish. It changes the orientation of it's claws each turn.", "L'implacable écrevisse. Elle change l'orientation de ses pinces à chaque tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cremator", "Incinérateur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Paladin", "Paladin cramoisi", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Mouse", "Souris tordue", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was never the same after a run in with a crooked cat...", "Elle n'a plus jamais été la même après avoir croisé un chat tordu...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Wraith", "Spectre tordu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange one, this. Even I don't know its twisted past.", "Voilà un être étrange. Même moi, j'ignore son passé tortueux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crucibulum", "Crucibulum", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar little snail, forever growing it's conical shell.", "Un petit escargot particulier, dont la coquille conique grandit sans fin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Healer", "Guérisseur de cristal", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cubit", "Cubit", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curly-Legged Cat", "Chat aux pattes torses", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its twisted legs coil and bend in ways inexplicable. It is full of potential.", "Ses pattes tordues se replient et se courbent d'une manière inexplicable. Il possède un grand potentiel.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curruid", "Curruid", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clawed lord of the waves, the Curruid has but one blind spot.", "Seigneur griffu des flots, le Curruid n'a qu'un seul angle mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Child", "Enfant maudit", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That... should not be in my deck...", "Cela... ne devrait pas être dans mon deck...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Stunted... Wolf... I thought I threw him- ...I mean, this, away...", "Le loup... chétif... Je croyais l'avoir jeté... lui... enfin, ça...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The... stoat. Did I leave this here?", "L'... hermine. L'aurais-je laissée ici ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The... pungent... stinkbug?..", "La... malodorante... punaise ?..", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cyclops", "Cyclope", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The diminutive cyclops. It's great eye holds a perfect image of the past.", "Le cyclope minuscule. Son grand œil conserve une image parfaite du passé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aim well.", "Visez bien.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoot with caution.", "Tirez avec prudence.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aim me well.", "Visez bien avec moi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable draw.", "Pioche acceptable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survive.", "Survivez.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am your instrument.", "Je suis votre instrument.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will succeed.", "Je réussirai.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you are", "Si vous en êtes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "certain.", "certain.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I trust", "Je fais confiance", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bigger", "à l'ensemble", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "picture.", "du tableau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Over exposed.", "Trop exposé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This turn?", "Ce tour-ci ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temporal Misplay.", "Erreur temporelle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember this.", "Retenez ceci.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Certainly.", "Certainement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have", "Vous avez", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "aimed... well.", "bien... visé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Within acceptable", "Dans les limites", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "parameters.", "acceptables.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Betrayal.", "Trahison.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Judas.", "Judas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once more?", "Encore une fois ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How many times...", "Combien de fois...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable.", "Acceptable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Modification.", "Modification.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is desirable.", "C'est souhaitable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Picturesque.", "Pittoresque.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regards.", "Salutations.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undesirable.", "Indésirable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cease.", "Cessez.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is unfriendly.", "C'est hostile.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cease considerations.", "Cessez d'y réfléchir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Halt.", "Halte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have been...", "J'ai reçu...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...dealt a blow", "...un coup", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...a blow", "...un coup", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suffered.", "Encaissé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Assessing damages.", "Évaluation des dégâts.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dealt a blow...", "Un coup reçu...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So... familiar...", "Si... familier...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is unfortunate", "Il est regrettable", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "that we must", "que nous devions", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "trade blows...", "nous affronter...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel... kinship.", "Je ressens... une affinité.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am improved.", "J'ai été amélioré.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Improvement", "Amélioration", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edit in progress.", "Modification en cours.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A new instrument.", "Un nouvel instrument.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Under analysis", "Analyse en cours", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "statistically viable", "statistiquement viable", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A lineup?", "Une formation ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Darter", "Anhinga", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind the splash.", "Attention aux éclaboussures.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\"When the Lamb broke the fourth seal, I heard the voice of the fourth living creature saying, \"Come.\" I looked, and behold, an ashen horse; and he who sat on it had the name Death; and Hades was following with him.\"", "« Lorsque l'Agneau ouvrit le quatrième sceau, j'entendis la voix du quatrième être vivant dire : “Viens.” Je regardai, et voici qu'apparut un cheval blême. Celui qui le montait se nommait la Mort, et le séjour des morts le suivait. »", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death", "Mort", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deaths Door", "Porte de la mort", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't worry, we'll pull you through.", "Ne vous inquiétez pas, nous vous aiderons à vous en sortir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathstalker", "Rôdeur mortel", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The deathstalker scorpion. It's tail packs a potent venom.", "Le rôdeur mortel. Sa queue renferme un puissant venin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "De Bug", "Débogue", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What... is that?", "Qu'est-ce... que c'est ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Decorator Crab", "Crabe décorateur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lowly decorator crab. It scrounges the bottom of the ocean for detritus to stick to it's body.", "L'humble crabe décorateur. Il fouille les fonds marins à la recherche de débris qu'il colle sur son corps.", Language.French);


        }
    }
    public class NeedMoreWaterMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for NeedMoreWater Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack:NMW", "Paquet de cartes : NMW", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cardumen", "Banc de poissons", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cuando una carta que lleve este sello mate a otra criatura en combate, se crea una copia de esa carta en tu mano.", "Lorsqu'une carte ornée de cet emblème tue une autre créature au combat, une copie de la carte porteuse est créée dans votre main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rape", "Baudroie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Engañoso y altamente peligroso ese Rape.", "Cette baudroie est rusée et extrêmement dangereuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "La sangre derramada las atrae...", "Le sang versé les attire...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Arquero", "Poisson-archer", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su disparo de agua derriba a los insectos para comérselos.", "Il abat les insectes d'un jet d'eau pour les dévorer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Beta", "Combattant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El Pez Beta. Una belleza viva de las aguas.", "Le combattant. Une beauté vivante des eaux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Gato", "Poisson-chat", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El Pez Gato. Nunca te faltarán cebos.", "Le poisson-chat. Vous ne manquerez jamais d'appâts.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cocodrilo", "Crocodile", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cocodrilo, gran cazador. Ningún nadador escapa de sus fauces.", "Le crocodile, grand chasseur. Aucun nageur n'échappe à ses mâchoires.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morena", "Murène", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acecha entre las grietas, esperando a que algo nade demasiado cerca.", "Elle guette dans les fissures, attendant que quelque chose nage trop près.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez León", "Poisson-lion", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su veneno no es letal, pero sacará a la vista tus puntos débiles.", "Son venin n'est pas mortel, mais il exposera vos points faibles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Piraña", "Piranha", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pirañas, nunca hay una sola en el agua.", "Les piranhas ne sont jamais seuls dans l'eau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Globo", "Poisson-globe", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su combinación de veneno y espinas es letal para cualquier ser vivo.", "Son poison et ses épines réunis sont mortels pour tout être vivant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Remo", "Poisson-ruban", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Una de las bestias mas raras que he fotografiado jamás.", "L'une des bêtes les plus rares que j'aie jamais photographiées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhyzostoma", "Rhizostome", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nada sobrevive a la Rhyzostoma, ni dentro ni fuera del agua.", "Rien ne survit au rhizostome, ni dans l'eau ni hors de l'eau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salmón", "Saumon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El salmón, pez difícil de pescar.", "Le saumon, un poisson difficile à pêcher.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Esturión", "Esturgeon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El inundible esturión, acorazado marino.", "L'insubmersible esturgeon, cuirassé des mers.", Language.French);



        }
    }
    public class SauriaSigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SauriaSigils Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avenging", "Vengeur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever an adjacent card perishes during combat, a card bearing this sigil gains 1 Power.", "Chaque fois qu'une carte adjacente périt au combat, une carte ornée de cet emblème gagne 1 puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avenging Strike", "Frappe vengeresse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The loss of its friend will not go unpunished.", "La perte de son ami ne restera pas impunie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever a friendly card is killed during combat by an opponent's card, a card bearing this sigil moves to that space and strikes the attacker.", "Chaque fois qu'une carte alliée est tuée au combat par une carte adverse, une carte ornée de cet emblème se déplace vers sa case et frappe l'attaquant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To avenge the fallen...", "Pour venger les disparus...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleeding", "Saignement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil loses 1 Health at the end of their owner's turn.", "Une carte ornée de cet emblème perd 1 santé à la fin du tour de son propriétaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How much longer can it endure?", "Combien de temps pourra-t-elle encore tenir ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blessing", "Bénédiction", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Bones to increase Health of this and adjacent creatures by 1 if they have less than 10.", "Dépensez 4 os pour augmenter de 1 la santé de cette créature et des créatures adjacentes dont la santé est inférieure à 10.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beasts feel better now.", "Vos bêtes se sentent mieux maintenant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blizzard", "Blizzard", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, unoccupied spaces on its owner's side are filled with blocks of ice.", "Lorsqu'une carte ornée de cet emblème est placée, les cases libres du côté de son propriétaire sont remplies de blocs de glace.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winter is coming.", "L'hiver vient.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bone to gnaw on.", "Un os à ronger.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Blast", "Explosion d'os", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When initiating combat, a card bearing this sigil dies. Upon death, all other cards take damage equal to the amount of owner's bones.", "Au début du combat, une carte ornée de cet emblème meurt. À sa mort, toutes les autres cartes subissent autant de dégâts que son propriétaire possède d'os.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not a pretty sight", "Un spectacle peu plaisant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Gift", "Don d'os", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, a Bone is created in your hand. [define:Sauria_Bone]", "Lorsqu'une carte ornée de cet emblème est placée, un os est créé dans votre main. [define:Sauria_Bone]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gift for its master.", "Un cadeau pour son maître.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Offering", "Offrande d'os", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card on the opponent's side of board that costs Bones or Blood. Pay its price in Bones to add it to your hand. Blood is counted as 3 Bones, cannot choose cards that cost neither resource.", "Choisissez une carte du côté adverse du plateau qui coûte des os ou du sang. Payez son prix en os pour l'ajouter à votre main. Chaque point de sang compte pour 3 os ; les cartes ne coûtant aucune de ces ressources ne peuvent pas être choisies.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've managed to entice one of my beasts.", "Vous avez réussi à séduire l'une de mes bêtes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cannibalistic", "Cannibale", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When another card on the owner's side of board takes damage and its Health no longer exceeds Power of the bearer of this sigil, this card attacks it.", "Lorsqu'une autre carte du côté du propriétaire subit des dégâts et que sa santé ne dépasse plus la puissance du porteur de cet emblème, cette carte l'attaque.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A grim opportunity to feast.", "Une sinistre occasion de festoyer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caretaker", "Soigneur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, all other cards on the owner's side of board heal 1 Health while a card bearing this sigil is alive.", "À la fin du tour, tant qu'une carte ornée de cet emblème est en vie, toutes les autres cartes du côté de son propriétaire récupèrent 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It tends to their wounds.", "Il soigne leurs blessures.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catapult", "Catapulte", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to select another card on your side of the board to move to another space, including opponent's side of the board.", "Dépensez 1 os pour déplacer une autre carte de votre côté du plateau vers une autre case, même du côté adverse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for falling beasts.", "Attention aux chutes de bêtes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Change Form", "Changement de forme", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil transform into an alternate form.", "Une carte ornée de cet emblème se transforme en une autre forme.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch it shift its form.", "Regardez-la changer de forme.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Shifter", "Métamorphe osseux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Bones to transform this card into an alternate form.", "Dépensez 3 os pour transformer cette carte en une autre forme.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Concerned", "Inquiet", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a friendly card takes damage, a card bearing this sigil attempts to move to its closest adjacent space. If that space is occupied, it attempts to move one space in that direction instead.", "Lorsqu'une carte alliée subit des dégâts, une carte ornée de cet emblème tente de rejoindre la case adjacente la plus proche de cette alliée. Si cette case est occupée, elle tente plutôt d'avancer d'une case dans cette direction.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It responds to its ally's distress.", "Il répond à la détresse de son allié.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cruelty", "Cruauté", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card through any other means, it deals 1 damage to its target.", "Lorsqu'une carte ornée de cet emblème inflige des dégâts à une autre carte par tout autre moyen, elle inflige 1 dégât supplémentaire à sa cible.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This beasts wishes to inflict more grievous injuries.", "Cette bête souhaite infliger de plus graves blessures.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deep Freeze", "Congélation profonde", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes within 2 turns, the creature within is released.", "Si une carte ornée de cet emblème périt en 2 tours, la créature qu'elle renferme est libérée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free at last.", "Enfin libre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desperate Push", "Poussée désespérée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes during combat while opposing space is occupied, it pushes the opposing cards back.", "Si une carte ornée de cet emblème périt au combat alors que la case en face est occupée, elle repousse les cartes adverses.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps its sacrifice will pay off.", "Son sacrifice portera peut-être ses fruits.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dismember", "Démembrement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card, gain bones equal to the damage dealt, up to 5 bones at once.", "Lorsqu'une carte ornée de cet emblème inflige des dégâts à une autre carte, gagnez autant d'os que de dégâts infligés, jusqu'à 5 os à la fois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How gruesome.", "Quelle horreur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Embolden", "Enhardir", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are adjacent cards with less Power than the bearer of this sigil, lose 1 Power and give 1 Power to them.", "À la fin du tour du propriétaire, si des cartes adjacentes ont moins de puissance que le porteur de cet emblème, celui-ci perd 1 puissance et leur donne 1 puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its strength with its allies.", "Il partage sa force avec ses alliés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enduring", "Durable", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 2 Health at the start of its third turn on the board.", "Une carte ornée de cet emblème gagne 2 santé au début de son troisième tour sur le plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prolonged combat is fortifying this beast.", "Le combat prolongé fortifie cette bête.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic March", "Marche erratique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move in the direction inscribed on the sigil at the end of its owner's turn. If there are cards in its way or this card is at edge of the board, it will try to move to the opponent's side of board first.", "À la fin du tour de son propriétaire, une carte ornée de cet emblème se déplace dans la direction indiquée. Si une carte bloque son chemin ou si elle se trouve au bord du plateau, elle tente d'abord de passer du côté adverse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its movements are unpredictable.", "Ses mouvements sont imprévisibles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fervor", "Ferveur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 Power at the start of its third turn on the board.", "Une carte ornée de cet emblème gagne 1 puissance au début de son troisième tour sur le plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prolonged combat is making this beast grow more ferocious.", "Le combat prolongé rend cette bête plus féroce.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genetic Flaw", "Défaut génétique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil loses 1 Health at the end of their owner's turn.", "Une carte ornée de cet emblème perd 1 santé à la fin du tour de son propriétaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps it's not meant to live.", "Peut-être n'est-il pas destiné à vivre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genetic Perfection", "Perfection génétique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If card bearing this sigil has its stats reduced below their normal values, it gains 1 Power and/or Health at the end of its owner's turn. If this card has Genetic Flaw sigil, remove it.", "Si les caractéristiques d'une carte ornée de cet emblème passent sous leurs valeurs normales, elle gagne 1 puissance et/ou santé à la fin du tour de son propriétaire. Si elle possède l'emblème Défaut génétique, retirez-le.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is perfection incarnate.", "C'est la perfection incarnée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Catapult", "Grande catapulte", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Bones to select another card on your side of the board to move to another space, including opponent's side of the board. If there is an obstruction with a free opposing space, it takes damage equal to this card's Attack first. If obstruction remains, selected card attempts to move to its opposing space instead.", "Dépensez 3 os pour déplacer une autre carte de votre côté vers une autre case, y compris du côté adverse. Si la case cible contient un obstacle dont la case opposée est vide ou occupée par la carte choisie, il subit d'abord des dégâts égaux à l'attaque du porteur de cet emblème. S'il reste, la carte choisie tente de rejoindre la case en face.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good aim.", "Bien visé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Embolden", "Grand enhardissement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are any cards on owner's side of the board with less Power than the bearer of this sigil, lose 1 Power and give 1 Power to them.", "À la fin du tour du propriétaire, si des cartes de son côté ont moins de puissance que le porteur de cet emblème, celui-ci perd 1 puissance et leur donne 1 puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its strength with all of its allies.", "Il partage sa force avec tous ses alliés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Grudge Bearer", "Grand porteur de rancune", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever cards belonging to the owner of the card bearing this sigil are struck, the attacker is marked. At the start of the owner's turn, this card attacks all marked cards owned by the opponent.", "Chaque fois qu'une carte du propriétaire d'une carte ornée de cet emblème est frappée, l'attaquant est marqué. Au début du tour de ce propriétaire, cette carte attaque toutes les cartes adverses marquées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death is the only suitable punishment.", "La mort est la seule punition appropriée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Nurture", "Grand élevage", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are any cards on owner's side of the board with less Health than the bearer of this sigil, lose 1 Health and give 1 Health to them.", "À la fin du tour du propriétaire, si des cartes de son côté ont moins de santé que le porteur de cet emblème, celui-ci perd 1 santé et leur donne 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its essence with all of its allies.", "Il partage son essence avec tous ses alliés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grievous Display", "Spectacle affligeant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks an opposing creature and it perishes, creatures to the left and right of the target lose 1 Power.", "Lorsqu'une carte ornée de cet emblème attaque une créature adverse et que celle-ci périt, les créatures à gauche et à droite de la cible perdent 1 puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not easy on the eyes.", "Ce n'est pas beau à voir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ground Pound", "Coup au sol", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, cards in opposing and adjacent spaces take 1 damage. This effect is additionally activated when moving 2 spaces away from last position or the opponent's side of board.", "Lorsqu'une carte ornée de cet emblème est placée, les cartes à sa gauche et à sa droite sur la même rangée, ainsi que celle en face, subissent 1 dégât. L'effet se déclenche aussi si elle change de côté ou se déplace d'au moins 2 cases sur la même rangée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A less than graceful landing.", "Un atterrissage peu gracieux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ground Smash", "Fracassement du sol", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, it deals damage to cards in opposing and adjacent spaces equal to its Attack or at least 1 damage. This effect is additionally activated when moving 2 spaces away from last position or the opponent's side of board.", "Lorsqu'une carte ornée de cet emblème est placée, elle inflige aux cartes à sa gauche et à sa droite sur la même rangée et à celle en face des dégâts égaux à son attaque, au minimum 1. L'effet se déclenche aussi si elle change de côté ou se déplace d'au moins 2 cases sur la même rangée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a nasty shockwave.", "Quelle violente onde de choc.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge Bearer", "Porteur de rancune", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the attacker is marked. At the start of the owner's turn, this card attacks a random marked card owned by the opponent.", "Lorsqu'une carte ornée de cet emblème est frappée, l'attaquant est marqué. Au début du tour de son propriétaire, cette carte attaque une carte adverse marquée au hasard.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It will remember this.", "Il s'en souviendra.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge-Powered", "Alimenté par la rancune", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of opponent's creatures marked by Grudge Bearer sigils and the number of said creatures killed by the bearer of this sigil.", "La valeur représentée par cet emblème est égale au nombre de créatures adverses marquées par des emblèmes Porteur de rancune, plus le nombre de ces créatures tuées par son porteur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of opponent's creatures marked by Grudge Bearer sigils and the number of said creatures killed by [creature].", "La puissance de [creature] est égale au nombre de créatures adverses marquées par des emblèmes Porteur de rancune, plus le nombre de ces créatures tuées par [creature].", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge Target", "Cible de rancune", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will be attacked by opponent's cards bearing Grudge Bearer sigils.", "Une carte ornée de cet emblème sera attaquée par les cartes adverses ornées d'emblèmes Porteur de rancune.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A permanent stain.", "Une tache indélébile.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hasty Escape", "Fuite précipitée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon taking damage, the bearer of this sigil returns to owner's hand if it's still alive.", "Lorsqu'il subit des dégâts, le porteur de cet emblème retourne dans la main de son propriétaire s'il est encore en vie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sometimes, cowards do survive.", "Parfois, les lâches survivent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Block of Ice", "Plus grand bloc de glace", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A block of ice, nothing to see", "Un bloc de glace, rien à voir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its meal with its newfound family.", "Il partage son repas avec sa nouvelle famille.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knock Back", "Repousser", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card, it attempts to move its target to an adjacent space, prioritizing right.", "Lorsqu'une carte ornée de cet emblème inflige des dégâts à une autre carte, elle tente de déplacer sa cible vers une case adjacente, en priorité à droite.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A nasty blow.", "Un coup terrible.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juicy Meat", "Viande juteuse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meat", "Viande", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Makes you salivate.", "De quoi vous mettre l'eau à la bouche.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Memento", "Souvenir", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes during combat, adjacent cards gain 1 Power.", "Si une carte ornée de cet emblème périt au combat, les cartes adjacentes gagnent 1 puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its friends will not forgive those fiends.", "Ses amis ne pardonneront pas à ces monstres.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete and total extermination is the only reasonable response.", "Une extermination complète et totale est la seule réponse raisonnable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Micro", "Micro", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Movement Command", "Ordre de déplacement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, move the bearer of this sigil to a selected empty space.", "Une fois par tour, déplacez le porteur de cet emblème vers une case vide de votre choix.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beast follows your command.", "La bête suit vos ordres.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nurture", "Élever", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are adjacent cards with less Health than the bearer of this sigil, lose 1 Health and give 1 Health to them.", "À la fin du tour du propriétaire, si des cartes adjacentes ont moins de santé que le porteur de cet emblème, celui-ci perd 1 santé et leur donne 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its essence with its allies.", "Il partage son essence avec ses alliés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Outburst", "Déchaînement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, a card bearing this sigil performs an additional attack against opposing space if it's occupied by a card whose Attack is above 0.", "À la fin du tour de son propriétaire, une carte ornée de cet emblème attaque une fois de plus la case en face si celle-ci contient une carte dont l'attaque est supérieure à 0.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It won't be moving for long at this rate.", "À ce rythme, il ne bougera plus longtemps.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitoid Propagation", "Propagation parasitoïde", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a copy of this card is created in your hand.", "Lorsqu'une carte ornée de cet emblème tue une autre créature, une copie de cette carte est créée dans votre main.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life can be unsightly at times.", "La vie peut parfois être disgracieuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parental Care", "Soins parentaux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, creatures with Fledgling sigil adjacent to a card bearing this sigil gain 1 Health.", "À la fin du tour du propriétaire, les créatures ornées de l'emblème Oisillon qui sont adjacentes à une carte ornée de cet emblème gagnent 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good parent.", "Un bon parent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parting Bone", "Os d'adieu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil dies or is sacrificed, a Bone is created in your hand. [define:Sauria_Bone]", "Lorsqu'une carte ornée de cet emblème meurt ou est sacrifiée, un os est créé dans votre main. [define:Sauria_Bone]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A parting gift for its master.", "Un cadeau d'adieu pour son maître.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persistent", "Persistance", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil would die during combat for the first time, it revives and gains 2 Power.", "Lorsqu'une carte ornée de cet emblème devrait mourir au combat pour la première fois, elle ressuscite et gagne 2 puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That creature will not give up so easily.", "Cette créature n'abandonnera pas si facilement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protective", "Protecteur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an adjacent card is struck, a card bearing this sigil strikes the attacker.", "Lorsqu'une carte adjacente est frappée, une carte ornée de cet emblème frappe l'attaquant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It doesn't appreciate having its comrades hurt.", "Il n'apprécie pas qu'on blesse ses camarades.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protective Parent", "Parent protecteur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When owner's cards with Fledgling sigil are struck, bearer of this sigil strikes the attacker.", "Lorsque les cartes du propriétaire ornées de l'emblème Oisillon sont frappées, le porteur de cet emblème frappe l'attaquant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Few things inspire more awe and fear than a protective parent.", "Peu de choses inspirent autant de respect et de crainte qu'un parent protecteur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pursuer", "Poursuivant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever an opponent's card moves to another space, a card bearing this sigil attempts to move to its current opposing space. If successful, it deals 1 damage to its opposing space.", "Chaque fois qu'une carte adverse se déplace, une carte ornée de cet emblème tente de rejoindre la case en face de sa nouvelle position. Si elle y parvient, elle inflige 1 dégât à cette carte si elle est encore en vie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no escape...", "Aucune issue...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quake", "Séisme", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Bones to deal 1 damage to all enemy cards. This sigil is removed afterwards.", "Dépensez 4 os pour infliger 1 dégât à toutes les cartes adverses. Cet emblème est ensuite retiré.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrifying display of power.", "Une terrifiante démonstration de puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Served Dinner", "Dîner servi", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card on the owner's side of board. Add stats of the card bearing this sigil to the selected card. This card dies afterwards. This effect can also be activated by sacrificing or killing this page directly.", "Choisissez une carte du côté du propriétaire. Ajoutez à cette carte les caractéristiques de la carte ornée de cet emblème. Cette dernière meurt ensuite. Cet effet peut aussi être activé en sacrifiant ou en tuant directement cette carte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dinner is served.", "Le dîner est servi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoal Strike", "Frappe de banc", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, it deals 1 damage to all of opponent's submerged cards and forces them to surface.", "Lorsqu'une carte ornée de cet emblème est placée, elle inflige 1 dégât à toutes les cartes adverses immergées et les force à remonter.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hunt begins...", "La chasse commence...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skittish", "Craintif", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card moves into space opposing the one bearing this sigil, deal 1 damage to it, then move to a random unoccupied space on the owner's side of board if possible.", "Lorsqu'une carte rejoint la case en face du porteur de cet emblème, infligez-lui 1 dégât, puis déplacez le porteur vers une case libre aléatoire du côté de son propriétaire si possible.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature appears to be rather skittish.", "Cette créature semble plutôt farouche.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sprinter Strike", "Frappe de sprint", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenener a card bearing this sigil moves, it deals 1 damage to its opposing space. If said space is not occupied, the opponent is deald 1 damage immediately.", "Chaque fois qu'une carte ornée de cet emblème se déplace, elle inflige 1 dégât à la case en face. Si cette case est vide, l'adversaire subit immédiatement 1 dégât.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A swift strike.", "Une frappe rapide.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sticky Tongue", "Langue collante", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owners turn, a card bearing this sigil attempts to drag creatures adjacent to opposing space or queued behind it in front of itself, prioritizing the latter. If affected card has 1 Health, this card immediately attacks it.", "Au début du tour de son propriétaire, une carte ornée de cet emblème tente d'attirer devant elle les créatures adjacentes à la case en face ou en attente derrière celle-ci, en privilégiant ces dernières. Si la carte attirée a 1 santé, elle l'attaque immédiatement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a sticky situation.", "Une situation bien collante.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tactical Retreat", "Retraite tactique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, the bearer of this sigil returns to owner's hand if it's still alive.", "À la fin du tour de son propriétaire, le porteur de cet emblème retourne dans sa main s'il est encore en vie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It doesn't feel the need to stay on the board.", "Il ne ressent pas le besoin de rester sur le plateau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TearThrough", "Percée", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If opposing space is occupied, a card bearing this sigil will move in the direction inscribed on the sigil at the end of its owner's turn, dealing 1 damage to the card in that space and trying to move it as well.", "Si la case en face est occupée, une carte ornée de cet emblème se déplace dans la direction indiquée à la fin du tour de son propriétaire, inflige 1 dégât à la carte sur cette case et tente aussi de la déplacer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A brutal display", "Une démonstration brutale", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Territorial", "Territorial", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When another creature moves into an adjacent or opposing space, a card bearing this sigil attacks it.", "Lorsqu'une autre créature rejoint une case adjacente ou en face, une carte ornée de cet emblème l'attaque.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To intrude upon its territory...", "Oser pénétrer sur son territoire...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyranny", "Tyrannie", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Blood to increase Attack and Health of this and adjacent creatures by 1, then remove this sigil.", "Dépensez 2 sang pour augmenter de 1 l'attaque et la santé de cette créature et des créatures adjacentes, puis retirez cet emblème.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sacrifice this beast is willing to make.", "Un sacrifice que cette bête est prête à faire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vicious Growth", "Croissance féroce", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, it gains 1 Power and 1 Health.", "Lorsqu'une carte ornée de cet emblème tue une autre créature, elle gagne 1 puissance et 1 santé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One life to nourish another.", "Une vie pour en nourrir une autre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wounding", "Blessure", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card without Made of Stone, its target gains Bleeding effect. Bleeding cards lose 1 Health at the end of their owner's turn.", "Lorsqu'une carte ornée de cet emblème inflige des dégâts à une carte sans Pétrification, sa cible reçoit l'effet Saignement. Les cartes qui saignent perdent 1 santé à la fin du tour de leur propriétaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This must sting.", "Cela doit piquer.", Language.French);



            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's a Grudgin'", "Ça mérite une rancune", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a card collect grudges from 10 marked cards in a single battle", "Faites accumuler à une carte des rancunes provenant de 10 cartes marquées dans un même combat.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete and Total Extermination", "Extermination complète et totale", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a card with Greater Grudge Bearer wipe out 4 marked cards at once.", "Faites éliminer 4 cartes marquées à la fois par une carte ornée de Grand porteur de rancune.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Completely Boned", "Complètement désossé", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wipe out the whole board via Bone Blast.", "Videz tout le plateau grâce à Explosion d'os.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus School of Thought", "L'école de pensée du Plateosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a philosopher bother 10 cards with questions in a single battle.", "Faites importuner 10 cartes par un philosophe avec ses questions au cours d'un même combat.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrible Roommate", "Un colocataire terrible", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a territorial card lash out at friendly cards in a single battle", "Faites attaquer des cartes alliées par une carte territoriale au cours d'un même combat.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beast Cannon", "Canon à bêtes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill at least 2 enemy cards by throwing a hefty beast at them.", "Tuez au moins 2 cartes adverses en leur lançant une lourde bête.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Et Tu, Majungasaurus?", "Toi aussi, Majungasaurus ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a cannibalistic card devour 10 friendly cards in a single battle.", "Faites dévorer 10 cartes alliées par une carte cannibale au cours d'un même combat.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Tis But A Scratch", "Ce n'est qu'une égratignure", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have one of your cards survive 10 turns while bleeding.", "Faites survivre une de vos cartes pendant 10 tours alors qu'elle saigne.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empathetic", "Empathique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a nurturing card sacrifice 10 Health in a single battle.", "Faites sacrifier 10 santé à une carte qui élève ses alliés au cours d'un même combat.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rally", "Ralliement", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have an emboldening card sacrifice 10 Power in a single battle.", "Faites sacrifier 10 puissance à une carte qui enhardit ses alliés au cours d'un même combat.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascended Arts", "Arts transcendés", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a certain card fully remove cost of 6 cards in a single run.", "Faites entièrement supprimer le coût de 6 cartes par une certaine carte au cours d'une même aventure.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raptor Attack", "Attaque de rapaces", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain at least 10 Raptor cards in a single run.", "Obtenez au moins 10 cartes Raptor au cours d'une même aventure.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jurassic World", "Monde jurassique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 3 secret cards. Life finds a way.", "Terminez une aventure avec 3 cartes secrètes. La vie trouve toujours un chemin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apex Predators", "Superprédateurs", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have three biggest theropods in your deck in a single run.", "Ayez les trois plus grands théropodes dans votre deck au cours d'une même aventure.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "King of the Monsters", "Roi des monstres", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unleash the King of the Monsters upon the enemy.", "Lâchez le Roi des monstres sur l'ennemi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ballad of Big Al", "La ballade du grand Al", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Help get the big girl back on her feet. Poor thing.", "Aidez la grande à se remettre sur pied. La pauvre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indomitable One", "L'indomptable", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Create a genetic abomination with more teeth.", "Créez une abomination génétique avec plus de dents.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Monster Resurrected", "Le retour du monstre", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Make Spinosaurus feel like a monster.", "Faites sentir à Spinosaurus qu'il est un monstre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jurassic Painter", "Peintre jurassique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Promote Stokesosaurus to a painter.", "Promouvez Stokesosaurus au rang de peintre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All Outta Gum", "À court de chewing-gum", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give the little guy balls of steel.", "Donnez au petit des couilles d'acier.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Novel Look", "Nouvelle allure", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take the frills off the crested critter.", "Retirez la collerette de la créature à crête.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bird Up", "À plumes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Put too many feathers where they don't belong.", "Mettez trop de plumes là où elles n'ont pas leur place.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wu's Secrets", "Les secrets de Wu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have Compstegnathus, Spinoraptor and Ankylodocus in your deck in a single run.", "Ayez Compstegnathus, Spinoraptor et Ankylodocus dans votre deck au cours d'une même aventure.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Welcome to Jurassic Park", "Bienvenue à Jurassic Park", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with Jurassic Park deck and at least 7 related cards.", "Terminez une aventure avec le deck Jurassic Park et au moins 7 cartes associées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prehistoric Collection", "Collection préhistorique", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play a copy of every common Sauria card.", "Jouez un exemplaire de chaque carte Sauria commune.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rare Fossils", "Fossiles rares", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play a copy of every rare Sauria card.", "Jouez un exemplaire de chaque carte Sauria rare.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paleo-Novice", "Paléo-novice", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 5 Sauria decks.", "Terminez des aventures avec au moins 5 decks de départ Sauria différents.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dino-Fan", "Fan de dinosaures", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 20 Sauria decks.", "Terminez des aventures avec au moins 20 decks de départ Sauria différents.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deck-O-Saurus", "Deck-o-saure", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with every available Sauria deck.", "Terminez une aventure avec chacun des decks Sauria disponibles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gyarouucore", "Gyarouucore", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtained every other achievement! Good job!", "Vous avez obtenu tous les autres succès ! Bravo !", Language.French);

        }
    }
    public class SauriaCardsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SauriaCards Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acrocanthosaurus", "Acrocanthosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acrocanthosaurus, terror of the North. It does not take much to provoke this giant into attacking.", "Acrocanthosaurus, la terreur du Nord. Il en faut peu pour pousser ce géant à attaquer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allosaurus", "Allosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This tenacious predator doesn't know when to stop its assault.", "Ce prédateur tenace ne sait pas quand cesser son assaut.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amargasaurus", "Amargasaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amargasaurus, a surprisingly small beast for its kind. Size is relative, however.", "Amargasaurus, une bête étonnamment petite pour son espèce. Mais la taille est relative.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "American Lion", "Lion américain", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The American Lion, a vicious feline predator with a soft heart. It does not extend its kindness towards its prey, however.", "Le lion américain, un félin féroce au cœur tendre. Il ne fait toutefois preuve d'aucune bonté envers ses proies.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "American Lion Cub", "Lionceau américain", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An American Lion Cub, an adorable kitten. It's hard to imagine something like this growing up to become a terrifying predator", "Un lionceau américain, un adorable petit félin. Difficile d'imaginer qu'il deviendra un prédateur terrifiant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankylosaurus", "Ankylosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sturdy Ankylosaurus. It may not feel claws and teeth strike its hide, but it does not appreciate being pestered during mealtime.", "Le robuste Ankylosaurus. Il ne sent peut-être pas les griffes et les crocs frapper sa peau, mais il n'aime pas être dérangé pendant son repas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anomalocaris", "Anomalocaris", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ancient Anomalocaris, one of the first apex predators to live in this world. It does its best against modern beasts.", "L'antique Anomalocaris, l'un des premiers superprédateurs de ce monde. Il fait de son mieux contre les bêtes modernes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apatosaurus", "Apatosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The formidable Apatosaurus. It doesn't need to be the biggest of its kind to crush enemies into dust.", "Le redoutable Apatosaurus. Il n'a pas besoin d'être le plus grand de son espèce pour réduire ses ennemis en poussière.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Argentinosaurus", "Argentinosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The titanic Argentinosaurus, truly a sight to behold. Make sure to keep your distance if you do not wish to be crushed.", "Le titanesque Argentinosaurus, un spectacle à contempler. Gardez vos distances si vous ne voulez pas être écrasé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arthropleura", "Arthropleura", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arthropleura, an oversized centipede with a taste for decaying plants. Its movements are unpredictable.", "Arthropleura, un mille-pattes démesuré amateur de végétaux en décomposition. Ses mouvements sont imprévisibles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspidorhynchus", "Aspidorhynchus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is much bigger fish out there, but Aspidorhynchus is still perfectly capable of biting your fingers off.", "Il existe des poissons bien plus grands, mais Aspidorhynchus reste tout à fait capable de vous arracher les doigts d'un coup de mâchoire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Australovenator", "Australovenator", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious Australovenator. It pierces and tears through the hide of its victims with its enlarged claws.", "Le féroce Australovenator. Il perce et déchire la peau de ses victimes avec ses grandes griffes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Austroraptor", "Austroraptor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keen-eyed Austroraptor, a skilled fisher of light build. It's far from harmless, however.", "Austroraptor à l'œil vif, un habile pêcheur à la carrure légère. Il est pourtant loin d'être inoffensif.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baryonyx", "Baryonyx", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baryonyx, a crocodile-faced beast with a taste for fish. Refrain from smiling if you do not wish to expand its diet.", "Baryonyx, une bête à tête de crocodile qui aime le poisson. Évitez de sourire si vous ne souhaitez pas élargir son régime alimentaire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beipiaosaurus", "Beipiaosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Beipiaosaurus is armed with sharp claws to rend its foes apart...but it does not have the courage to stand up to anything bigger.", "Ce Beipiaosaurus possède des griffes acérées pour déchirer ses ennemis... mais manque de courage face à plus grand que lui.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachiosaurus", "Brachiosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mighty Brachiosaurus. It can use its immense size to draw aggressors away from allies.", "Le puissant Brachiosaurus. Sa taille immense lui permet d'éloigner les assaillants de ses alliés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachiosaurus Hatchling", "Jeune Brachiosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Brachiosaurus hatchling. It will take some time for it to reach its full size.", "Un jeune Brachiosaurus. Il lui faudra du temps pour atteindre sa taille adulte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachytrachelopan", "Brachytrachelopan", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachytrachelopan, a bizarre creature for its kind. Though it lacks their characteristic long neck, its long tail makes up for its absence.", "Brachytrachelopan, une créature étrange pour son espèce. Son long cou caractéristique lui manque, mais sa longue queue compense cette absence.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camarasaurus", "Camarasaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ginormous Camarasaurus. Though it does not wish to bring harm directly, its great size allows it to fling beasts across the battlefield.", "L'énorme Camarasaurus. Il ne souhaite pas blesser directement, mais sa grande taille lui permet de projeter des bêtes à travers le champ de bataille.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria", "Sauria", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnotaurus", "Carnotaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though not as swift as commonly believed, this beast can hardly be stopped once it gains momentum.", "Bien qu'elle ne soit pas aussi rapide qu'on le croit, cette bête est presque impossible à arrêter une fois lancée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cartorhynchus", "Cartorhynchus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Cartorhynchus may be tiny, but there is bigger fish following its trail.", "Ce Cartorhynchus est peut-être minuscule, mais un plus gros poisson suit sa trace.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caturus", "Caturus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caturus, an imposing predator to some, an enticing snack for others.", "Caturus, un prédateur imposant pour certains, un en-cas tentant pour d'autres.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cearadactylus", "Cearadactylus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Too busy fretting over its meals, Cearadactylus does not make for a great fighter.", "Trop occupé à se soucier de ses repas, Cearadactylus ne fait pas un grand combattant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cephalaspis", "Cephalaspis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cephalaspis, an armored fish shaped like a shovel. Its thick armor lets it feed in peace.", "Cephalaspis, un poisson cuirassé en forme de pelle. Son épaisse armure lui permet de se nourrir en paix.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ceratodus", "Ceratodus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peculiar Ceratodus, a fish with the ability to live on land. Makes for a fine meal.", "Le curieux Ceratodus, un poisson capable de vivre sur terre. Il fait un bon repas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ceratosaurus", "Ceratosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though often overshadowed by its bigger competitors, Ceratosaurus is a formidable threat in its own right.", "Souvent éclipsé par ses concurrents plus grands, Ceratosaurus n'en demeure pas moins une menace redoutable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chasmosaurus", "Chasmosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stalwart Chasmosaurus. It uses its shield-like frill to protect allies.", "L'inébranlable Chasmosaurus. Il utilise sa collerette en forme de bouclier pour protéger ses alliés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chungkingosaurus", "Chungkingosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though it may not be eager to hurt other creatures, you do not want to get near the tail of Chungkingosaurus.", "Même s'il ne souhaite pas blesser d'autres créatures, mieux vaut ne pas s'approcher de la queue de Chungkingosaurus.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coelophysis", "Coelophysis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coelophysis, one of the first of its kind. Many more terrible beasts have spawned from its lineage.", "Coelophysis, l'un des premiers de son espèce. Bien d'autres bêtes terribles sont issues de sa lignée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compsognathus", "Compsognathus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The diminutive Compsognathus. It can hardly pose a threat while alone.", "Le minuscule Compsognathus. Seul, il ne représente guère une menace.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corythosaurus", "Corythosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corythosaurus, a cautious beast that does not travel alone. It finds safety in a herd.", "Corythosaurus, une bête prudente qui ne voyage pas seule. Elle trouve la sécurité dans le troupeau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dacentrurus", "Dacentrurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dacentrurus, a beast with an oddly elongated neck that fiercely protects its allies.", "Dacentrurus, une bête au cou étrangement allongé qui protège farouchement ses alliés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Daeodon", "Daeodon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrible Daeodon. It may not be a pig, but it is certainly prepared for war.", "Le terrible Daeodon. Ce n'est peut-être pas un cochon, mais il est assurément prêt pour la guerre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinocheirus", "Deinocheirus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once thought to be a terrible beast, Deinocheirus turned out to be far more bizarre than anyone expected. Its strength is not to be underestimated, however.", "Autrefois considéré comme une terrible bête, Deinocheirus s'est révélé bien plus étrange que prévu. Sa force n'est pourtant pas à sous-estimer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinonychus", "Deinonychus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinonychus, a vicious hunter known for the enlarged claws adorning its feet. How's that for a 'six-foot turkey'?", "Deinonychus, un chasseur féroce connu pour les grandes griffes de ses pattes. Alors, que pensez-vous de cette « dinde de six pieds » ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sicilian Dwarf Elephant", "Éléphant nain de Sicile", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sicilian Dwarf Elephant, a severely undersized counterpart of one of the biggest animals to roam the land today. Such is life on small island.", "L'éléphant nain de Sicile, une version minuscule de l'un des plus grands animaux terrestres actuels. Ainsi va la vie sur une petite île.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desmatosuchus", "Desmatosuchus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though not blessed with sharp teeth or claws, Desmatosuchus tries to make up for it with its thick hide", "Dépourvu de griffes et de crocs acérés, Desmatosuchus tente de compenser avec sa peau épaisse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dilophosaurus", "Dilophosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This little critter cripples prey by spitting its uncharacteristic venom.", "Cette petite créature crache un venin inhabituel pour neutraliser ses proies.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dilophosaurus, a terror of the Early Jurassic period. Losing its ridiculous frill does not hinder its venomous nature.", "Dilophosaurus, la terreur du Jurassique inférieur. La perte de sa ridicule collerette ne l'empêche pas d'être venimeux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimetrodon", "Dimetrodon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimetrodon, a reptilian mammal with an impressive sail. Its sharp teeth are a far bigger concern, however.", "Dimetrodon, un reptile mammalien doté d'une impressionnante voile dorsale. Ses dents acérées sont toutefois bien plus préoccupantes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimorphodon", "Dimorphodon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimorphodon, a mostly unremarkable little critter. Do not startle it, those teeth will leave a mark during its hasty retreat.", "Dimorphodon, une petite créature assez ordinaire. Ne l'effrayez pas : ses dents laisseront une marque lors de sa fuite précipitée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dinosaur Egg", "Œuf de dinosaure", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Dinosaur Egg", "Plus gros œuf de dinosaure", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An egg left behind by some dinosaur. I wonder what will hatch from it?", "Un œuf abandonné par un dinosaure. Je me demande ce qui en sortira.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diplodocus", "Diplodocus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If sheer size alone is not enough to deter predators, then perhaps a mighty tail whip will make them reconsider.", "Si sa taille ne suffit pas à dissuader les prédateurs, un puissant coup de queue les fera peut-être changer d'avis.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dryosaurus", "Dryosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dryosaurus, an adorable creature with a flighty attitude.", "Dryosaurus, une adorable créature au tempérament craintif.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunkleosteus", "Dunkleosteus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ravenous Dunkleosteus, an armored fish from distant past. Its true length has little bearing on its crushing jaws.", "Le vorace Dunkleosteus, un poisson cuirassé venu d'un lointain passé. Sa véritable longueur ne change rien à la puissance de ses mâchoires.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edmontosaurus", "Edmontosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edmontosaurus, a massive creature with very few natural predators. Do not expect to find it alone.", "Edmontosaurus, une créature massive qui a très peu de prédateurs naturels. Ne vous attendez pas à la trouver seule.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elasmosaurus", "Elasmosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elasmosaurus, a prehistoric beast with an incredibly long neck. It can snatch prey far out of the reach of others.", "Elasmosaurus, une bête préhistorique au cou incroyablement long. Elle attrape des proies hors de portée des autres.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eobasileus", "Eobasileus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eobasileus, the largest of its kind. Do not stand in its path if you wish to see the sun rise again.", "Eobasileus, le plus grand de son espèce. Ne lui barrez pas la route si vous souhaitez revoir le soleil se lever.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Euoplocephalus", "Euoplocephalus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The thick hide of this Euoplocephalus and the equally hefty club at the end of its tail protect it from most predators", "La peau épaisse de cet Euoplocephalus et la massue tout aussi lourde au bout de sa queue le protègent de la plupart des prédateurs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gallimimus", "Gallimimus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gallimimus, a bird-like beast that is rather quick on its feet. It is about as friendly as it looks.", "Gallimimus, une bête semblable à un oiseau, plutôt rapide sur ses pattes. Elle est aussi amicale qu'elle en a l'air.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gastornis", "Gastornis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vigilant Gastornis. It watches over its comrades, growing furious if it loses any.", "Le vigilant Gastornis. Il veille sur ses camarades et devient furieux s'il en perd un.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Ground Sloth", "Paresseux terrestre géant", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Giant Ground Sloth, a massive beast far surpassing its modern relatives. It is much less friendly than you would think.", "Le paresseux terrestre géant, une bête massive qui dépasse de loin ses parents modernes. Il est bien moins amical qu'on ne le croirait.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gigantoraptor", "Gigantoraptor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gigantoraptor, a disturbingly large beast. Any attempts to resist will only further provoke it.", "Gigantoraptor, une bête d'une taille inquiétante. Toute tentative de résistance ne fera que l'énerver davantage.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gojirasaurus", "Gojirasaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once the biggest predator to roam the land, Gojirasaurus' reign did not last. It's hard to match the titans that followed it.", "Jadis le plus grand prédateur terrestre, Gojirasaurus ne régna pas longtemps. Difficile de rivaliser avec les titans qui lui ont succédé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guanlong", "Guanlong", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guanlong, a vicious predator emboldened by the thrill of combat. Many more terrible beasts have spawned from its lineage.", "Guanlong, un féroce prédateur enhardi par l'excitation du combat. Bien d'autres terribles bêtes sont issues de sa lignée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hadrosaurus", "Hadrosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vengeful Hadrosaurus. It makes quick work of those who harm members of its herd.", "Le vindicatif Hadrosaurus. Il vient rapidement à bout de ceux qui blessent les membres de son troupeau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haolong", "Haolong", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haolong, a bizarre beast covered in many sharp quills. Very few predators dare to clamp their jaws around its prickly hide.", "Haolong, une étrange bête couverte de piquants acérés. Peu de prédateurs osent mordre sa peau hérissée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herrerasaurus", "Herrerasaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Herrerasaurus hails from the age before dinosaurs took over the world. Being more primitive does not make it any less successful.", "Ce Herrerasaurus vient d'une époque antérieure à la domination des dinosaures. Son caractère plus primitif ne l'empêche pas de réussir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hesperornis", "Hesperornis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hesperornis, a swimming bird with a taste for fish. It has yet to lose its teeth.", "Hesperornis, un oiseau nageur amateur de poisson. Il n'a pas encore perdu ses dents.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homalocephale", "Homalocephale", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an adorable Homalocephale. Alas, a grim fate awaits this poor creature. Will your heart sink when you hear its cries?", "Quel adorable Homalocephale. Hélas, un destin sinistre attend cette pauvre créature. Votre cœur se serrera-t-il en entendant ses cris ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyornis", "Ichthyornis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyornis, a prehistoric bird with sharp teeth. It is no less annoying than its modern counterparts.", "Ichthyornis, un oiseau préhistorique aux dents acérées. Il est tout aussi agaçant que ses cousins modernes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyosaurus", "Ichthyosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift Ichthyosaurus. It can attack submerged foes in the blink of an eye.", "Le rapide Ichthyosaurus. Il peut attaquer des ennemis immergés en un clin d'œil.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iguanodon", "Iguanodon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind your manners before this Iguanodon if you do not wish to feel its clawed thumb pierce you.", "Tenez-vous bien devant cet Iguanodon si vous ne voulez pas sentir son pouce griffu vous transpercer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inostrancevia", "Inostrancevia", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inostrancevia, a surprisingly agile apex predator of its age. The grievous injuries left by the beast's fangs are far less suprising.", "Inostrancevia, un superprédateur étonnamment agile pour son époque. Les graves blessures que laissent ses crocs sont bien moins surprenantes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Irish Elk", "Élan d'Irlande", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic Irish Elk, the biggest of its kind. Its massive horns grant it extended reach.", "Le majestueux élan d'Irlande, le plus grand de son espèce. Ses immenses bois lui offrent une plus grande portée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Irritator", "Irritator", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The patient Irritator. Though it primarily feeds on fish, its claws are perfectly suited for tearing into other beasts.", "Le patient Irritator. Bien qu'il se nourrisse surtout de poissons, ses griffes sont parfaites pour déchirer d'autres bêtes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Isisaurus", "Isisaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Isisaurus leads a herd of its own. Though they do not belong to its kind, those beasts trust this experienced titan.", "Cet Isisaurus mène son propre troupeau. Même si ces bêtes ne sont pas de son espèce, elles font confiance à ce titan expérimenté.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jeholopterus", "Jeholopterus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jeholopterus, nothing more than a bug-eating critter. Don't expect much else out of it.", "Jeholopterus, rien de plus qu'une petite créature insectivore. N'en attendez pas davantage.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Katifelis", "Katifelis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Katifelis, an unremarkable feline. It does not respond well to approaching strangers.", "Katifelis, un félin ordinaire. Il réagit mal à l'approche des inconnus.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kentrosaurus", "Kentrosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kentrosaurus, a herbivore with a threatening appearance. Said appearance is far from deceiving, however.", "Kentrosaurus, un herbivore à l'apparence menaçante. Et cette apparence n'est pas trompeuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Koolasuchus", "Koolasuchus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Koolasuchus, a dreadfull creature lurking in the water. It does not pass up any opportunity to feast.", "Koolasuchus, une terrible créature qui guette dans l'eau. Elle ne manque aucune occasion de festoyer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lambeosaurus", "Lambeosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The solitary Lambeosaurus. It strikes its foes multiple times when disturbed.", "Le solitaire Lambeosaurus. Il frappe plusieurs fois ses ennemis lorsqu'on le dérange.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Liopleurodon", "Liopleurodon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While much smaller than some may believe, Liopleurodon is still a vicious predator, always ready to tear its prey apart.", "Bien plus petit que certains ne le croient, Liopleurodon reste un féroce prédateur, toujours prêt à déchirer ses proies.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majungasaurus", "Majungasaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voracious Majungasaurus. It will not hesitate to devour its own comrades to sate its hunger.", "Le vorace Majungasaurus. Il n'hésitera pas à dévorer ses propres camarades pour apaiser sa faim.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masiakasaurus", "Masiakasaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masiakasaurus, a bizarre dinosaur of unimpressive size. It does not stay in battle for long.", "Masiakasaurus, un étrange dinosaure de taille modeste. Il ne reste pas longtemps au combat.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mawsonia", "Mawsonia", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mawsonia, an enormous fish drifting in search of prey. Pray you do not bump into one while swimming.", "Mawsonia, un poisson énorme qui dérive en quête de proies. Priez pour ne pas en croiser un en nageant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalania", "Megalania", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The monstrous Megalania. A single bite from this oversized reptile is enough to cripple most beasts.", "La monstrueuse Megalania. Une seule morsure de ce reptile géant suffit à neutraliser la plupart des bêtes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Metriacanthosaurus", "Metriacanthosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Metriacanthosaurus mercilessly tears into its prey, unwilling to let any meal get away from its jaws.", "Ce Metriacanthosaurus déchire ses proies sans pitié, refusant de laisser échapper le moindre repas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Microceratus", "Microceratus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlike its bigger relatives, Microceratus stands on two legs and lacks any meaningful protection against predators. The best it can do is draw attention of something bigger.", "Contrairement à ses grands parents, Microceratus marche sur deux pattes et n'a aucune protection efficace contre les prédateurs. Il peut au mieux attirer l'attention d'un être plus grand.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minmi", "Minmi", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Minmi may seem adorable, but it is far from defenseless. In fact, defense might be all it has.", "Ce Minmi a l'air adorable, mais il est loin d'être sans défense. En fait, se défendre est peut-être tout ce qu'il sait faire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muttaburrasaurus", "Muttaburrasaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The persistent Muttaburrasaurus. It does not fall in battle while its herd is still in danger.", "Le persévérant Muttaburrasaurus. Il ne tombe pas au combat tant que son troupeau est en danger.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nanotyrannus", "Nanotyrannus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Living in the shadow of the King does not make this beast any less formidable.", "Vivre dans l'ombre du Roi ne rend pas cette bête moins redoutable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nigersaurus", "Nigersaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nigersaurus, a beast with countless teeth. It loses many while feeding, but they regrow just as quickly.", "Nigersaurus, une bête aux innombrables dents. Elle en perd beaucoup en mangeant, mais elles repoussent tout aussi vite.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothosaurus", "Nothosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though this Nothosaurus is clumsy on land, it is an adept swimmer with a mouth full of sharp teeth.", "Ce Nothosaurus est maladroit sur terre, mais nage habilement et possède une bouche pleine de dents acérées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Olorotitan", "Olorotitan", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Olorotitan is more concerned about helping its allies than itself. Such altruism.", "Cet Olorotitan se soucie davantage d'aider ses alliés que de lui-même. Quel altruisme.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Othnielia", "Othnielia", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Othnielia, hardly more than a snack for more ferocious beasts.", "Othnielia, à peine plus qu'un en-cas pour les bêtes les plus féroces.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ouranosaurus", "Ouranosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though it is not an outstanding fighter, this Ouranosaurus encourages its comrades to fight with greater strength.", "Ce Ouranosaurus n'est pas un combattant exceptionnel, mais il encourage ses camarades à lutter avec plus de force.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oviraptor", "Oviraptor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once thought to be a mere egg thief, this feathered fiend takes great care of its young.", "Autrefois considéré comme un simple voleur d'œufs, ce diable à plumes prend grand soin de ses petits.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pachycephalosaurus", "Pachycephalosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stubborn Pachycephalosaurus. It will attack anything that intrudes upon its territory regardless of size.", "L'obstiné Pachycephalosaurus. Il attaque tout ce qui envahit son territoire, quelle qu'en soit la taille.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pachyrhinosaurus", "Pachyrhinosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The nomadic Pachyrhinosaurus. It lost many brothers during its travels. It cannot bear to lose more.", "Le nomade Pachyrhinosaurus. Il a perdu bien des frères au cours de ses voyages et ne supporterait pas d'en perdre davantage.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus", "Parasaurolophus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peaceful Parasaurolophus. Its peculiar crest allows it to call upon its allies when in trouble.", "Le paisible Parasaurolophus. Son étrange crête lui permet d'appeler ses alliés à l'aide.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus Hatchling", "Jeune Parasaurolophus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A meek Parasaurolophus hatchling. It has yet to develop a prominent crest to match its parents.", "Un jeune Parasaurolophus docile. Il n'a pas encore développé la crête remarquable de ses parents.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patagopelta", "Patagopelta", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While far from the biggest armored dinosaur, Patagopelta is still perfectly capable of enduring blows.", "Loin d'être le plus grand dinosaure cuirassé, Patagopelta est néanmoins parfaitement capable d'encaisser des coups.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus", "Plateosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus, one of the first titans to roam the land. Though its descendants have far surpassed its size, it is by no means small.", "Plateosaurus, l'un des premiers titans à parcourir la terre. Ses descendants sont devenus bien plus grands, mais il est loin d'être petit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Platybelodon", "Platybelodon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Platybelodon, a beast so bizarre that few would believe it existed. It can use its unsightly skull to uproot obstacles in your path.", "Platybelodon, une bête si étrange que peu de gens croiraient à son existence. Son crâne disgracieux peut déraciner les obstacles sur votre chemin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raptor Plushie", "Peluche Raptor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cute little toy, nothing more.", "Un joli petit jouet, rien de plus.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stuffing", "Rembourrage", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All that's left of a toy.", "Tout ce qui reste d'un jouet.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Postosuchus", "Postosuchus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Postosuchus, a bipedal crocodilian. Its bite is no less devastating than that of its modern relatives.", "Postosuchus, un crocodilien bipède. Sa morsure n'est pas moins dévastatrice que celle de ses parents modernes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Proceratosaurus", "Proceratosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The deceptive Proceratosaurus. It makes up for its lacking offense with whatever wit you may attribute to a beast.", "Le trompeur Proceratosaurus. Il compense son faible pouvoir offensif par toute la ruse qu'on peut attribuer à une bête.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Procompsognathus", "Procompsognathus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Procompsognathus, a tiny terror with a surprisingly potent venom. It's particularly fond of feasting on greedy old men.", "Procompsognathus, une minuscule terreur au venin étonnamment puissant. Il aime tout particulièrement se régaler de vieux hommes cupides.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prongdeer", "Cerf à cornes fourchues", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prongdeer, a relatively small horned creature with an ill-fitting pair of fangs. They are not just for show, however.", "Le cerf à cornes fourchues, une créature cornue assez petite dotée de crocs qui semblent déplacés. Ils ne sont pourtant pas décoratifs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protoceratops", "Protoceratops", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Protoceratops may not seem like a threat, but the ferocity it displays when desperate is a sight to behold.", "Ce Protoceratops ne semble pas menaçant, mais sa férocité lorsqu'il est désespéré vaut le détour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protosphyraena", "Protosphyraena", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protosphyraena, a lightning-fast predator that cleaves its prey in half with its extended snout.", "Protosphyraena, un prédateur rapide comme l'éclair qui coupe ses proies en deux avec son long museau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psittacosaurus", "Psittacosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The timid Psittacosaurus. Many beasts form bonds with this adorable creature. Few wish to see it hurt.", "Le timide Psittacosaurus. Beaucoup de bêtes se lient à cette adorable créature et peu souhaitent la voir blessée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pteranodon", "Ptéranodon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pteranodon, an iconic flying reptile. It may not have teeth to maul you with, but that beak spells trouble.", "Ptéranodon, un reptile volant emblématique. Il n'a peut-être pas de dents pour vous déchirer, mais son bec est redoutable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodaustro", "Pterodaustro", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...No, I did not fabricate this creature. Even the most bizarre forms can serve their own purposes.", "...Non, je n'ai pas inventé cette créature. Même les formes les plus étranges peuvent avoir leur utilité.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Qianzhousaurus", "Qianzhousaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ambitious Qianzhousaurus. Though yet to reach the true King's might, it has potential for growth.", "L'ambitieux Qianzhousaurus. Il n'égale pas encore la puissance du véritable Roi, mais il a le potentiel de grandir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quercylurus", "Quercylurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quercylurus, a massive beast resembling saber-toothed cats. It gnaws on the many bones of its numerous victims.", "Quercylurus, une énorme bête ressemblant aux félins à dents de sabre. Elle ronge les nombreux os de ses innombrables victimes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhamphorhynchus", "Rhamphorhynchus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhamphorhynchus, a tiny flying reptile with a mouth full of sharp teeth. Though it prefers fish, it can and will bite your fingers.", "Rhamphorhynchus, un minuscule reptile volant à la bouche pleine de dents acérées. Il préfère le poisson, mais peut vous mordre les doigts et ne s'en privera pas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacabambaspis", "Sacabambaspis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The jawless Sacabambaspis, an adorable little fish with an armored hide.", "Le Sacabambaspis sans mâchoire, un adorable petit poisson à la peau cuirassée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sansanosmilus", "Sansanosmilus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sansanosmilus, a cat-like predator with a particularly wounding bite. Smaller size does not make it any less dangerous.", "Sansanosmilus, un prédateur félin dont la morsure inflige de graves blessures. Sa petite taille ne le rend pas moins dangereux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcoprion", "Sarcoprion", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcoprion, a monstrous shark with a bizarre set of jaws. It uses them to cut its prey in half.", "Sarcoprion, un requin monstrueux aux mâchoires étranges. Il s'en sert pour couper ses proies en deux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Segisaurus", "Segisaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Segisaurus, hardly more than a pest. It comes in great numbers, however.", "Segisaurus, guère plus qu'une nuisance. Ils sont toutefois très nombreux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shringasaurus", "Shringasaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shringasaurus, a horned reptile from the distant past. It shoves its attackers back in retaliation.", "Shringasaurus, un reptile cornu venu d'un lointain passé. Il repousse ses agresseurs en guise de riposte.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shunosaurus", "Shunosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shunosaurus, a long-necked creature with a club at the end of its tail. It can land debilitating strikes upon its enemies.", "Shunosaurus, une créature au long cou et à la queue terminée par une massue. Il peut infliger des coups affaiblissants à ses ennemis.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simosuchus", "Simosuchus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simosuchus, an adorable and completely harmless crocodilian. It protects itself with its thick scales.", "Simosuchus, un crocodilien adorable et totalement inoffensif. Ses épaisses écailles le protègent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sinosauropteryx", "Sinosauropteryx", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sneaky Sinosauropteryx, a feathered reptilian pest resembling a racoon in more than appearance.", "Le sournois Sinosauropteryx, une petite nuisance reptilienne à plumes qui ne ressemble pas au raton laveur que par son apparence.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stegosaurus", "Stegosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This territorial Stegosaurus is not willing to share room with anyone, friend or foe.", "Ce Stegosaurus territorial refuse de partager son espace avec qui que ce soit, ami ou ennemi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stokesosaurus", "Stokesosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stokesosaurus, an unassuming predator. Perhaps it is more intelligent than it appears at a glance.", "Stokesosaurus, un prédateur discret. Il est peut-être plus intelligent qu'il n'y paraît au premier regard.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stygimoloch", "Stygimoloch", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stygimoloch, a stubborn beast with an unpleasant attitude. It won't go down without a fight.", "Stygimoloch, une bête obstinée au mauvais caractère. Elle ne tombera pas sans se battre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Styracosaurus", "Styracosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tenacious Styracosaurus. It's not content with simply fending off its attackers.", "Le tenace Styracosaurus. Il ne se contente pas de repousser ses assaillants.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suchomimus", "Suchomimus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suchomimus, a beats with a narrow snout that primarily hunts fish. It is no stranger to hunting prey on land, however.", "Suchomimus, une bête au museau étroit qui chasse surtout le poisson. Elle sait toutefois aussi chasser sur terre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Supersaurus", "Supersaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The altruistic Supersaurus. It is determined to use what's left of its essence to support its comrades.", "L'altruiste Supersaurus. Il est résolu à utiliser ce qui reste de son essence pour soutenir ses camarades.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tapejara", "Tapejara", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The illustrious Tapejara. It calls upon its kin to aid it in battle.", "L'illustre Tapejara. Il appelle ses semblables à l'aider au combat.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiktaalik", "Tiktaalik", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiktaalik, the great progenitor. You may thank it for your ability to live on land.", "Tiktaalik, le grand ancêtre. Vous pouvez le remercier de votre capacité à vivre sur terre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanis", "Titanis", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanis, an oversized carnivorous bird with a foul temper. Don't expect to outrun this beast.", "Titanis, un énorme oiseau carnivore au sale caractère. N'espérez pas courir plus vite que cette bête.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torosaurus", "Torosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This elderly beast can hardly muster the will to retaliate. I advise against testing its patience, however.", "Cette vieille bête trouve à peine la volonté de riposter. Je vous déconseille toutefois de mettre sa patience à l'épreuve.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triceratops", "Triceratops", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Many have tried to best this lone Triceratops. Few could walk away.", "Beaucoup ont tenté de vaincre ce Triceratops solitaire. Peu ont pu repartir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triceratops Hatchling", "Jeune Triceratops", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A playful Triceratops hatchling. Cherish these moments before it turns into a fierce behemoth.", "Un jeune Triceratops joueur. Chérissez ces moments avant qu'il ne devienne un féroce géant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Troodon", "Troodon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New life shall spring from those unfortunate to feel its venomous bite.", "Une nouvelle vie jaillira de ceux qui auront le malheur de subir sa morsure venimeuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyrannosaurus Hatchling", "Jeune Tyrannosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The innocent Tyrannosaurus hatchling. When the time comes, the throne will belong to this little creature.", "L'innocent jeune Tyrannosaurus. Le moment venu, le trône appartiendra à cette petite créature.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utahraptor", "Utahraptor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utahraptor, an unpleasantly large beast for its kind. It can disembowel you in seconds.", "Utahraptor, une bête désagréablement grande pour son espèce. Elle peut vous éventrer en quelques secondes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utatsusaurus", "Utatsusaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The nimble Utatsusaurus. It has little trouble passing over obstacles.", "L'agile Utatsusaurus. Il franchit les obstacles sans grande difficulté.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velociraptor", "Velociraptor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift Velociraptor, a tiny menace of the desert. Were you expecting something bigger?", "Le rapide Velociraptor, une minuscule menace du désert. Vous attendiez-vous à quelque chose de plus grand ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Rhinoceros", "Rhinocéros laineux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Rhinoceros, a particularly hairy beast with eyesight that does not help its temper. Its long horn can pierce multiple foes.", "Le rhinocéros laineux, une bête très velue dont la mauvaise vue n'arrange pas le caractère. Sa longue corne peut transpercer plusieurs ennemis.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xiphactinus", "Xiphactinus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xiphactinus, a monstrous fish with endless appetite. A single bite is not enough to sate it.", "Xiphactinus, un poisson monstrueux à l'appétit insatiable. Une seule bouchée ne suffit pas à le rassasier.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yutyrannus", "Yutyrannus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fiendish Yutyrannus. It tears its prey apart while it's still alive.", "Le diabolique Yutyrannus. Il déchire ses proies alors qu'elles sont encore en vie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zhenyuanopterus", "Zhenyuanopterus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zhenyuanopterus, a flying pest with a mouth full of needle-like teeth. It accompanies larger beasts into battle.", "Zhenyuanopterus, une nuisance volante à la bouche pleine de dents fines comme des aiguilles. Il accompagne les grandes bêtes au combat.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards", "Cartes Sauria", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards consisting of a random assortment of prehistoric animals, mostly reptiles.", "Une collection d'environ [count] cartes comprenant un assortiment aléatoire d'animaux préhistoriques, surtout des reptiles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A set of [summary] exclusively featuring a random assortment of prehistoric animals, mostly reptiles.", "Un ensemble de [summary] composé exclusivement d'un assortiment aléatoire d'animaux préhistoriques, surtout des reptiles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fisher", "Pêcheur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "Lorsqu'une carte ornée de cet emblème est placée, un Ceratodus est créé dans votre main. [define:Sauria_Ceratodus]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A successful hunt for fish.", "Une pêche fructueuse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fisher Strike", "Frappe du pêcheur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "Lorsqu'une carte ornée de cet emblème tue une autre créature, un Ceratodus est créé dans votre main. [define:Sauria_Ceratodus]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears the beast caught something.", "La bête semble avoir attrapé quelque chose.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Promise of such a feast is too enticing for them to ignore.", "La promesse d'un tel festin est trop alléchante pour être ignorée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mysterious power infuses your beast.", "Un pouvoir mystérieux imprègne votre bête.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something is off...", "Quelque chose cloche...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like it left something precious.", "Il semble avoir laissé quelque chose de précieux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marine Shuffle", "Mélange marin", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a free Ceratodus is shuffled into your side deck. [define:Sauria_Ceratodus]", "Lorsqu'une carte ornée de cet emblème tue une autre créature, un Ceratodus gratuit est mélangé à votre deck secondaire. [define:Sauria_Ceratodus]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A surprise awaits you.", "Une surprise vous attend.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like it lost some teeth while grazing. They are yours to keep.", "Il semble avoir perdu quelques dents en broutant. Vous pouvez les garder.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not alone anymore.", "Il n'est plus seul.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nourishment", "Nourriture", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small sacrifice for small growth.", "Un petit sacrifice pour une petite croissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an abhorent creature, crafted by the hands of madmen...", "Quelle créature abjecte, façonnée par des mains de fous...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parting Fish", "Poisson d'adieu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil dies or is sacrificed, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "Lorsqu'une carte ornée de cet emblème meurt ou est sacrifiée, un Ceratodus est créé dans votre main. [define:Sauria_Ceratodus]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many questions to ask.", "Tant de questions à poser.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another beast rises from its ashes.", "Une autre bête renaît de ses cendres.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fatal mistake.", "Une erreur fatale.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can you feel the ground beneath your feet rumble?", "Sentez-vous la terre trembler sous vos pieds ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will be dragged to the depths.", "Tout sera entraîné dans les profondeurs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not satisfied with its stolen goods just yet.", "Il n'est pas encore satisfait de son butin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Being in the presence of that animal is making it feel like a monster.", "La présence de cet animal lui donne l'impression d'être un monstre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking up the arts? Interesting.", "Vous vous mettez aux arts ? Intéressant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such is the might of a titan.", "Telle est la puissance d'un titan.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king has no need for restraint. More sacrifices must be made.", "Le roi n'a pas besoin de retenue. Il faut davantage de sacrifices.", Language.French);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ancient Iguanodon", "Iguanodon ancien", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of an old belief and proof of science's perpetual march, this beast has much to learn.", "Vestige d'une ancienne croyance et preuve de la marche perpétuelle de la science, cette bête a encore beaucoup à apprendre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankylodocus", "Ankylodocus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Far less abominable than most of its artificial kin, Ankylodocus can almost be called a gentle giant.", "Bien moins abominable que la plupart de ses semblables artificiels, Ankylodocus mérite presque le nom de gentil géant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anzu", "Anzu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anzu, the vicious beast that brings thunder. Do not invite its wrath upon yourself.", "Anzu, la bête féroce qui apporte le tonnerre. N'attirez pas sa colère sur vous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archelon", "Archelon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wise Archelon. It fortifies its allies upon entering the battle.", "Le sage Archelon. Il fortifie ses alliés en entrant au combat.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilosaurus", "Basilosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilosaurus, the King Lizard. While not even remotely related to reptiles, it certainly earns the title of royalty.", "Basilosaurus, le roi lézard. Bien qu'il n'ait aucun lien de parenté avec les reptiles, il mérite assurément son titre royal.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beautiful Feather", "Belle plume", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dazzling.", "Éblouissant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "Brontosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus, the so-called thunderbringer. Its name may not be entirely unearned.", "Brontosaurus, celui que l'on dit porteur de tonnerre. Il n'a peut-être pas volé son nom.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carchadontosaurus", "Carcharodontosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloodthirsty Carcharodontosaurus. The smell of blood drives it into a frenzy.", "Le sanguinaire Carcharodontosaurus. L'odeur du sang le rend frénétique.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cave Bear", "Ours des cavernes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The reclusive Cave Bear. Though it may not be a vicious predator, it gives shelter to a fair share of beasts craving flesh.", "L'ours des cavernes reclus. Ce n'est peut-être pas un féroce prédateur, mais il abrite bon nombre de bêtes avides de chair.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compstegnathus", "Compstegnathus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compstegnathus, a deformed beast bred for nefarious deeds. I do not enjoy looking at it.", "Compstegnathus, une bête difforme élevée à des fins maléfiques. Je n'aime pas la regarder.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cryolophosaurus", "Cryolophosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This crested beast brings the unforgiving cold of winter with it. When it enters battle, you may find some poor creatures trapped in ice as a result.", "Cette bête à crête apporte avec elle le froid impitoyable de l'hiver. À son entrée au combat, de pauvres créatures peuvent se retrouver prises dans la glace.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an unsightly beast, truly an eyesore. Who could have spawned it?", "Quelle bête disgracieuse, une véritable horreur. Qui a pu l'engendrer ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus Hatchling", "Jeune Deinosuchus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A helpless Deinosuchus hatchling. It has yet to grow into a fearsome apex predator.", "Un jeune Deinosuchus sans défense. Il doit encore devenir un superprédateur redoutable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish Meat", "Chair de poisson", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juicy Fish Meat", "Chair de poisson juteuse", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giganotosaurus", "Giganotosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrifying Giganotosaurus. Though it normally hunts alone, big enough prey may attract more of its kind.", "Le terrifiant Giganotosaurus. Bien qu'il chasse normalement seul, une proie assez grande peut attirer ses semblables.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Godzilla", "Godzilla", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The legendary King of the Monsters. It will take more than claws and fangs to take it down.", "Le légendaire Roi des monstres. Il faudra plus que des griffes et des crocs pour l'abattre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Godzillasaurus", "Godzillasaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a relatively peaceful beast, Godzillasaurus would go down in history as the King of the Monsters.", "Jadis une bête relativement paisible, Godzillasaurus entrera dans l'histoire sous le nom de Roi des monstres.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gwangi", "Gwangi", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voracious Gwangi, a relic of the past. Do not attribute malice to this poor creature, it merely wishes to live.", "Le vorace Gwangi, vestige du passé. Ne prêtez pas de malveillance à cette pauvre créature : elle souhaite simplement vivre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homotherium", "Homotherium", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homotherium, a vicious pack hunter. It will endlessly pursue its prey to nourish its kin.", "Homotherium, un féroce chasseur en meute. Il poursuit sa proie sans relâche pour nourrir les siens.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hypsilophodon", "Hypsilophodon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Hypsilophodon should be little more than prey for most beast... However...", "Cet Hypsilophodon ne devrait être guère plus qu'une proie pour la plupart des bêtes... Et pourtant...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyotitan", "Ichthyotitan", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyotitan, an awe-inspiring aquatic titan. Its sheer size alone dictates the flow of tides.", "Ichthyotitan, un titan aquatique impressionnant. Sa seule taille impose le mouvement des marées.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indominus", "Indominus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such is the power of science...", "Telle est la puissance de la science...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaellynasaura", "Leaellynasaura", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mysterious Leaellynasaura. Other beasts seem to undergo drastic changes in its presence.", "Le mystérieux Leaellynasaura. Les autres bêtes semblent subir de profonds changements en sa présence.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leedsichthys", "Leedsichthys", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gigantic Leedsichthys, one of the biggest fish to ever inhabit the oceans. However, it is hardly one of the most dangerous.", "Le gigantesque Leedsichthys, l'un des plus grands poissons à avoir peuplé les océans. Il est pourtant loin d'être l'un des plus dangereux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maiasaura", "Maiasaura", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maiasaura, the 'Good Mother Lizard'. It will not let harm befall the little ones as long as it breathes.", "Maiasaura, la « bonne mère lézard ». Tant qu'elle respirera, elle ne laissera rien arriver aux petits.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalodon", "Mégalodon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The titanic Megalodon, an apex predator plagued by insatiable hunger. Make sure it always has prey to feast on.", "Le titanesque Mégalodon, un superprédateur tourmenté par une faim insatiable. Veillez à ce qu'il ait toujours une proie à dévorer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalosaurus", "Megalosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalosaurus, one of the first to be discovered. Though its own fame did not last, it paves the path for others to attain it.", "Megalosaurus, l'un des premiers à avoir été découverts. Sa propre célébrité n'a pas duré, mais il ouvre la voie aux autres.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Microraptor", "Microraptor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This particularly petty Microraptor resembles ravens in more than its appearance. Do not get on its bad side.", "Ce Microraptor particulièrement mesquin ressemble aux corbeaux par plus que son apparence. Ne l'énervez pas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mosasaurus", "Mosasaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This aquatic behemoth is no less vicious than any land-dwelling titan of its time.", "Ce géant aquatique est aussi féroce que n'importe quel titan terrestre de son époque.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Mysterious Egg", "Plus gros œuf mystérieux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something about this egg doesn't seem right...", "Quelque chose ne semble pas normal avec cet œuf...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noasaurus", "Noasaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valley of the Dinosaurs is in danger... Alas, few heed its words.", "La vallée des dinosaures est en danger... Hélas, rares sont ceux qui l'écoutent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ornithomimus", "Ornithomimus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vain Ornithomimus, a feast for the eyes. When threatened, it flees and leaves behind colorful feathers for predators to marvel at.", "Le vaniteux Ornithomimus, un régal pour les yeux. Menacé, il s'enfuit en laissant derrière lui des plumes colorées pour émerveiller les prédateurs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paraceratherium", "Paraceratherium", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paraceratherium, one of the largest mammals to set foot on land. Kindred beasts walk by its side.", "Paraceratherium, l'un des plus grands mammifères à avoir foulé la terre. Des bêtes apparentées marchent à ses côtés.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Philosoraptor", "Philosoraptor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pensive Philosoraptor, always asking the questions none dare to voice aloud.", "Le pensif Philosoraptor pose toujours les questions que personne n'ose formuler à voix haute.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyroraptor", "Pyroraptor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Like a bird of legend, Pyroraptor rose from the ashes to greet the world. Perhaps it could use a bit more fire?", "Tel un oiseau de légende, Pyroraptor s'est élevé des cendres pour saluer le monde. Peut-être lui faudrait-il un peu plus de feu ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quetzalcoatlus", "Quetzalcoatlus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrible Quetzalcoatlus, an alarmingly massive ruler of skies with an appetite to match.", "Le terrible Quetzalcoatlus, un souverain des cieux d'une taille alarmante et à l'appétit tout aussi grand.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Real Parasaurolophus", "Véritable Parasaurolophus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Definitely Real Parasaurolophus", "Parasaurolophus absolument véritable", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus, a dragon with a bizarre appearance. It produces flames by igniting the fuel stored in its crest via flint-like teeth.", "Parasaurolophus, un dragon à l'apparence étrange. Il produit des flammes en enflammant le carburant de sa crête avec des dents semblables à du silex.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhedosaurus", "Rhedosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Rhedosaurus from a distant world. The plague it carries in its blood is much too alien for most creatures to bear.", "Un Rhedosaurus venu d'un monde lointain. La peste dans son sang est bien trop étrangère pour que la plupart des créatures y résistent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shantungosaurus", "Shantungosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shantungosaurus, absurdly massive for something that can stand on its rear legs. Their herds are as awe-inspiring as they are terrifying.", "Shantungosaurus, absurdement massif pour un animal capable de se tenir sur ses pattes arrière. Ses troupeaux sont aussi impressionnants que terrifiants.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spicomellus", "Spicomellus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spicomellus, a beast covered in numerous spikes. It does not look pleasant to touch and it is even less pleasant to strike.", "Spicomellus, une bête couverte d'innombrables piquants. Le toucher ne semble pas agréable, et le frapper encore moins.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinoraptor", "Spinoraptor", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abomination born of science, Spinoraptor is an adept fisher and hunter.", "Abomination née de la science, Spinoraptor est un habile pêcheur et chasseur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinosaurus", "Spinosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bizarre reptile of monstrous size, few marine animals can evade its narrow jaws.", "Un étrange reptile de taille monstrueuse. Peu d'animaux marins peuvent échapper à ses mâchoires étroites.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The monstrous Spinosaurus, the only being worthy of challenging the King.", "Le monstrueux Spinosaurus, le seul être digne de défier le Roi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanatosdrakon", "Thanatosdrakon", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanatosdrakon, a beast that has breached the boundary between life and death... Hm... Perhaps this creature has been blessed by...", "Thanatosdrakon, une bête qui a franchi la frontière entre la vie et la mort... Hum... Peut-être cette créature a-t-elle reçu la bénédiction de...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Al", "Le grand Al", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Al, a female Allosaurus that has suffered greatly during its short life. Perhaps you can help this poor creature?", "Le grand Al, une femelle Allosaurus qui a beaucoup souffert durant sa courte vie. Peut-être pouvez-vous aider cette pauvre créature ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Wars", "Guerre des os", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They fought to protect their pride, sparing no expense. In the end, what were they left with?", "Ils se sont battus pour défendre leur fierté, sans regarder à la dépense. Au bout du compte, que leur restait-il ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Therizinosaurus", "Therizinosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Therizinosaurus can hardly see these days. However, you do not want to approach a half-blind giant with claws of such length.", "Ce Therizinosaurus ne voit presque plus de nos jours. Mieux vaut pourtant ne pas approcher un géant à moitié aveugle aux griffes si longues.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanosaurus", "Titanosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life was not meant to reach such sizes on land. This titan bears more resemblance to a force of nature than a beast.", "La vie terrestre n'était pas censée atteindre une telle taille. Ce titan ressemble davantage à une force de la nature qu'à une bête.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tupandactylus", "Tupandactylus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic Tupandactylus. Many flying creatures find themselves drawn to its exceptional crest.", "Le majestueux Tupandactylus. Nombre de créatures volantes sont attirées par sa crête exceptionnelle.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyrannosaurus", "Tyrannosaurus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infamous Tyrant Lizard King. Do you have the courage to oppose the largest land predator the world has ever seen?", "Le tristement célèbre roi des lézards tyrans. Aurez-vous le courage d'affronter le plus grand prédateur terrestre que le monde ait jamais connu ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feathered Tyrannosaurus", "Tyrannosaurus à plumes", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This whole...feather thing is getting out of hand. Have you considered that not every dinosaur was covered in them?", "Cette histoire de... plumes devient incontrôlable. Avez-vous envisagé que tous les dinosaures n'en étaient pas couverts ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velocipastor", "Vélocipasteur", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I... uh... I'm afraid there's little I can say to explain this. It was worth the time.", "Je... euh... Je crains de ne pas pouvoir vraiment expliquer cela. Ça valait le temps passé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Mammoth", "Mammouth laineux", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Mammoth, an iconic beast of the Ice Age. They are never alone.", "Le mammouth laineux, une bête emblématique de l'âge de glace. Ils ne sont jamais seuls.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many bones to claim...", "Tant d'os à réclamer...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus Juvenile", "Deinosuchus juvénile", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A juvenile Deinosuchus. It is still growing, but it is already a fearsome predator.", "Un Deinosuchus juvénile. Il grandit encore, mais c'est déjà un prédateur redoutable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus", "Deinosuchus", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus, a fearsome apex predator. Not even prehistoric giants could escape from its jaws.", "Deinosuchus, un superprédateur redoutable. Même les géants préhistoriques ne pouvaient échapper à ses mâchoires.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater defense is more than sufficient.", "Une défense accrue est plus que suffisante.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not satisfied yet...", "Il n'est pas encore satisfait...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astonishing recovery.", "Un rétablissement stupéfiant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beast is offering comrades to assist you in this battle.", "La bête vous offre des camarades pour vous aider dans ce combat.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is getting out of hand.", "La situation devient incontrôlable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is strength in numbers.", "L'union fait la force.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something wicked lurks in these waters.", "Quelque chose de maléfique rôde dans ces eaux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are more of them now? End this before it gets any worse.", "Ils sont encore plus nombreux ? Mettez-y fin avant que cela ne s'aggrave.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a voracious little beast.", "Quelle petite bête vorace.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still has room for growth.", "Il peut encore grandir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What did you do to that beast?", "Qu'avez-vous fait à cette bête ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's... It's Godzilla!!!", "C'est... C'est Godzilla !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's done being a victim.", "Il refuse désormais d'être une victime.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A feast for its kin.", "Un festin pour les siens.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still clings to its glory, unwilling to be surpassed.", "Il s'accroche encore à sa gloire et refuse d'être surpassé.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Blood)", "Cartes Sauria (sang)", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Blood. Features a random assortment of prehistoric animals, mostly reptiles.", "Une collection d'environ [count] cartes coûtant du sang. Elle présente un assortiment aléatoire d'animaux préhistoriques, surtout des reptiles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Bones)", "Cartes Sauria (os)", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Bones. Features a random assortment of prehistoric animals, mostly reptiles.", "Une collection d'environ [count] cartes coûtant des os. Elle présente un assortiment aléatoire d'animaux préhistoriques, surtout des reptiles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Mixed)", "Cartes Sauria (mixte)", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Blood and Bones. Features a random assortment of prehistoric animals, mostly reptiles.", "Une collection d'environ [count] cartes coûtant du sang et des os. Elle présente un assortiment aléatoire d'animaux préhistoriques, surtout des reptiles.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ginormous Camarasaurus. Its great size allows it to fling beasts across the battlefield.", "L'énorme Camarasaurus. Sa grande taille lui permet de projeter des bêtes à travers le champ de bataille.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Blood to increase Health of a card bearing this sigil by 1, then remove this sigil.", "Dépensez 1 sang pour augmenter de 1 la santé d'une carte ornée de cet emblème, puis retirez cet emblème.", Language.French);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue, the most reliable among the r... This beast shouldn't be human... Hm...", "Blue, la plus fiable parmi les r... Cette bête ne devrait pas être humaine... Hum...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Hm?[w:0.5]", "[e:Curious]Hum ?[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]You're...[w:0.3][e:Anger] You're not Owen.[w:0.5]", "[e:Curious]Vous êtes...[w:0.3][e:Anger] Vous n'êtes pas Owen.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I could tear you to bits right now[w:0.5].[w:0.5].[w:0.5].[w:0.5]", "[e:Anger]Je pourrais vous mettre en pièces dès maintenant[w:0.5].[w:0.5].[w:0.5].[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But Owen doesn't like it when we do that.[w:0.5]", "[e:Anger]Mais Owen n'aime pas quand nous faisons ça.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Maybe if he", "[e:Quiet]Peut-être que s'il", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Pleased to meet you!", "[e:Laughter]Enchantée !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Take good care of me and everything will be fine.", "[e:Neutral]Prenez bien soin de moi et tout ira bien.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Hey there!", "[e:Neutral]Salut !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can make quick work of 'em.", "[e:Laughter]Je peux m'en débarrasser rapidement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Ready to go!", "[e:Neutral]Prête à partir !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If you want them dead, let me know!", "[e:Laughter]Si vous voulez leur mort, dites-le-moi !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Another task? I can handle it.", "[e:Neutral]Une autre tâche ? Je peux m'en charger.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I've never been in a place like this...[w:0.5]", "[e:Curious]Je n'ai jamais vu un endroit pareil...[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]But hey, if there are no fences here[w:0.5]", "[e:Laughter]Mais si cet endroit n'a pas de clôtures[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Then I don't need to restrain myself.", "[e:Quiet]Alors je n'ai pas besoin de me retenir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I don't get to just kill things often.", "[e:Laughter]Je n'ai pas souvent l'occasion de tuer comme ça.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Roger that!", "[e:Laughter]Bien reçu !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'm excited to tear into prey again.", "[e:Neutral]J'ai hâte de déchiqueter à nouveau des proies.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Got it!", "[e:Neutral]Compris !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Weakness means death.", "[e:Quiet]La faiblesse signifie la mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Consider it done!", "[e:Neutral]C'est comme si c'était fait !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Is this the right choice?", "[e:Curious]Est-ce le bon choix ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]I'll remember this.[c:]", "[e:Anger][c:R]Je m'en souviendrai.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Don't expect to get away with this.", "[e:Quiet]Ne vous attendez pas à vous en tirer comme ça.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]So be it.", "[e:Anger]Qu'il en soit ainsi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Wuh?", "[e:Surprise]Hein ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oooh, what's this?", "[e:Curious]Oh, qu'est-ce que c'est ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]What's going to happen next?", "[e:Curious]Que va-t-il se passer ensuite ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I trust your decisions.", "[e:Laughter]Je fais confiance à vos décisions.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't feel like participating.", "[e:Anger]Je n'ai pas envie de participer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]No.", "[e:Anger]Non.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Think again.", "[e:Anger]Réfléchissez encore.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Can't say I didn't expect this.[w:0.4]", "[e:Anger]Je ne peux pas dire que je ne m'y attendais pas.[w:0.4]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]It's okay, I've done this with the rest of my pack", "[e:Neutral]Ce n'est rien, j'ai déjà fait ça avec les autres membres de ma meute", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]plenty of times, this is nothing", "[e:Neutral]bien des fois, ce n'est rien", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You're dead.", "[e:Anger]Vous êtes mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I did not appreciate that.", "[e:Anger]Je n'ai pas apprécié.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll return the favour.", "[e:Quiet]Je vous rendrai la pareille.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Just a natural part of the hunt.", "[e:Neutral]Une partie naturelle de la chasse.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'll return the favour.", "[e:Neutral]Je vous rendrai la pareille.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Oh, a test?[w:0.5]", "[e:Surprise]Oh, une épreuve ?[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I've always been good at those!", "[e:Laughter]J'ai toujours été douée pour ça !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Is it done?", "[e:Curious]C'est terminé ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Did I do good?", "[e:Laughter]J'ai bien réussi ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]How did it go?", "[e:Neutral]Comment cela s'est-il passé ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Ooooh...[w:0.5]", "[e:Surprise]Oh...[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Don't mind if I do!", "[e:Laughter]Avec plaisir !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I've been looking forward to this.", "[e:Quiet]J'attendais cela avec impatience.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You were simply not good enough.", "[e:Laughter]Vous n'étiez tout simplement pas à la hauteur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Where are the others?[w:0.3].[leshy:I might have made a mistake... Very well.][w:2]", "[e:Anger]Où sont les autres ?[w:0.3].[leshy:J'ai peut-être commis une erreur... Très bien.][w:2]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, hi!", "[e:Laughter]Oh, salut !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Didn't expect to see you again!", "[e:Laughter]Je ne pensais pas vous revoir !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How are you?", "Comment allez-vous ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Huh?", "[e:Surprise]Hein ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'll remember this.", "[e:Anger]Je m'en souviendrai.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Don't get cocky.", "[e:Anger]Ne prenez pas la grosse tête.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Angry]I don't like the way he smells...[w:0.5]", "[e:Angry]Je n'aime pas son odeur...[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's kill him!", "[e:Laughter]Tuons-le !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy...[w:0.5]", "[e:Anger]Ce type...[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Make it hurt this time.", "[e:Neutral]Faites-lui mal cette fois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I hate the noise.", "[e:Anger]Je déteste ce bruit.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Kill him.", "[e:Anger]Tuez-le.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Fish...[w:0.3]?[w:0.5]", "[e:Surprise]Du poisson...[w:0.3]?[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I never really liked that stuff.[w:0.3]", "[e:Neutral]Je n'ai jamais vraiment aimé ça.[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll eat him instead.", "[e:Quiet]Je vais plutôt le manger, lui.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I won't fall for his tricks.", "[e:Anger]Je ne tomberai pas dans ses pièges.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Can't even enjoy eating him...", "[e:Anger]Je ne peux même pas savourer le moment où je le dévore...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We've done this before, let's kill him again!", "[e:Neutral]On l'a déjà fait, tuons-le encore !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Wuh?[w:0.5] He wasn't on our side?[w:0.5]", "[e:Curious]Hein ?[w:0.5] Il n'était pas de notre côté ?[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Then I can kill him?", "[e:Quiet]Alors je peux le tuer ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, the two-faced guy again! Let's beat him up!", "[e:Laughter]Oh, encore ce type à deux visages ! Tabassons-le !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Two birds with one stone!", "[e:Laughter]D'une pierre deux coups !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's get rid of him.", "[e:Neutral]Débarrassons-nous de lui.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oh, this is the end?[w:0.5]", "[e:Curious]Oh, c'est la fin ?[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Well, it's been fun.[w:0.5]", "[e:Neutral]Eh bien, c'était amusant.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We'll see each other again, right?[w:0.5]", "[e:Neutral]Nous nous reverrons, n'est-ce pas ?[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope we get to have a good time later!", "[e:Laughter]J'espère qu'on s'amusera bien plus tard !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]The finale![w:0.5]", "[e:Laughter]Le grand final ![w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This should be fun!", "[e:Neutral]Ça devrait être amusant !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]It sucks having to part ways...[w:0.5]", "[e:Anger]C'est nul de devoir se séparer...[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope to see you again!", "[e:Laughter]J'espère vous revoir !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's end this with a bang!", "[e:Laughter]Finissons en beauté !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I think...[w:0.3]", "[e:Curious]Je crois...[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I think I've seen somebody like this before.[w:0.5]", "[e:Curious]Je crois avoir déjà vu quelqu'un comme ça.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Owen scolded me for snarling at that guy.", "[e:Anger]Owen m'a grondée parce que j'avais grogné contre ce type.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'd rather not deal with those cannons.", "[e:Anger]Je préférerais éviter ces canons.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Not again...", "[e:Anger]Pas encore...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This isn't particularly fun.", "[e:Anger]Ce n'est pas particulièrement amusant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Oh, what's this?[w:0.5]", "[e:Surprise]Oh, qu'est-ce que c'est ?[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, I guess my task is still the same!", "[e:Laughter]Eh bien, je suppose que ma tâche n'a pas changé !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I like when they struggle more.", "[e:Neutral]J'aime quand ils se débattent davantage.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, this one looks fun!", "[e:Laughter]Oh, celui-là a l'air amusant !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's just kill them.", "[e:Neutral]Tuons-les, tout simplement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, another one!", "[e:Laughter]Oh, encore un !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What will it be this time?", "[e:Neutral]Qu'est-ce que ce sera cette fois ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This woman?[w:0.5]", "[e:Surprise]Cette femme ?[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Owen always told me to be more gentle with the elderly.[w:0.4]", "[e:Neutral]Owen me disait toujours d'être plus douce avec les personnes âgées.[w:0.4]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Y'know, don't startle them and all that?[w:0.5]", "[e:Neutral]Vous savez, ne pas les effrayer et tout ça ?[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I didn't listen.", "[e:Quiet]Je ne l'ai pas écouté.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Weakness means death.", "[e:Laughter]La faiblesse signifie la mort.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If she's our enemy, then we should kill her!", "[e:Laughter]Si elle est notre ennemie, il faut la tuer !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]No hesitation!", "[e:Neutral]Aucune hésitation !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I've never liked their smell.[w:0.5]", "[e:Anger]Je n'ai jamais aimé leur odeur.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Reminded me of him.[w:0.3]", "[e:Anger]Ça me rappelait son odeur à lui.[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Now, let's kill them!", "[e:Laughter]Maintenant, tuons-les !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]More faces means more to bite!", "[e:Neutral]Plus de visages, ça fait plus à mordre !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]You think they'll live with one of his faces clawed off?", "[e:Curious]Vous pensez qu'il survivra si je lui arrache un visage à coups de griffes ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I wonder if he'll feel spongy...", "[e:Neutral]Je me demande s'il sera spongieux...", Language.French);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm... Maybe something got mixed up in there...", "Hum... Il y a peut-être eu un mélange là-dedans...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You.[w:0.5]", "Vous.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know who you are.", "Je ne sais pas qui vous êtes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't particularly care either.", "Et ça m'est plutôt égal.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Either you get me out of this mess or[w:0.5].[w:0.5].[w:0.5][e:Laughter].[w:0.5]", "Soit vous me sortez de ce pétrin, soit[w:0.5].[w:0.5].[w:0.5][e:Laughter].[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]No, I [e:Quiet]don't[w:0.5][e:Laughter] need to spell it out.[w:0.5]", "[e:Laughter]Non, je n'ai [e:Quiet]pas[w:0.5][e:Laughter] besoin de préciser.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Know your place and you will live.[c:]", "[e:Quiet][c:R]Restez à votre place et vous vivrez.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Make it quick.", "[e:Neutral]Faites vite.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Morsels, all for me.", "[e:Laughter]Des bouchées, rien que pour moi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]A fine opportunity.", "[e:Neutral]Une belle occasion.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Now is a good time to feed me.", "[e:Laughter]C'est le moment de me nourrir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Good timing. I was feeling quite peckish.", "[e:Laughter]Quel bon timing. Je commençais à avoir faim.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I've been looking for something", "[e:Laughter]Je cherche quelque chose", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]to tear into since I got into this mess.", "[e:Laughter]à déchiqueter depuis que je suis dans ce pétrin.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I won't make it quick.", "[e:Quiet]Je ne ferai pas vite.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I won't leave anything behind.", "[e:Laughter]Je ne laisserai rien derrière moi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]A feast, just for me.", "[e:Laughter]Un festin, rien que pour moi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Don't expect to survive.", "[e:Neutral]Ne comptez pas survivre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Who wishes to die first?", "[e:Quiet]Qui souhaite mourir en premier ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I've been itching for a fight.", "[e:Quiet]Je brûle d'envie de me battre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Are you sure about this choice?", "[e:Curious]Êtes-vous sûr de ce choix ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You traitor!!![c:]", "[e:Anger][c:R]Traître !!![c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll remember this.", "[e:Quiet]Je m'en souviendrai.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You bastard!!![c:]", "[e:Anger][c:R]Espèce de salaud !!![c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise][c:R]You...![c:]", "[e:Surprise][c:R]Vous... ![c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oh, what's this now?", "[e:Curious]Oh, qu'est-ce que c'est encore ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Who will die this time?", "[e:Curious]Qui va mourir cette fois ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]There is only one correct choice.", "[e:Laughter]Il n'y a qu'un seul bon choix.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Do not make any choices I would make you regret.", "[e:Quiet]Ne faites aucun choix que je vous ferais regretter.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's get this done and over with.", "[e:Neutral]Finissons-en.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Pick anyone else.", "[e:Neutral]Choisissez n'importe qui d'autre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You did this on purpose...[w:0.4]", "[e:Anger]Vous l'avez fait exprès...[w:0.4]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]Didn't you!?[c:][w:0.5]", "[c:R]N'est-ce pas !?[c:][w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'll let it slide for now.", "[e:Neutral]Je laisse passer pour cette fois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You dare...![c:]", "[e:Anger][c:R]Vous osez... ![c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]I'll tear you limb from limb!!![c:]", "[e:Anger][c:R]Je vais vous arracher membre par membre !!![c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]You've made your choice.", "[e:Quiet]Vous avez fait votre choix.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Tsk!", "[e:Anger]Tss !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Gh!", "[e:Anger]Grr !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Is this some kind of a test?[w:0.5]", "[e:Surprise]Est-ce une sorte d'épreuve ?[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I don't expect to fail.", "[e:Laughter]Je ne compte pas échouer.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Are we done?", "[e:Curious]Avons-nous fini ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I shall aid you.", "[e:Laughter]Je vous aiderai.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Waste of my time.", "[e:Neutral]Une perte de temps.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Interesting...[w:0.5]", "[e:Curious]Intéressant...[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]There are enough voices screaming from within my blood.", "[e:Neutral]Assez de voix hurlent déjà dans mon sang.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]What's another one?", "[e:Quiet]Qu'est-ce qu'une de plus ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Become a part of me.", "[e:Laughter]Devenez une partie de moi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I shall claim your power.", "[e:Quiet]Je m'emparerai de votre puissance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]It is only natural.", "[e:Laughter]C'est tout naturel.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]What did you do to me!?[c:][w:0.5].[leshy:It appears that this beast is... more human than it appeared. No matter.][w:2]", "[e:Anger][c:R]Que m'avez-vous fait !?[c:][w:0.5].[leshy:Il semble que cette bête soit... plus humaine qu'elle n'en avait l'air. Peu importe.][w:2]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We meet again.", "[e:Laughter]Nous nous retrouvons.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You shall serve me once more.", "[e:Laughter]Vous me servirez à nouveau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do not disappoint me this time.", "Ne me décevez pas cette fois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]No, you can't...!", "[e:Surprise]Non, vous ne pouvez pas... !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Curse you!!!", "[e:Anger]Maudit soyez-vous !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I will remember this!!!", "[e:Anger]Je m'en souviendrai !!!", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What an eyesore...", "[e:Neutral]Quelle horreur...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get rid of him.[w:0.5]", "Débarrassez-vous de lui.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The noise bothers me.", "Ce bruit m'importune.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You...[w:0.5]", "[e:Anger]Vous...[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Do not make the same mistakes.", "[e:Neutral]Ne refaites pas les mêmes erreurs.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This noise again...", "[e:Anger]Encore ce bruit...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Get him out of my sight.", "[e:Anger]Ôtez-le de ma vue.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This...[w:0.5] This smell...[w:0.5]", "[e:Surprise]Cette...[w:0.5] Cette odeur...[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]I remember a smell like this...[w:0.5]", "[e:Surprise]Je me souviens d'une telle odeur...[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]We must get out of here.", "[e:Surprise]Nous devons partir d'ici.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Don't let those things near me!", "[e:Surprise]Ne laissez pas ces choses m'approcher !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]I won't die like this again!", "[e:Surprise]Je ne mourrai pas ainsi une seconde fois !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]There's something lurking in the waters...", "[e:Surprise]Quelque chose rôde dans l'eau...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I have little patience for traitors.[w:0.5]", "[e:Anger]Je n'ai guère de patience pour les traîtres.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Skin him alive.[c:]", "[e:Quiet][c:R]Écorchez-le vif.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]He'll make for a fine pelt.", "[e:Laughter]Il fera une belle fourrure.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]The smell in the air is pleasant.", "[e:Laughter]L'odeur dans l'air est agréable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Let's enrich it further with his blood.[c:]", "[e:Quiet][c:R]Enrichissons-la encore avec son sang.[c:]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You should know how this works by now.", "[e:Laughter]Vous devriez maintenant savoir comment cela fonctionne.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]This is it...[w:0.5]", "[e:Curious]C'est le moment...[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We've made it this far.[w:0.5]", "[e:Neutral]Nous sommes arrivés jusque-là.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose you weren't too bad.[w:0.5]", "Je suppose que vous n'étiez pas si mauvais.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't miss you[w:0.5], but I've seen worse humans.[w:0.5]", "Vous ne me manquerez pas[w:0.5], mais j'ai vu pire comme humain.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Let's put an end to his games.", "[e:Quiet]Mettons fin à ses jeux.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You can do this.[w:0.5]", "[e:Laughter]Vous pouvez y arriver.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Be of service to me once again.", "[e:Laughter]Servez-moi encore une fois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We shall part soon.[w:0.5]", "[e:Laughter]Nous nous séparerons bientôt.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope to see you again.", "[e:Laughter]J'espère vous revoir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]It's been fun so far.[w:0.5]", "[e:Laughter]C'était amusant jusqu'ici.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's have some more fun in the future.", "[e:Laughter]Amusons-nous encore à l'avenir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Not...[w:0.5] Not the water again...[w:0.5]", "[e:Surprise]Pas...[w:0.5] Pas encore l'eau...[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]What will attack me this time?", "[e:Surprise]Qu'est-ce qui va m'attaquer cette fois ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't appreciate getting shot with cannons. Kill him quickly.", "[e:Anger]Je n'apprécie pas qu'on me tire dessus au canon. Tuez-le vite.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This moron again...", "[e:Anger]Encore cet imbécile...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]There isn't even anything to gnaw on.", "[e:Anger]Il n'y a même rien à ronger.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]The air is different.[w:0.5]", "[e:Surprise]L'air est différent.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]They are prey all the same.", "[e:Laughter]Ils restent des proies malgré tout.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What a chore.", "[e:Neutral]Quelle corvée.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Perhaps something bigger to chew on?", "[e:Laughter]Peut-être quelque chose de plus gros à mâcher ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Eyesore.", "[e:Neutral]Une horreur.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]This changes nothing.", "[e:Laughter]Cela ne change rien.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]They should know their place.", "[e:Laughter]Ils devraient connaître leur place.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Hmph.[w:0.5]", "[e:Neutral]Humph.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This foolish hag has outlived her usefulness.[w:0.5]", "[e:Neutral]Cette vieille idiote n'a plus la moindre utilité.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Her skull would be a fine decoration for a totem.", "[e:Quiet]Son crâne ferait une belle décoration pour un totem.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's shave off what few years she has left.", "[e:Laughter]Raccourcissons les quelques années qui lui restent.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]One foot in the grave, another soon to come.", "[e:Laughter]Un pied dans la tombe, l'autre suivra bientôt.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]She'd die in a few years regardless.", "[e:Laughter]Elle mourrait de toute façon dans quelques années.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Not particularly surprising.[w:0.5]", "[e:Neutral]Ce n'est pas particulièrement surprenant.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]These experimental types don't know loyalty.[w:0.5]", "[e:Neutral]Ces spécimens expérimentaux ne connaissent pas la loyauté.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather get my claws on that bastard Wu", "[e:Quiet]Je préférerais mettre mes griffes sur ce salaud de Wu", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]but this shall do for now.", "[e:Laughter]mais ça fera l'affaire pour l'instant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's return the favour.", "[e:Neutral]Rendons-lui la pareille.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]There won't be much left to stitch together.", "[e:Laughter]Il ne restera pas grand-chose à recoudre.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Two heads to tear off.[e:Quiet]What a treat.", "[e:Neutral]Deux têtes à arracher.[e:Quiet]Quel régal.", Language.French);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owen", "Owen", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A human? ...No matter. I have a feeling this man will prove himself capable against claws and fangs of your opponents.", "Un humain ? ...Peu importe. J'ai le sentiment que cet homme saura affronter les griffes et les crocs de vos adversaires.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I don't know what this whole thing is about[w:0.3]", "[e:Curious]Je ne sais pas de quoi il retourne[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]but we'll make it", "[e:Laughter]mais nous allons y arriver", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]trust me.", "[e:Laughter]faites-moi confiance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Stay on guard.", "[e:Anger]Restez sur vos gardes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]So much for taking a break, huh.", "[e:Laughter]Adieu la pause, hein.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You can count on me.", "[e:Laughter]Vous pouvez compter sur moi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Let's hope working at Jurassic World didn't make me rusty...", "[e:Quiet]Espérons que mon travail à Jurassic World ne m'a pas rouillé...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't like doing this, but it's us or them here.", "[e:Anger]Je n'aime pas faire ça, mais c'est eux ou nous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This rifle better not act up on me now...", "[e:Anger]Ce fusil a intérêt à ne pas me lâcher maintenant...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's do this.", "[e:Neutral]Allons-y.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Gotta focus if we both want to keep our skins.", "[e:Quiet]Il faut se concentrer si nous voulons sauver notre peau.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Not sure about this position, but I can make it work.", "[e:Quiet]Cette position ne m'inspire pas, mais je peux m'en sortir.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Now would be a bad time to forget my training.", "[e:Quiet]Ce serait le mauvais moment pour oublier mon entraînement.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Wait, what are you doing!?", "[e:Surprise]Attendez, que faites-vous !?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Huh, why me?", "[e:Surprise]Hein, pourquoi moi ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I haven't told her I-", "[e:Anger]Je ne lui ai pas dit que je...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]What kind of-", "[e:Anger]Quelle sorte de...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Whatever this is, I don't like it.", "[e:Anger]Quoi que ce soit, ça ne me plaît pas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather sit this one out.", "[e:Quiet]Je préférerais passer mon tour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]If I have to...", "[e:Quiet]S'il le faut...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I have a bad feeling about this one.", "[e:Anger]J'ai un mauvais pressentiment.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Could you pick anyone else?", "[e:Quiet]Pourriez-vous choisir quelqu'un d'autre ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather not...", "[e:Quiet]Je préférerais éviter...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Damn...[w:0.3]", "[e:Anger]Mince...[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]The situation is worse than I thought.[w:0.3]", "[e:Anger]La situation est pire que je ne le pensais.[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can still handle this, don't worry.", "[e:Laughter]Je peux encore gérer, ne vous inquiétez pas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Shit!", "[e:Anger]Merde !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This will leave a mark.", "[e:Anger]Ça va laisser une marque.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Sure, I could use another scar.", "[e:Anger]Bien sûr, une cicatrice de plus ne me fera pas de mal.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Ow!", "[e:Anger]Aïe !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Tsk, got careless.", "[e:Anger]Tss, j'ai baissé ma garde.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]A trial?[w:0.3]", "[e:Surprise]Une épreuve ?[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Well, did we pass it?", "[e:Curious]Alors, avons-nous réussi ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]How did we do?", "[e:Curious]Comment nous en sommes-nous sortis ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I have a good feeling about this one.", "[e:Laughter]J'ai un bon pressentiment pour celle-ci.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I didn't just blow it, did I?", "[e:Quiet]Je n'ai pas tout gâché, si ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Me?[w:0.3]", "[e:Surprise]Moi ?[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Well... Sorry, buddy", "[e:Quiet]Eh bien... Désolé, mon pote", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]but it looks like there's no other choice.", "[e:Quiet]mais il ne semble pas y avoir d'autre choix.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I hate doing this.", "[e:Quiet]Je déteste faire ça.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]If we want to survive...", "[e:Quiet]Si nous voulons survivre...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Really wish we could avoid this, but...", "[e:Quiet]J'aimerais vraiment éviter ça, mais...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]What is this place?[w:0.3]", "[e:Curious]Quel est cet endroit ?[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, you look like a reasonable fellow.", "[e:Laughter]Vous avez l'air raisonnable.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If we stick together", "[e:Laughter]Si nous restons ensemble", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]we can escape in one piece", "[e:Laughter]nous pourrons nous en sortir en un seul morceau", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Hello again.", "[e:Laughter]Rebonjour.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Did you miss me?", "[e:Laughter]Je vous ai manqué ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess we're doing this again...", "On dirait qu'on remet ça...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Hold on, this looks bad!", "[e:Surprise]Attendez, ça a l'air mal parti !", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]A prospector?[w:0.5]", "[e:Curious]Un prospecteur ?[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This feels like some kind of an attraction[w:0.5]", "On dirait une sorte d'attraction[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But we won't be having fun here, are we?", "[e:Anger]Mais nous ne sommes pas là pour nous amuser, n'est-ce pas ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy again?[w:0.3]", "[e:Anger]Encore ce type ?[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Let's be a bit more careful this time.", "[e:Anger]Soyons un peu plus prudents cette fois.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'll keep hearing this ringing for the rest of my life.", "[e:Anger]J'entendrai ce sifflement le reste de ma vie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You know what's gonna happen soon. Get ready.", "[e:Anger]Vous savez ce qui va se passer. Préparez-vous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Woah![w:0.5]", "[e:Surprise]Waouh ![w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This guy's huge![w:0.5]", "[e:Surprise]Ce type est énorme ![w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]But I've dealt with bigger fish than this.", "[e:Laughter]Mais j'ai déjà affronté de plus gros poissons.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's do this.", "[e:Laughter]Allons-y.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]This guy again...[w:0.3]", "[e:Curious]Encore ce type...[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've done this before, let's get him.", "[e:Laughter]On l'a déjà fait, attrapons-le.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You know...[w:0.3]", "[e:Anger]Vous savez...[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]maybe I don't need to feel so bad about the sharks we fed to that thing.", "[e:Anger]je n'ai peut-être pas à me sentir si mal pour les requins qu'on a donnés à cette chose.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]The smell doesn't get any better...", "[e:Anger]L'odeur ne s'améliore pas...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I knew something was off[w:0.3]", "[e:Anger]Je savais que quelque chose clochait[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Guess I've got a good grasp of people too.", "[e:Laughter]Je crois que je cerne bien les gens aussi.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Get ready.", "[e:Laughter]Préparez-vous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Nothing to worry about", "[e:Laughter]Pas de quoi s'inquiéter", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can disarm the traps from afar.", "[e:Laughter]je peux désamorcer les pièges à distance.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We shouldn't have any trouble at all.", "[e:Laughter]Nous ne devrions avoir aucun problème.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Here we go.", "[e:Laughter]C'est parti.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If you don't want to sacrifice anybody", "[e:Laughter]Si vous ne voulez sacrifier personne", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]let me get rid of these things myself.", "[e:Laughter]laissez-moi me débarrasser de ces choses moi-même.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]So this is the guy behind everything?[w:0.3]", "[e:Curious]Alors c'est lui qui est derrière tout ça ?[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Not sure what I was expecting", "[e:Curious]Je ne sais pas trop à quoi je m'attendais", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But it doesn't matter.[w:0.3]", "[e:Anger]Mais peu importe.[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Let's end this.", "[e:Anger]Finissons-en.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've done this before", "[e:Laughter]Nous l'avons déjà fait", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]let's do it again.", "[e:Laughter]recommençons.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy's no joke.", "[e:Anger]Ce type n'est pas une plaisanterie.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Don't let your guard down.", "[e:Anger]Ne baissez pas votre garde.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've got this, don't worry.", "[e:Laughter]On va y arriver, ne vous inquiétez pas.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]A...[w:0.3]pirate?", "[e:Surprise]Un...[w:0.3] pirate ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Hah, good one![w:0.3]", "[e:Laughter]Ha, bien joué ![w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, there's only one thing left to do.", "[e:Laughter]Eh bien, il ne reste qu'une chose à faire.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Watch out for the cannons.", "[e:Anger]Attention aux canons.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This will be tough, but we can do this.", "[e:Anger]Ce sera difficile, mais on peut y arriver.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy isn't playing around, stay on guard.", "[e:Anger]Ce type ne plaisante pas, restez sur vos gardes.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Is this some kind of...[w:0.5] Magic?[w:0.5]", "[e:Surprise]C'est une sorte de...[w:0.5] magie ?[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Well, I guess this is going to get much weirder.", "[e:Quiet]Eh bien, je crois que ça va devenir encore plus étrange.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]They're getting empowered. Stay alert.", "[e:Anger]Ils se renforcent. Restez vigilant.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Not this thing again...", "[e:Anger]Pas encore cette chose...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]How come I don't get fancy toys like this?", "[e:Curious]Pourquoi je n'ai pas droit à des gadgets aussi sophistiqués ?", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Just a little handicap, nothing more.", "[e:Laughter]Un petit handicap, rien de plus.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's not give up just yet.", "[e:Laughter]N'abandonnons pas tout de suite.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]What?[w:0.5] You of all people?[w:0.5]", "[e:Surprise]Quoi ?[w:0.5] Vous, entre tous ?[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I wish it didn't come down to this, but...[w:0.3]", "[e:Neutral]J'aurais préféré qu'on n'en arrive pas là, mais...[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Guess we've got no choice.", "[e:Quiet]Je crois que nous n'avons pas le choix.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This one's tough. Get ready.", "[e:Anger]Celui-là est coriace. Préparez-vous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]One wrong move and we're done for.", "[e:Anger]Un faux pas et c'est fini pour nous.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I really don't like dealing with her...", "[e:Anger]Je n'aime vraiment pas l'affronter...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I always got bad vibes from these guys.[w:0.5]", "[e:Anger]Ces types m'ont toujours donné une mauvaise impression.[w:0.5]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I've seen people like them.[w:0.3]", "[e:Anger]J'ai déjà vu des gens comme eux.[w:0.3]", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Whatever drives them,", "[e:Anger]Quoi que ce soit qui les motive,", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]we can get through just fine.", "[e:Laughter]nous nous en sortirons très bien.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]These guys again...", "[e:Neutral]Encore ces types...", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Come on, we didn't get this far just to kick the bucket here.", "[e:Laughter]Allons, nous ne sommes pas arrivés jusque-là pour mourir ici.", Language.French);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This is getting dangerous. Get ready.", "[e:Neutral]Ça devient dangereux. Préparez-vous.", Language.French);


        }
    }
